('00c060d8-c387-435d-91d9-88d7e6d4a48c', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '3cd6aeb4-305c-4941-a123-ab4da9914b36', 'MUTIARA PATRIOT RELIGI SERIES # 20 Tema \" Kewajiban Mengenal Allah SWT\"', 'mutiara-patriot-religi-series-20-tema-kewajiban-mengenal-allah-swt', NULL, '<p>Mengenal Allah SWT adalah kewajiban setiap Muslim dan menjadi fondasi utama dalam membangun keimanan serta ketakwaan. Dengan mengenal Allah, kita semakin memahami kebesaran, kekuasaan, dan kasih sayang-Nya, sehingga tumbuh kesadaran untuk senantiasa beribadah, menaati perintah-Nya, dan menjauhi larangan-Nya. Mari memperkuat iman dengan mengenal Allah SWT lebih dekat.</p>', 'images/ZlzBy1RqJTBInZuuLowQh9Zv5bBYcrPtwaGsnvcp.png', '2026-10-29 17:00:00', 'online', NULL, '2026-10-30 10:00:00', '2026-10-30 11:00:00', 'https://www.youtube.com/watch?v=aeNWnR46dKI', NULL, NULL, NULL, NULL, 6, 1, 0, 0, 0, 'Mutiara Patriot Religi, Mengenal Allah SWT, Tauhid, Akidah Islam, Keimanan, Ketakwaan, Kajian Islam, Dakwah Islam', 'published', 'index', NULL, '2026-10-11 19:36:01', '2026-10-31 07:59:12', NULL, 'dibatalkan'),
('6e44d8e4-650a-4803-a811-15fa24ac2efd', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'tes agenda diskom', 'tes-agenda-diskom', 'disdkom agenda', '<p>agenda</p>', 'images/89Ln514bEfZ8sccI6ezRvyaTF4sw37j6saCQfDi7.jpg', '2026-10-27 17:00:00', 'online', NULL, '2026-10-28 15:24:00', '2026-10-28 19:28:00', 'https://disdik.bekasikota.go.id', NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, NULL, 'pending', 'index', NULL, '2026-10-28 01:25:02', '2026-10-28 01:47:54', NULL, NULL);
