(1359, '787b72ea-59d0-4d54-848b-c200bddafdd2', 'super-admin', 'super@admin.com', 'deleted', 'App\\Models\\Page', '32c3f3dd-5ed8-4024-a573-9cba76118bb4', 'Lambang Daerah Kota Bekasi', '{\"uuid\":\"32c3f3dd-5ed8-4024-a573-9cba76118bb4\",\"title\":\"Lambang Daerah Kota Bekasi\",\"slug\":\"lambang-daerah-kota-bekasi\",\"excerpt\":\"Lambang Daerah Kota Bekasi\",\"content\":\"<p>sa<\\/p>\",\"featured_image\":\"pages\\/UMQVsYqH3un4AecOmara9A40quAbB1mXkRyb8VEM.png\",\"is_published\":1,\"user_uuid\":\"787b72ea-59d0-4d54-848b-c200bddafdd2\",\"has_sidebar\":0}', NULL, 'http://127.0.0.1:8000/backend/pages/32c3f3dd-5ed8-4024-a573-9cba76118bb4', '127.0.0.1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', '2026-11-01 05:59:38', '2026-11-01 05:59:38');
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bad60-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Forum Kerukunan Umat Beragama Kota Bekasi Mendapat Respon Yang Positif.', 'forum-kerukunan-umat-beragama-kota-bekasi-mendapat-respon-yang-positif', 'Kota Bekasi (10/11)-Walikota Bekasi Dr. Rahmat Effendi menjanjikan pemberian insentif bagi para veteran kemerdekaan yang tinggal di wilayahnya mulai 2017.&nbsp; &nbsp;&quot;Hal ini dilakukan sebagai b', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span color:=\"\" font-family:=\"\" span=\"\">Kota Bekasi (10/11)-Walikota Bekasi Dr. Rahmat Effendi menjanjikan pemberian insentif bagi para veteran kemerdekaan yang tinggal di wilayahnya mulai 2017.&nbsp; &nbsp;&quot;Hal ini dilakukan sebagai bentuk perhatian dari pemerintah daerah atas jasa-jasa pahlawan kemerdekaan&quot;kata Walikota Bekasi tersebut.</span></div>\n\n<p>&nbsp;</p>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span color:=\"\" font-family:=\"\" span=\"\">Menurut Rahmat Effendi &nbsp;pihaknya akan memberikan insentif sebesar Rp1 juta pada masing-masing warga yang berstatus sebagai mantan pejuang kemerdekaan di Kota Bekasi.</span><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Ketua RT saja kita kasih, hansip, kader Posyandu pun diberikan insentif, maka digaribawahi veteran pun akan kita berikan insentif.Akan kita ajukan dalam pembahasan APBD 2017, Dinsos pun akan mendata jumlah veteran yang ada di Kota Bekasi,&quot; Jelas Walikota Bekasi .</span></div>\n\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp; &nbsp; Terkait rencana ini, Kepala Dinas Sosial (Dinsos) Kota Bekasi, Junaedi mengatakan pihaknya akan segera mendata jumlah veteran yang tinggal di wilayahnya.&nbsp;&nbsp;&quot;Selama ini seluruh veteran yang ada di Kota Bekasi memiliki kantor sekretariat di daerah Jatiasih&quot;katanya.Mendata veteran di Kota Bekasi, kata dia, tidaklah sulit, sebab selain mereka punya wadah, para veteran juga memegang Surat Keputuasan (SK) yang menyatakan dirinya adalah seorang pahlawan. &quot;Meskipun pangkatnya rendah sekelas kopral sekalipun tetap akan kita berikan insentifnya,&quot; jelas Kadinsos.(Dimz).</span></div>', 'images/20171004223842-2017-10-04post223840.jpg', NULL, NULL, 2027, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 03:38:00', '2016-11-15 03:38:00', NULL),
('eb3bb0cc-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Menerima TIm Penilai Posyandu Tingkat Propinsi', 'walikota-menerima-tim-penilai-posyandu-tingkat-propinsi', 'Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pembangunan dan Pemukiman Kota Bekasi, Dadang Ginanjar memantau dan melihat pekerjaan Pembangunan Lanjutan 8 Lantai Rumah Sakit U', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pembangunan dan Pemukiman Kota Bekasi, Dadang Ginanjar memantau dan melihat pekerjaan Pembangunan Lanjutan 8 Lantai Rumah Sakit Umum Daerah (RSUD) Kota Bekasi di Mayor Oking, Ex Proyek pada hari Rabu (01/06).</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Pembangunan Gedung 8 Lantai RSUD Kota Bekasi khusus paru dan rehabilitasi narkoba yang sedang tahap pengerjaannya sudah mencapai 37%,&nbsp;dan akan perencanaannya selesai dan rampung pada bulan Desember 2016 ini.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Bulan desember akan sudah terlihat, dan akan rampung seperti setara gedung 8 lantai RSUD yang telah dibangun&quot; Jelas Kepala Dinas Pembangunan dan Pemukiman</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dari pihak PT. Sasmito yang mengerjakan pembangunan tersebut, bahwa akses jalan keluar nanti bisa tembus melalui Gedung RSUD yang berada di Jalan Veteran (RSUD lama) dan bisa juga melalui Mayor Oking karena jembatan penghubung antar RSUD Kota Bekasi ke Jalan Mayor Oking sudah jadi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi, menjelaskan bahwa kedepannya akan direncanakan jalan tembus dari Jalan Juanda menuju Jalan Veteran yang akan memudahkan akses pengguna jalan terhindar dari macet di perempatan Bekasi Junction, yang akan direncanakan akan ditahun 2018 mendatang setelah selesai pengerjaan semua rencana pembangunan di Kota Bekasi. (Ndoet)</span></span></div>', 'images/20170823084337-2017-08-23post084336.jpg', NULL, NULL, 2099, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 03:43:00', '2016-11-15 03:43:00', NULL),
('eb3bb20c-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Bekasi Sidak Keliling RSUD Mendengarkan Keluhan Warga.', 'walikota-bekasi-sidak-keliling-rsud-mendengarkan-keluhan-warga', 'Kota Bekasi (18/10)- Walikota Bekasi Dr Rahmat Effendi dipagi hari sudah berada di Rumah Sakit Umum Daerah (RSUD) Kota Bekasi guna melihat dan mendengar langsung kekurangan dan kelebihan pelayanan RSU', '<p border-box=\"\">Kota Bekasi (18/10)- Walikota Bekasi Dr Rahmat Effendi dipagi hari sudah berada di Rumah Sakit Umum Daerah (RSUD) Kota Bekasi guna melihat dan mendengar langsung kekurangan dan kelebihan pelayanan RSUD.</p>\n\n<p>&nbsp;</p>\n\n<p border-box=\"\">&nbsp;Diawali dengan melihat pelayanan di loket &nbsp;BPJS Walikota Bekasi tersebut sempat berkomunikasi dengan pasien,dirinya menanyakan kepada pasien sejak jam berapa mendaftar untuk berobat dan mendapati pada pukul 6.00 sudah ada 400 nmr antrian yang tersebar.Untuk itu dirinya meminta untuk di buatkan tempat memasukkan blangko pendaftaran berdasarkan poli klinik yang di tuju,sehingga dapat lebih efisien dan fleksibel.</p>\n\n<div border-box=\"\">&nbsp;</div>\n\n<div border-box=\"\">Walikota Bekasi kemudian melanjutkan ke lab RSUD,dia mendapati loket tersebut masih tutup walaupun sudah banyak yang mengantri.&quot;Saya minta pelayanan Lab harus 24 jam &nbsp;mulai hari ini,tempat kan pegawai dan berikan uang lembur yg sesuai,dan untuk pelayanan pendaftaran harus datang lebih pagi dan jam 6 berkas pendaftaran tersebut sudah Running&quot;tegas Walikota Bekasi Dr.Rahmat Effendi kepada Wadirum,Dra.Tri Sulistya M.Si.</div>\n\n<div border-box=\"\">&nbsp;</div>\n\n<div border-box=\"\">Rahmat Effendi juga berkeliling ke berbagai ruangan seperti ruang cuci darah dan ruang-ruang pasien untuk memastikan RSUD Kota Bekasi mampi memberikan pelayanan yang optimal dan lebih baik lg. (DIMZ).</div>', 'images/20171004223819-2017-10-04post223818.jpg', NULL, NULL, 2888, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 03:55:00', '2016-11-15 03:55:00', NULL),
('eb3bb2df-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Mengunjungi GKI Hankam Raya.', 'walikota-mengunjungi-gki-hankam-raya', '&nbsp;Disambut beberapa pendeta ,Walikota Bekasi sempat berdialog langsung dengan jamaat GKI tersebut ,Rahmat Effendi selaku Walikota Bekasi mengatakan bahwa selepas pengukuhan Majelis Umat,dirinya in', '<p 0px=\"\" 45=\"\" adalah=\"\" aula=\"\" beberapa=\"\" bekasi=\"\" beragama=\"\" berkunjung=\"\" berlokasi=\"\" dan=\"\" di=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" gereja=\"\" gki=\"\" hankam=\"\" ind=\"\" jalan=\"\" jatirahayu=\"\" ke=\"\" kecamatan=\"\" kota=\"\" kristen=\"\" langsung=\"\" line-height:=\"\" lokasi.diantaranya=\"\" majelis=\"\" margin:=\"\" melati=\"\" melihat=\"\" mengunjungi=\"\" nomer=\"\" p=\"\" p3bk=\"\" pekerjaan=\"\" pengukuhan=\"\" raya=\"\" selepas=\"\" text-align:=\"\" umat=\"\" walikota=\"\" yang=\"\">&nbsp;Disambut beberapa pendeta ,Walikota Bekasi sempat berdialog langsung dengan jamaat GKI tersebut ,Rahmat Effendi selaku Walikota Bekasi mengatakan bahwa selepas pengukuhan Majelis Umat,dirinya ingin mengunjungi GKI Hankam Raya,ia mengatakan sebagai bagian dari Pemerintah dirinya wajib mengayomi semua umat beragama,tak terkecuali jemaat GKI ini,sebagai Kepala Daerah dirinya harus tetap berada di tengah-tengah setiap umat beragama,&quot;Saya semenjak tahun 2010 sudah berkeliling kota Bekasi untuk selalu mengajak masyarakat beragama mejaga sikap toleran,tidak boleh kita mempertentangkan perbedaan agama suku dan ras,sebagai anak bangsa yang lahir di tanah NKRI ,menjadi kewajiban saya memberikan manfaat bagi masyarakat Kota Bekasi.Agama islam juga mengajarkan kepada saya bahwa islam adalah agama yang membawa rahmat dan kesejahteraan bagi semua seluruh alam semesta, termasuk hewan, tumbuhan, apalagi sesama manusia&quot;jelas Rahmat Effendi.</p>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\">Dirinya menambahkan bahwa untuk itulah ia dan para pemangku jabatan menyempatkan diri berkunjung ke GKI Hankam Raya sebagai bagian dari kewajiban dirinya sebagai Kepala Daerah,Walikota semua umat beragama.&quot;Tidak ada lagi khususnya di Kota Bekasi kaum minoritas dan mayoritas,yang ada hanya anak bangsa Indonesia yang hidup secara berdampingan&quot;pungkas Dr.Rahmat Effendi. (DIMZ).</div>', 'images/20171004223801-2017-10-04post223800.jpg', NULL, NULL, 3234, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 04:01:00', '2016-11-15 04:01:00', NULL),
('eb3bb3e0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kota Bekasi Akan Menggunakan Aplkasi Sorot', 'kota-bekasi-akan-menggunakan-aplkasi-sorot', 'Kota Bekasi, --&nbsp;Para ahli pengelolaan keuangan sangat strategis dan penting dalam sebuah organisasi baik dijajaran pemerintah maupun swasta. Dengan SDM yang mumpuni diyakini akan menghasilkan pro', '<p border-box=\"\">Kota Bekasi, --&nbsp;<span border-box=\"\">Para ahli pengelolaan keuangan sangat strategis dan penting dalam sebuah organisasi baik dijajaran pemerintah maupun swasta. Dengan SDM yang mumpuni diyakini akan menghasilkan produk administrasi keuangan yang bisa dipertanggungjawabkan.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">Sejalan dengan hal tersebut, Pemkot Bekasi tengah memulai penataan jabatan fungsional analisis keuangan dijajarannya.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Kali ini, sebanyak 20 pegawai Pemkot Bekasi mengikuti pelatihan persiapan pembentukan jabatan fungsional analisis keuangan pusat dan daerah, Senin, (7/11) bertempat di Hotel Santika, Giant Hypermal Bekasi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Direktorat Jendral Perimbangan Keuangan (DJPK) Kementerian Keuangan RI bersama Badan Pengelolaan Keuangan dan Aset Daerah (BPKAD) memfasilitasi kegiatan ini.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Wakil Walikota Bekasi H Ahmad Syaikhu membuka kegiatan pelatihan tersebut. Para peserta akan mengikuti pelatihan hingga Jumat, 11 November 2016 dan dilanjutkan pelaksanaan ujian kompetensi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Wawali Ahmad Syaikhu dalam sambutannya mengatakan pelatihan persiapan pembentukan jabatan fungsional menjadi upaya menata SDM aparatur Pemkot, sesuai dengan amanat UU No 5 Tahun 2014 tentang Aparatur Sipil Negara.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dalam kesempatan itu, Ia pun mengapresiasi jajaran BPKAD Kota Bekasi telah memulai kerjasama dengan Pemerintah Pusat terkait pembinaan jabatan fungsional analis keuangan daerah.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Banyak orang-orang kompeten akan mampu mengantarkan kinerja terbaik pada Pemkot Bekasi. Seperti kompetensi analis keuangan kita tunjukan kinerja terbaik dan Insya Allah, WTP yang telah dicapai bisa dipertahankan dan sempurnakan dengan prestasi di bidang keuangan yang lain,&quot; kata Wawali Ahmad Syaikhu.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Lanjut dia, rencana pembentukan jabatan fungsional analis keuangan menjadi agenda pemerintah menata aparatur pusat hingga daerah sesuai kompetensi masing-masing. Disamping menjadi solusi terkait terbatasnya pola karir jabatan struktural.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Untuk itu, ia harapkan Badan Kepegawaian Daerah (BKD) untuk terus berkoordinasi dengan SKPD yang didalamnya terdapat para pejabat fungsional.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Ini menggembirakan mengenai pola karir ASN pusat dan daerah. Pemerintah pusat melalui Kemnkeu dan BKN mengeluarkan Permenkeu terkait juknis maupun standar kompetensi jabfung Analis Keuangan. Namun Perpres terkait tunjangan belum selesai,&quot; kata Ahmad Syaikhu.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Pemkot Bekasi, kata dia melalui Tim Anggaran juga akan memikirkan pemberian tunjangan bagi pejabat fungsional yang ada. Dan itu dibolehkan sepanjang sesuai perundang-undangan yang berlaku diantaranya guna mendorong kinerja aparaturnya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Pak Walikota, saya dan Tim Anggaran setuju mengembangkan pola karir sesuai penghasilan. Dan ini dibolehkan bahwa Pemda memberikan tunjangan lainnya diluar tunjangan Perpres Jabfung Analis Keuangan,&quot; kata Wawali Ahmad Syaikhu.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Untuk itu ia berpesan agar aparatur Pemkot Bekasi menunaikan kewajiban pekerjaan dengan baik dan rewardnya Pemkot Bekasi mempertimbangkan kenaikan tunjangan yang sesuai.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Keinginan kita bersama, memperoleh penghasilan besar dengan cara halal ketimbang penghasilan besar dengan cara mengutip yang berdampak permasalahan hukum kedepan,&quot; kata Wawali Ahmad Syaikhu mengingatkan</p>', 'images/20171004223745-2017-10-04post223736.jpg', NULL, NULL, 2151, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:07:00', '2016-11-15 05:07:00', NULL),
('eb3bb46e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Konsep Smart City Diharapkan Membantu Menyelesaikan Permasalahan.', 'konsep-smart-city-diharapkan-membantu-menyelesaikan-permasalahan', 'Kota Bekasi, --&nbsp;Bidang Perencanaan dan Tata Ruang Dinas Tata Kota Bekasi, Erwin Gwinda\r\nDi Indonesia sendiri, kota bogor menduduki posisi kedua predikat kota termacet di dunia setelah Negara elsa', '<p 0px=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" line-height:=\"\" lucida=\"\" margin:=\"\" span=\"\" text-align:=\"\">Kota Bekasi, --<span 0px=\"\" asing=\"\" atau=\"\" bagi=\"\" bandung=\"\" banyak=\"\" begitu=\"\" bekasi=\"\" berhasil=\"\" besar=\"\" biasa=\"\" city=\"\" cukup=\"\" dan=\"\" dasar=\"\" di=\"\" dikeluhkan=\"\" font-family:=\"\" font-size:=\"\" gagas=\"\" helvetica=\"\" ind=\"\" indonesia.=\"\" ini=\"\" k=\"\" kalangan=\"\" karena=\"\" kerusakan=\"\" kota=\"\" kota-kota=\"\" lagi=\"\" lainnya=\"\" lama.=\"\" line-height:=\"\" lirik=\"\" lucida=\"\" margin:=\"\" masalah=\"\" masyarakat=\"\" menjadi=\"\" menyelesaikan=\"\" nilai=\"\" p=\"\" pekerjaan=\"\" pemikiran=\"\" pintar=\"\" rumah=\"\" saja=\"\" sampah=\"\" sebenarnya=\"\" sebut=\"\" seperti=\"\" sering=\"\" smart=\"\" sudah=\"\" tentang=\"\" text-align:=\"\" tidak=\"\" yang=\"\">&nbsp;<span agar=\"\" bekasi=\"\" bertujuan=\"\" city=\"\" color:=\"\" dan=\"\" di=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" k=\"\" kemacetan=\"\" kota=\"\" line-height:=\"\" lucida=\"\" mencanangkan=\"\" menyelesaikan=\"\" nyaman=\"\" open=\"\" permasalahan=\"\" sampah=\"\" seperti=\"\" smart=\"\" span=\"\" tercipta=\"\" ujar=\"\" untuk=\"\" yang=\"\">Bidang Perencanaan dan Tata Ruang Dinas Tata Kota Bekasi, Erwin Gwinda</span><br c=\"\" cerminan=\"\" city=\"\" dan=\"\" dapat=\"\" dikatakannya=\"\" dinilai=\"\" dir=\"ltr\" div=\"\" font-family:=\"\" font-size:=\"\" governance.=\"\" helvetica=\"\" kemacetan=\"\" kota=\"\" lucida=\"\" masalah=\"\" meliputi=\"\" public=\"\" saja=\"\" sebagai=\"\" smart=\"\" tata=\"\" text-align:=\"\" yang=\"\" />\r\n<span awak=\"\" bagian=\"\" dengan=\"\" di=\"\" dir=\"ltr\" div=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" jumat=\"\" lucida=\"\" media=\"\" melakukan=\"\" pertemuan=\"\" press=\"\" raung=\"\" room=\"\" saat=\"\" text-align:=\"\">Di Indonesia sendiri, kota bogor menduduki posisi kedua predikat kota termacet di dunia setelah Negara elsavador. ini tentu bukan prestasi yang membanggakan. tuturnya.&nbsp;<br br=\"\" />\r\nSmart city dapat di akses melalui internet, tekhnologi menjadi hal yang sangat penting dan mutlak sekarang ini. Teknologi informasi juga berkembang begitu cepat dan sudah menjadi life style masyarakat dewasa ini. </span></span></p>\r\n\r\n<div br=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" helvetica=\"\" lucida=\"\" text-align:=\"\"><span 0px=\"\" asing=\"\" atau=\"\" bagi=\"\" bandung=\"\" banyak=\"\" begitu=\"\" bekasi=\"\" berhasil=\"\" besar=\"\" biasa=\"\" city=\"\" cukup=\"\" dan=\"\" dasar=\"\" di=\"\" dikeluhkan=\"\" font-family:=\"\" font-size:=\"\" gagas=\"\" helvetica=\"\" ind=\"\" indonesia.=\"\" ini=\"\" k=\"\" kalangan=\"\" karena=\"\" kerusakan=\"\" kota=\"\" kota-kota=\"\" lagi=\"\" lainnya=\"\" lama.=\"\" line-height:=\"\" lirik=\"\" lucida=\"\" margin:=\"\" masalah=\"\" masyarakat=\"\" menjadi=\"\" menyelesaikan=\"\" nilai=\"\" p=\"\" pekerjaan=\"\" pemikiran=\"\" pintar=\"\" rumah=\"\" saja=\"\" sampah=\"\" sebenarnya=\"\" sebut=\"\" seperti=\"\" sering=\"\" smart=\"\" sudah=\"\" tentang=\"\" text-align:=\"\" tidak=\"\" yang=\"\"><span awak=\"\" bagian=\"\" dengan=\"\" di=\"\" dir=\"ltr\" div=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" jumat=\"\" lucida=\"\" media=\"\" melakukan=\"\" pertemuan=\"\" press=\"\" raung=\"\" room=\"\" saat=\"\" text-align:=\"\">Warga bekasi harus paham betul pentingnya tekhnologi. Menjadi sangat penting karena tekhnologi sangat bermanfaat untuk membangun kota Bekasi menjadi lebih maju karena di nilai sangat efektif dan efisien dalam penggunaanya.</span></span></div>\r\n\r\n<div dir=\"ltr\" div=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" lucida=\"\" text-align:=\"\"><span 0px=\"\" asing=\"\" atau=\"\" bagi=\"\" bandung=\"\" banyak=\"\" begitu=\"\" bekasi=\"\" berhasil=\"\" besar=\"\" biasa=\"\" city=\"\" cukup=\"\" dan=\"\" dasar=\"\" di=\"\" dikeluhkan=\"\" font-family:=\"\" font-size:=\"\" gagas=\"\" helvetica=\"\" ind=\"\" indonesia.=\"\" ini=\"\" k=\"\" kalangan=\"\" karena=\"\" kerusakan=\"\" kota=\"\" kota-kota=\"\" lagi=\"\" lainnya=\"\" lama.=\"\" line-height:=\"\" lirik=\"\" lucida=\"\" margin:=\"\" masalah=\"\" masyarakat=\"\" menjadi=\"\" menyelesaikan=\"\" nilai=\"\" p=\"\" pekerjaan=\"\" pemikiran=\"\" pintar=\"\" rumah=\"\" saja=\"\" sampah=\"\" sebenarnya=\"\" sebut=\"\" seperti=\"\" sering=\"\" smart=\"\" sudah=\"\" tentang=\"\" text-align:=\"\" tidak=\"\" yang=\"\"><span awak=\"\" bagian=\"\" dengan=\"\" di=\"\" dir=\"ltr\" div=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" jumat=\"\" lucida=\"\" media=\"\" melakukan=\"\" pertemuan=\"\" press=\"\" raung=\"\" room=\"\" saat=\"\" text-align:=\"\">&nbsp;untuk itu, pemerintah daerah terus memberikan sosialisasi kepada masyarakat tentang program ini, tentunya juga dengan meningkatkan fasislitas-fasilitas penunjang prgroam smart city ini sal;ah satunya memasang Wi-fi di setiap area-area lingkungan masyarakat, seperti taman, halte. sehingga masyarakat dengan mudah mengakses informasi lewat handphone, tandasnya.</span></span></div>', 'images/20171004223713-2017-10-04post223712.jpg', NULL, NULL, 4512, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:12:00', '2016-11-15 05:12:00', NULL),
('eb3bb506-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Institut STIAMI Bekasi Gelar Seminar Nasional Startegi Smart City.', 'institut-stiami-bekasi-gelar-seminar-nasional-startegi-smart-city', 'Kota Bekasi - Institut STIAMI&nbsp; Jakarta Kampus&nbsp; Kota Bekasi menggelar Seminar Nasional 2016 dengan tema &quot;Strategi Mewujudkan Smart City Melalui Tata Kelola Pemerintah yang Baik&quot;, be', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Institut STIAMI&nbsp; Jakarta Kampus&nbsp; Kota Bekasi menggelar Seminar Nasional 2016 dengan tema &quot;Strategi Mewujudkan Smart City Melalui Tata Kelola Pemerintah yang Baik&quot;, bertempat di Hotel Horison Bekasi, Kalimalang, Bekasi Selatan, Sabtu (19/3).</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Seminar tersebut dibuka langsung oleh Rektor Institut Panji Hendrarso, dengan menghadirkan tiga narasumber sebagai pakar Smart City&nbsp; Indonesia adalah ; Keynot Speaker Suhono Harso Supangkat, Ketua Smart City sekaligus Kepala Dinas Tata Kota Pemerintah Kota Bekasi,&nbsp; Ir.Koswara&nbsp; dan TS.Reza sekaligus Dosen tetap&nbsp; Institut STIAMI.</span></span></div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Seminar tersebut juga dihadiri ribuan Mahasiswa /Mahasiswi STIAMI&nbsp; pusat, Cikarang&nbsp; Bekasi, Kota Bekasi dan mahasiswa dari perguruan tinggi lainnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Direktur&nbsp; Institut STIAMI&nbsp; Jakarta Kampus&nbsp; Kota Bekasi, Diana Prihadini mengatakan&nbsp; Smart City untuk meningkatkan kualitas hidup masyarakat perkotaan. Dengan cara membangun kehidupan masyarakat melalui instrumen sistem smart city.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Tak terkecuali kata dia Kota Bekasi yang tengah berbenah mengadopsi konsep smart city seperti kota-kota besar lainnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dengan pesatnya pertumbuhan kota dan peningkatan jumlah pendudukan, pemerintah dan masyarakat perlu pemikiran cerdas dalam membangun kota Bekasi kedepan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&ldquo;Konsep Smart City ini sebagai salah satu solusi dalam mengatasi berbagai masalah seperti kemacetan, banjir, kriminalitas, dan lain-lainnya. Hal demikian diperlukan pemikiran cerdas, serta dukungan&nbsp; penuh dari berbagai pihak, khususnya&nbsp; bagi mahasiswa STIAMI di Kota Bekasi,&quot; ungkap Diana.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Ketua Smart City Kota Bekasi Ir.Koswara menyampaikan dalam seminar tersebut bahwa pencapaian Visi Kota Bekasi Sejalan dengan konsep Smart City&nbsp; memerlukan inovasi, kreatifitas dan dukungan dari kalangan mahasiswa, kedisiplinan dan partisipasi masyarakat dalam mengelola Kota.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Konsep smart city bagi pemerintah untuk meningkatkan pelayanan publik, membangun efisiensi, akuntabilitas dan transparani dalam memanfaatkan semua sumber daya. termasuk sumbangsih para tenaga ahli, akademisi dan mahasiswa,&quot; kata Koswara.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Lebih lanjut kata Koswara memaparkan, kehadiran Patriot Operation Center (POT) sebagai komponen infrastruktur membangun smart city.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sarana POT adanya Wifi, sensor, dan CCTV serta ada berbagai aplikasi aduan masyarakat yang dimasukan salah satunya melalui aplikasi Qlue dan media jejaring sosial.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Diharapkan aparatur mampu menguasai sistem informasi termasuk dalam menjawab partisipasi warga. Kita miliki Qlue dan Informasi&nbsp;akan terintegrasi melalui POT,&quot; kata Koewara.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Lanjut dia, penerapan Bekasi Smart City akan dilanjutkan dalam sektor transportasi. Program kereta LRT akan masuk ke Kota Bekasi. Untuk itu kota Bekasi juga merintis program kereta cepat aeromovel dalam kota.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&ldquo;Tahun ini kita akan membuat kajian, dan nanti bentuknya akan menjadi Perwal. Karena Kota Bekasi saat ini sudah maju. Apalagi kedepannya Pemkot Bekasi akan menghadirkan Aeromovel akan di kembangkan melalui jalur, Harapan Indah, Kalibaru, Summareon, Ahmad Yani dan Kemang Pratama sejauh12 km. ,&quot;tutur Koswara. (ais/goeng)&nbsp;</span></span></div>', 'images/20171004223658-2017-10-04post223649.jpg', NULL, NULL, 5302, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:15:00', '2016-11-15 05:15:00', NULL),
('eb3bb596-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Semangat Wawali Sosialisasikan Bekasi Smart City', 'semangat-wawali-sosialisasikan-bekasi-smart-city', 'Wakil Walikota Bekasi H Ahmad Syaikhu terus bersemangat melakukan kunjungan ke sekolah-sekolah dalam rangka mensosialisasikan Kota Bekasi Smart City dikalangan generasi muda Kota Bekasi.\r\n\r\n&nbsp;\r\n\r\n', '<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" kota=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Wakil Walikota Bekasi H Ahmad Syaikhu terus bersemangat melakukan kunjungan ke sekolah-sekolah dalam rangka mensosialisasikan Kota Bekasi Smart City dikalangan generasi muda Kota Bekasi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Kota Bekasi Smart City menjadi bagian dari penyelenggaraan Pemerintah Kota Bekasi agar lebih responsif dan perlu didukung keterlibatan aktif masyarakatanya.</p>\r\n\r\n<p 0px=\"\" ahmad=\"\" bekasi=\"\" berkunjung=\"\" bertemu=\"\" color:=\"\" dan=\"\" dari=\"\" dengan=\"\" didik=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" ia=\"\" kali=\"\" ke=\"\" line-height:=\"\" mandalahayu=\"\" margin:=\"\" melati.=\"\" mendapatkan=\"\" p=\"\" peserta=\"\" pihak=\"\" positif=\"\" puluhan=\"\" resp=\"\" sandikta=\"\" smk=\"\" syaikhu=\"\" text-align:=\"\" timur=\"\">Di dua sekolah ia memotivasi para siswa untuk terus belajar dan meningkatkan kualitas ilmu demi menuju era persaingan global. Kota Bekasi memiliki potensi dari sumber daya manusianya dan harapan sumbangsih generasi muda kedepan khususnya bagi Kota Bekasi.</p>\r\n\r\n<p 0px=\"\" 2.6=\"\" ahmad=\"\" akan=\"\" bekasi=\"\" bersaing=\"\" bisa=\"\" color:=\"\" dan=\"\" dari=\"\" dengan=\"\" depan=\"\" di=\"\" dir=\"ltr\" era=\"\" font-family:=\"\" font-size:=\"\" harus=\"\" ini=\"\" jadi=\"\" jiwa.=\"\" juta=\"\" kurang=\"\" line-height:=\"\" margin:=\"\" masa=\"\" minim=\"\" namun=\"\" p=\"\" pelajar=\"\" pemimpin=\"\" penduduknya=\"\" persaingan=\"\" saat=\"\" sda=\"\" sdm=\"\" segi=\"\" text-align:=\"\" tidak=\"\" unggul=\"\" ungkap=\"\" wawali=\"\">&quot;Adik-adik tidak boleh ketinggalan dan terus membekali diri dengan belajar lebih sungguh-sungguh,&quot; sambungnya.</p>\r\n\r\n<p 0px=\"\" baru=\"\" bekasi=\"\" berperan=\"\" bisa=\"\" cerdas.=\"\" city=\"\" color:=\"\" dan=\"\" dekat=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" hal=\"\" informasi=\"\" ini=\"\" k=\"\" kota=\"\" lebih=\"\" line-height:=\"\" margin:=\"\" membantu=\"\" menerapkan=\"\" menurutnya=\"\" merupakan=\"\" mewujudkan=\"\" p=\"\" pelajar=\"\" saat=\"\" smart=\"\" teknologi=\"\" text-align:=\"\" turut=\"\" yang=\"\">&quot;Bekasi punya aplikasi layanan pengaduan online melalui SOROT dan POT berbasis android. Aduan masyarakat bisa disampaikan lewat dua aplikasi dan sosial media yang ada. Aduan termonitor langsung di ruang kontrol Bekasi Smart City di Patriot Operating Center,&quot; ungkapnya.</p>\r\n\r\n<p 0px=\"\" aduan=\"\" akan=\"\" bekasi.=\"\" bisa=\"\" color:=\"\" dan=\"\" dengan=\"\" dicari=\"\" diidentifikasi=\"\" dir=\"ltr\" diungkapkan=\"\" font-family:=\"\" font-size:=\"\" jerap=\"\" juga=\"\" kepada=\"\" kota=\"\" langsung=\"\" lewat=\"\" line-height:=\"\" margin:=\"\" masyarajat=\"\" masyarakat=\"\" media=\"\" p=\"\" pemkot=\"\" penyelesaiannya.=\"\" permasalaham=\"\" selanjutnya=\"\" skpd=\"\" terkait=\"\" text-align:=\"\">&quot;Kota besar termasuk Bekasi tidak luput dari permaslahan. Kemacetan, sampah, infrastruktur dan lainnya. Melalui perangkat Bekasi Smart City kita ingin persoalan itu bisa diminimalisir. Mewujudkan Kota Bekasi Maju, Sejahtera dan Ihsan,&quot; ungkapnya.</p>\r\n\r\n<p 0px=\"\" ahmad=\"\" color:=\"\" dengan=\"\" didepan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" lalu=\"\" line-height:=\"\" margin:=\"\" memberikan=\"\" p=\"\" para=\"\" sebuah=\"\" siswa=\"\" syaikhu=\"\" text-align:=\"\">Neng farah mau beli terasi&nbsp;<br belinya=\"\" br=\"\" pakai=\"\" />\r\nJangah marah Bekasi dibuli<br 0px=\"\" aksi=\"\" color:=\"\" dengan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" jawab=\"\" line-height:=\"\" margin:=\"\" p=\"\" tapi=\"\" text-align:=\"\" />\r\n&quot;Tunjukkan kreasi adik-adik sebagai penerus bangsa agar pembuli akan semakin yakin Bekasi sekarang ini terus memperbaiki diri menjadi lebih baik,&quot; pungkasnya.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&lt;p dir=&quot;ltr&quot; border-box;=&quot;&quot; margin:=&quot;&quot; 0px=&quot;&quot; 10px;=&quot;&quot; text-align:=&quot;&quot; justify;=&quot;&quot; font-size:=&quot;&quot; 12.8px;=&quot;&quot; line-height:=&quot;&quot; 22px;=&quot;&quot; color:=&quot;&quot; rgb(34,=&quot;&quot; 34,=&quot;&quot; 34);=&quot;&quot; font-family:=&quot;&quot; arial,=&quot;&quot; sans-serif;&quot;=&quot;&quot;&gt;Diakhir kunjungannya, agar semuanya lebih bersemangat, ia mengajak para siswa dan guru empat kali salam patriot. Dilanjutkan dengan berfoto bersama dan pemberian beberapa flash disk, alat penyimpan data, sebagai hadiah bagi para siswa. (goeng)</p>', 'images/20170823080838-2017-08-23post080837.jpeg', NULL, NULL, 2989, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:17:00', '2016-11-15 09:17:00', NULL),
('eb3bb633-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sekda Kota Bekasi Ingatkan Pejabat Tingkatkan Kinerja.', 'sekda-kota-bekasi-ingatkan-pejabat-tingkatkan-kinerja', 'Kota Bekasi, --&nbsp;Sekretaris Daerah Kota Bekasi Drs Rayendra Sukarmadji melantik dan mengambil sumpah sejumlah pejabat eselon III dan IV dalam jabatan baru, Jumat, (4/11) di Aula Nonon Sontanie, Ka', '<p border-box=\"\">Kota Bekasi, --&nbsp;<span border-box=\"\">Sekretaris Daerah Kota Bekasi Drs Rayendra Sukarmadji melantik dan mengambil sumpah sejumlah pejabat eselon III dan IV dalam jabatan baru, Jumat, (4/11) di Aula Nonon Sontanie, Kantor Walikota Bekasi.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">Saat itu sebanyak 42 pejabat terdiri dari 7 pejabat eselon III dan 35 Eselon IV diambil sumpah termasuk beberapa staf yang mendapatkan promosi jabatan.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Sekda Kota Bekasi Rayendra mengatakan rotasi dan mutasi menjadi hal yang biasa didalam organisasi. Terutama&nbsp;guna memaksimalkan roda pemerintahan diantaranya melalui penempatan jabatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dalam pelantikan kali ini ia menegaskan pejabat Kota Bekasi harus meningkat kinerjanya. Bahkan ia tidak segan-segan merotasi kembali pejabat yang baru dilantik bila tidak berkinerja baik.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Ada laporan tidak mampu bekerja, pejabat bisa kita rotasi kembali. Pa Wali dan Pa Wakil akan memberikan reward dan punishment kepada pejabat atas kinerjanya selama ini,&quot; ungkap Rayendra.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Bila dibutuhkan untuk kepentingan organisasi akan terus dilakukan perputaran. Seperti kemarin kita lakukan rotasi pejabat bagi eselon II dan III,&quot; lanjutnya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Namun ia pun mengapresiasi sejumlah pejabat yang mengantarkan Kota Bekasi mampu beprestasi di tingkat Jawa Barat dan Nasional. Dan ia mengungkapkan perlu diberikan reward bagi para pejabat tersebut berupa kenaikan jabatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Selaku Baperjakat, dan Pimpinan daerah, kami akan apresiasi berupa reward bagi mereka,&quot; kata Rayendra.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Ia pun mengatakan seiring rencana perubahan kelembagaan organisasi di 2017 , sangat memungkinkan akan kembali dilakukan rotasi dan mutasi pejabat dilingkungan Pemkot Bekasi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Yang baru dilantik, mungkin tidak lama akan dilantik kembali. Ini karena SKPD akan bertambah dan berubah. Seperti pada Dinas Kebersihan, DP3JU, Tata Kota dan dinas lainnya. Sosialisasi perubahan kelembagaan juga akan kita lakukan,&quot; kata Sekda Kota Bekasi Rayendra. (goeng)</p>', 'images/20171004223613-2017-10-04post223611.jpg', NULL, NULL, 3289, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:19:00', '2016-11-15 05:19:00', NULL),
('eb3bb6d5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Pantau Pengerjaan Sisi Selatan Kalimalang.', 'walikota-pantau-pengerjaan-sisi-selatan-kalimalang', 'Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi lakukan tinjauan lapangan pembangunan tanggul kali malang ( site pel ) bersama jajaran dinas terkait pada hari Senin (22/02).\r\n\r\n&nbsp;\r\n\r\nIni dana pe', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi lakukan tinjauan lapangan pembangunan tanggul kali malang ( site pel ) bersama jajaran dinas terkait pada hari Senin (22/02).</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Ini dana pembangunan dari prof DKI Jakarta senilai kurabg kebih 60 milyar untuk pemasangan site pel dengan panjang sekitar 4 km dan saya temukan masih ada yang bocor makanya harus di cari solusinya ,&quot; Ungkap Rahmat Effendi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Menurutnya di sisi kali malang juga akan di bangun taman di samping perbaikan penempatan panggung dan papan reklame.Kedepan jalan sisi selatan kalimalang akan menjadi solusi kemacetan jalan raya Noer Ali.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot; Sisinya kita bangun taman ,tata kota yang mendesain Pertamanan yang akan mengerjakan ,biar selaras dengan desain Kota ,&quot; tambahnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Pihaknya juga tidak menginginkan adanya pemasangan pagar di atas pembangunan pembatas kali yang baru selesai di kerjakan dinas Binamarga Tata Air.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot; Jangan di pasang pagar lagi ,karena akan jadi kumuh ,sudah mulai sepanduk di pasang di pagar imbasnya akan jelek estetika kota ,tamanya saja segera di bangun ,&quot; katanya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sementara Kepala Dinas Binamarga Tata Air Kota Bekasi Tri Adhianto mengatakan jika pemasangan pagar di lakukan ,karena sebelumnya sudah ada pagar tersebut dan merupakan aset kota.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot; Ya ada yang bocor dikit wajar lah ,nanti kita tambal dan masalah pagar ini kan aset jadi kita pasang lagi ,kedepan kita akan copot dan di pasang tempat lain ,&quot; Ungkap Tri.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Selain itu, di Jalan Ahmad Yani, Kota Bekasi, menggunakan jalan umum untuk parkir seperti taksi yang berada di pinggir jalan samping Mall Metropolitan, juga angkutan umum yang sembarangan berjajar menunggu penumpang depan mall yang mengakibatkan penyempitan badan jalan, bahkan memicu kemacetan arus lalu lintas.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kepala Dinas Perhubungan Kota Bekasi Yayan Yuliana mengatakan bakal memanggil pengelola mal untuk mempertanyakan ihwal penggunaan jalan umum tersebut sebagai tempat parkir. &quot;Akan disosialisasikan bahwa itu adalah jalan umum. Kami target, Kamis sudah tertib,&quot; ujar Yayan. (Bay/ndoet)</span></span></div>', 'images/20171004223544-2017-10-04post223534.jpg', NULL, NULL, 2411, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:21:00', '2016-11-15 05:21:00', NULL),
('eb3bb762-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dispenda Gelar Senam Pagi Setiap Jumat', 'dispenda-gelar-senam-pagi-setiap-jumat', '&nbsp;\r\n\r\n&ldquo;Kegiatan senam bersama yang dilakukan di area parkir kantor Dispenda ini bertujuan untuk mempererat persatuan dan kesatuan serta &nbsp;menggairahkan minat berolahragasekaligus menyada', '<div font-family:=\"\" font-size:=\"\" span=\"\"><span 3-3-2014.=\"\" aan=\"\" aparatur=\"\" area=\"\" bekasi=\"\" bersama=\"\" daerah=\"\" dalam=\"\" dan=\"\" dari=\"\" dengan=\"\" di=\"\" diikuti=\"\" dilaksanakan=\"\" dinas=\"\" dispenda=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jumat=\"\" kabid=\"\" kantor=\"\" kasubid=\"\" kebersamaan=\"\" kebugaran=\"\" kegiatan=\"\" kepala=\"\" kota=\"\" menjadwalkan=\"\" menjaga=\"\" menjalin=\"\" mulai=\"\" oleh=\"\" pagi=\"\" parkir=\"\" pendapatan=\"\" rangka=\"\" seluruh=\"\" senam=\"\" serta=\"\" setiap=\"\" staf=\"\" yang=\"\">&nbsp;</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\"><span 3-3-2014.=\"\" aan=\"\" aparatur=\"\" area=\"\" bekasi=\"\" bersama=\"\" daerah=\"\" dalam=\"\" dan=\"\" dari=\"\" dengan=\"\" di=\"\" diikuti=\"\" dilaksanakan=\"\" dinas=\"\" dispenda=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jumat=\"\" kabid=\"\" kantor=\"\" kasubid=\"\" kebersamaan=\"\" kebugaran=\"\" kegiatan=\"\" kepala=\"\" kota=\"\" menjadwalkan=\"\" menjaga=\"\" menjalin=\"\" mulai=\"\" oleh=\"\" pagi=\"\" parkir=\"\" pendapatan=\"\" rangka=\"\" seluruh=\"\" senam=\"\" serta=\"\" setiap=\"\" staf=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&ldquo;Kegiatan senam bersama yang dilakukan di area parkir kantor Dispenda ini bertujuan untuk mempererat persatuan dan kesatuan serta &nbsp;menggairahkan minat berolahragasekaligus menyadarkan kepada para aparatur agar mengerti pentingnya arti kesehatan jasmani, sebab kita memerlukan kesehatan jasmani dan rohani&quot;, ujar Kepala Dinas Pendapatan, Aaan Suhanda, ditemui usai melaksanakan senam bersama di Kantornya,Jumat(28/02).</span></span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot; untuk mendapatkan kesehatan rohani,maka perlu menyehatkan jasmani dulu , agar aktivitas dalam bekerja dapat berjalan dengan baik&quot;, katanya,.&nbsp;</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Sementara itu, Trisnawati , salah satu aparatur Dispenda menyambut baik kegiatan yang akan dilaksanaka rutin setiap jumat ini. Dirinya mengaku sangat jarang melakukan olahraga setelah sampai di rumah&quot;, katanya. (yas/rdn/foto:yas).</span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2118, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:28:00', '2016-11-15 05:28:00', NULL),
('eb3bb7f7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '2017 ,Walikota Bekasi Akan Berikan Insentif Bagi Veteran', '2017-walikota-bekasi-akan-berikan-insentif-bagi-veteran', 'Kota Bekasi (10/11)-Walikota Bekasi Dr. Rahmat Effendi menjanjikan pemberian insentif bagi para veteran kemerdekaan yang tinggal di wilayahnya mulai 2017.&nbsp; &nbsp;&quot;Hal ini dilakukan sebagai b', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span color:=\"\" font-family:=\"\" span=\"\">Kota Bekasi (10/11)-Walikota Bekasi Dr. Rahmat Effendi menjanjikan pemberian insentif bagi para veteran kemerdekaan yang tinggal di wilayahnya mulai 2017.&nbsp; &nbsp;&quot;Hal ini dilakukan sebagai bentuk perhatian dari pemerintah daerah atas jasa-jasa pahlawan kemerdekaan&quot;kata Walikota Bekasi tersebut.</span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span color:=\"\" font-family:=\"\" span=\"\">Menurut Rahmat Effendi &nbsp;pihaknya akan memberikan insentif sebesar Rp1 juta pada masing-masing warga yang berstatus sebagai mantan pejuang kemerdekaan di Kota Bekasi.</span><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Ketua RT saja kita kasih, hansip, kader Posyandu pun diberikan insentif, maka digaribawahi veteran pun akan kita berikan insentif.Akan kita ajukan dalam pembahasan APBD 2017, Dinsos pun akan mendata jumlah veteran yang ada di Kota Bekasi,&quot; Jelas Walikota Bekasi .</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp; &nbsp; Terkait rencana ini, Kepala Dinas Sosial (Dinsos) Kota Bekasi, Junaedi mengatakan pihaknya akan segera mendata jumlah veteran yang tinggal di wilayahnya.&nbsp;&nbsp;&quot;Selama ini seluruh veteran yang ada di Kota Bekasi memiliki kantor sekretariat di daerah Jatiasih&quot;katanya.Mendata veteran di Kota Bekasi, kata dia, tidaklah sulit, sebab selain mereka punya wadah, para veteran juga memegang Surat Keputuasan (SK) yang menyatakan dirinya adalah seorang pahlawan. &quot;Meskipun pangkatnya rendah sekelas kopral sekalipun tetap akan kita berikan insentifnya,&quot; jelas Kadinsos.(Dimz).</span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2407, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 05:34:00', '2016-11-15 05:34:00', NULL),
('eb3bb88b-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pemerintah Kota Bekasi Menerima Tim Monev Ki Jabar', 'pemerintah-kota-bekasi-menerima-tim-monev-ki-jabar', 'Bekasi, -- Pemerintah Kota&nbsp; Bekasi menerima Tim Monitoring dan Evaluasi (Monev) Komisi Informasi (KI) Provinsi Jawa Barat bertempat di Pressroom Bagian Humas Setda Kota Bekasi Senin (10/10).\r\n\r\n&', '<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Bekasi, -- Pemerintah Kota&nbsp; Bekasi menerima Tim Monitoring dan Evaluasi (Monev) Komisi Informasi (KI) Provinsi Jawa Barat bertempat di Pressroom Bagian Humas Setda Kota Bekasi Senin (10/10).</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Tim Menov KI Jabar yang terdiri dari 3 orang ini diterima Kepala Bagian Humas Dr. H. MHD Jufri dan Teti Handayani, S.IP Kasubag Eksternal Bagian Humas.</p>\r\n\r\n<p 0px=\"\" br=\"\" color:=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" text-align:=\"\">Dalam sambutannya Kabag Humas MHD Jufri mengatakan koordinasi antar PPID SKPD Kota Bekasi dilakukan melalui aplikasi Whats App. Laporan kinerja pemerintahan yang dilakukan secara online dengan aplikasi SIKEPO real time setiap hari. Aplikasi ini tersedia atas kerjasama Tim dari Bagian Telematika Setda Kota Bekasi.&nbsp;<br br=\"\" />\r\nKata dia, semua laporan yang ada tambahnya baik WA dan Sikepo ditampilkan pada layar televisi yang ada di media center Kota Bekasi. Dengan kemudahan tampilan laporan kinerja ini diharapkan rekan media dapat mengakses dan melihat kegiatan yang dilakukan SKPD untuk menjadi bahan berita.<br br=\"\" />\r\n&quot;PPID di Pemkot Bekasi tersebar disemua SKPD, masing-masing SKPD mempunyai PPID tersendiri sehingga SKPD dapat memberikan pelayanan Informasi langsung kepada masyarakat dan LSM,&quot; imbuhnya.<br br=\"\" />\r\nDimas, salah satu anggota TIM Monev menyampaikan bahwa kegiatan ini bertujuan untuk mengukur akuntabilitas dalam bentuk pemetaan penerapan UU KIP, meningkatan kualitas program kegiatan yang dibuat pada badan publik masing-masing dan stimulant bagi PPID kabupaten atau kota untuk dapat saling bekerjasama dalam melakukan implementasi UU KIP<br br=\"\" />\r\nDalam kegiatan ini tambahnya tim Monev KI Jabar tidak bermaksud melakukan sidak melainkan hanya ingin tahu bagaimana KIP Pemkot Bekasi. Dan dari hasil penilaian sementara Pemkot Bekasi masuk kedalam 15 besar daerah yang dikunjungi oleh tim monev KI Jabar.<br br=\"\" />\r\nSeusai Monev dilakukan Teti Handayani, S.IP Kasubag Hubungan Ekaternal Bagian Humas mengatakan,&quot; Kami telah menunjukkan apa yang kami miliki, baik sarana dan pasarana atau regulasi dalam mendukung implementasi UU KIP ini.&quot;<br br=\"\" />\r\nSelain di Bagian Humas, Lanjut Teti, TIM Monev juga mengunjungi PPID di Badan Perencanaan Pembangunan Daerah (Bappeda) Kota Bekasi mengingat tema yang diusung pada Monev kali ini adalah Perencanaan Pembangunan.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&lt;p dir=&quot;ltr&quot; border-box;=&quot;&quot; margin:=&quot;&quot; 0px=&quot;&quot; 10px;=&quot;&quot; text-align:=&quot;&quot; justify;=&quot;&quot; font-size:=&quot;&quot; 12.8px;=&quot;&quot; line-height:=&quot;&quot; 22px;=&quot;&quot; color:=&quot;&quot; rgb(34,=&quot;&quot; 34,=&quot;&quot; 34);=&quot;&quot; font-family:=&quot;&quot; arial,=&quot;&quot; sans-serif;&quot;=&quot;&quot;&gt;Tim lalu melihat bagaimana Bappeda Kota Bekasi menyampaikan informasi kepada masyarakat tentang perencanaan pembangunan di Kota Bekasi. (azza/gie)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 5641, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:13:00', '2016-11-15 09:13:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bb918-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sekda Kota Bekasi Ingatkan Pejabat Tingkatkan Kinerja', 'sekda-kota-bekasi-ingatkan-pejabat-tingkatkan-kinerja-2', 'Kota Bekasi, --&nbsp;Sekretaris Daerah Kota Bekasi Drs Rayendra Sukarmadji melantik dan mengambil sumpah sejumlah pejabat eselon III dan IV dalam jabatan baru, Jumat, (4/11) di Aula Nonon Sontanie, Ka', '<p border-box=\"\">Kota Bekasi, --&nbsp;<span border-box=\"\">Sekretaris Daerah Kota Bekasi Drs Rayendra Sukarmadji melantik dan mengambil sumpah sejumlah pejabat eselon III dan IV dalam jabatan baru, Jumat, (4/11) di Aula Nonon Sontanie, Kantor Walikota Bekasi.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">Saat itu sebanyak 42 pejabat terdiri dari 7 pejabat eselon III dan 35 Eselon IV diambil sumpah termasuk beberapa staf yang mendapatkan promosi jabatan.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Sekda Kota Bekasi Rayendra mengatakan rotasi dan mutasi menjadi hal yang biasa didalam organisasi. Terutama&nbsp;guna memaksimalkan roda pemerintahan diantaranya melalui penempatan jabatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dalam pelantikan kali ini ia menegaskan pejabat Kota Bekasi harus meningkat kinerjanya. Bahkan ia tidak segan-segan merotasi kembali pejabat yang baru dilantik bila tidak berkinerja baik.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Ada laporan tidak mampu bekerja, pejabat bisa kita rotasi kembali. Pa Wali dan Pa Wakil akan memberikan reward dan punishment kepada pejabat atas kinerjanya selama ini,&quot; ungkap Rayendra.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Bila dibutuhkan untuk kepentingan organisasi akan terus dilakukan perputaran. Seperti kemarin kita lakukan rotasi pejabat bagi eselon II dan III,&quot; lanjutnya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Namun ia pun mengapresiasi sejumlah pejabat yang mengantarkan Kota Bekasi mampu beprestasi di tingkat Jawa Barat dan Nasional. Dan ia mengungkapkan perlu diberikan reward bagi para pejabat tersebut berupa kenaikan jabatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Selaku Baperjakat, dan Pimpinan daerah, kami akan apresiasi berupa reward bagi mereka,&quot; kata Rayendra.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Ia pun mengatakan seiring rencana perubahan kelembagaan organisasi di 2017 , sangat memungkinkan akan kembali dilakukan rotasi dan mutasi pejabat dilingkungan Pemkot Bekasi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Yang baru dilantik, mungkin tidak lama akan dilantik kembali. Ini karena SKPD akan bertambah dan berubah. Seperti pada Dinas Kebersihan, DP3JU, Tata Kota dan dinas lainnya. Sosialisasi perubahan kelembagaan juga akan kita lakukan,&quot; kata Sekda Kota Bekasi Rayendra. (goeng)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3289, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:18:00', '2016-11-15 09:18:00', NULL),
('eb3bb9b5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Mendukung Raih Adipura, BPLH Berikan Mesin Olah Sampah Kepada RW 12 Bekasi Jaya', 'mendukung-raih-adipura-bplh-berikan-mesin-olah-sampah-kepada-rw-12-bekasi-jaya', 'Kota Bekasi --&nbsp;Sebagai bentuk dukungan atas aksi kepedulian lingkungan warga RW 12 Bekasi Jaya Kecamatan Bekasi Timur, Pemkot Bekasi memberikan bantuan alat pengolahan sampah dan komposting.\r\n\r\nB', '<p border-box=\"\">Kota Bekasi --&nbsp;<span border-box=\"\">Sebagai bentuk dukungan atas aksi kepedulian lingkungan warga RW 12 Bekasi Jaya Kecamatan Bekasi Timur, Pemkot Bekasi memberikan bantuan alat pengolahan sampah dan komposting.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Bertempat di halaman kantor kelutahan Bekasi Jaya, Kepala Badan Pengelolaan Lingkungan Hidup (BPLH) menyerahkan satu unit mesin pengolah kompos dan tong komposter kepada&nbsp; RW 12 Kelurahan Bekasi Jaya, Selasa, (4/10).</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">&quot;Ini adalah kita menfasilitasi sarana prasarana pengelolaan sampah, karena pengelolaan sampah ini mempunyai bobot yang sangat tinggi dalam penilaian Adipura. Dan sekarang kita terus dapat dukungan warga,&quot;kata Kepala Badan Pengelolaan Lingkungan Hidup (BPLH), Supandi Budiman.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Menurut Supandi,ini adalah suatu bentuk keseriusan Pemerintah Kota Bekasi mengatasi problemmatika sampah dengan menggerakan swadaya masyarakat. Termasuk dengan pemenuhan sarana dan prasarana pengelolaan dan pemilahan sampah yang diberikan ke warganya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Mudah mudahan dengan pemberian ini akan membawa manfaat,sehingga pengolahan sampah dikecamatan Bekasi Timur bisa menjadi efektif dan mempunyai nilai Adipura yang tinggi. Sehingga mempunyai azas manfaat bagi warga masyarakat sekitar,&quot; kata Supandi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Sementara itu Lurah Bekasi Jaya,Muhamad AR mengatakan terimakasih kepada Dinas BPLH Kota Bekasi yang telah memberikan mesin Komposting kepada RW 12.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Menurut AR,bank sampah di RW 12 Kelurahan Bekasi Jaya,menjadi adalan Kecamatan Bekasi Timur karena telah berdiri gedung bank sampah di RW 12. Namun kondisinya pasca terbakar perlu segera diperbaiki.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Nah dengan adanya bantuan mesin kompos dari BPLH&nbsp; bisa menambah semangat lagi warga RW 12 untuk memilah dan mengolahsampah. Kita harap kantor bank sampah segera diperbaiki ,&quot; ucap lurah Bekasi Jaya Muhamad AR. (Sapta/goeng)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3416, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:22:00', '2016-11-15 09:22:00', NULL),
('eb3bba4a-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Program Saba Kampung Dilakukan Unsur 3 Pilar Kecamatan Bekasi Barat', 'program-saba-kampung-dilakukan-unsur-3-pilar-kecamatan-bekasi-barat', 'Kota Bekasi --&nbsp;Camat Bekasi Barat,M Bunyamin didampingi Lurah Kranji Andi Kristanto mengadakan kegiatan Saba Kampung di wilayah Kelurahan Kranji,Jumat (7/10/2016).\r\n\r\n&quot;Kegiatan ini kita laku', '<p border-box=\"\">Kota Bekasi --&nbsp;<span border-box=\"\">Camat Bekasi Barat,M Bunyamin didampingi Lurah Kranji Andi Kristanto mengadakan kegiatan Saba Kampung di wilayah Kelurahan Kranji,Jumat (7/10/2016).</span></p>\r\n\r\n<p><span 14px=\"\">&quot;Kegiatan ini kita lakukan agar warga masyarakat dapat mengenal Camat,Lurah,Kapolsek dan Danramilnya.Selain itu pun kita bisa menditeksi warga mulai dari yang miskin sampai yang susah sama sama kita membangun Kota Bekasi khususnya wilayah Kelurahan Kranji,Kecamatan Bekasi Barat.&quot; Ungkap Camat Bekasi Barat M Bunyamin.</span></p>\r\n\r\n<div border-box=\"\" class=\"ii gt adP adO\" id=\":lz\">\r\n<div border-box=\"\" class=\"a3s aXjCH m1579f10f0c20f820\" id=\":ov\">\r\n<p border-box=\"\" dir=\"ltr\">Jadi dengan kegiatan ini kita secara tidak langsung melihat secara langsung jalan dan saluran yang rusak,nanti saat musrenbang kita sudah tahu jalan dan saluran mana yang perlu diperbaiki,dan juga gunanya Saba Kampung ini secara tidak langsung kita dapat dekat warga masyarakat serta memudahkan warga masyarakat menyampaikan aspirasi dan keluhan kepada Camat,Lurah, Kapolsek dan Danramil secara langsung,katanya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Sementara itu dilokasi yang sama Lurah Kranji Andi Kristanto mengatakan Saba Kampung ini adalah program baru diKecamatan Bekasi Barat ini merupakan sinergisitas kinerja aparatur bersama Tiga Pilar dan unsur masyarakat.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Kegiatan ini juga untuk mengevaluasi dan menggali potensi solusi permasalahan yang ada diwilayah Kelurahan Kranji,dengan seperti ini bukan hanya administrasi saja akan tetapi kita bisa mengetahui keluhan keluhan masyarakat secara langsung dan bukan hanya mendengar saja.Akan tetapi kita harus bisa menunjukan kerja yang baik sebagai aparatur serta sebagai pelayan warga masyarakat.&quot;pungkasnya.(Sapta/<wbr border-box=\"\" />goeng)</p>\r\n</div>\r\n</div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3104, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:23:00', '2016-11-15 09:23:00', NULL),
('eb3bbad7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Tantangan Humas Di Era Teknologi Informasi Dalam Mengamankan Kebijakan Pemerintah', 'tantangan-humas-di-era-teknologi-informasi-dalam-mengamankan-kebijakan-pemerintah', 'Kota Bekasi - asda 3, dadang hidayah membuka kegiatan pertemuan Badan Koordinasi Kehumasan &nbsp; &nbsp;Daerah (Bakohumasda) Kota Bekasi yang digelar di Islamic centre, Selasa ( 04/10).\r\n\r\nPertemuan i', '<p border-box=\"\">Kota Bekasi - asda 3, dadang hidayah membuka kegiatan pertemuan Badan Koordinasi Kehumasan &nbsp; &nbsp;Daerah (Bakohumasda) Kota Bekasi yang digelar di Islamic centre, Selasa ( 04/10).</p>\r\n\r\n<p><span muli=\"\">Pertemuan ini dihadiri para sekretaris SKPD, Sekretaris Kecamatan, humas BUMD se-Kota Bekasi, Humas perguruan tinggi Bekasi, Humas dari unsur Musyawarah Pimpinan Daerah (Muspida) Kota Bekasi, dan perwakilan media penyiaran. Pertemuan kehumasan daerah ini mengusung tema &quot;Tantangan humas di era teknologi informasi dalam mengamankan kebijakan informasi&quot;.</span></p>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">Dalam sambutannya. Asisten Administrasi Umum. Dadang hidayat.Mengatakan, peran bakohumasda dinilai penting menjadi penyampai berbagai kebijakan pemerintah daerah di berbagai bidang. Terlebih dgn adanya UU KIP no 14 TH 2008. Didalam undang-undang tersebut juga dikeluarkan dalam rangka mendorong terjadinya reformasi penyelenggaraan pemerintahan ke arah yang lebih transparan, akuntabel, partisipatif, efektif, dan efisien dan sesuai hukum sehingga tiap kebijakan akan mudah diakses dan diawasi publik.&nbsp;</div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">&quot;Humas harus menjadi corong atau juru bicara pemerintah ,mengkomunikasikan segala yang berkenaan dengan pelaksanaan pemerintahan, pembangunan dan pelayanan kepada masyarakat. &nbsp;saya melihat sering terjadi pemberitaan yang tidak baik dikarenakan masih sulitnya mendapatkan informasi yang benar dari PPID instansi terkait&quot;, ucapnya.</div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">Salah satu media yang harus digunakan melalui website. Disitu kita dapat menyampaikan informasi-informasi apa yang diperlukan masyarakat. Karena ini merupakan komitmen perintah didalam trannsparasi dan akuntabitlitas dmi penyelenggaraan pemerintah yang Baik.&nbsp;</div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">Dalam kegiatan ini dihadiri nara sumber dari tenaga Ahli Kementrian KOMINFO RI. KPU. Kantor pajak.&nbsp;</div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">Berapa pertanyaann disampaikan kepada nara sumber. Salah satunya dari dinkes terkait bagaimana menghadapi isu -isu &nbsp;yang menyudutkan.(yas)</div>', 'images/20170823081723-2017-08-23post081712.jpg', NULL, NULL, 1227, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-15 09:25:00', '2016-11-15 09:25:00', NULL),
('eb3bbb66-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'HKN 2016, Walikota Bekasi Imbau Warga Terapkan Perilaku Hidup Bersih dan Sehat', 'hkn-2016-walikota-bekasi-imbau-warga-terapkan-perilaku-hidup-bersih-dan-sehat', 'Kota Bekasi - Walikota Bekasi Dr.Rahmat Effendi menjadi inspektur upacara pada peringatan Hari Kesehatan Nasional tingkat Kota Bekasi tahun 2016, Senin, (14/11) di Plasa Kantor Walikota Bekasi Jalan A', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Walikota Bekasi Dr.Rahmat Effendi menjadi inspektur upacara pada peringatan Hari Kesehatan Nasional tingkat Kota Bekasi tahun 2016, Senin, (14/11) di Plasa Kantor Walikota Bekasi Jalan Ahmad Yani.</span>&nbsp;</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi menyampaikan sambutan Menteri Kesehatan RI Nila Farid Moeloek di depan para peserta upacara. Pesan yang disampaikan diantaranya mengenai pentingnya menjaga kesehatan dengan m<span border-box=\"\" class=\"text_exposed_show\">enjaga prilaku hidup bersih dan sehat di masyarakat.</span></span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\" class=\"text_exposed_show\">\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Seringkali masyarakat baru menyadari arti penting kesehatan saat penyakit datang mengancam,&quot; kata Walikota Bekasi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Lanjut dia, kesehatan merupakan investasi sebuah aset yang bernilai tinggi. Setiap orang berhak atas kesehatan tapi juga berkewajiban untuk berperilaku sehat guna mempertahankan derajat kesehatan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Untuk itu, beliau pun berharap warga masyarakat Kota Bekasi selalu menjaga kebugaran dengan berolahraga. Mengenai kebijakan bidang kesehatan dasar masyarakat ia menegaskan kepada Badan Perencanaan Pembangunan Daerah (Bappeda) Kota Bekasi dan Dinkes untuk mempersiapkan operasional semua pusat kesehatan masyarakat (Puskesmas) di 56 kelurahan yang ada.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Peningkatan puskesmas yang masih memiliki lahan untuk dibangun puskesmas rawat inap. Dan khusus di Puskes Bantar gebang semuanya menjadi puskesmas rawat inap dan ditingkatkan menjadi RS tipe D terletak di sebelah kantor kecamatan,&quot; kata Rahmat Effendi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi juga menjelaskan pada tahun 2017, untuk kartu bekasi sehat akan dipermudah jika ada yang sakit bagi warga yang kurang mampu hanya menyerahkan Kartu Keluarga saja. Hal ini mempermudah warga bila belum memakai Surat keterangan tidak mampu (SKTM) maupun anggota program kesehatan dari pemerintah pusat.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Terhitung 1 januari 2017, Pemkot Bekasi mempercepat pelayanan kesehatan bagi warga masyarakat tidak mampu dan mereka hanya membawa KK tanpa perlu berbelit dengan surat keterangan kesehatan. Cukup dengan KK saja bisa masuk rumah sakit umum maupun swasta,&quot; pungkasnya. (goeng/foto:ndoet/ronz)</span>&nbsp;</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3565, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:39:00', '2016-11-16 02:39:00', NULL),
('eb3bbc12-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ahmad Syaikhu Hadiri Pelantikan FKPAI Kota Bekasi', 'wawali-ahmad-syaikhu-hadiri-pelantikan-fkpai-kota-bekasi', 'Wawali Ahmad Syaikhu Hadiri Pelantikan FKPAI Kota Bekasi&nbsp;', 'Wawali Ahmad Syaikhu Hadiri Pelantikan FKPAI Kota Bekasi&nbsp;', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3790, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:47:00', '2016-11-16 02:47:00', NULL),
('eb3bbcc3-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Bekasi Lantik Majelis Umat Beragama (MUB) Kelurahan Se-Kota Bekasi', 'walikota-bekasi-lantik-majelis-umat-beragama-mub-kelurahan-se-kota-bekasi', 'Kota Bekasi - Walikota Bekasi, Dr.Rahmat Effendi hadir dan melantik Majelis Umat Beragama (MUB) Kelurahan se-Kota Bekasi pada hari Senin, (14/11) di Toton Baho, Kecamatan Bekasi Selatan bersama Ketua ', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Walikota Bekasi, Dr.Rahmat Effendi hadir dan melantik Majelis Umat Beragama (MUB) Kelurahan se-Kota Bekasi pada hari Senin, (14/11) di Toton Baho, Kecamatan Bekasi Selatan bersama Ketua Forum Kerukunan Umat Beragama (FKUB) Kota Bekasi, H. Abdul Manan dan segenap Camat se-Kota Bekasi dan Lurah Ss-Kota Bekasi.</span>&nbsp;</span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\" id=\"id_582a9b39c08fc5859935689\">\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">12 Ketua Majelis Umat Beragama tiap Kecamatan yang telah rampung, kini pemerintah Kota Bekasi memiliki 56 Ketua MUB Kelurahan se-Kota Bekasi dan telah dilantik, dari tiap-tiap agama yang ada di Kota Bekasi hadir perwakilan dan masuk dalam bagian Majelis Umat Beragama.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi usai melantik, dalam sambutannya mengucapkan selamat kepada para Ketua yang telah dilantik, dan walau ada ragam agama, budaya, suku harus tetap bersatu, tetap dalam bhineka tunggal ika, dan menjadikan Kota Bekasi sebagai miniatur kerukunan umat beragama di Indonesia.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dahulu, Kota Bekasi lebih menjadi mayoritas umat muslim namun kini Kota Bekasi seiring waktu berjalan warga Kota Bekasi terus berkembang sesuai perkembangan era, agama pun juga pemeluknya juga bertambah seperti nasrani, budha, hindu dann sebagainya. Maka dari itu, kini terbentuklah Forum Kerukunan Umat Beragama (FKUB) dalam wilayah Kota Bekasi, dan di bawahnya berdiri Majelis Umat Beragama di tiap-tiap Kecamatan yang telah rampung, lalu berjalan ke tingkat lebih rendah yakni terbentuknya Majelis Umat Beragama di tiap Kelurahan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Bekerja tidak boleh setengah-setengah, jika boleh di tingkat RW juga jika bisa kita bentuk MUB ini, sehingga jika ada permasalahan baik dari segi agama tetap ada yang mengurus&quot;, ujar Walikota Bekasi disela-sela wawancara.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi tidak hanya hadir dalam peresmian-peresmian Masjid saja dan memikirkan untuk agama muslim saja, dalam bentuk keharmonisan umat beragama selaku Kepala Daerah, ia juga hadir dalam pembentukan pengurus di Gereja-Gereja di Kota Bekasi, di Klenteng milik agama Budha, dan tempat ibadat agama Hindu yang ada di Kota Bekasi sehingga perbedaan bisa adil di tiap-tiap agamanya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Pembangunan juga di rencanakan baik dari rumah ibadah, infrastruktur jalan, bahkan bagi pengurus rumah ibadah juga tetap di rencanakan mengenai anggarannya, contohnya sebelumnya pada saat anggaran mengenai sarana anggaran Marbot Masjid telah dianggarkan akan tetapi dari BPK RI Jawa Barat tidak mengijinkan, namun pada tahun 2017 akan direncanakan kembali dengan anggaran pengurus Ruma ibadah di Kota Bekasi termasuk Nasrani dan lainnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Terbentuknya Majelis Umat Beragama sampai tingkat Kelurahan agar menjadi satu tampungan permasalahan-permasalahan terkait agama yang ada di wilayah masing- masing, sehingga keharmonisan akan tetap terjaga di Kota Bekasi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Saya tekankan kembali, tidak ada kaum mayoritas minoritas, perbedaan agama, ras, suki, budaya, semua sama menjadi Warga Kota Bekasi&quot;, &nbsp;tegas Rahmat Effendi. (ndoet/ronz)&nbsp;</span></span></div>\r\n</div>\r\n</div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2638, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:50:00', '2016-11-16 02:50:00', NULL),
('eb3bbd8d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Puluhan Ribu Umat Islam Padati Stadion Candrabhaga Ikuti Penutupan OPQ', 'puluhan-ribu-umat-islam-padati-stadion-candrabhaga-ikuti-penutupan-opq', 'Bekasi Selatan - Puluhan ribu umat Islam hadiri puncak acara Olimpiade Pecinta Al-Quran (OPQ) yang diselenggarakan oleh Komunitas One Day One Juz (ODOJ) di Stadion Patriot Candrabhaga, Bekasi Selatan,', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">Bekasi Selatan - Puluhan ribu umat Islam hadiri puncak acara Olimpiade Pecinta Al-Quran (OPQ) yang diselenggarakan oleh Komunitas One Day One Juz (ODOJ) di Stadion Patriot Candrabhaga, Bekasi Selatan, Kota Bekasi, Minggu (13/11).</span>&nbsp;</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Acara puncak OPQ diakhiri dengan Tilawah Akbar dari ribuan peserta dan ditutup dengan konser amal dari band religi Wali Band serta aksi dari Komite Nasional Rakyat Palestina.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Disela&nbsp;kegiatan juga diisi taushiyah dari ustad Ahmad Al-Habsyi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\">\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Hadir dalam puncak penutupan OPQ, Gubernur Jawa Barat, Ahmad Haryawan, Gubernur NTB, Muhammad Zainul Majdi dan Tokoh Agama yang juga mantan Wakil Ketua MPR 2014, Muhammad Hidayat Nur Wahid.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dari pemerintah Kota Bekasi turut hadir diantaranya Wakil Walikota Bekasi, H.Ahmad Syaikhu, Sekretaris Daerah (Sekda), Drs.H.Rayendra Sukarmadji,MSi, Kepala Dinas Perhubungan Kota Bekasi, Yayan Yuliana, Kepala BPLH, Supandi Budiman, Kepala Bappeda, Jumhana Lutfi, Kasatpol PP, Cecep Suherlan, Kepala BKD, Reny Hendrawati dan Kepala Kesbangpol Kota Bekasi, Dinar Faisal.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Saat puncak acara penutupan OPQ dihadiri juga qori dan qoriah dari seluruh Indonesia. Selain itu, hadir juga Syaikh dari lima benua berbeda. Tampak memeriahkan puncak OPQ, qori asal Amerika Serikat (AS) keturunan Bosnia yaitu Fatih Seferagic.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Ketua Panitia OPQ, Bakat Setyaji mengatakan, penutupan ini diawali dengan pertunjukkan robot OPQ yang bisa membaca Al-Quran, juga ada ikrar 1000 pengajar Al-Quran.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&ldquo;Acara ini dimeriahkan dengan tilawah akbar 50.000 umat Islam, konser kemanusiaan oleh Band Wali, pertunjukkan robot ODOJ dan parade kontingen peserta lombaOPQ dari seluruh perwakilan ODOJ dari dalam dan luar negeri,&rdquo; katanya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dalam kesempatan tersebut, Wakil Walikota Bekasi, H.Ahmad Syaikhu berharap, dengan dilangsungkannya kegiatan ini bisa memotivasi masyarakat Kota Bekasi agar lebih dekat lagi terhadap Al- Quran.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&ldquo;Al- Quran sebagai sumber motivasi untuk melakukan ahlak ahlak yang baik,&rdquo; katanya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Lebih lanjut, Ahmad Syaikhu yang juga seorang ustad mengatakan, semakin kita dekat dengan Al &ndash; Quran, dan mampu memahaminya dengan sebaik-baiknya Insya Allah akan menjadi modal utama mengimplementasikan nilai-nilai quran.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Dengan memahami Al&ndash;Quran kita akan menjadi ahlak yang baik, dengan begitu kita akan mampu mewujudkan Kota Bekasi yang lebih harmonis,&rdquo; tandasnya. (tnc/goeng/ronz)&nbsp;</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 1884, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:52:00', '2016-11-16 02:52:00', NULL),
('eb3bbe55-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Silaturahmi Toga dan Tomas, Walikota berharap Jaga Keharmonisan Umat Beragama', 'silaturahmi-toga-dan-tomas-walikota-berharap-jaga-keharmonisan-umat-beragama', 'Kota Bekasi --- Walikota Bekasi, Dr. Rahmat Effendi bersama dari Unsur Muspida dari Kalpolerstro Bekasi Kota hadir WakaPolres, Unsur Kodim 05/07 yang diwakili oleh Kasdim, Kementerian Agama, dan Ketua', '<p border-box=\"\"><span border-box=\"\">Kota Bekasi --- Walikota Bekasi, Dr. Rahmat Effendi bersama dari Unsur Muspida dari Kalpolerstro Bekasi Kota hadir WakaPolres, Unsur Kodim 05/07 yang diwakili oleh Kasdim, Kementerian Agama, dan Ketua FKUB, H. Abdul Manan hadir dalam acara Silaturahmi dengan tokoh agama seKota Bekasi pada hari Rabu (26/10) di Griya Wulan Sari.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">Walikota dalam sambutannya mengatakan bahwa Melakukan proses penyelenggaraan dalam kerukunan beragama, tidak perlu takut masuk ke rumah ibadah lainnya, camat lurah sebagai kepala pemerintahan di wilayah harus bisa mengkoordinasikan warganya yang berbeda agama, suku, dan budaya. Tidak ada minoritas dan mayoritas di Kota Bekasi, semua sama warga Kota Bekasi.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Awalnya, Marbot Masjid telah di insentifkan dari anggaran Pemerintah Kota Bekasi namun terputus karena adanya persoalan audit Badan Pengawas Keuangan, akan tetapi Imam Masjid masih ada untuk insentifnya, akan tetapi&nbsp; yang nantinya akan dimasukan kembali dengan insentif nama pengurus rumah ibadah, yang didalamnya ada semua agama khusus pengelola rumah ibadah tersebut, Walikota menegaskan ke Kepala Bappeda yakin semua punya hak yang sama di 2018, hanya kemampuan keuangan daerah besar kecilnya penentuan insentifnya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Walikota juga mengapresiasikan kebentukan Majelis umat Beragama di tiap tiap Kecamatan yang telah dikukuhkan, yang nantinya akan masuk ke ranah Kelurahan dan terbentuk 56 Majelis Umat Beragama di Kelurahan masing masing.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Melalui FKUB yang hanya bisa sampai rana Kota, maka dibentuk Majelis Umat Beragama yang akan membantu peran FKUB dalam permasalahan permasalahan mengenai keagamaan, dan menjadi penyeimbang di daerah masing masing, sebelum lepas tahun 2016, MUB tingkat Kelurahan harus terbentuk&quot; ujar Walikota.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Duta Besar Indonesia di Vatikan melalui uskup Suharyo mengucapkan salam kenal dan terima kasih dari Kedutaan Besar Indonesia di Vatikan untuk Walikota Bekasi terkait kerukunan dan perhatian umat beragama di wilayah Kota Bekasi.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dalam Dialog antar Walikota Bekasi, Ust. Asep Basuni, menyarankan terkait FKUB dan peran dan perbedaan dari MUB, serta penambahan IT pada penggunaan Media sosial yang akan menyemarakkan bahwa Kota Bekasi menjadi miniatur kerukunan umat beragama sesuai harapan Walikota Bekasi, yang juga pernah menyemarakkan apel kerukunan umat beragama. (Ndoet)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 1881, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:53:00', '2016-11-16 02:53:00', NULL),
('eb3bbf14-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pengurus DPC Granat Kota Bekasi Dilantik', 'pengurus-dpc-granat-kota-bekasi-dilantik', 'Kota Bekasi, --&nbsp;Dewan Pimpinan Cabang Gerakan Nasional Anti Narkotika (Granat) Kota Bekasi periode 2016-2021 resmi dilantik, Sabtu, (22/10) di Pendopo Kantor Walikota Bekasi.\r\n\r\n&nbsp;\r\n\r\nImam Ma', '<p border-box=\"\">Kota Bekasi, --&nbsp;<span border-box=\"\">Dewan Pimpinan Cabang Gerakan Nasional Anti Narkotika (Granat) Kota Bekasi periode 2016-2021 resmi dilantik, Sabtu, (22/10) di Pendopo Kantor Walikota Bekasi.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\"><span border-box=\"\">Imam Maliki, Ketua DPC Granat Kota Bekasi bersama pengurus dilantik Ketua DPD Granat Provinsi Jawa Barat H Djoni Widjadja.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Pelantikan kali ini juga disaksikan Ketua Umum DPP Granat Henry Yosodiningrat, Wakapolres Metro Bekasi Kota AKBP Wijonarko, Kasdim 0507 Mayor Sali, Kepala Badan Kesbangpol Kota Bekasi Momon Sulaeman, Ketua dan pengurus&nbsp; Granat cabang Purwakarta, Bogor dan Karawang serta pengurus Forza Indonesia (Forum Pemuda Anti Napza) Kota Bekasi.&nbsp;</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Usai melantik Ketua Granat Jabar Djoni Widjadja mengatakan kepengurusan Granat Kota Bekasi harus lebih aktif bersama sejumlah elemen dan pemerintah memerangi bahaya narkoba.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Pengurus sekarang usai dilantik langsung bergerak untuk melaksanakan kegiatan. Jangan usai dilantik malah fakum. Jangan sampai terulang dan ini yang tidak kita harapkan,&quot; kata H Djoni.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Saat itu Djoni mengatakan pengurus sebelumnya belum maksimal melaksanakan tampuk organisasi dan bisa dikatakan Granat periode sebelumnya vakum dari kegiatan.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Ketua DPC Granat Kota Bekasi Imam Maliki mengucapkan dukungan pimpinan daerah dan pusat Granat sangat ia apresiasi. Dan jabatan yang ia emban memiliki tanggung jawab besar untuk pencegahan narkoba di Kota Bekasi. Ia juga meminta dukungan semua pihak dalam pelaksanaan tugasnya.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Ia mengatakan keinginannya bersama semua stakeholder seperti pemerintah untuk mewujudkan generasi penerus yang handal. Dan sekarang ini bahaya narkoba menjadi penghambat besar demi cita-cita bersama mencetak SDM unggul khususnya di Kota Bekasi.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Bagaiman generasi muda kedepan bila orang-orang baik memilih diam dan kalah sama orang jahat. Orang jahat perusak generasi muda sudah bergerak sejak lama.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Pemimpin besar kita adalah pemimpin yang mampu mewariskan generasi penerus yang handal. Ini sering kita lupakan, malah memikirkan perbedaan jaman dulu dan sekarang. Tantangan tiap zaman berbeda dan sekarang narkoba menjadi musuh kita bersama,&quot; kata Imam Maliki.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Dalam kesempatan itu, Wakapolrea AKBP Wijonarko mengapresiasi pengurus baru Granat Kota Bekasi. Dengan begitu akan banyak pihak membantu pihak kepolisian memerangi narkoba dan ancaman lainnya dimasyarakat.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Melalui pelantikan DPC Granat Kota Bekasi menjadi momentum perang tehadap penyalahgunaan narkoba di Kota Bekasi,&quot; ucap Wijonarko.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Menurutnya, banyaknya pengungkapan kasus narkoba menjadi keprihatinan bukan prestasi yang membanggakan bagi Polri. Ini menandakan banyak kasus narkoba mengancam kehidupan masyarakat.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Dan fenomena narkoba kata dia seperti puncak gunung es yang hanya terlihat di permukaannya saja. Jumlah personil dijajaran Polres Metro pun menurutnya jauh dari mencukupi untuk mengurus permasalahan Pekat (Penyakit Masyarakat) diantaranya kasus narkoba warga Kota Bekasi. Dengan jumlah penduduk Kota Bekasi sekarang sekitar 2,4 Juta Jiwa lebih.&nbsp;</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Kita butuh mitra strategis. Dan Laporkan indikasi penyebarluasan narkoba di wilayah. Akan kami tangani bersama instansi terkait,&quot; kata Wakapolres Metro Bekasi Kota Wijonarko.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Lanjut dia, jumlah personil Polresta Metro Bekasi Kota sebanyak 1713 personil dan 82 diantaranya dijajaran Satnarkoba. Dengan jumlah personil ini pihaknya ditahun 2016 memecahkan ratusan kasus narkoba dan mengamankan ratusan pelaku berikut barang bukti.&nbsp;</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Ia menyebutkan hingga periode Januari-Oktober 2016 sebanyak 325 kasus narkoba dengan mengamankan 355 pelaku dan 11 diantaranya berjenis kelamin perempuan.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Lanjut dia, kasus narkoba yang diungkap paling banyak dari peredaran jenis Sabu-Sabu dengan 216 kasus, disusul jenis ganja 103 kasus dan sisanya dari jenis narkoba lainnya.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Demi memerangi penyebarluasan dan penyalahgunaan narkoba ia mengimbau kepada orang tua warga Kota Bekasi untuk lebih mengawasi anak-anaknya dari aktifitas merugikan seperti merokok. Merokok menurutnya menjadi pintu gerbang masuknya narkoba.</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Narkoba biasanya berawal dari kebiasaan merokok. Saya ingatkan para orang tua pehatikan anak-anak dari kebiasaan merokok. Abis merokok ingin mencoba yang lain. Kecenderungannya demikian,&quot; kata AKPB Wijonarko.&nbsp;</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">Diakhir sambutanya, di Jajaran intern Kepolisian komitmen memberantas narkoba juga terus digalakkan. Terbukti bila ada anggota terkait kasus narkoba pihaknya tidak segan untuk memberhentikan dengan tidak hormat.&nbsp;</span><br border-box=\"\" />\r\n<br border-box=\"\" />\r\n<span border-box=\"\">&quot;Tida ada tolerasi bagi siapa saja yang tertangkap terkait narkoba bahkan termasuk dalam jajaran polisi sendiri. Kita sudah membuat pakta integritas untuk seluruh anggota Polres. Bila terbukti, siap di PDTH (Pemberhentian dengan tidak hormat),&quot; pungkas Wakapolres Metro Bekasi Kota AKBP Wijonarko. (goeng)</span></p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3472, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:55:00', '2016-11-16 02:55:00', NULL),
('eb3bc001-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Hadir di Pelantikan LPM Teluk Pucung, Walikota : \"Aparatur malas, akan ditindak tegas diberhentikan\"', 'hadir-di-pelantikan-lpm-teluk-pucung-walikota-aparatur-malas-akan-ditindak-tegas-diberhentikan', 'Kota Bekasi - Usai ke acara apel akbar Hari Santri Nasional, Walikota Bekasi, Dr. Rahmat Effendi melanjutkan acara ke Pelantikan Pengurus Lembaga Pemberdayaan Masyarakat (LPM) Kelurahan Teluk Pucung, ', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Usai ke acara apel akbar Hari Santri Nasional, Walikota Bekasi, Dr. Rahmat Effendi melanjutkan acara ke Pelantikan Pengurus Lembaga Pemberdayaan Masyarakat (LPM) Kelurahan Teluk Pucung, Kecamatan Bekasi Utara pada hari Sabtu, (22/10), pelantikan di serahkan oleh Sekretaris Kecamatan, Heriyanto.</span></span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Pelantikan pengurus LPM Kelurahan Teluk Pucung ini berlangsung secara lancar, Ketua Terpilih periode 2016 - 2021, Sulistiadi mengucapkan terima kasih atas kedatangan Walikota Bekasi yang menjadi semangat awal dalam kinerja pembentukan LPM di Kelurahan Teluk Pucung ini, dan akan siap bekerja dengan penuh tanggung jawab terhadap komitmen yang telah diberikan termasuk anggaran dana pemerintah kota yang telah mengucur untuk keperluan pembangunan wilayah Teluk Pucung.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota Bekasi dalam sambutannya, mengutarakan bahwa LPM menjadi salah satu faktor penentu kemajuan Pemerintah melalui Kelurahan masing masing, juga dibantu oleh P3BK yang selalu berkoordinasi dengan LPM termasuk masukan Musyawarah Pembangunan berpotensi untuk pembangunan di daerahnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Selalu berkoordinasi dengan Lurah, Camat dan dibantu Oleh P3BK agar masukan masyarakat, pembangunan jalan, saluran, program Rumah Tidak Layak Huni (Rutilahu) berjalan sesuai rencana.&quot; ujar Walikota.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota juga tetap mengingatkan, bahwa Kota Bekasi sudah berkembang dengan pesat, tidak ada lagi kaim minoritas mayoritas, perbedaan agama ras suku dan budaya, semua sama menjadi warga Kota Bekasi yang peduli dalam perkembangan daerahnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Walikota menegaskan kepada masyarakat bahwa nanti rencana pada tahun 2017, warga yang mempunyai penghasilan dibawah rata rata akan tidak perlu lagi sulit jika ada yang sakit, karena pihak RSUD maupun rumah sakit swasta akan membuat perjanjian dengan Kartu Keluarga saja warga bisa masuk ke Rumah sakit manapun, asal sesuai dengan kriterianya, untuk itu peran Lurah dan dibantu dengan LPM harus benar benar tepat sasaran dalam mendata warga yang benar benar tidak mampu.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Termasuk dalam masa kerja para Lurah, Camat, dan aparatur Pemerintah otta Bekasi jika bermalas malasan dalam bekerja, selaku Walikota Bekasi akan dengan mudah memberhentikan jabatan yang ada, warga membutuhkan pelayanan yang harus cepat dan sesuai target, tidak menyusahkan warga apalagi sampai bertele tele dalam pelayanan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Usai melihat proses pengukuhan, Walikita Bersama Sekretaris Kecamatan melihat prigram Rumah Tidak Layak Huni yang sedang dalam proses dibangun. (Ndoet)</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2654, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:56:00', '2016-11-16 02:56:00', NULL),
('eb3bc0dc-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '12 Kecamatan di Kota Bekasi Resmi Memiliki Majelis Umat Beragama.', '12-kecamatan-di-kota-bekasi-resmi-memiliki-majelis-umat-beragama', 'Kota Bekasi --- Hari ini 12 Kecamatan yang terdiri dari 56 Kelurahan di Kota Bekasi sudah memiliki Majelis Umat Beragama, setelah Kecamatan Medan Satria dan Bekasi Utara pada Rabu (19/10), siang tadi ', '<p border-box=\"\"><span border-box=\"\">Kota Bekasi --- Hari ini 12 Kecamatan yang terdiri dari 56 Kelurahan di Kota Bekasi sudah memiliki Majelis Umat Beragama, setelah Kecamatan Medan Satria dan Bekasi Utara pada Rabu (19/10), siang tadi Kamis (20/10), Walikota Bekasi, Dr. Rahmat Effendi juga mengukuhkan Majelis Umat Beragama Kecamatan Bekasi Selatan dan Kecamatan Bekasi Barat.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">Dengan 2,6 juta penduduk yang latar belakangnya heterogen baik dari segi suku maupun agama, Pemerintah Kota Bekasi berupaya keras mewujudkan kerukunan antarwarga.</span></p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Setelah dirintis melalui deklarasi pembentukan Forum Kerukunan Umat Beragama (FKUB) tahun 2012 dan dilanjutkan dengan apel akbar kerukunan umat beragama pada 16 April 2016, kini Kota Bekasi hampir merampungkan pembentukan Majelis Umat Beragama di 12 kecamatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Dua belas kecamatan sudah terbentuk majelis berikut susunan pengurusnya, sekarang dua kecamatan dikukuhkan Kamis yakni Bekasi Selatan dan Bekasi Barat,&quot; kata Walikota Bekasi Rahmat Effendi, usai pelantikan Majelis Umat Beragama Kecamatan Bekasi Selatan dan Bekasi Barat di Kantor Kecamatan Bekasi Selatan.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dijelaskan Rahmat, kehadiran majelis ini tidak terlepas dari keberadaan FKUB. Justru kehadiran majelis menjadi perpanjangan FKUB hingga tingkat kelurahan yang diharapkan bisa bersentuhan langsung dengan warga masyarakat.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;FKUB cakupannya kota, sedangkan majelis ranahnya kecamatan hingga kelurahan. Jadi, tetap bersinergi. FKUB mempunyai peranan menjaga kerukunan agama yang ada sedangkan majelis umat menjaga umat masing-masing agama dengan membimbing umat mereka menjaga nilai-nilai pluralisme yang diajarkan agama masing-masing,&quot; terangnya.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Peran majelis umat beragama tersebut yakni mewakili setiap agama yang diakui di Indonesia untuk terus menyampaikan pentingnya toleransi umat beragama serta menjunjung tinggi nilai Pancasila dengan semangat Bhineka Tunggal Ika.</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Kota Bekasi sekarang berbeda dengan dulu karena sangat heterogen. Mayoritas merupakan Muslim sebanyak dua juta penduduk, sedangkan pemeluk Katolik 65.000 orang, Budha 12.000 orang, Kristen Protestan 195.000 orang, Hindu 47.000 orang, dan Konghucu 196 orang. Kota Bekasi harus menjadi salah satu miniatur umat beragama, tidak ada lagi kaum minoritas atau mayoritas. Hak warga Kota Bekasi sama tidak dibeda-bedakan,&quot; ucap Rahmat. (Ndoet/ndi)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 7856, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:57:00', '2016-11-16 02:57:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bc1de-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kemen-PPPA Gelar Pelatihan Lansia Berkebun Organik di Kota Bekasi', 'kemen-pppa-gelar-pelatihan-lansia-berkebun-organik-di-kota-bekasi', 'Kemen Pemberdayaan Perempuan dan Perlindungan Anak (Kemen-PPA) menggelar pelatihan ini dan disuport Kelompok Petani Organik (KePo), Pusat Program Pelatihan Nasio, dan Posdaya Nasio.\r\n\r\nRatusan lansia ', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span 100=\"\" bekasi=\"\" berkebun=\"\" bumi=\"\" dahlia=\"\" di=\"\" div=\"\" ek=\"\" font-family:=\"\" font-size:=\"\" indah=\"\" jati=\"\" jatikramat=\"\" kecamatan=\"\" kelurahan=\"\" kota=\"\" lansia=\"\" melalui=\"\" mengikuti=\"\" nasio=\"\" pelatihan=\"\" pemberdayaan=\"\" pertanian=\"\" perumahan=\"\" program=\"\" rw=\"\" sebanyak=\"\" senja=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Kemen Pemberdayaan Perempuan dan Perlindungan Anak (Kemen-PPA) menggelar pelatihan ini dan disuport Kelompok Petani Organik (KePo), Pusat Program Pelatihan Nasio, dan Posdaya Nasio.</span></span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Ratusan lansia ini selama beberapa hari mengikuti pelatihan berkebun agar nantinya menghasilkan produk pertanian dan dapat mencukupi kebutuhan ekonomi keluarga dan pemenuhan gizi lansia itu sendiri.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Ketua Lansia Perumahan Nasio, Ratna mengaku senang mendapatkan pelatihan terutama berkaitan dengan program lingkungan. Selain guna mewujudkan lansia produktif dan mandiri, kata dia, kegiatan berkebun sayur organik sangat menyenangkan dan menyehatkan.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Produk ekonomi yang dihasilkan berupa sayur mayur organik seperti sawi, seledri, tomat, dan ada pula produk madu murni. Hasilnya kata dia dipasarkan kepada warga Nasio bahkan hingga warga di kecamatan Jati Asih lainnya.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Program lingkungan seperti berkebun ini telah dijalankan di perumahan Nasio. Kita terus beraktifitas, tetap sehat dan bahagia serta tidak hanya mengandalkan keluarga. Lansia Dahlia ingin terus berpartisipasi dalam program ini,&quot; kata Ratna saat ditemui di tempat pelatihan di Balai Pertemuan RW 15 Perum Bumi Nasio.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Program pemberdayaan lansia yang digelar di Perumahan Nasio ternyata mendapatkan perhatian lebih dari Kementerian Pemberdayaan Perempuan dan Perlindungan Anak (Kemen-PPA).</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Deputi Bidang Perlindungan Hak Perempuan (Kemen PPA) Prof Vennetia Danes secara langsung hadir serta membuka pelatihan kali ini.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Prof Vennetia mengatakan banyak mendengar berbagai prestasi telah ditorehkan warga perum Nasio seperti juara III Posdaya Nasio tingkat Nasional dan giat melakukan program lingkungan seperti bank Sampah. Dan hal ini membuat dirinya mengusahakan untuk datang ke tempat pelatihan lansia berkebun sayur organik secara langsung.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Kita harap program pemberdayan perempuan terutama lansia dapat menular ke wilayah lain. Dan menjadikan lansia sehat, produktif dan mandiri. Ini juga kampanye mengenai hak perempuan yang didalamnya hak lansia tetap berusaha dan beraktifitas,&quot; kata Prof Vennetia.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Kita ketahui bersama, Lingkungan perumaham Bumi Nasio kerap dilanda banjir seperti beberapa wilayah lainnya di Kota Bekasi. Namun hal ini tidak menyurutkan niat warga lebih berprestasi dan bermanfaat bagi lingkungan dan kota Bekasi pada umumnya. Terbukti beberapa posdaya dari kecamatan lain di Kota Bekasi dan luar kota melakukan studi banding mengenai program di posdaya Nasio.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Selain Deputi Kemen PPA, hadir Wakil Walikota Bekasi H Ahmad Syaikhu didampingi Camat Jati Asih Nesan Sujana, Lurah Jati Kramat Ferdinan serta Kapolsek dan Danramil Jatiasih.</span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Wawali Ahmad Syaikhu selaku Ketua Komda Lansia Kota Bekasi mengucapkan terimakasih kepada Deputi Kemen PPA Prof Vennetia dan jajaran melakukan pelatihan berkebun organik kepada lansia di Perumahan Bumi Nasio.</span></span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Ekonomi produktif bagi lansia ini sangat membanggakan Pemerintah dan warga Kota Bekasi. Kita harap lansia tetap sehat dan produktif. Ini bukti harapan untuk berubah dan bermanfaat bagi yang lain.&nbsp;</span></div>\r\n\r\n<div -webkit-padding-start:=\"\" br=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Dan pelatihan ini semoga lebih banyak lagi dilakukan hingga percepatan kegiatan diikuti Posbindu yang lain,&quot; kata Wawali Ahmad Syaikhu.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Selaku Ketua Komda Lansia Kota Bekasi, Wawali Ahmad Syaikhu juga mengatakan aktifitas program lansia diantaranya senam lansia setiap bulannya di rumah dinas Wakil Walikota. Selain itu juga dilakukan pemeriksaan kesehatan gula darah dan tensi darah bagi peserta.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Usai acara pembukaan simbolis Ketua&nbsp; Prof Vennetia dan Wawali Ahmad Syaikhu menerima hasil peranian kebun dari Kelompok Petani Organik (KePo) Perum Bumi Nasio Indah. (goeng)</span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2713, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 02:59:00', '2016-11-16 02:59:00', NULL),
('eb3bc2ae-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gala Diner Peserta Coop Expo 2016', 'gala-diner-peserta-coop-expo-2016', 'Coop Expo 2016 telah dibuka Menteri UMKM dan Koperasi Puspa Yoga dan menjadi bagian dari pengenalan produk dan ajang promosi usaha daerah dan negara asean-asia.\r\n\r\nSaat jamuan, Wakil Walikota Bekasi H', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span 2016=\"\" asean-asia=\"\" atau=\"\" bagi=\"\" ballroom=\"\" bekasi=\"\" coop=\"\" dalam=\"\" dan=\"\" di=\"\" dinner=\"\" div=\"\" duta=\"\" expo=\"\" font-family:=\"\" font-size:=\"\" gala=\"\" hari=\"\" hotel=\"\" jamuan=\"\" ke-69=\"\" koperasi=\"\" kota=\"\" makan=\"\" malam=\"\" medan=\"\" menggelar=\"\" negara=\"\" panitia=\"\" pengusaha=\"\" peringatan=\"\" perwakilan=\"\" puncak=\"\" santika=\"\" se-jabar=\"\" serta=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Coop Expo 2016 telah dibuka Menteri UMKM dan Koperasi Puspa Yoga dan menjadi bagian dari pengenalan produk dan ajang promosi usaha daerah dan negara asean-asia.</span></span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Saat jamuan, Wakil Walikota Bekasi H Ahmad Syaikhu&nbsp;didampingi Ketua Dekopinda Jabar Mustofa Jamaludin dan Kepala Dinas Perindustrian, Perdagangan dan Koperasi (Disperindagkop) Kota Bekasi Aceng Solehudin, Ketua Dekopinda Kota Bekasi Anim Imanudin.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Gala diner juga sekaligus menambah kehangatan hubungan baik para usahawan daerah maupun dari negara asean dalam ajang Coop Expo 2016 di Kota Bekasi, selaku tuan rumah kali ini.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Wawali Ahmad Syaikhu di awal sambutannya mengatakan Kota Bekasi berkembang juga berkat peran serta para pengusaha dalam membantu pemerintah. Selain itu Pemkot Kota Bekasi terus mewujudkan iklim investasi agar semakin menjanjikan dan kondusif di mata investor.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Keikutsertaan perwakilan negara Asean dan Asia dalam gelaran Coop Expo 2016 di Kota Bekasi salah satu upaya agar Kota Bekasi lebih diminari Investor. Coop Expo 2016 digelar dari tanggal 2-9 Agustus 2016 di Bekasi Town Square, Bekasi Timur.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Dalam perjalanannya para investor mempercepat proses pembangunan dan&nbsp; ekonomi di Kota Bekasi. Kerjasama ini kita optimis yakin membawa keuntungan bagi semua. Intinya agar masyarakat lebih maju dan sejahtera sebagai bagian dari negeri yang diidamkan bersama,&quot; ungkap Wawali Ahmad Syaikhu didepan para undangan dari negara luar.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Terkait peningkatan investasi kedepan, menjadi perhatian pemerintahan Walikota Bekasi Dr H Rahmat Effendi dan legislatif bersama dirinya yang telah menetapkan di 2017 Kota Bekasi sebagai tahun Investasi dan Perekonomian Daerah.</span></div>\r\n\r\n<div div=\"\" font-family:=\"\" font-size:=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&quot;Semoga Investasi terus bergeliat guna mendorong perekonomian daerah,&quot; katanya.</span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span aeromovel=\"\" angin=\"\" atau=\"\" bahkan=\"\" beberapa=\"\" bekasi=\"\" dari=\"\" dengan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" halnya=\"\" ini=\"\" inisasi=\"\" investor=\"\" keinginan=\"\" kereta=\"\" lanjut=\"\" menghubungkan=\"\" mewujudkan=\"\" moda=\"\" pemkot=\"\" pengusaha=\"\" perbelanjaan.=\"\" perumahan=\"\" pusat=\"\" rencana=\"\" seperti=\"\" text-align:=\"\" transportasi=\"\" yang=\"\">&nbsp;</span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span aeromovel=\"\" angin=\"\" atau=\"\" bahkan=\"\" beberapa=\"\" bekasi=\"\" dari=\"\" dengan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" halnya=\"\" ini=\"\" inisasi=\"\" investor=\"\" keinginan=\"\" kereta=\"\" lanjut=\"\" menghubungkan=\"\" mewujudkan=\"\" moda=\"\" pemkot=\"\" pengusaha=\"\" perbelanjaan.=\"\" perumahan=\"\" pusat=\"\" rencana=\"\" seperti=\"\" text-align:=\"\" transportasi=\"\" yang=\"\"><span 10=\"\" aeromovel=\"\" bagian=\"\" bentang=\"\" dan=\"\" dari=\"\" dia=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jalur=\"\" kata=\"\" km=\"\" mengatasi=\"\" menjadi=\"\" sejauh=\"\" text-align:=\"\" upaya=\"\">&nbsp;</span></span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span aeromovel=\"\" angin=\"\" atau=\"\" bahkan=\"\" beberapa=\"\" bekasi=\"\" dari=\"\" dengan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" halnya=\"\" ini=\"\" inisasi=\"\" investor=\"\" keinginan=\"\" kereta=\"\" lanjut=\"\" menghubungkan=\"\" mewujudkan=\"\" moda=\"\" pemkot=\"\" pengusaha=\"\" perbelanjaan.=\"\" perumahan=\"\" pusat=\"\" rencana=\"\" seperti=\"\" text-align:=\"\" transportasi=\"\" yang=\"\"><span 10=\"\" aeromovel=\"\" bagian=\"\" bentang=\"\" dan=\"\" dari=\"\" dia=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jalur=\"\" kata=\"\" km=\"\" mengatasi=\"\" menjadi=\"\" sejauh=\"\" text-align:=\"\" upaya=\"\"><span aeromovel=\"\" ahmad=\"\" bisa=\"\" dalam=\"\" dan=\"\" dari=\"\" dengan=\"\" di=\"\" dilakukan=\"\" disambut=\"\" div=\"\" font-family:=\"\" font-size:=\"\" gede.=\"\" inisasi=\"\" inisiasi=\"\" juga=\"\" kanada=\"\" kata=\"\" kerjasama=\"\" kita=\"\" lain=\"\" langsung=\"\" malaysia=\"\" optimis=\"\" p=\"\" para=\"\" pembangunan=\"\" pembentukan=\"\" plan=\"\" syaikhu=\"\" tangan=\"\" temen-temen=\"\" tepuk=\"\" text-align:=\"\" treatmen=\"\" untuk=\"\" water=\"\">&nbsp;</span></span></span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span aeromovel=\"\" angin=\"\" atau=\"\" bahkan=\"\" beberapa=\"\" bekasi=\"\" dari=\"\" dengan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" halnya=\"\" ini=\"\" inisasi=\"\" investor=\"\" keinginan=\"\" kereta=\"\" lanjut=\"\" menghubungkan=\"\" mewujudkan=\"\" moda=\"\" pemkot=\"\" pengusaha=\"\" perbelanjaan.=\"\" perumahan=\"\" pusat=\"\" rencana=\"\" seperti=\"\" text-align:=\"\" transportasi=\"\" yang=\"\"><span 10=\"\" aeromovel=\"\" bagian=\"\" bentang=\"\" dan=\"\" dari=\"\" dia=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jalur=\"\" kata=\"\" km=\"\" mengatasi=\"\" menjadi=\"\" sejauh=\"\" text-align:=\"\" upaya=\"\"><span aeromovel=\"\" ahmad=\"\" bisa=\"\" dalam=\"\" dan=\"\" dari=\"\" dengan=\"\" di=\"\" dilakukan=\"\" disambut=\"\" div=\"\" font-family:=\"\" font-size:=\"\" gede.=\"\" inisasi=\"\" inisiasi=\"\" juga=\"\" kanada=\"\" kata=\"\" kerjasama=\"\" kita=\"\" lain=\"\" langsung=\"\" malaysia=\"\" optimis=\"\" p=\"\" para=\"\" pembangunan=\"\" pembentukan=\"\" plan=\"\" syaikhu=\"\" tangan=\"\" temen-temen=\"\" tepuk=\"\" text-align:=\"\" treatmen=\"\" untuk=\"\" water=\"\"><span bahkan=\"\" bernyanyi.=\"\" dalam=\"\" dari=\"\" di=\"\" dihadirkan=\"\" ditampilkan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" hiburan=\"\" ikut=\"\" ini=\"\" jamuan=\"\" juga=\"\" kali=\"\" koppas=\"\" musik=\"\" para=\"\" penari=\"\" perwakilan=\"\" peserta=\"\" sanggar=\"\" sela=\"\" tari=\"\" text-align:=\"\" topeng=\"\">&nbsp;</span></span></span></span></div>\r\n\r\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span aeromovel=\"\" angin=\"\" atau=\"\" bahkan=\"\" beberapa=\"\" bekasi=\"\" dari=\"\" dengan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" halnya=\"\" ini=\"\" inisasi=\"\" investor=\"\" keinginan=\"\" kereta=\"\" lanjut=\"\" menghubungkan=\"\" mewujudkan=\"\" moda=\"\" pemkot=\"\" pengusaha=\"\" perbelanjaan.=\"\" perumahan=\"\" pusat=\"\" rencana=\"\" seperti=\"\" text-align:=\"\" transportasi=\"\" yang=\"\"><span 10=\"\" aeromovel=\"\" bagian=\"\" bentang=\"\" dan=\"\" dari=\"\" dia=\"\" div=\"\" font-family:=\"\" font-size:=\"\" jalur=\"\" kata=\"\" km=\"\" mengatasi=\"\" menjadi=\"\" sejauh=\"\" text-align:=\"\" upaya=\"\"><span aeromovel=\"\" ahmad=\"\" bisa=\"\" dalam=\"\" dan=\"\" dari=\"\" dengan=\"\" di=\"\" dilakukan=\"\" disambut=\"\" div=\"\" font-family:=\"\" font-size:=\"\" gede.=\"\" inisasi=\"\" inisiasi=\"\" juga=\"\" kanada=\"\" kata=\"\" kerjasama=\"\" kita=\"\" lain=\"\" langsung=\"\" malaysia=\"\" optimis=\"\" p=\"\" para=\"\" pembangunan=\"\" pembentukan=\"\" plan=\"\" syaikhu=\"\" tangan=\"\" temen-temen=\"\" tepuk=\"\" text-align:=\"\" treatmen=\"\" untuk=\"\" water=\"\"><span bahkan=\"\" bernyanyi.=\"\" dalam=\"\" dari=\"\" di=\"\" dihadirkan=\"\" ditampilkan=\"\" div=\"\" font-family:=\"\" font-size:=\"\" hiburan=\"\" ikut=\"\" ini=\"\" jamuan=\"\" juga=\"\" kali=\"\" koppas=\"\" musik=\"\" para=\"\" penari=\"\" perwakilan=\"\" peserta=\"\" sanggar=\"\" sela=\"\" tari=\"\" text-align:=\"\" topeng=\"\">&lt;span border-box;=&quot;&quot; font-family:=&quot;&quot; tahoma;&quot;=&quot;&quot;&gt;Diakhir sambutannya, Ahmad Syaikhu atas nama Walikota Bekasi H Rahmat Effendi mengucapkan harapannya agar suasana para tamu setelah sekembalinya ke daerah maupun negara asal, lebih berbahagia. Dengan pengalaman yang didapat di Kota Bekasi. (goeng)</span></span></span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2083, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:01:00', '2016-11-16 03:01:00', NULL),
('eb3bc3b0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Menteri Koperasi dan UMKM RI Resmikan Jawa Barat Coop Expo 2016 di Kota Bekasi', 'menteri-koperasi-dan-umkm-ri-resmikan-jawa-barat-coop-expo-2016-di-kota-bekasi', 'Kota Bekasi -&nbsp;Kegiatan Coop Expo 2016 dalam rangka hari Koperasi Ke-69 resmi dibuka Menteri Koperasi dan UMKM RI Puspa Yoga di halaman Bekasi Town Square, Jalan Cut Meutia Kota Bekasi, Selasa, (2', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi -&nbsp;Kegiatan Coop Expo 2016 dalam rangka hari Koperasi Ke-69 resmi dibuka Menteri Koperasi dan UMKM RI Puspa Yoga di halaman Bekasi Town Square, Jalan Cut Meutia Kota Bekasi, Selasa, (2/8).</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sesuai dengan tag-linenya ASEAN &ndash; International Cooperative Summit &amp; Trade Expo, Jabar Coop Expo 2016 merupakan ajang promosi bergengsi bagi perusahaan dan usaha koperasi diikuti oleh 27 Kota dan Kabupaten se-Jawa Barat, juga diikuti 9 negara ASEAN serta 2 negara Asia lainnya seperti Cina dan India. Kegiatan Coop Expo&nbsp;akan berlanjut hingga 9 Agustus 2016.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dalam kesempatan itu juga hadir Gubernur Jawa Barat Ahmad Heryawan dan Muspida Jawa Barat dan Wakil Walikota Bekasi Ahmad Syaikhu dan Muspida Kota Bekasi, Ketua Dewan Koperasi Indonesia (Dekopindo) Jawa Barat, Mustofa Jamaludin, Ketua Dekopinda Kota Bekasi Anim Imanudin. Serta kehadiran para perwakilan kepala daerah dan dinas Koperasi dan UMKM se-Jawa Barat.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Menteri Koperasi dan UMKM Puspa Yoga membuka kegiatan Coop Expo 2016 dengan memukul beduk bersama Gubernur Jabar dan Wakil Walikota Bekasi.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Melalui peringatan hari koperasi 2016 kita tingkatkan pemerataan ekonomi kerakyatan melalui lembaga koperasi. Komitmen Jawa Barat dalam hal koperasi luar biasa terbukti koperasi menjadi program unggulan pemberdayaan ekonomi selama ini,&quot; kata Menteri Koperasi dan UMKM Tubagus Yoga.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Selain itu, pemerintah pusat melakukan deregulasi sebagai upaya meningkatkan kebebasan atau kemudahan berusaha.&nbsp; Empat fokus deregulasi yang tengah dilakukan pemerintah Pusat melalui pemerintahan Presiden Joko Widodo, ia menyampaikan pertama segi peningkatan infrastruktur, kedua bidang turisme, ketiga bidang energi dan keempat kemaritiman.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Sehingga empat fokus deregulasi ini guna meningkatkan perekonomian. Meningkatkan lapangan kerja, kesejahteraan dan kita ingin angka kemiskinan semakin berkurang,&quot; kata Tubagus.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Mengenai jumlah koperasi ia mengatakan saat ini terdata dalam data base kementerian Koperasi dan UMKM sebanyak 170 ribu se-Indonesia yang aktif mengerakan roda koperasi.</span></span></div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Kita lakukan pendataan, pemberdayaan koperasi hingga desa,&quot; pungkasnya.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Gubernur Jawa Barat Ahmad Heryawan berharap koperasi Jawa Barat terus berkembang dan menjadi lembaga di masyarakat yang mampu mengelorakan semangat berusaha dengan azaz kekeluargaan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Lewat koperasi perekomonian merata. sebab modal terkumpul bersumber dari anggota. Koperasi, membuat keuntungan bersama dan kesejahteraan bersama melalui permodalan yang diusahakan juga bersama. Modal terkumpul kecil tapi dari anggota yang banyak itu untuk keberlangsungan koperasi,&quot; kata Ahmad Heryawan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sementara itu, Wawali Ahmad Syaikhu menyampaikan ucapan terimakasih kepada semua pihak yang sudah berupaya menggelar serangkaian kegiatan Coop Expo 2016 di Kota Bekasi. Dan harapannya Kota Bekasi kedepan meiliki tempat strategis untuk mendukung kegiatan hasil UMKM se-Jawa Barat.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Kota Bekasi menjadi tempat pemasaran. dan Pemerintah Provinsi pun mendukung melalui Gubernur. Mudah-mudahan bidang UMKM melalui lembaga koperasi di Kota Bekasi khususnya bisa terus berkembang ditengah era persaingan usaha sekarang ini,&quot; harap Ahmad Syaikhu.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Usai pembukaan Coop Expo, Menteri Koperasi dan UMKM, bersama Gunernur Jawa Barat, dan Wakil Walikota Bekasi menyerahkan sejumlah penghargaan kepada penggerak perkoperasian se-Jawa Barat. Koperasi Kota Bekasi yang diberi penghargaan diantaranya Koperasi PT Arnot, Koperasi Kusuma Dinas Kesehatan Kota Bekasi, Dan Koperasi Unio Bererot.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kemudian dilanjutkan untuk meninjau sejumlah stand pameran UMKM. Diantaranya mereka beberapa kali mencicipi hasil produksi UMKM makanan dan minuman. (goeng)</span></span></div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Rangkaian Program acara Jabar Coop Expo 2016 diantaranya:</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Program Edukasi, Talkshow Koperasi Syariah, Workshop eMarketing, Cooperative Sharing Session, Training Enterpreneurship<br border-box=\"\" />\r\nPelatihan dan Sertifikasi bagi Pelaku Koperasi, Talkshow Revitalisasi Koperasi Mahasiswa &amp; Universitas<br border-box=\"\" />\r\ndan lainnya, Program Hiburan, Parade Budaya Jawa Barat, Parade Band Kota Bekasi, Blues Music Performance<br border-box=\"\" />\r\nCharity Concert, Stand Up Comedy, Beatbox Performance, Community Show<br border-box=\"\" />\r\nFashion Show, dan lainnya</span></span></div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Program Pelayanan Publik<br border-box=\"\" />\r\nDISDUKCAPIL: Pengurusan KTP, KK, Akta Kelahiran dan lainnya<br border-box=\"\" />\r\nBPPT: Pengurusan SIUP, TDP, Reklame dan lainnya<br border-box=\"\" />\r\nDISPENDA: BPHTB, PBB<br border-box=\"\" />\r\nSAMSAT: Pengurusan Perpanjangan/Pembayaran STNK<br border-box=\"\" />\r\nPOLRES: Perpanjangan SIM<br border-box=\"\" />\r\nRSUD: Pemeriksaan Kesehatan, Ambulance dan lainnya<br border-box=\"\" />\r\nDISNAKER: Jobfair (Bursa Lowongan Kerja)<br border-box=\"\" />\r\nYONIFMEK 202: Pameran Alutsista<br border-box=\"\" />\r\nProgram Kompetisi<br border-box=\"\" />\r\nTurnamen Panahan PERPANI<br border-box=\"\" />\r\nTurnamen Futsal<br border-box=\"\" />\r\nTurnamen Street Soccer<br border-box=\"\" />\r\nModern Dance Competition<br border-box=\"\" />\r\nCosplay Competition<br border-box=\"\" />\r\nFestival Qasidah dan Marawis<br border-box=\"\" />\r\nCerdas Cermat Koperasi Pelajar<br border-box=\"\" />\r\nColouring Competition<br border-box=\"\" />\r\nBeatbox Competition<br border-box=\"\" />\r\nFunwalk<br border-box=\"\" />\r\nLomba &amp; Pameran Fotografi<br border-box=\"\" />\r\nExhibitor Terbaik.</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 7073, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:02:00', '2016-11-16 03:02:00', NULL),
('eb3bc465-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Ratusan Warga Serbu paket Sembako Murah', 'ratusan-warga-serbu-paket-sembako-murah', 'Kota Bekasi - Ratusan Warga yang berada di Wilayah Kecamatan Medan Satria mengantri untuk mendapatkan paket sembako murah yang digelar oleh Disperindakop kota Bekasi bekerjsama dengan Disperindakop da', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Ratusan Warga yang berada di Wilayah Kecamatan Medan Satria mengantri untuk mendapatkan paket sembako murah yang digelar oleh Disperindakop kota Bekasi bekerjsama dengan Disperindakop dan UMKM Provinsi jabar, bertempat di halaman Kelurahan Harapan Mulya ,Kecamatan Medan Satria, Kamis,( 23/6).</span></span>&nbsp;</span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Pemerintah menyediakan 10.000 paket sembako murah yang terdiri dari 5 KG beras, 3 Kg gula pasir dan 3 Liter minyak goreng yang terbagi di 4 kecamatan, diantaranya kecamatan Mustikajaya, Kecamatan Medan Satria, Kecamatan Bekasi utara dan Kecamatan Rawalumbu masingmasing 2500 paket, terang Sekretaris Disperindakop kota Bekasi, Deded.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Menurutnya tingginya harga kebutuhan pokok menjadi salah satu penyebab menurunnya daya beli masyarakat. bayak hal telah dilakukan oleh pemerintah maupun dunia usaha untuk membantu masayrakat yang kurang mampu, akan tetapi upaya tersebut juga belum mampu mengatasi permasalahan pemenuhan kebutuhan dasar seperti pemenuhan kebutuhan pokok, katanya.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sementara itu, Wakil Walikota Bekasi, Ahmad Syaikhu yang hadir dalam kegiatan tersebut menjealaskan kegiatan ini dilaksanakan dalam mensukseskan agenda program kegiatan serta alokasi belanja subsidi provinsi jabar untuk membantu masyarakat ekonomi kurang mampu untuk memenuhi kebutuhan pokok, tutur Syaikhu.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Ditambahakannya lagi, kegiatan ini juga sangat baik , karena menjadi sarana para pelaku UMKM binaan Kota Bekasi untuk menampilkan produk-produknya sehingga daapta lebih berkembang. &quot; saya berharap bazzar ini dapat membantu masyarakat untuk mendapatkan kebutuhan pokok yang lebih murah&quot;, ujarnya.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Salah satu warga, Sunarsi (40) mengatakan, sangat terbantukan degnan adannya bazzar ini, apalagi sebentar lagi umat muslim merayakan hari raya idul fitri, katanya saat ditemui usai mendapatkan paket sembako.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Turut hadir dalam bazar tersebut, Wakil Walikota Bekasi, Ahmad Syaikhu, Camat Medan Satria, lurah se kecamtan Medan Satria, Unsur Muspika, ketua dan Wakil PKK ktoa Bekasi. (yas)</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 6182, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:03:00', '2016-11-16 03:03:00', NULL),
('eb3bc509-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Meraih 7 Mendali Pemerintah Kota Bekasi Meraih Posisi Kedua Di PORPEMDA JABAR XII 2016', 'meraih-7-mendali-pemerintah-kota-bekasi-meraih-posisi-kedua-di-porpemda-jabar-xii-2016', 'Kota Bekasi - &nbsp;Perbaikan peringkat terus ditorehkan Pemkot Bekasi dalam kejuaraan Pekan Olahraga Pemerintah Daerah (PORPEMDA) Jabar XII Tahun 2016 dimana kota bekasi menjadi tuan rumah dalam ajan', '<p border-box=\"\"><span border-box=\"\">Kota Bekasi - &nbsp;Perbaikan peringkat terus ditorehkan Pemkot Bekasi dalam kejuaraan Pekan Olahraga Pemerintah Daerah (PORPEMDA) Jabar XII Tahun 2016 dimana kota bekasi menjadi tuan rumah dalam ajang ini.</span></p>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3165\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3242\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3241\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3240\">&nbsp;</span></span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;<span border-box=\"\">&nbsp;Tahun lalu Kota Bekasi meraih peringkat ke tiga, ini merupakan peningkatan yang baik, kita berhasil menduduki peringkat dua, ujar salah satu pengurus bapor, Dr. Ekowati usai menyerahkan medali emas untuk cabang tenis Lapang , Kamis(10/11).</span></p>\r\n\r\n<p border-box=\"\"><span border-box=\"\">Pada kejuaraan kali ini, Pemkot Bekasi mampu meraih peringkat ke 2 dalam kejuaraan yang berlangsung di kota bekasi ,Jawabarat tanggal 7-10 nopmeber 2016.tersebut, atlet Pemkot Bekasi meraih 3 emas, 1 perak dan 1 perunggu.&nbsp;</span></p>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3174\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3176\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3177\">&nbsp;</span></span><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3179\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3180\">Medali emas yang diraih atlet PNS Pemkot Bekasi, diantaranya berasal dari cabang olahraga (cabor) tenis lapang 3 emas, &nbsp;terompah panjang &nbsp;1 emas, &nbsp;Golf 1 emas, Senam 1 perak, &nbsp;serta 1 perunggu dari cabang Bulu tangkis.</span></span></div>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3181\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3183\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3184\">&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\" dir=\"ltr\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3185\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3186\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3187\">ini dapat menjadi semangat ditahun kedepannya, karena setiap tahunnya kita selalu ada peningkatan posisi. &quot; suatu peningkatan prestasi yang patut disyukuri oleh kita semua, agar pada tahun mendatang peringkat ini bisa ditingkatkan lagi&quot;, tutur Dr. Ekowati ,yang juga sebagai Kepala Sekolah SMAN 2 Kota Bekasi.</span></span></div>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3188\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3190\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3191\">&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3192\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3193\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3194\">Perbaikan peringkat yang berhasil diraih atlet PNS Pemkot Bekasi merupakan kerja keras dari hasil latihan yang dijalani para atlet sebelum Porpemda berlangsung.&quot; , kami selalu lakukan seleksi ketat, karena kami ingin mendapatkan hasil yang maksimal&quot;, ujar Eko.</span></span></div>\r\n\r\n<div border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3195\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3197\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3198\">&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\" dir=\"ltr\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3199\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3200\"><span border-box=\"\" id=\"m_1972991086488702562yui_3_16_0_ym19_1_1478775545980_3201\">Untuk Tahun depan kami berharap terus adanya peningkatan, tentunya harus ada komitmen dari atlit itu sendiri serta dukungan dari Pemerintah Daerah dalam hal pembinaan, tandasnya. (yas)</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3608, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:04:00', '2016-11-16 03:04:00', NULL),
('eb3bc5af-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Menang di Pertandingan Eksebisi Bulutangkis Porpemda Ke-12 Jabar', 'wawali-menang-di-pertandingan-eksebisi-bulutangkis-porpemda-ke-12-jabar', 'Kota Bekasi, -- Pekan Olahraga Pemerintah Daerah (Porpemda) Ke-12 resmi digelar mulai 7-10 November 2016 mendatang. Sebanyak 13 cabang olahraga mulai dipertandingkan diantaranya cabang olahraga Buluta', '<p border-box=\"\">Kota Bekasi, -- Pekan Olahraga Pemerintah Daerah (Porpemda) Ke-12 resmi digelar mulai 7-10 November 2016 mendatang. Sebanyak 13 cabang olahraga mulai dipertandingkan diantaranya cabang olahraga Bulutangkis.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Porpemda Jabar mengusung tema meningkatkan silaturahmi, kebersamaan dan kekeluargaan dan poin penting sama-sama mampu meningkatkan kinerja untuk pelayanan publik di masing-masing ASN pemerintah daerah.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Bertempat di Gor Badmintin HI-Qua Wijaya Kelurahan Teluk Pucung, Wakil Walikota Bekasi H Ahmad Syaikhu melihat pertandingan cabor Bulutangkis, Selasa, (8/11). Ia pun sempat melakukan pertandingan eksebisi sebelum laga resmi bulutangkis atlet Porpemda dimulai.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Dipasangkan dengan Staf Ahli Walikota Bekasi, Momon Sulaeman, Wawali Ahmad Syaikhu adu ketangkasan Bulutangkis dengan Ketua Korpri Jabar Dr Guntoro dan pasangannya saat itu, Taufiq.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Pertandingan pun berlangsung seru dan disaksikan para atlet yang juga tengah bersiap bertanding. Dengan raket kepunyaan masing-masing, mereka mempraktekan kebolehan mengolah pukulan smash dan back hand. Tidak jarang permainan netting juga ditunjukan kedua pasangan.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Tapi diakhir pertandingan pasangan Kota Bekasi akhirnya mampu menyudahi pertandingan dengan kemenangan dua set langsung 21-15 dan 21-10.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">&quot;Terima kasih sudah bersama berolahraga bersama. Ini ujud keseriusan kita bersama menjaga fisik dan kebugaran selain itu Porpemda menjaga silaturahmi dan produktifitas kerja antar ASN se-Jabar,&quot; kata Wawali Ahmad Syaikhu.</p>\r\n\r\n<p border-box=\"\">&nbsp;</p>\r\n\r\n<p border-box=\"\" dir=\"ltr\">Usai bertanding Wawali Ahmad Syaikhu memberikan kenang-kenangan berupa kaos badminton kepada Ketua Korpri Guntoro dan Taupik. Dan tidak lama setelahnya panitia pertandingan memulai pertandingan lanjutan Porpemda. (goeng)</p>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 3694, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:06:00', '2016-11-16 03:06:00', NULL),
('eb3bc64d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Gubernur Jawa Barat Bersama Walikota Bekasi Buka PORPEMDA Jawa Barat XII Tahun 2016', 'wakil-gubernur-jawa-barat-bersama-walikota-bekasi-buka-porpemda-jawa-barat-xii-tahun-2016', 'Kota Bekasi - Pekan Olahraga Pemerintah Daerah (PORPEMDA) Jawa Barat XII Tahun 2016 diselenggarakan di Kota Bekasi, di hadiri dan di Buka oleh Wakil Gubernur Jawa Barat, H. Dedi Mizwar didampingi Ketu', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi - Pekan Olahraga Pemerintah Daerah (PORPEMDA) Jawa Barat XII Tahun 2016 diselenggarakan di Kota Bekasi, di hadiri dan di Buka oleh Wakil Gubernur Jawa Barat, H. Dedi Mizwar didampingi Ketua Korpri Jawa Barat, Prof. Dr. Guntoro, sebagai tuan rumah Walikota Bekasi, Dr. Rahmat Effendi memberikan ucapan selamat datang di Kota Bekasi dan memperkenalkan Stadion Patriot Candrabhaga yang menjadi tempat pembukaan PORPEMDA Jawa Barat XII Tahun 2016 pada hari Senin Malam, (07/11).</span></span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Hadir juga para Kepala Daerah atau perwakilannya dari Kota dan Kabupaten Se Jawa Barat, dan dalam pelaksanaan de ville para atlet yang bertanding memberikan salam hangat kepada Wakil Gubernur di atas Podium.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dengan lantang mengeluarkan semangat &quot;Salam Patriot&quot;, Walikota Bekasi dengan semangat memberikan sambutannya di atas podium mengatakan selamat data g di Kota Bekasi, Kota yang telah berubah dan memiliki ikon Stadion Kebanggaan yakni Stadion Patriot Candrabhaga yang kini dipakai pembukaan PORPEMDA Jawa Barat XII, ucapan terimakasih disampaikan juga ke Wakil Gubernur Jawa Barat yang telah berkali kali datang di Stadion Patriot Cabdrabhaga, juga tidak lupa kepada perwakilan dari masing masing daerah se Jawa Barat yang hadir menyaksikan pembukaan acara tersebut.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Terselenggaranya PORPEMDA Jawa Barat ini merupakan ajang pelaksanaan tahunan dengan berbagai perlombaan di cabang olahraga masing masing, juga selain itu meningkatkan tali silaturahni antar aparatur di lingkungan Pemerintah Kota/Kabupaten di Provinsi Jawa Barat.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Penanggung jawab kegiatan tersebut berada di Dinas Pemuda, Olahraga, Budaya dan Pariwisata untuk menaungi seluruh aparatur terhadap suksesnya perhelatan tersebut.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sebanyak 27 pemerintah daerah di Jawa Barat akan mengirimkan 100 atletnya untuk berlomba di ajang Porpemda kali ini.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Sebagai informasi, lomba tersebut akan mempertandingkan 12 cabang olahraga di antaranya futsal, bola voli, bola basket, bulutangkis, tenis lapang, tenis meja, catur, billiard, senam, terompah, gerak jalan dan golf.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Wakil Gubernur Provinsi Jawa Barat, H. Dedi Mizwar dalam sambutannya mengungkapkan untuk para atlet yang ikut ajang PORPEMDA Tahun ini, agar menjaga kestabilan tubuh secara teratur dan berkesinambungan, sehingga pada saat bertanding memiliki kebugaran jasmani, selain itu juga bisa diterapkan kepada Aparatur Sipil Negara (ASN) agar tetap berolahrga meskipun di waktu sempit, seperti program dari Provinsi Jawa Barat &quot;Gerakan Ayo Olahraga !!&quot; bagi para ASN, sehingga dapat terintegritasi dalam kehidupan sehari haru, mempertahankan dan meningkatkan kualitas gerak yang disipilin.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Selanjutnya, Wagub Jawa Barat berpendapat seperti Program Car Free Day merupaka suatu langkah menuju Kota Sehat, dan pembangunan seperti Sport Centre untuk masyarakat merupakan satu langkah menciptakan program Gerakan Ayo Olahraga.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Usai sambutan, Wakil Gubernur Jawa Barat, Walikota Bekasi dan Wakil Walikota Bekasi serta Ketua Korpri Provinsi Jawa Barat menekan tombol peringatan ya g telah disediakan yang merupakan tanda PORPEMDA Jawa Barat XII Tahun 2016, siap untuk berlaga di Kota Bekasi sebagai tuan rumah dalam waktu 3 hari kedepan. (Ndoet)</span></span></div>', 'images/20170823093937-2017-08-23post093936.jpg', NULL, NULL, 2411, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:07:00', '2016-11-16 03:07:00', NULL),
('eb3bc6fb-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Ramah Tamah Jelang Pembukaan Porpemda Ke-12 Berlangsung Meriah', 'ramah-tamah-jelang-pembukaan-porpemda-ke-12-berlangsung-meriah', 'Kota Bekasi -&nbsp;Acara ramah tamah kepada tamu kontingen Pemerintah Daerah Se-Jawa Barat berlangsung meriah di Hotel Horison Kota Bekasi, Senin, (7/11).\r\n\r\n&nbsp;\r\n\r\nAcara ramah tamah dimulai sejak ', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi -&nbsp;Acara ramah tamah kepada tamu kontingen Pemerintah Daerah Se-Jawa Barat berlangsung meriah di Hotel Horison Kota Bekasi, Senin, (7/11).</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Acara ramah tamah dimulai sejak sore hari ini sebagai awal jelang pembukaan Pekan Olahraga Pemerintah Daerah (Porpemda) Ke-12 Jawa Barat tahun 2016. Ramah tamah diisi dengan sajian tarian topeng Bekasi, pemberian maskot Porpemda, dan menyanyi lagu nostalgia dari peserta.</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Usai ramah tamah dilanjutkan kegiatan pembukaan Porpemda di Stadion Patriot Chandrabaga Kota Bekasi oleh Wakil Gubernur Jabar Deddy Mizwar.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Diinformasikan, sebanyak 27 kabupaten/Kota se-Jawa Barat ditambah satu kontingen dari Provinsi Jawa Barat akan mengikuti ajang perlombaan Pekan Olahraga Pemerintah Daerah (Porpemda) Ke-13 di Kota Bekasi selaku tuan rumah.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\"><br border-box=\"\" />\r\n<span border-box=\"\"><span border-box=\"\">Porpemda dimulai dari tanggal 7-10 November 2016 dengan mempertandingkan sebanyak13 cabang olahraga.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dalam acara ramah tamah, Wakil Walikota Bekasi H Ahmad Syaikhu, Sekda Kota Bekasi Rayendra Sukarmadji, dan unsur Muspida Kota Bekasi menyambut kontingen pemerintah daerah Se-Jawa. Banyak diantara para tamu diantaranya para kepala daerah maupun sekretaris daerah dan para kepala satuan kerja.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Total 28 kontingen ini berpartisipasi pada even perlombaan olahraga yang dikhususkan bagi Aparatur Sipil Negara (ASN). Tema yang diusung Porpemda mamapu meningkatkan silaturahmi, produksifitas kerja untuk pelayanan masyarakat.&nbsp;</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Wawali Ahmad Syaikhu mengatakan selamat datang di Kota Bekasi, Kota Patriot. Dan ia menyampaikan Visi misi Pemkot Bekasi ingin mewujukan Masyarakat Kota Bekasi yang Maju, Sejahtera dan Ihsan.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Tentu dalam even Porpemda bukan hanya prestasi yang mampu diukir tapi juga menjalin kebersamaan, kekeluargaan untuk memajukan daerah kita masing-masing,&quot; kata Wawali Ahmad Syaikhu.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Ia pun berterima kasih dukungan pemerintah Provinsi Jawa Barat terkait pembangunan Stadion Patriot Chandrabaga Kota Bekasi. Dan harapan kedepan Kota Bekasi juga disuport&nbsp; perningkatan trek lintasan cabor sepeda hingga berskala internasional.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Selain menjadi pusat olahraga, diharapkan menjadi daya tarik tersendiri bagi wisatawan untuk datang ke kota Bekasi dan Jawa Barat.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Melihat Kota Bekasi sebelum ke ibukota Jabar, kota Bandung. Kota Bekasi display Jawa Barat. Infrastukturnya menambah ketertarikan wisatawan,&quot; kata Wawali Ahmad Syaikhu.</span></span></div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Usai menyampaikan ucapan selamat datang, Wawali Kota Bekasi Ahmad Syaikhu memberikan maskot Porpemda Ke-12 berupa boneka menyerupai burung bangau atau burung Blekok kepada Walikota Sukabumi H Mohamad Muraz.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Dipilihnya maskot ini sebab Kota Bekasi dikenal memiliki banyak rawa-rawa termasuk keanekaragaman hayati diantaranya burung bangau atau burung blekok. (goeng)</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2002, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 03:08:00', '2016-11-16 03:08:00', NULL),
('eb3bc7b1-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ahmad Syaikhu Resmikan Masjid Al Muhajirin Sumur Batu', 'wawali-ahmad-syaikhu-resmikan-masjid-al-muhajirin-sumur-batu', 'Kota Bekasi -&nbsp;Wakil Walikota Bekasi H. Ahmad&nbsp; Syaikhu meresmikan Masjid Al Muhajirin di Cluster Jasmine Perumahan Bekasi Timur Regency 5 Kelurahan Sumurbatu Kecamatan Bantar Gebang, Kota Bek', '<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Kota Bekasi -&nbsp;Wakil Walikota Bekasi H. Ahmad&nbsp; Syaikhu meresmikan Masjid Al Muhajirin di Cluster Jasmine Perumahan Bekasi Timur Regency 5 Kelurahan Sumurbatu Kecamatan Bantar Gebang, Kota Bekasi, Minggu, (8/5).</span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Acara peresmian dihadiri oleh Lurah Sumurbatu Topik Ajimulya, Kapospol Subsektor Sumurbatu, Bhabinkamtibmas, DKM, Ketua Forum Umat Islam Sumurbatu (Formatis), Ketua RW dan RT serta tokoh masyarakat dan jamaah.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Peresmian yang sekaligus juga peringatan Isra&#39; Mi&#39;raj Nabi Muhammad SAW tersebut diisi tauziah oleh Wakil Walikota yang bertema &quot;Fungsi Masjid dalam Tatanan Masyarakat Madani&quot;.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Wawali Ahmad Syaikhu berpesan kepada masyarakat yang hadir untuk senantiasa memakmurkan masjid yang ada. Dalam artian telah dibangunnya masjid Al Muhajiri tidak hanya indah dan bagus saja namun dapat menjadi pusat syiar agama Islam dilingkungan sekitar.<br border-box=\"\" />\r\n<br border-box=\"\" />\r\n&rdquo;Kota Bekasi saat ini memiliki hampir 900 masjid, dan Pemerintah Kota Bekasi berkewajiban untuk bersama-sama memakmurkan masjid sehingga mewujudkan masyarakat Kota Bekasi yang madani,&quot; kata Ahmad Syaikhu.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">Lanjut dia, Pemkot Bekasi akan terus memberikan perhatian bagi para marbot dan pengurus masjid yang ada.</span></span></div>\r\n\r\n<div border-box=\"\">&nbsp;</div>\r\n\r\n<div border-box=\"\"><span border-box=\"\"><span border-box=\"\">&quot;Mari kita makmurkan masjid-masjid,&quot; ajaknya. (sapta/goeng)</span></span></div>', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 2479, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 04:22:00', '2016-11-16 04:22:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bc874-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Bekasi Buka Ground Breaking Pembangunan Instalansi Pengelolaan Air (IPA) Teluk Buyung', 'walikota-bekasi-buka-ground-breaking-pembangunan-instalansi-pengelolaan-air-ipa-teluk-buyung', 'Kota Bekasi - Dalam rangkaian HUT Kota Bekasi ke-19, PDAM Tirta Patriot melangsungkan groundbreaking WTP Teluk Buyung dengan kapasitas 200 liter per detik. Walikota Bekasi, Dr. Rahmat Effendi bersama ', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\"><span  border-box; color: rgb(46, 46, 46); line-height: 25.7143px;\">Kota Bekasi - Dalam rangkaian HUT Kota Bekasi ke-19, PDAM Tirta Patriot melangsungkan groundbreaking WTP Teluk Buyung dengan kapasitas 200 liter per detik. Walikota Bekasi, Dr. Rahmat Effendi bersama Wakil Walikota, Ahmad Syaikhu hadir untuk meresmikan Ground breaking Pembangunan Instalasi Pengelolaan Air Teluk Buyung tersebut pada hari Kamis (10/03/2016).</span></span></span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\"><span  border-box; color: rgb(46, 46, 46); line-height: 25.7143px;\">Perayaan hari jadi Kota Bekasi memberikan suasana yang berbeda, terus melakukan pembangunan demi menggerakkan roda perekonomian yang mengarah pada kesejahteraan masyarakat Kota Bekasi. PDAM Tirta Patriot sebagai operator penyedia air bersih Kota Bekasi turut serta mendukung program pemerintah dalam penyediaan air bersih.</span></span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&ldquo;Jangan hanya profit yang di cari penyedia layanan air bersih dalam hal ini PDAM Tirta Patriot, akan tetapi pemerataan air bersih yang dapat dinikmati oleh masyarakat juga harus diberikan,&rdquo; jelas Rahmat Effendi.</span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Setitik pembangunan yang sudah dilakukan diharapkan dapat meningkatkan kenyamanan dalam pelayanan kepada masyarakat, termasuk peningkatan jumlah rumah tangga yang nantinya dapat menerima layanan air bersih dari PDAM Tirta Patriot.</span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Sementara itu, dari pihak Climater water and Energy team leader USAID Indonesia, Brian Duza mengatakan bahwa, realiasi instalasi PDAM baru sebagai bagian penyediaaan air minum yang ber kapasitas 200 liter per detik dapat mencakup tiga wilayah, diantaranya&nbsp; Bintara, Kanji dan sebagian Summarecon Bekasi.</span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dengan pembangunan WTP Teluk Buyung, nantinya sekitar 15.000 rumah tangga akan dapat terlayani air bersih di Kota&nbsp; Bekasi. Sementara, di Indonesia masih banyak masyarakat yang belum mendapatkan jangkauan air bersih dari PDAM,<span  border-box; line-height: 25.7143px;\">&nbsp;kendala keterbatasan cakupan air bersih diantaranya&nbsp; kapasitas air dan sistem alirannya. Hal ini kata dia, akibat keterbatasan dana dan banyaknya jumlah penduduk yang ada di Indonesia.</span></span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\"><span id=\"yui_3_16_0_1_1457662721762_4370\"  border-box; line-height: 25.7143px;\">Ia berharap, dengan dibangunnya WTP Teluk Buyung akan dapat memperluas cakupan air minum bersih di Kota Bekasi.</span></span></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Sekadar diinformasikan, proyek WTP Teluk Buyung sendiri lokasinya masih berada dalam komplek kantor PDAM Patriot dengan jumlah anggaran yang akan digelontorkan untuk pembangunan sebesar Rp 9,4 Miliar dengan rencana pembangunan mencapai 340 hari atau hampir satu tahun ke depan. (ndoet/tnc/ronz)</span></span></div>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-16 04:24:00', '2016-11-16 04:24:00', NULL),
('eb3bc918-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sejarah Kota Bekasi', 'sejarah-kota-bekasi', 'Wilayah Bekasi tercatat sebagai daerah yang banyak memberi infirmasi tentang keberadaan Tatar Sunda pada masa lampau. Diantaranya dengan ditemukannya empat prasasti yang dikenal dengan nama Prasasti K', '<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span .=\"\" 0px=\"\" 1567-1579=\"\" 669-723=\"\" adalah=\"\" ahli=\"\" asal=\"\" atau=\"\" bekasi=\"\" bogor=\"\" cimanuk=\"\" daerah=\"\" dan=\"\" dayeuh=\"\" di=\"\" disebut=\"\" dulu=\"\" font-family:=\"\" font-size:=\"\" generasi=\"\" hingga=\"\" ibukota=\"\" indramayu.=\"\" ini=\"\" inilah=\"\" itulah=\"\" jayagiri=\"\" ke=\"\" ke-40=\"\" kerajaan=\"\" leatak=\"\" line-height:=\"\" luas=\"\" maharaja=\"\" margin:=\"\" mencakup=\"\" menurunkan=\"\" menurut=\"\" p=\"\" para=\"\" pendiri=\"\" pula=\"\" ragumulya=\"\" raja=\"\" raja-raja=\"\" ratu=\"\" sampai=\"\" sebagai=\"\" sebutan=\"\" sejarah=\"\" sekarang.dayeuh=\"\" seterusnya=\"\" sunda=\"\" sundasembawa=\"\" sungai=\"\" tarumanagara=\"\" tarusbawa=\"\" tempo=\"\" text-align:=\"\" wilayah=\"\" yaitu=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Wilayah Bekasi tercatat sebagai daerah yang banyak memberi infirmasi tentang keberadaan Tatar Sunda pada masa lampau. Diantaranya dengan ditemukannya empat prasasti yang dikenal dengan nama Prasasti Kebantenan. Keempat prasasti ini merupakan keputusan (piteket) dari Sri Baduga Maharaja (Prabu Siliwangi, Jayadewa 1482-1521 M) yang ditulis dalam lima lembar lempeng tembaga. Sejak abad ke 5 Masehi pada masa Kerajaan Tarumanagara abad kea 8 Kerajaan Galuh, dan Kerajaan Pajajaran pada abad ke 14, Bekasi menjadi wilayah kekuasaan karena merupakan salah satu daerah strategis, yakni sebagai penghubung antara pelabuhan Sunda Kelapa (Jakarta).<br br=\"\" />\n<br font-weight:=\"\" span=\"\" />\n<span br=\"\" font-weight:=\"\" sebelum=\"\" sejarah=\"\" tahun=\"\">Sejarah Tahun 1949 sampai Terbentuknya Kota Bekasi</span><br br=\"\" />\nSejarah setelah tahun 1949, ditandai dengan aksi unjuk rasa sekitar 40.000 rakyat Bekasi pada tanggal 17 Februari 1950 di alum-alun Bekasi. Hadir pada acara tersebut Bapak Mu&rsquo;min sebagai Residen Militer Daerah V. Inti dari unjuk rasa tersebut adalah penyampaian pernyataan sikap sebagai berikut :</span></span></p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span agar=\"\" bekasi=\"\" bekasi.=\"\" belakang=\"\" berdiri=\"\" br=\"\" di=\"\" font-family:=\"\" jatinegara=\"\" kabupaten=\"\" kepada=\"\" kesatuan=\"\" mengajukan=\"\" menjadi=\"\" negara=\"\" pemerintah=\"\" pusat=\"\" rakyat=\"\" republik=\"\" tetap=\"\" usul=\"\">Selanjutnya berdasarkan hasil pemilihan terhitung mulai tanggal 23 Pebruari 1998 Walikotamadya Kepala Daerah Tingkat II Bekasi definitif dijabat oleh Bapak Drs. H Nonon Sonthanie (1998-2003). Setelah pemilihan umum berlangsung terpilihlah Walikota dan Wakil Walikota Bekasi yaitu : Akhmad Zurfaih dan Moechtar Muhammad (perode 2003 - 2008).</span></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:29:00', '2016-11-21 11:29:00', NULL),
('eb3bc978-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Lambang Daerah Kota Bekasi', 'lambang-daerah-kota-bekasi', 'Melalui Peraturan Daerah Kota Bekasi Nomor : 01 Tahun 1998 disahkanlah lambang daerah Kota Bekasi. Lambang tersebut berbentuk perisai dengan warna dasar hijau muda dan biru langit yang berarti harapan', '<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Melalui Peraturan Daerah Kota Bekasi Nomor : 01 Tahun 1998 disahkanlah lambang daerah Kota Bekasi. Lambang tersebut berbentuk perisai dengan warna dasar hijau muda dan biru langit yang berarti harapan masa depan dan keluasan wawasan serta jernih pikiran. Sesanti &quot; KOTA PATRIOT &quot; artinya adalah semangat pengabdian dalam perjuangan bangsa.</p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">a. Bambu runcing berujung lima yang berdiri tegak mempunyai dua makna :</p>\n\n<ul>\n <li font-size:=\"\" span=\"\"><span 01=\"\" 0px=\"\" 1998=\"\" :=\"\" adalah=\"\" artinya=\"\" bekasi=\"\" bekasi.=\"\" berarti=\"\" berbentuk=\"\" biru=\"\" daerah=\"\" dalam=\"\" dan=\"\" dasar=\"\" dengan=\"\" depan=\"\" disahkanlah=\"\" font-family:=\"\" font-size:=\"\" harapan=\"\" hijau=\"\" jernih=\"\" keluasan=\"\" kota=\"\" lambang=\"\" langit=\"\" line-height:=\"\" margin:=\"\" masa=\"\" melalui=\"\" muda=\"\" nomor=\"\" p=\"\" patriot=\"\" pengabdian=\"\" peraturan=\"\" perisai=\"\" perjuangan=\"\" pikiran.=\"\" semangat=\"\" serta=\"\" sesanti=\"\" tahun=\"\" tersebut=\"\" text-align:=\"\" warna=\"\" wawasan=\"\" yang=\"\">Melambangkan hubungan vertikal Mahluk dengan Khaliknya (Manusia dengan Tuhannya) yang mencerminkan masyarakat Bekasi yang religius.</span></li>\n</ul>\n\n<ul>\n <li font-size:=\"\" span=\"\"><span 01=\"\" 0px=\"\" 1998=\"\" :=\"\" adalah=\"\" artinya=\"\" bekasi=\"\" bekasi.=\"\" berarti=\"\" berbentuk=\"\" biru=\"\" daerah=\"\" dalam=\"\" dan=\"\" dasar=\"\" dengan=\"\" depan=\"\" disahkanlah=\"\" font-family:=\"\" font-size:=\"\" harapan=\"\" hijau=\"\" jernih=\"\" keluasan=\"\" kota=\"\" lambang=\"\" langit=\"\" line-height:=\"\" margin:=\"\" masa=\"\" melalui=\"\" muda=\"\" nomor=\"\" p=\"\" patriot=\"\" pengabdian=\"\" peraturan=\"\" perisai=\"\" perjuangan=\"\" pikiran.=\"\" semangat=\"\" serta=\"\" sesanti=\"\" tahun=\"\" tersebut=\"\" text-align:=\"\" warna=\"\" wawasan=\"\" yang=\"\"><span 0px=\"\" berikut=\"\" daerah=\"\" dalam=\"\" di=\"\" font-family:=\"\" font-size:=\"\" lambang=\"\" line-height:=\"\" lukisan-lukisan=\"\" margin:=\"\" merupakan=\"\" p=\"\" sebagai=\"\" terdapat=\"\" tersebut=\"\" text-align:=\"\" unsur-unsur=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 2=\"\" bambu=\"\" berdiri=\"\" berujung=\"\" dengan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" kokoh=\"\" lima=\"\" list-style:=\"\" makna=\"\" margin:=\"\" mempunyai=\"\" padding-left:=\"\" padding-right:=\"\" runcing=\"\" tegak=\"\" ul=\"\" yang=\"\"><span bekasi=\"\" dengan=\"\" font-family:=\"\" hubungan=\"\" khaliknya=\"\" li=\"\" mahluk=\"\" manusia=\"\" masyarakat=\"\" melambangkan=\"\" mencerminkan=\"\" vertikal=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Melambangkan semangat patriotisme rakyat Bekasi dalam merebut dan mempertahankan kemerdekaan Bangsa dan Negara yang tidak kenal menyerah sehingga Bekasi menyandang predikat sebagai Kota Patriot.</span></span></span></span></span></span></li>\n</ul>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span 01=\"\" 0px=\"\" 1998=\"\" :=\"\" adalah=\"\" artinya=\"\" bekasi=\"\" bekasi.=\"\" berarti=\"\" berbentuk=\"\" biru=\"\" daerah=\"\" dalam=\"\" dan=\"\" dasar=\"\" dengan=\"\" depan=\"\" disahkanlah=\"\" font-family:=\"\" font-size:=\"\" harapan=\"\" hijau=\"\" jernih=\"\" keluasan=\"\" kota=\"\" lambang=\"\" langit=\"\" line-height:=\"\" margin:=\"\" masa=\"\" melalui=\"\" muda=\"\" nomor=\"\" p=\"\" patriot=\"\" pengabdian=\"\" peraturan=\"\" perisai=\"\" perjuangan=\"\" pikiran.=\"\" semangat=\"\" serta=\"\" sesanti=\"\" tahun=\"\" tersebut=\"\" text-align:=\"\" warna=\"\" wawasan=\"\" yang=\"\"><span 0px=\"\" berikut=\"\" daerah=\"\" dalam=\"\" di=\"\" font-family:=\"\" font-size:=\"\" lambang=\"\" line-height:=\"\" lukisan-lukisan=\"\" margin:=\"\" merupakan=\"\" p=\"\" sebagai=\"\" terdapat=\"\" tersebut=\"\" text-align:=\"\" unsur-unsur=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 2=\"\" bambu=\"\" berdiri=\"\" berujung=\"\" dengan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" kokoh=\"\" lima=\"\" list-style:=\"\" makna=\"\" margin:=\"\" mempunyai=\"\" padding-left:=\"\" padding-right:=\"\" runcing=\"\" tegak=\"\" ul=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">b.</span>&nbsp;Perisai segi lima melambangkan ketahanan fisik dan mental masyarakat Bekasi dalam menghadapi segala macam ancaman, gangguan, halangan dan tantangan yang datang dari manapun juga terhadap kelangsungan hidup Bangsa dan Negara Republik Indonesia yang berdasarkan Pancasila.</span></span></span></span></p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span 01=\"\" 0px=\"\" 1998=\"\" :=\"\" adalah=\"\" artinya=\"\" bekasi=\"\" bekasi.=\"\" berarti=\"\" berbentuk=\"\" biru=\"\" daerah=\"\" dalam=\"\" dan=\"\" dasar=\"\" dengan=\"\" depan=\"\" disahkanlah=\"\" font-family:=\"\" font-size:=\"\" harapan=\"\" hijau=\"\" jernih=\"\" keluasan=\"\" kota=\"\" lambang=\"\" langit=\"\" line-height:=\"\" margin:=\"\" masa=\"\" melalui=\"\" muda=\"\" nomor=\"\" p=\"\" patriot=\"\" pengabdian=\"\" peraturan=\"\" perisai=\"\" perjuangan=\"\" pikiran.=\"\" semangat=\"\" serta=\"\" sesanti=\"\" tahun=\"\" tersebut=\"\" text-align:=\"\" warna=\"\" wawasan=\"\" yang=\"\"><span 0px=\"\" berikut=\"\" daerah=\"\" dalam=\"\" di=\"\" font-family:=\"\" font-size:=\"\" lambang=\"\" line-height:=\"\" lukisan-lukisan=\"\" margin:=\"\" merupakan=\"\" p=\"\" sebagai=\"\" terdapat=\"\" tersebut=\"\" text-align:=\"\" unsur-unsur=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">c.</span>&nbsp;Segi empat melambangkan Prasasti Perjuangan Kerawang Bekasi.</span></span></p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">d.</span>&nbsp;Pilar Batas Wilayah.</p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">e.</span>&nbsp;Padi dan Buah-buahan melambangkan jumlah Kecamatan dan Kelurahan / Desa pada saat membentuk Kota Bekasi.</p>\n\n<ul font-family:=\"\" font-size:=\"\" li=\"\" list-style:=\"\" margin:=\"\" padding-left:=\"\" padding-right:=\"\">\n <li><span font-family:=\"\" font-size:=\"\" span=\"\">Buah-buahan berjumlah 7 (tujuh) besar dan 1 (satu) kecil melambangkan 7 Kecamatan ; Pondok Gede, Jati Asih, Bantar Gebang, Bekasi Timur, Bekasi Selatan, Bekasi Barat dan Bekasi Utara serta 1 Kecamatan Pembantu ; Jati Sampurna.</span></li>\n <li font-size:=\"\" span=\"\">Padi berjumlah 50 (lima puluh) butir melambangkan 50 kelurahan /desa.</li>\n <li font-size:=\"\" span=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span air=\"\" akan=\"\" atau=\"\" baris=\"\" berhenti=\"\" br=\"\" daerah=\"\" dan=\"\" dinamika=\"\" dua=\"\" font-weight:=\"\" gelombang=\"\" laut=\"\" masyarakat=\"\" melambangkan=\"\" membangun=\"\" pemerintah=\"\" pernah=\"\" riak=\"\" tidak=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\"><span :=\"\" color:=\"\" daerah=\"\" dan=\"\" kemuliaan=\"\" li=\"\" menunjukkan=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span color:=\"\" font-weight:=\"\" span=\"\">Biru Langit</span></span>&nbsp;: Keluasan wawasan dan kejernihan pikiran serta menunjukkan zone Industri.</span></span></span></span></span></span></span></li>\n <li font-size:=\"\" span=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span air=\"\" akan=\"\" atau=\"\" baris=\"\" berhenti=\"\" br=\"\" daerah=\"\" dan=\"\" dinamika=\"\" dua=\"\" font-weight:=\"\" gelombang=\"\" laut=\"\" masyarakat=\"\" melambangkan=\"\" membangun=\"\" pemerintah=\"\" pernah=\"\" riak=\"\" tidak=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">Putih</span>&nbsp;: Kesucian perjuangan.</span></span></span></span></span></li>\n <li font-size:=\"\" span=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\"><span :=\"\" berkorban=\"\" color:=\"\" daerah=\"\" dan=\"\" keberanian=\"\" li=\"\" menunjukkan=\"\" pertanian=\"\" serta=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span color:=\"\" font-weight:=\"\" span=\"\">Hijau Muda</span></span>: Harapan masa depan serta menunjukkan daerah Pertanian dan Hortikultura</span></span></span></span></span></li>\n <li font-size:=\"\" span=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span font-family:=\"\" font-weight:=\"\" span=\"\">Hitam&nbsp;</span>: Ketegaran patriot sejati.</span></span></span></li>\n</ul>\n\n<p><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\">f. Tali simpul berjumlah 10 (sepuluh) yang mengikat ujung tingkai padi dan buah-buahan melambangkan tanggal hari jadi,3 buah anak tangga penyangga bambu runcing melambangkan bulan Hari jadi Kota Bekasi.</span></span></span></span></span></span></p>\n\n<p><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\"><span 0px=\"\" 50=\"\" berjumlah=\"\" butir=\"\" font-family:=\"\" font-size:=\"\" kelurahan=\"\" lima=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" p=\"\" padi=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span 0px=\"\" 10=\"\" 3=\"\" anak=\"\" bambu=\"\" berjumlah=\"\" buah=\"\" buah-buahan=\"\" bulan=\"\" dan=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" hari=\"\" jadi=\"\" kota=\"\" line-height:=\"\" margin:=\"\" melambangkan=\"\" mengikat=\"\" p=\"\" padi=\"\" penyangga=\"\" runcing=\"\" simpul=\"\" tali=\"\" tangga=\"\" tanggal=\"\" tangkai=\"\" text-align:=\"\" ujung=\"\" yang=\"\">g. Dua baris Gelombang Laut atau Riak Air melambangkan dinamika Masyarakat dan Pemerintah Daerah yang tidak pernah berhenti membangun Daerah dan Bangsanya.&nbsp;</span></span></span></span></span></span></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:31:00', '2016-11-21 11:31:00', NULL),
('eb3bc9c7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Peta Administrasi Wilayah Kota Bekasi', 'peta-administrasi-wilayah-kota-bekasi', 'Download &nbsp;&gt;&gt;PETA ADMINISTRASI&nbsp;WILAYAH KOTA BEKASI\n\nDownload &gt;&gt; PETA CITRA BEKASI\n', '<p><span font-family:=\"\" font-size:=\"\" font-weight:=\"\" span=\"\">Download &nbsp;&gt;&gt;</span><a href=\"https://drive.bekasikota.go.id/index.php/s/vOkA6Yd8yph7u7M\"><u font-family:=\"\" font-size:=\"\" font-weight:=\"\" span=\"\"><span 0px=\"\" a=\"\" background:=\"\" color:=\"\" font-size:=\"\" href=\"http://bekasikota.go.id/files/fck/peta_wilayah_administrasi(2).pdf\" text-decoration:=\"\">PETA ADMINISTRASI&nbsp;WILAYAH KOTA BEKASI</span></u></a></p>\n\n<p>Download &gt;&gt; <a href=\"https://drive.bekasikota.go.id/index.php/s/HLhV1NrF0MuHcch\">PETA CITRA BEKASI</a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:32:00', '2016-11-21 11:32:00', NULL),
('eb3bca12-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Visi & Misi', 'visi-misi', 'Visi\r\n\r\n&ldquo;Bekasi Maju, Sejahtera dan Ihsan&rdquo;\r\n\r\nVisi ini dijelaskan sebagai berikut :\r\n\r\n&ldquo;Bekasi Maju&rdquo;&nbsp;menggambarkan pembangunan Kota Bekasi dan kehidupan warga yang dinamis', '<p>Visi</p>\r\n\r\n<p>&ldquo;Bekasi Maju, Sejahtera dan Ihsan&rdquo;</p>\r\n\r\n<p>Visi ini dijelaskan sebagai berikut :</p>\r\n\r\n<p>&ldquo;Bekasi Maju&rdquo;&nbsp;menggambarkan pembangunan Kota Bekasi dan kehidupan warga yang dinamis, inovatif dan kreatif yang didukung ketersediaan prasarana dan sarana sebagai bentuk perwujudan kota yang maju.</p>\r\n\r\n<p>&ldquo;Bekasi Sejahtera&rdquo;&nbsp;menggambarkan derajat kehidupan warga Kota Bekasi yang meningkat dengan terpenuhinya kebutuhan dasar pendidikan, kesehatan, terbukanya kesempatan kerja dan berusaha, serta lingkungan fisik, social dan religious sebagai bentuk perwujudan masyarakat yang sejahtera.</p>\r\n\r\n<p>&ldquo;Bekasi Ihsan&rdquo;&nbsp;menggambarkan situasi terpelihara dan menguatnya nilai, sikap dan perilaku untuk berbuat baik dalam lingkup individu, keluarga dan masyarakat Kota Bekasi. Kedisiplinan, ketertiban social, keteladanan dan partisipasi masyarakat dalam pembangunan tumbuh seiring dengan meningkatnya tata kelola pemerintahan yang baik untuk mewujudkan kehidupan yang beradab</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Misi</p>\r\n\r\n<p>1. Menyelenggarakan tata kelelola kepemerintahan yang baik</p>\r\n\r\n<p>Misi ini bermakna bahwa tata kelola kepemerintahan dalam mewujudkan Visi Kota Bekasi dilakukan melalui fungsi pengaturan, pelayanan, pemberdayaan masyarakat, dan pembangunan, menempatkan aparat ur sebagai pamong praja yang menjunjung tinggi integritas terhadap amanah, tugas, dan tanggungjawab, berdasarkan 10 (sepuluh) prinsip Good Governance, yakni: ( 1) Partisipasi masyarakat; (2) Tegaknya supremasi hukum; (3) Transparansi; (4) Kesetaraan; (5) Daya tanqqap kepada stakeholders; (6) Berorientasi pada visi; (7) Akuntabilitas: (8) Pengawasan; (9) Efektivitas dan efisiensi: (10) Profesionalisme.</p>\r\n\r\n<p>Pendekatan yang dilakukan untuk aktualisasi misi ini melalui penataan sistem, peningkatan kinerja dan penguatan integritas aparatur.</p>\r\n\r\n<p>2.&nbsp;.&nbsp;Membangun Prasarana dan sarana yang serasi &nbsp;dengan dinamika dan pertumbuhan kota</p>\r\n\r\n<p>Misi ini bermakna bahwa pembangunan prasarana diarahkan untuk terpenuhinya kelengkapan dasar fisik lingkungan kota bagi kehidupan yang layak, sehat, aman, dan nyaman; terpenuhinya sarana perkotaan untuk mendukung penyelenggaraan dan pengembangan kehidupan sosial, budaya, dan ekonomi; dan terpenuhinya kelengkapan penunjang (utilitas) untuk pelayanan warga kota. Misi ini juga mengarahkan pembangunan prasarana dan sarana yang meningkat dan serasi, untuk memenuhi kehidupan warga kota yang dinamis, inovatif, dan kreatif, denqan memperhatikan prinsip pengelolaan, pengendalian, dan pelestarian lingkungan hidup, dalam mewujudkan kota yang maju, tumbuh dan berkembang secara berkelanjutan.</p>\r\n\r\n<p>3. Meningkatkan kehidupan sosial masyarakat melalui layanan pendidikan, kesehatan, dan layanan sosial lainnya.</p>\r\n\r\n<p>Misi ini bermakna bahwa layanan pendidikan, kesehatan, dan layanan sosial lainnya diarahkan untuk meningkatkan derajat kehidupan sosial masyarakat, seiring dengan terbangunnya kehidupan keluarga sejahtera, terkelolanya persoalan dan dampak sosial perkotaan, meningkatnya partisipasi perempuan dan peran serta pemuda dalam pembangunan, aktivitas olahraga pendidikan, rekreasi. dan prestasi. serta aktualisasi budaya daerah sebagai fungsi sosial, normatif, dan apresiatif.</p>\r\n\r\n<p>4. Meningkatkan perekonomian melalui pengembangan usaha mikro, kecil, dan menengah, peningkatan investasi, dan penciptaan iklim usaha yang kondusif.</p>\r\n\r\n<p>Misi ini bermakna bahwa upaya untuk meningkatkan perkonomian ditempuh melalui peningkatan kapasitas dan perluasan sektor usaha bagi pelaku Usaha Mikro, Kecil dan Menengah (UMKMJ, pengembangan industri kreatif, peningkatan daya tarik investasi, dan penciptaan iklim usaha yang kondusif, yang bermuara pada pembentukan lapangan kerja baru dan kesempatan berusaha, terbentuknya daya saing perekonomian kota, dan laju pertumbuhan ekonomi yang meningkat.</p>\r\n\r\n<p>5. Mewujudkan kehidupan masyarakat yang aman, tertib, tenteram dan damai.</p>\r\n\r\n<p>Misi ini bermakna bahwa dinamika pembangunan dan kehidupan warga Kota Bekasi harus diimbangi dengan upaya pengendalian terhadap potensi kerawanan sosial, gangguan ketertiban, penegakan perda, penanggulangan bencana, kesatuan dan ketahanan bangsa, kerukunan hidup dan umat beragama, serta meningkatnya partisipasi masyarakat dalam kegiatan pembangunan.</p>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:33:00', '2016-11-21 11:33:00', NULL),
('eb3bca67-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kondisi Geografis Wilayah Kota Bekasi', 'kondisi-geografis-wilayah-kota-bekasi', 'Luas Wilayah dan Letak Geografis\nKota Bekasi memiliki luas wilayah sekitar 210,49 km2, dengan batas wilayah Kota Bekasi adalah:\n&bull; Sebelah Utara : Kabupaten Bekasi\n&bull; Sebelah Selatan : Kabupat', '<p>Luas Wilayah dan Letak Geografis<br />\nKota Bekasi memiliki luas wilayah sekitar 210,49 km2, dengan batas wilayah Kota Bekasi adalah:<br />\n&bull; Sebelah Utara : Kabupaten Bekasi<br />\n&bull; Sebelah Selatan : Kabupaten Bogor dan Kota Depok<br />\n&bull; Sebelah Barat : Provinsi DKI Jakarta<br />\n&bull; Sebelah Timur : Kabupaten Bekasi<br />\nLetak geografis : 106o48&rsquo;28&rsquo;&rsquo; &ndash; 107o27&rsquo;29&rsquo;&rsquo; Bujur Timur dan 6o10&rsquo;6&rsquo;&rsquo; &ndash; 6o30&rsquo;6&rsquo;&rsquo; Lintang Selatan.</p>\n\n<p>Topografi<br />\nKondisi Topografi kota Bekasi dengan kemiringan antara 0 &ndash; 2 % dan terletak pada ketinggian antara 11 m &ndash; 81 m di atas permukaan air laut.<br />\n&bull; Ketinggian &gt;25 m : Kecamatan Medan Satria, Bekasi Utara, Bekasi Selatan, Bekasi Timur dan Pondok Gede<br />\n&bull; Ketinggian 25 &ndash; 100 m : Kecamatan Bantargebang, Pondok Melati, Jatiasih</p>\n\n<p>Wilayah dengan ketinggian dan kemiringan rendah yang menyebabkan daerah tersebut banyak genangan, terutama pada saat musim hujan yaitu: di Kecamatan Jatiasih, Bekasi Timur, Rawalumbu, Bekasi Selatan, Bekasi Barat, dan Kecamatan Pondok Melati.</p>\n\n<p>Geologi dan Jenis Tanah<br />\nStruktur geologi wilayah Kota Bekasi didominasi oleh pleistocene volcanik facies namun terdapat dua kecamatan yang memiliki karakteristik struktur lainnya yaitu:<br />\n&bull; Bekasi Utara : Struktur Aluvium<br />\n&bull; Bekasi Timur : Struktur Miocene Sedimentary Facies<br />\nDi Bekasi Selatan terdapat sumur gas JNG-A (106o 55&rsquo; 8,687&rdquo; BT; 06o 20&rsquo;54,051&rdquo;) dan Sumur JNGB (106o 55&rsquo; 21,155&rdquo; BT; 06o 21&rsquo; 10,498&rdquo;)</p>\n\n<p>Hidrologi dan klimatologi<br />\nKondisi hidrologi Kota Bekasi dibedakan menjadi dua:</p>\n\n<p>1. Air permukaan, mencakup kondisi air hujan yang mengalir ke sungai-sungai.</p>\n\n<p>Wilayah Kota Bekasi dialiri 3 (tiga) sungai utama yaitu Sungai Cakung, Sungai Bekasi dan Sungai Sunter, beserta anak-anak sungainya. Sungai Bekasi mempunyai hulu di Sungai Cikeas yang berasal dari gunung pada ketinggian kurang lebih 1.500 meter dari permukaan air.</p>\n\n<p>Air permukaan yang terdapat di wilayah Kota Bekasi meliputi sungai/kali Bekasi dan beberapa sungai/kali kecil serta saluran irigasi Tarum Barat yang selain digunakan untuk mengairi sawah juga merupakan sumber air baku bagi kebutuhan air minum wilayah Bekasi (kota dan kabupaten) dan wilayah DKI Jakarta. Kondisi air permukaan kali Bekasi saat ini tercemar oleh limbah industri yang terdapat di bagian selatan wilayah Kota Bekasi (industri di wilayah Kabupaten Bogor).</p>\n\n<p>2. Air tanah</p>\n\n<p>Kondisi air tanah di wilayah Kota Bekasi sebagian cukup potensial untuk digunakan sebagai sumber air bersih terutama di wilayah selatan Kota Bekasi, tetapi untuk daerah yang berada di sekitar TPA Bantargebang kondisi air tanahnya kemungkinan besar sudah tercemar.</p>\n\n<p>Wilayah Kota Bekasi secara umum tergolong pada iklim kering dengan tingkat kelembaban yang rendah. Kondisi lingkungan sehari-hari sangat panas. Hal ini terlebih dipengaruhi oleh tata guna lahan yang meningkat terutama industri/perdagangan dan permukiman. Temperatur harian diperkirakan berkisar antara 24 &ndash; 33&deg; C.</p>\n\n<p>Permukiman</p>\n\n<p>Jumlah Penduduk Kota Bekasi saat ini lebih dari 2,2 juta jiwa yang tersebar di 12 kecamatan, yaitu Kecamatan Pondok Gede, Jati Sampurna, Jati Asih, Bantar Gebang, Bekasi Timur, Rawa Lumbu, Bekasi Selatan, Bekasi Barat, Medan Satria, Bekasi Utara, Mustika Jaya, Pondok Melati.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:33:00', '2016-11-21 11:33:00', NULL),
('eb3bcab7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Go To Bekasi Kota', 'go-to-bekasi-kota', '\r\n\r\nBandara Soekarno-Hatta\r\n\r\nDari Bandara Soekarno Hatta Jakarta menuju arah Tol Dalam Kota dan masuk Tol Cikampek. Terdapat dua pintu keluar tol, yaitu Tol Bekasi Barat dan Tol Bekasi Timur. Jarak d', '<p><img alt=\"\" src=\"http://www.bekasikota.go.id/files/fck/bandara.JPG\"  150px; height: 151px;\" /></p>\r\n\r\n<p>Bandara Soekarno-Hatta</p>\r\n\r\n<p>Dari Bandara Soekarno Hatta Jakarta menuju arah Tol Dalam Kota dan masuk Tol Cikampek. Terdapat dua pintu keluar tol, yaitu Tol Bekasi Barat dan Tol Bekasi Timur. Jarak dekat menuju kantor Walikota Bekasi adalah dengan keluar tol Bekasi Barat. Alternatif lainnya adalah menggunakan Angkutan Umum Bus Damri rute Bandara &ndash; Bekasi. Pool terminal bus Damri berada di parkiran mall Giant &ndash; depan pintu keluar Tol Bekasi Barat. Jarak tempuh Bandara &ndash; Kota Bekasi: &plusmn;2,5 jam.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"http://www.bekasikota.go.id/files/fck/stasiun.JPG\"  150px; height: 150px;\" />&nbsp;</p>\r\n\r\n<p>Stasiun Kereta Api Gambir &ndash; Jakarta</p>\r\n\r\n<p>KRL ekonomi AC berangkat dari Stasiun KA Jakarta Kota ke Bekasi via Stasiun Gambir.</p>\r\n\r\n<p>Gayabaru Malam Selatan<br />\r\nTarif Jakarta Kota &ndash; Bekasi : Ekonomi &ndash; Rp. 26.000<br />\r\nJadwal Kereta : KA 144 Berangkat: 12.00 (Jakartakota), Datang: 12.47 (Bekasi)</p>\r\n\r\n<p>Serayu<br />\r\nTarif Jakartakota &ndash; Bekasi : Ekonomi &ndash; Rp. 19.000<br />\r\nJadwal Kereta : KA 170 Berangkat: 08.25 (Jakartakota) , Datang: 09.06 (Bekasi)<br />\r\nKA 172 Berangkat: 20.20 (Jakartakota) , Datang: 21.03 (Bekasi)</p>\r\n\r\n<p><img alt=\"\" src=\"http://www.bekasikota.go.id/files/fck/terminal.JPG\"  150px; height: 150px;\" />&nbsp;</p>\r\n\r\n<p>Terminal Bis Kota Bekasi</p>\r\n\r\n<p>Letak terminal berada di tengah kota, berada di<br />\r\nJln Cut Meutia Kel. Margahayu,<br />\r\nBekasi Timur<br />\r\nBekasi 17113.</p>\r\n\r\n<p>Kemacetan sering terjadi di sekitar jalan terminal, terutama saat perayaan hari besar dan jam kerja.<br />\r\n&nbsp;</p>\r\n\r\n<p><em>(Sumber : Bappeda Kota Bekasi)</em></p>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:34:00', '2016-11-21 11:34:00', NULL),
('eb3bcb02-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Bekasi', 'walikota-bekasi', 'NAMA:&nbsp;&nbsp;\r\n\r\nDr. H. RAHMAT EFFENDI\r\n\r\nTEMPAT TANGGAL LAHIR:\r\n\r\nBEKASI, 3 PEBRUARI 1964\r\n\r\nALAMAT: &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\r\n\r\nJL. RAYA PEKAYON INDAH BLOK DD NO 37 &ndash; 39\r\n\r\nPEKAY', '<p><em>NAMA:&nbsp;&nbsp;</em></p>\r\n\r\n<p>Dr. H. RAHMAT EFFENDI</p>\r\n\r\n<p><em>TEMPAT TANGGAL LAHIR:</em></p>\r\n\r\n<p>BEKASI, 3 PEBRUARI 1964</p>\r\n\r\n<p><em>ALAMAT: &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</em></p>\r\n\r\n<p>JL. RAYA PEKAYON INDAH BLOK DD NO 37 &ndash; 39</p>\r\n\r\n<p>PEKAYON JAYA &ndash; BEKASI SELATAN</p>\r\n\r\n<p><em>RIWAYAT PENDIDIKAN:&nbsp;</em></p>\r\n\r\n<p>SD NEGERI TAHUN 1979</p>\r\n\r\n<p>SMP TAHUN 1982</p>\r\n\r\n<p>SMA TAHUN 1985</p>\r\n\r\n<p>SARJANA S1 TAHUN 2000</p>\r\n\r\n<p>SARJANA S2 TAHUN 2006</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>SARJANA S3 TAHUN 2010</p>\r\n\r\n<p><em>PENGALAMAN ORGANISASI : &nbsp; &nbsp; &nbsp;</em></p>\r\n\r\n<p>KETUA LKMD PEKAYON JAYA</p>\r\n\r\n<p>KETUA PK&nbsp;GOLKAR BEKASI SELATAN</p>\r\n\r\n<p>KETUA DPD MKGR&nbsp;KOTA&nbsp;BEKASI</p>\r\n\r\n<p>KETUA DPD AMPI&nbsp;KOTA&nbsp;BEKASI</p>\r\n\r\n<p>WASEKJEN DPD MKGR</p>\r\n\r\n<p>PENGURUS KONI&nbsp;KOTA&nbsp;BEKASI</p>\r\n\r\n<p>KETUA PERBASI KOTA BEKASI</p>\r\n\r\n<p>PENGURUS DAERAH PSSI JAWA BARAT</p>\r\n\r\n<p>ANGGOTA RAPI KOTA BEKASI</p>\r\n\r\n<p>PENASEHAT ORARI KOTA BEKASI (YG1BKS)</p>\r\n\r\n<p>DEWAN PENASEHAT PEKAT&nbsp;INDONESIA&nbsp;BERSATU BEKASI</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>PENGALAMAN PEKERJAAN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</em></p>\r\n\r\n<p>ASSISTEN WAREHOUSING PT HALLIBURTON&nbsp;INDONESIA</p>\r\n\r\n<p>LOGISTIC SUPERVISOR PT HALLIBURTON&nbsp;INDONESIA</p>\r\n\r\n<p>DIREKTUR PT RAMPITA ADITAMA RIZKI</p>\r\n\r\n<p>ANGGOTA DPRD KOTA BEKASI 1999 &ndash; 2004</p>\r\n\r\n<p>KETUA DPRD KOTA BEKASI 2004 &ndash; 2008</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>JABATAN SEKARANG : &nbsp;&nbsp;</em></p>\r\n\r\n<p>WALIKOTA BEKASI</p>\r\n\r\n<p>KETUA DPP PARTAI GOLONGAN KARYA</p>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:47:00', '2016-11-21 11:47:00', NULL),
