('eb3bcb99-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sekretaris Daerah', 'sekretaris-daerah', '&nbsp;Sekretaris Daerah Kota Bekasi\r\n\r\n&nbsp;\r\n\r\nDrs. H. RAYENDRA SUKARMADJI, M.Si\r\n\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;19580724 198603 1 007\r\n', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px;\"><span  border-box; font-size: small;\">&nbsp;Sekretaris Daerah Kota Bekasi</span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px;\">&nbsp;</div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px;\"><span  border-box; font-size: small;\"><u  border-box;\"><span  border-box; line-height: 14.95px;\">Drs. H. RAYENDRA SUKARMADJI, M.Si</span></u></span></div>\r\n\r\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;19580724 198603 1 007</div>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:52:00', '2016-11-21 11:52:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bcbef-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sekretariat DPRD Kota Bekasi', 'sekretariat-dprd-kota-bekasi', 'Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah mengatur bahwa DPRD&nbsp; dan Kepala Daerah mempunyai kedudukan yang setara dan bersifat kemitraan. Dalam kedudukan kerja yang setaraf ant', '<p >Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah mengatur bahwa DPRD&nbsp; dan Kepala Daerah mempunyai kedudukan yang setara dan bersifat kemitraan. Dalam kedudukan kerja yang setaraf antara Eksekutif dan Legislatif tersebut, Sekretariat DPRD menempati posisi sebagai unsur Pemerintah Daerah yang bertugas memfasilitasi kinerja DPRD dalam melaksanakan tugas pokok dan fungsi yang meliputinya. Adapun tugas pokok dan fungsi DPRD adalah :&nbsp;<br />\r\n<br />\r\na.&nbsp;&nbsp; &nbsp;Bidang Legislasi, bersama Walikota&nbsp; menyusun Raperda menjadi Perda,<br />\r\nb.&nbsp;&nbsp; &nbsp;Bidang Anggaran, bersama Walikota&nbsp; menyusun RAPBD menjadi APBD, dan&nbsp;<br />\r\nc.&nbsp; Bidang Pengawasan Pelaksanaan Perda, APBD, Perundang-undangan dan Kebijakan Walikota &nbsp;<br />\r\n<br />\r\nDengan adanya tugas pokok dan fungsi dimaksud diatas, menunjukan bahwa DPRD adalah bagian dari penyelenggara Pemerintahan Daerah. Dalam posisi tersebut, Sekretariat DPRD berfungsi sebagai jembatan&nbsp; penghubung kerja antara DPRD dengan Pemerintah Daerah. Sehingga, dengan kata lain Sekretariat DPRD kedudukannya berdiri di atas dua telapak kaki, disatu pihak adalah unsur eksekutif sebagai SKPD dan dilain pihak sebagai fasilitator tugas-tugas legislatif serta bertanggungjawab secara operasional kepada Pimpinan DPRD.&nbsp;<br />\r\n<br />\r\n&nbsp; Proses pembangunan daerah harus melibatkan para pelaku pembangunan dan dilaksanakan secara akuntabel serta diarahkan untuk menyelesaikan permasalahan pembangunan di berbagai bidang. Sejalan dengan itu, maka pengertian kata Kreatif, Inovatif dan Partisiptif adalah:&nbsp;<br />\r\nKreatif :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &rdquo; Terwujudnya cara berfikir kreatif yang mampu memahami serta&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; dapat memberikan masukkan dengan beragam alternatif, yang mampu mencerminkan bahwa dimasa datang tugas pokok, dan fungsi Sekretraiat Dewan Perwakilan Rakyat Daerah Kota Bekasi tidak dimaknai secara sempit yaitu hanya secara administratif / ketatausahaan (Clerical Work) akan tetapi diarahkan pada dukungan, pemberimasukan dan mitra terkait pelaksanaan tugas fungsi legislasi, fungsi penganggaran dan fungsi pengawasan Dewan Perwakilan Rakyat Derah baik dari aspek teknis maupun akademis&rdquo;.&nbsp;<br />\r\nInovatif :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &rdquo; Sekretariat DPRD sebagai sumber inovasi lembaga legislatif mengoptimalkan peran public relationnya, melalui sikap proaktif dalam berkomunikasi dan berkoordinasi serta bersinergi dengan stakeholder guna mewujudkan keharmonisan, mengembangkan penerapan praktis nilai dan konteks ilmu pengetahuan yang baru, atau cara baru ke dalam Program/kegiatan untuk mendukung sinergitas eksekutif dan legislatif sebagai unsur penyelenggara Pemerintahan Daerah &rdquo;<br />\r\nPartisipatif :<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &ldquo; Merepresentasikan manajemen sekretariat DPRD yang mendorong SDM untuk turut serta secara aktif melaksanakan semua keputusan dan kegiatan-kegiatan yang telah ditetapkan. Selain itu Sekretariat DPRDharus bisa berkerjasama dengan Anggota DPRD Kota Bekasi. Bertukar ide didalam pemecahan masalah dan pembuatan keputusan. Dalam hal ini komunikasi dua arah ditingkatkan untuk meningkatkan kemampuan dalam melaksanakan tugas dan fungsi Sekretariat DPRD.<br />\r\n<br />\r\nSekretariat DPRD sebagai unsur Pemerintah Kota Bekasi terus menata diri agar kinerja DPRD Kota Bekasi dapat berjalan secara optimal. Pada tahun 2011, seiring dengan pelaksanaanPeraturan Daerah Kota Bekasi Nomor 04 Tahun 2010 tentang Perubahan Atas Peraturan Daerah Kota Bekasi Nomor 04 Tahun 2008 Tentang Sekretariat Daerah Dan Sekretariat Dewan Perwakilan Rakyat Daerah Kota Bekasi, Sekretariat DPRD Kota Bekasi telah dikembangkan strukturnya dari menjadi empat bagian dengan sepuluh sub bagian.<br />\r\n<br />\r\nPada tahun 2009 di DPRD Kota Bekasi juga terjadi masa transisi keanggotaan dari anggota DPRD periode 2004-2009 ke anggota DPRD 2009-2014 hasil Pemilihan Umum tahun 2009. Selain hal tersebut, juga terjadi dua perubahan Undang-Undang yang berpengaruh secara langsung terhadap kinerja DPRD Kota Bekasi, yaitu Undang-Undang Nomor 22 Tahun 2003 tentang Susunan dan Kedudukan Majelis Permusyawaratn Rakyat, Dewan Perwakilan Rakyat, Dewan Perwakilan Daerah dan Dewan Perwakilan Rakyat Daerah dan Undang-Undang Nomor 27 Tahun 2009 tentang Majelis Permusyawaratn Rakyat, Dewan Perwakilan Rakyat, Dewan Perwakilan Daerah dan Dewan Perwakilan Rakyat Daerah (Lembaran Negara Republik Indonesia Tahun 2009 Nomor 123, Tambahan Lembaran Negara Republik Indonesia Nomor 5043). Secara umum, kinerja DPRD Kota Bekasi sampai dengan bulan September 2015 dapat berjalan optimal.</p>\r\n\r\n<p>Untuk melaksanakan kegiatan Sekretariat DPRD Kota Bekasi pada tahun anggaran 2011, DPRD Kota Bekasi didukung oleh kondisi Pegawai dengan Jumlah seluruhnya =&nbsp; 78 orang,&nbsp;&nbsp; dengan rincian sebagai berikut&nbsp;&nbsp; :</p>\r\n\r\n<p>1. STATUS KEPEGAWAIAN :</p>\r\n\r\n<ul>\r\n <li>PNS&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;=&nbsp; &nbsp;&nbsp;&nbsp;&nbsp; 91 &nbsp; orang</li>\r\n <li>TKK &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; =&nbsp; &nbsp;&nbsp;&nbsp;&nbsp; 95&nbsp; orang</li>\r\n</ul>\r\n\r\n<p>2. PEMANGKU JABATAN STRUKTURAL</p>\r\n\r\n<ul>\r\n <li>Sekretaris DPRD (Esselon II) &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; =&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp; 1&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; orang</li>\r\n <li>Kepala Bagian (Esselon III) &nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp; =&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp; 4&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; orang&nbsp;</li>\r\n <li>Kepala Sub Bagian (Esselon IV) &nbsp;&nbsp; =&nbsp; &nbsp;&nbsp;&nbsp;&nbsp; 10 &nbsp;&nbsp;&nbsp;&nbsp; orang</li>\r\n</ul>\r\n\r\n<p>3. JABATAN FUNGSIONAL &nbsp; =&nbsp;&nbsp; &nbsp;Tidak Ada</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Alamat Sekretariat DPRD Kota Bekasi :</p>\r\n\r\n<p>Jl. Chairi Anwar No. 112 Bekasi. Telp : 021-88355761 / Fax :&nbsp; 021-88355762</p>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-21 11:53:00', '2016-11-21 11:53:00', NULL),
