('eb3bd124-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Bagian Humas', 'bagian-humas', 'Bagian Humas adalah salah satu bagian di Sekretariat&nbsp; Pemerintah Kota Bekasi&nbsp;&nbsp;&nbsp;\r\n\r\n&nbsp;\r\n\r\nBagian Humas terdiri dari tiga sub bagian yaitu:&nbsp;\r\n\r\n&nbsp;\r\n\r\n1. &nbsp;Sub Bagian', '<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: larger;\"><span  border-box; font-family: Tahoma;\"><big  border-box;\">Bagian Humas adalah salah satu bagian di Sekretariat&nbsp; Pemerintah Kota Bekasi&nbsp;</big>&nbsp;&nbsp;</span></span></p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;</p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: larger;\"><span  border-box; font-family: Tahoma;\"><big  border-box;\">Bagian Humas terdiri dari tiga sub bagian yaitu:</big>&nbsp;</span></span></p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;</p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: larger;\"><span  border-box; font-family: Tahoma;\"><big  border-box;\">1. &nbsp;Sub Bagian Publikasi</big>&nbsp;</span></span></p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: larger;\"><span  border-box; font-family: Tahoma;\"><big  border-box;\">2. &nbsp;Sub Bagian Hub. Eksternal</big></span></span></p>\r\n\r\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: larger;\"><span  border-box; font-family: Tahoma;\"><big  border-box;\">3.&nbsp; Sub Bagian&nbsp;Hub. Internal,Sandi dan Telekomunikasi</big></span></span></p>\r\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-22 04:58:00', '2016-11-22 04:58:00', NULL),
