\n   <p>(51,20%)</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p align=\"center\">13</p>\n   </td>\n   <td>\n   <p align=\"center\">Per 16 November 2015</p>\n   </td>\n   <td>\n   <p align=\"center\">Rp.1.102.639.472.989</p>\n\n   <p align=\"center\">(35,29%)</p>\n   </td>\n   <td>\n   <p>Rp.1.237.495.147.154</p>\n\n   <p>(78,96%)</p>\n   </td>\n   <td>\n   <p>Rp. 2.340.134.620.143</p>\n\n   <p>(49,88%)</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p align=\"center\">14</p>\n   </td>\n   <td>\n   <p align=\"center\">Per 19 November 2015</p>\n   </td>\n   <td>\n   <p>Rp.1.193.267.021.810</p>\n\n   <p>(38,20%)</p>\n   </td>\n   <td>\n   <p>Rp.1.240.053.397.154</p>\n\n   <p>(79,12%)</p>\n   </td>\n   <td>\n   <p>Rp. 2.433.320.418.964</p>\n\n   <p>(51,87%)</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p align=\"center\">15</p>\n   </td>\n   <td>\n   <p align=\"center\">Per 30 November 2015</p>\n   </td>\n   <td>\n   <p>Rp.1.273.876.699.385</p>\n\n   <p>(40,78%)</p>\n   </td>\n   <td>\n   <p>Rp.1.244.166.437.574</p>\n\n   <p>(79,39%)</p>\n   </td>\n   <td>\n   <p>Rp. 2.518.034.136.959</p>\n\n   <p>(53,67%)</p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p align=\"center\">16</p>\n   </td>\n   <td>\n   <p align=\"center\">Per 7 Desember 2015</p>\n   </td>\n   <td>\n   <p>Rp.1.361.048.958.025</p>\n\n   <p>(43,57%)</p>\n   </td>\n   <td>\n   <p>Rp.1.339.482.313.077</p>\n\n   <p>(85,47%)</p>\n   </td>\n   <td>\n   <p>Rp. 2.700.531.271.103</p>\n\n   <p>(57,56%)</p>\n   </td>\n  </tr>\n </tbody>\n</table>\n\n<p>&nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-23 19:18:00', '2016-11-23 19:18:00', NULL),
('eb3bdd51-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Realisasi Belanja Pemerintah Kota Bekasi Tahun 2016', 'realisasi-belanja-pemerintah-kota-bekasi-tahun-2016', 'Realisasi Belanja 22 Juli 2016 &nbsp; Download\n\nRekapitulasi Laporan Realisasi Penyerapan Anggaran 22 Juli 2016 &nbsp;Download\n', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Realisasi Belanja 22 Juli 2016 &nbsp; <a href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/REALISASI BELANJA 22 JULI 2016.pdf\"><em>Download</em></a></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Rekapitulasi Laporan Realisasi Penyerapan Anggaran 22 Juli 2016 &nbsp;<a href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/REKAPITULASI LAPORAN REALISASI PENYERAPAN ANGGARAN 22 JULI 2016.pdf\"><em>Download</em></a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-11-23 19:20:00', '2016-11-23 19:20:00', NULL),
('eb3bdd9b-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kunjungan Kerja Pemkot Payakumbuh Ke Kota Bekasi', 'kunjungan-kerja-pemkot-payakumbuh-ke-kota-bekasi', 'Pemerintah Kota Bekasi menerima kunjungan kerja jajaran Pemerintah Kota Payakumbuh Provinsi Sumatera Barat di Kota Bekasi, Kamis, (8/12) di kantor Walikota Bekasi Jalan Ahman Yani No 1 Bekasi Selatan.', '<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" kota=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Pemerintah Kota Bekasi menerima kunjungan kerja jajaran Pemerintah Kota Payakumbuh Provinsi Sumatera Barat di Kota Bekasi, Kamis, (8/12) di kantor Walikota Bekasi Jalan Ahman Yani No 1 Bekasi Selatan.</p>\n\n<p>&nbsp;</p>\n\n<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Dalam kesempatan itu, Wakil Walikota Bekasi H Ahmad Syaikhu menerima kedatangan Plt Walikota Payakumbuh Priyadi Syukur, Ketua DPRD Payakumbuh Yen&shy;dri Boda Dt Parmato Alam beserta jajarannya.</p>\n\n<p 0px=\"\" agama.=\"\" antar=\"\" berjalan=\"\" berkunjung=\"\" color:=\"\" damai=\"\" dan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" kampung=\"\" ke=\"\" line-height:=\"\" margin:=\"\" masyarakat=\"\" p=\"\" payakumbuh=\"\" pemeluk=\"\" pemkot=\"\" perc rencana=\"\" romb rukun=\"\" sawah=\"\" sawah.=\"\" sejak=\"\" seperti=\"\" sudah=\"\" text-align:=\"\" wilayah=\"\" yang=\"\">Kampung sawah juga sudah banyak dikenal masyarakat dan mendapatkan apresiasi dari Kementerian Agama sebagai wilayah percontohan pembinaan kerukunan umat beragama.</p>\n\n<p 0px=\"\" color:=\"\" daerah=\"\" dalam=\"\" dan=\"\" di=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" juga=\"\" kedatangan=\"\" k line-height:=\"\" mana=\"\" margin:=\"\" masyarakat=\"\" melalui=\"\" mengetahui=\"\" menjaga=\"\" p=\"\" payakumbuh=\"\" pembangunan=\"\" pemerintah=\"\" pemerintahan=\"\" pengelolaan=\"\" peran=\"\" pilar=\"\" polri=\"\" sejauh=\"\" suasana=\"\" tamu=\"\" text-align:=\"\" tiga=\"\" untuk=\"\" upaya=\"\" yakni=\"\">Selain itu kedatangan mereka untuk mengetahui program Forum Kerukunan Umat Beragama (FKUB) dan Majelis Ulama Indonesia (MUI), dan Komunitas Intelijen Daerah (Kominda).</p>\n\n<p 0px=\"\" ahmad=\"\" atas=\"\" bagi=\"\" bekasi=\"\" bekasi.=\"\" color:=\"\" daerah=\"\" dan=\"\" datang=\"\" di=\"\" dir=\"ltr\" dprd=\"\" font-family:=\"\" font-size:=\"\" h=\"\" kedatangan=\"\" ketua=\"\" kota=\"\" line-height:=\"\" margin:=\"\" mengucapkan=\"\" menjadi=\"\" p=\"\" pemkot=\"\" penghormatan=\"\" satu=\"\" selamat=\"\" syaikhu=\"\" tamu=\"\" terkait=\"\" text-align:=\"\" unsur=\"\" wakil=\"\" walikota=\"\">&quot;Kota Bekasi terus berbenah mewujudkan masyarakat Kota Bekasi yang Maju, Sejahtera dan Ihsan. Berkat suasana yang aman dan kondusif, semoga pembangunan berkelanjutan di wilayah Kota Bekasi bisa berjalan lancar,&quot; harapnya.</p>\n\n<p 0px=\"\" banyak=\"\" bekasi=\"\" berbagai=\"\" budaya=\"\" budaya.=\"\" color:=\"\" dan=\"\" dengan=\"\" dia=\"\" didukung=\"\" dir=\"ltr\" etnis=\"\" font-family:=\"\" font-size:=\"\" heterogen=\"\" ia=\"\" ind karenanya=\"\" kata=\"\" keragaman=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menegaskan=\"\" mengatakan=\"\" miniaturnya=\"\" oleh=\"\" p=\"\" pihak=\"\" sangat=\"\" sebagai=\"\" selain=\"\" termasuk=\"\" text-align:=\"\">Upaya menjaga kerukunan umat juga telah dilakukan bentuk komitmen bersama melalui apel akbar para seluruh elemen umat se-Kota Bekasi di Satdion Patriot Candrabaga dan melalui program Majelis Umat di 12 Kecamatan.</p>\n\n<p 0px=\"\" agama=\"\" ahmad=\"\" antar=\"\" bisa=\"\" color:=\"\" c dalam=\"\" dan=\"\" di=\"\" dir=\"ltr\" disana=\"\" disemua=\"\" font-family:=\"\" font-size:=\"\" kampung=\"\" kebhinekaan=\"\" kerukunan=\"\" kita=\"\" kota=\"\" lapisan=\"\" line-height:=\"\" margin:=\"\" masyarakat=\"\" melihat=\"\" menghormati=\"\" menjunjung=\"\" p=\"\" payakumbuh=\"\" pemeluk=\"\" romb saling=\"\" sangat=\"\" sawah.=\"\" sikap=\"\" teladan=\"\" text-align:=\"\" tinggi=\"\" ungkap=\"\" wawali=\"\">Plt Walikota Payakumbuh Priyadi Syukur menegaskan keinginan pihaknya berkunjung ke Kota Bekasi yang menjadi salah satu mitra Ibu Kota Jakarta. Dengan pesatnya pertumbuhan kota dan jumlah penduduknya ia mengatakan Kota Bekasi contoh ideal berbagi pengetahuan dan pengalaman bagaimana menjaga kerukunan umat.</p>\n\n<p 0px=\"\" bagaimana=\"\" beragama=\"\" color:=\"\" dan=\"\" dengan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" islam.=\"\" kata=\"\" keutuhan=\"\" kita=\"\" kota=\"\" line-height:=\"\" margin:=\"\" mayoritas=\"\" menjaga=\"\" p=\"\" payakumbuh=\"\" penduduknya=\"\" peran=\"\" ratusan=\"\" ribu=\"\" text-align:=\"\">Namun ia meyakini bukan hal mudah agar semua pihak menyadari kebhinekaan demi keutuhan dan persatuan bangsa. Tidak ada jalan lain selain keterlibatan peran pemerintah dan stake holder terkait agar kerukunan umat bisa dijaga secara bersama.</p>\n\n<p 0px=\"\" ada=\"\" beragama=\"\" color:=\"\" dan=\"\" di=\"\" dialog=\"\" dilakukan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" jawab=\"\" kedua=\"\" line-height:=\"\" margin:=\"\" p=\"\" penerimaan=\"\" permasalahan=\"\" sambutan=\"\" seputar=\"\" tanya=\"\" text-align:=\"\" umat=\"\" usai=\"\" yang=\"\">Sebagai bentuk silaturahmi kedua daerah, dilakukan penyerahan cinderamata berupa plakat dan kain tenun khas Payakumbuh serta satu kuliner khas Sumatera Barat, masakan Rendang. Payakumbuh pun memiliki satu kampung yang bernama kampung Rendang. (goeng)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:18:04', '2016-12-12 04:18:04', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bddf0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali: BUMD Bantu Wujudkan Smart City Kota Bekasi', 'wawali-bumd-bantu-wujudkan-smart-city-kota-bekasi', 'Bagian Bina Ekonomi Pembangunan dan Ketahanan Pangan (Ekbang-TP) Setda Kota Bekasi menggelar pertemuan pimpinan dan pengurus Badan Usaha Milik Daerah (BUMD), Kamis, (8/12) di Hotel Santika\n\n&nbsp;Bahk', '<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" kota=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Bagian Bina Ekonomi Pembangunan dan Ketahanan Pangan (Ekbang-TP) Setda Kota Bekasi menggelar pertemuan pimpinan dan pengurus Badan Usaha Milik Daerah (BUMD), Kamis, (8/12) di Hotel Santika</p>\n\n<p 0px=\"\" ahmad=\"\" bagian=\"\" bumd=\"\" color:=\"\" dari=\"\" dibentuknya=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" kegiatan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" membuka=\"\" mengatakan=\"\" menjadi=\"\" p=\"\" pembangunan=\"\" percepatan=\"\" saat=\"\" syaikhu=\"\" text-align:=\"\" wawali=\"\">&nbsp;<span 0px=\"\" ada=\"\" bekasi=\"\" bekasi.=\"\" bersinergi=\"\" bprs=\"\" bumd=\"\" color:=\"\" dan=\"\" dengan=\"\" diharpkan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" guna=\"\" ini=\"\" kota=\"\" line-height:=\"\" margin:=\"\" mendukung=\"\" meningkatkan=\"\" mewujudkan=\"\" migas=\"\" misi=\"\" mitra=\"\" p=\"\" pd=\"\" pdam=\"\" pemkot=\"\" perannya=\"\" sejahtera=\"\" sekarang=\"\" seperti=\"\" terutama=\"\" text-align:=\"\" tirta=\"\" untuk=\"\" visi=\"\" yang=\"\">Bahkan ia mengingatkan keempat BUMD saling bekerjasama dan bukan mengedepankan persaingan. Semata membantu tugas pembangunan daerah Kota Bekasi.</span></p>\n\n<p 0px=\"\" bagian=\"\" bekasi=\"\" berupaya=\"\" bisa=\"\" bumd=\"\" color:=\"\" daerah.=\"\" dan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" guna=\"\" itu=\"\" jaringan=\"\" kerja=\"\" kesemuanya=\"\" kota=\"\" lain=\"\" line-height:=\"\" margin:=\"\" memaksimalkan=\"\" membantu=\"\" meningkatakan=\"\" meningkatkan=\"\" oleh=\"\" p=\"\" pendapatan=\"\" permodalan=\"\" potensi=\"\" produktifitas=\"\" sebab=\"\" text-align:=\"\"><span 0px=\"\" ada=\"\" bekasi=\"\" bekasi.=\"\" bersinergi=\"\" bprs=\"\" bumd=\"\" color:=\"\" dan=\"\" dengan=\"\" diharpkan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" guna=\"\" ini=\"\" kota=\"\" line-height:=\"\" margin:=\"\" mendukung=\"\" meningkatkan=\"\" mewujudkan=\"\" migas=\"\" misi=\"\" mitra=\"\" p=\"\" pd=\"\" pdam=\"\" pemkot=\"\" perannya=\"\" sejahtera=\"\" sekarang=\"\" seperti=\"\" terutama=\"\" text-align:=\"\" tirta=\"\" untuk=\"\" visi=\"\" yang=\"\">Lanjut dia, BUMD juga perlu mendukung upaya mewujudkan Smart City di Kota Bekasi. Dengan jalan program jaringan fiberoptik bisa menjadi salah satu potensi pendapatan daerah bila dikembangkan BUMD Kota Bekasi. Pihak swasta kedepannya pun bisa menggunakan fiber optik milik Pemkot Bekasi. Pengembangan jaringan fober optik akan mendukung program Bekasi Smart City.</span></p>\n\n<p 0px=\"\" agar=\"\" anggaran=\"\" bekasi=\"\" belum=\"\" bisa=\"\" bumd=\"\" center.=\"\" city=\"\" color:=\"\" dengan=\"\" di=\"\" diakhir=\"\" diketahui=\"\" dipantau=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" hanya=\"\" hingga=\"\" ia=\"\" itu=\"\" juga=\"\" kinerja=\"\" laporan=\"\" line-height:=\"\" margin:=\"\" mengingatkan=\"\" menurutnya=\"\" operating=\"\" p=\"\" patriot=\"\" produktifitas=\"\" real=\"\" saat=\"\" secara=\"\" sehingga=\"\" semua=\"\" smart=\"\" tahun=\"\" terk text-align:=\"\" time=\"\" update.=\"\"><span 0px=\"\" ada=\"\" bekasi=\"\" bekasi.=\"\" bersinergi=\"\" bprs=\"\" bumd=\"\" color:=\"\" dan=\"\" dengan=\"\" diharpkan=\"\" dir=\"ltr\" font-family:=\"\" font-size:=\"\" guna=\"\" ini=\"\" kota=\"\" line-height:=\"\" margin:=\"\" mendukung=\"\" meningkatkan=\"\" mewujudkan=\"\" migas=\"\" misi=\"\" mitra=\"\" p=\"\" pd=\"\" pdam=\"\" pemkot=\"\" perannya=\"\" sejahtera=\"\" sekarang=\"\" seperti=\"\" terutama=\"\" text-align:=\"\" tirta=\"\" untuk=\"\" visi=\"\" yang=\"\">Bila BUMD terkoneksi Bekasi Smart City ia meyakini BUMD bisa merespon cepat segala bentuk keluhan dan masukan warga bahkan bisa menjadi peluang bisnis bila hal tersebut belum tertangani. Bekasi Smart City memiliki dua aplikasi aduan seperti SOROT dan POT dan Sistem Kinerja SKPD Online (siKepO)</span></p>\n\n<p>&nbsp;</p>\n\n<p>&lt;p dir=&quot;ltr&quot; border-box;=&quot;&quot; margin:=&quot;&quot; 0px=&quot;&quot; 10px;=&quot;&quot; text-align:=&quot;&quot; justify;=&quot;&quot; font-size:=&quot;&quot; 12.8px;=&quot;&quot; line-height:=&quot;&quot; 22px;=&quot;&quot; color:=&quot;&quot; rgb(34,=&quot;&quot; 34,=&quot;&quot; 34);=&quot;&quot; font-family:=&quot;&quot; arial,=&quot;&quot; sans-serif;&quot;=&quot;&quot;&gt;&quot;Ada keluhan lewat pengaduan tidak tersedianya jaringan air di satu wilayah kota kita akhirnya mengetahui bahwa wilayah tersebut belum mendapatkan pelayanan. Ini kemudian menjadi tugas kita dengan program pengembangan jaringan pelayanan,&quot; sebut Wawali Ahmad Syaikhu mencontohkan. (goeng)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:14:00', '2016-12-12 04:14:00', NULL),
('eb3bde3d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gerak Jalan HUT PGRI Kota Bekasi, Walikota Pedulikan Tunjangan Bagi Para Guru', 'gerak-jalan-hut-pgri-kota-bekasi-walikota-pedulikan-tunjangan-bagi-para-guru', 'Kota Bekasi - Gerak Jalan yang diselenggarakan oleh Persatuan Guru Republik Indonesia (PGRI) Cabang Kota Bekasi yang diadakan di Plaza Pemerintah Kota Bekasi tanggal (04/12) sekaligus memeriahkan ruti', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif; font-size: 13px;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kota Bekasi - Gerak Jalan yang diselenggarakan oleh Persatuan Guru Republik Indonesia (PGRI) Cabang Kota Bekasi yang diadakan di Plaza Pemerintah Kota Bekasi tanggal (04/12) sekaligus memeriahkan rutinitas car free daya yang digelar setiap minggunya. Walikota Bekasi, Dr. Rahmat Effendi bersama Wakil Walikota Bekasi, H. Ahmad Syaikhu hadir dalam acara tersebut sekaligus menyambut tamu undangan Bupati Purwakarta selaku Dewan Pembina PGRI Purwakarta, H. Dedi Mulyadi.</span></span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Peserta gerak jalan dihadiri dari para guru yang berada di Kota Bekasi dari perkecamatan wilayahnya masing masing, tedapat doorprise yang menarik dibagikan dari panitia yang juga dari Walikota Bekasi memberikan hadiah utama perjalanan Umroh untuk 2 orang, Wakil Walikota juga menyumbang satu tiket perjalanan umroh dan sepeda gunung serta dari Bupati Purwakarta, Dedi Mulyadi juga memberikan satu tiket perjalanan umroh juga.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dalam sambutannya, Dedi Mulyadi selaku Pembina PGRI Kabupaten Purwakarta menceritakan bahwa di Kabupaten Purwakarta mencanangkan belajar anti depresi, yang setiap minggunya satu hari dikhususkan untuk mengenal pribadi dengan para orang tua di luar sekolah, akan tetapi guru tetap memonitoring dengan tugasnya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Hal tersebut, akan membuat para siswa belajar mengenal arti dari pengalaman hidup, tidak hanya belajar diruang kelas yang bisa membuat depresi para siswa, pembelajaran tersebut agar diterapkan di Kota Bekasi&quot; ujar Dedi Mulyadi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Tidak hanya itu, Dedi Mulyadi juga mengenalkan program setiap 2 minggu sekali para orang tua murid diajak untuk berdialog diluar pelajaran sekolah, berfungsi agar si guru mengenal karakteristik siswa yang dibimbingnya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Walikota Bekasi dalam sambutannya mengutarakan bahwa kenaikan tunjangan untuk para guru di Kita Bekasi akam mencapai 3 Juta Rupiah perorangnya, ini suatu komitmen dengan Wakil Walikota yang mempunyai visi Sejahtera, sejahtera kan guru dan para pengajar pendidikan di Kota Bekasi, dan rencananya, pada tahun 2018 akan tetap dipikirkan menjadi 5 juta per guru di Kota Bekasi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Program tersebut, adalah bentuk harmonis antar Walikota Dan Wakil Walikota Bekasi, sampai saat ini belum ada di Kota atau Kabupaten manapun yang memikirkan tunjangan untuk guru, hanya baru Di Kota Bekasi saja&quot; Tegas Walikota.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dalam penegasannya, Walikota dengan Wakil Walikota Bekasi akan tetap berkomitmen dalam masa tugas akhirnya, demi warga Kota Bekasi keduanya saling tukar pikiran untuk warga, terbukti saat Gubernur Jawa Barat, Ahmad Heryawan mengatakan jika ingin belajar keharmonisan Kepala Daerah di manapun, contoh dan datang Kepala Daerah dan Wakilnya dalam sinegritas bekerja dan kehidupan sehari harinya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Usai sambutan, Walikota, Wakil Walikota serta Bupati Purwakarta melepas para peserta gerak jalan. (Ndoet)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:20:00', '2016-12-12 03:20:00', NULL),
('eb3bde89-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ahmad Syaikhu Apresesiasi Porseni Yayasan Patriot Bekasi', 'wawali-ahmad-syaikhu-apresesiasi-porseni-yayasan-patriot-bekasi', 'Kota Bekasi, --&nbsp;Wakil Walikota Bekasi H Ahmad Syaikhu membuka Pekan Olahraga dan Seni (Porseni) dilingkup Pelajar Yayasan Patriot Kota Bekasi, Kamis, (17/11) di lapangan Yayasna Patriot Kelurahan', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Kota Bekasi, --&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Wakil Walikota Bekasi H Ahmad Syaikhu membuka Pekan Olahraga dan Seni (Porseni) dilingkup Pelajar Yayasan Patriot Kota Bekasi, Kamis, (17/11) di lapangan Yayasna Patriot Kelurahan Kali Baru, Kecamatan Medan Satria.</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Ratusan pelajar peserta Poreseni berasal dari sekolah milik Yayasan Patriot yang berada di Kota Bekasi dan satu dari Kota Cirebon. Cabang olahraga yang dipertandingkan diantaranya Basket, futsal, bulutangkis, lomba pidato, dan kaligrafi.</span></p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Wakil Walikota Bekasi H Ahmad Syaikhu mendukung pelaksanaan kegiatan Porseni Patriot. Kegiatan ini menurutnya sangat bagus sebagai ajang silaturahmi antar pelajar Patriot dari berbagai wilayah.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Adik-adik dari Cirebon bisa datang ke Bekasi. Semangat untuk pertandingannya. Dan jaga terus sportifitas dan semangat bertanding,&quot; kata Wawali Ahmad Syaikhu.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Dengan jiwa raga yang sehat adik-adik kita harapkan mampu mengusung masa depan lebih baik. Kita juga berharap akan muncul atlet berbakat yang berprestasi hingga tingkat internasional,&quot; pungkas Wawali Ahmad Syaikhu.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Dalam kesempatan itu Ahmad Syaikhu didampingi Ketua Yayasan Patriot melepas puluhan balon ke udara sebagai tanda dimulainya Porseni Patriot. Ia pun mencoba bermain basket dan melakukan pertandingan eksebisi bukutangkis selama dua set melawan ketua Yayasan Patriot Asep Zam-Zam.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Ketua Yayasan Patriot Asep Zam-Zam mengatakan ucapan terimakasihnya atas kehadiran Wakil Walikota Bekasi H Ahmad Syaikhu. Kata dia, pelajar akan semakin termotivasi dan berupaya lebih giat lagi belajar.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Ini upaya kita agar para siswa selain memiliki ilmu pengetahuan yang tinggi juga ditunjang fisik jasmani yang sehat,&quot; kata Asep Zam-zam yang juga mengutip pribahasa,&quot;Didalam tubuh yang sehat terdapat jiwa yang kuat.&quot;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:29:00', '2016-12-12 03:29:00', NULL),
('eb3bdeda-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pemkot Bekasi Budayakan Masyarakatnya Bersepeda', 'pemkot-bekasi-budayakan-masyarakatnya-bersepeda', 'Kota Bekasi, --&nbsp;Pemerintah Kota Bekasi, Jawa Barat, terus mendorong aktivitas bersepeda sebagai olahraga populer di tengah masyarakat. Bersepeda secara rutin mampu meningkatkan kebugaran fisik da', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Kota Bekasi, --&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Pemerintah Kota Bekasi, Jawa Barat, terus mendorong aktivitas bersepeda sebagai olahraga populer di tengah masyarakat. Bersepeda secara rutin mampu meningkatkan kebugaran fisik dan kelebihan lainnya.</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&quot;Pemkot Bekasi terus menggalakan budaya bersepeda kepada masyarakat melalui sosialisasi maupun kegiatan rutin di kalangan komunitasnya,&quot; kata Wakil Wali Kota Bekasi Ahmad Syaikhu di Bekasi, Selasa, (29/11).</span><span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</span></p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nSalah satu kegiatan sosialisasi bersepeda yang dilakukan Pemkot Bekasi adalah pemasangan papan informasi terkait manfaat bersepeda di sejumlah halte.&nbsp;<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\n&quot;Di halte kita pasang sosialisasi sepeda, manfaatnya bagi penggunanya dari segi kesehatan serta efektivitas berkendara yang ramah lingkungan,&quot; katanya.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nSelain sosialisasi, kata dia, Pemkot Bekasi juag rutin menggelar kegiatan bersepeda setiap akhir pekan pada acara Car Free Day di Jalan Ahmad Yani.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nSelain itu, Pemkot Bekasi juga telah membuat komitmen dengan kalangan pengusaha properti untuk penyediaan fasilitas bersepeda.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\n&quot;Misalnya PT Summarecon Agung Tbk yang bersedia menyediakan track outdoor cross country, bersepeda di atas lahannya sampai lima tahun ke depan,&quot; katanya.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nSelain itu, ada pula keterlibatan pengelola mal untuk menyediakan track Indoor di dalam mal.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\n&quot;Namanya downmal. Kita dapat izin dari pengelola Blu Plaza Jalan Chairil Anwar Bekasi Timur. Tracknya dari atas mal turun ke dalam mal melalui tangga dan eskalator,&quot; katanya.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nTingginya animo masyarakat setempat terhadap olahraga bersepeda juga dibuktikan dengan semakin &#39;menjamurnya&#39; komunitas sepeda dari sejumlah kalangan masyarakat.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Pecinta sepeda di Kota Bekasi sangat banyak, ada yang berasal dari komunitas berdasarkan kesamaan jenis sepeda serta kesamaan profesi seperti penumpang kereta,&quot; katanya.<br  border-box;\" />\n&nbsp;&nbsp;&nbsp;&nbsp;<br  border-box;\" />\nSituasi itu pun mendorong Komite Nasional Olahraga Indonesia (KONI) Kota Bekasi untuk menggelar Jambore Sepeda 2016 yang dilaksanakan mulai 3-4 Desember di Summarecon Bekasi serta Blu Palza. Sekaligus kegiatan Jambore Sepeda yang akan digelar ini menjadi agenda HUT Ke-1 Ikatan Sepeda Sport Insonesia (ISSI) Kota Bekasi.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Kegiatan ini akan diikuti sekitar 1.400 peserta yang sudah mendaftar,&quot; kata Wawali Ahmad Syaikhu yang sempat mencoba trek sepeda di Summarecon Bekasi bersama Ketua ISSI Yayan Yuliana dan para pesepeda lainnya. (AF/goeng)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:30:00', '2016-12-12 03:30:00', NULL),
('eb3bdf26-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Lepas Patriot Jambore Sepeda Kota Bekasi, Wakil Walikota Iringi Peserta Gowes', 'walikota-lepas-patriot-jambore-sepeda-kota-bekasi-wakil-walikota-iringi-peserta-gowes', 'Kota Bekasi - Sebanyak 350 peserta mengikuti acara Patriot Jambore Sepeda Kota Bekasi Tahun 2016, Walikota Bekasi, Dr. Rahmat Effendi melepas para peserta pada hari Sabtu (03/12) di depan Hotel Haris ', '<div font-family:=\"\" font-size:=\"\" helvetica=\"\" lucida=\"\" segoe=\"\" span=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Kota Bekasi - Sebanyak 350 peserta mengikuti acara Patriot Jambore Sepeda Kota Bekasi Tahun 2016, Walikota Bekasi, Dr. Rahmat Effendi melepas para peserta pada hari Sabtu (03/12) di depan Hotel Haris Sumareccon Bekasi. Wakil Walikota, Ahmad Syaikhu bersama Dandim 05/07 Bekasi, Letkol Wawan K beserta para Muspida lainnya mengikuti rute area sepeda.</span></div>\n\n<p>&nbsp;</p>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span 100=\"\" 200=\"\" bekasi=\"\" daerah=\"\" dan=\"\" dari=\"\" dinas=\"\" div=\"\" dua=\"\" font-family:=\"\" font-size:=\"\" info=\"\" kabupaten=\"\" kepala=\"\" km=\"\" kota=\"\" mengitari=\"\" menjadi=\"\" menurut=\"\" rute=\"\" rutenterjauh=\"\" saja=\"\" sampai=\"\" sejauh=\"\" sepeda=\"\" terbagi=\"\" termasuk=\"\" terpendek=\"\" text-align:=\"\" yakni=\"\" yang=\"\" yayan=\"\">&nbsp;</span></div>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span 100=\"\" 200=\"\" bekasi=\"\" daerah=\"\" dan=\"\" dari=\"\" dinas=\"\" div=\"\" dua=\"\" font-family:=\"\" font-size:=\"\" info=\"\" kabupaten=\"\" kepala=\"\" km=\"\" kota=\"\" mengitari=\"\" menjadi=\"\" menurut=\"\" rute=\"\" rutenterjauh=\"\" saja=\"\" sampai=\"\" sejauh=\"\" sepeda=\"\" terbagi=\"\" termasuk=\"\" terpendek=\"\" text-align:=\"\" yakni=\"\" yang=\"\" yayan=\"\"><span acara=\"\" akhir=\"\" antara=\"\" bekasi=\"\" dengab=\"\" di=\"\" div=\"\" font-family:=\"\" font-size:=\"\" hampit=\"\" ikatan=\"\" isi=\"\" k kota=\"\" melaksanakan=\"\" memperart=\"\" menjadi=\"\" pemerintah=\"\" penghujung=\"\" rutin=\"\" sepeda=\"\" serta=\"\" silaturahmi=\"\" sport=\"\" tahun=\"\" tahunnya=\"\" target=\"\" text-align:=\"\" tiap=\"\" untuk=\"\" yang=\"\">&nbsp;</span></span></div>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span 100=\"\" 200=\"\" bekasi=\"\" daerah=\"\" dan=\"\" dari=\"\" dinas=\"\" div=\"\" dua=\"\" font-family:=\"\" font-size:=\"\" info=\"\" kabupaten=\"\" kepala=\"\" km=\"\" kota=\"\" mengitari=\"\" menjadi=\"\" menurut=\"\" rute=\"\" rutenterjauh=\"\" saja=\"\" sampai=\"\" sejauh=\"\" sepeda=\"\" terbagi=\"\" termasuk=\"\" terpendek=\"\" text-align:=\"\" yakni=\"\" yang=\"\" yayan=\"\"><span acara=\"\" akhir=\"\" antara=\"\" bekasi=\"\" dengab=\"\" di=\"\" div=\"\" font-family:=\"\" font-size:=\"\" hampit=\"\" ikatan=\"\" isi=\"\" k kota=\"\" melaksanakan=\"\" memperart=\"\" menjadi=\"\" pemerintah=\"\" penghujung=\"\" rutin=\"\" sepeda=\"\" serta=\"\" silaturahmi=\"\" sport=\"\" tahun=\"\" tahunnya=\"\" target=\"\" text-align:=\"\" tiap=\"\" untuk=\"\" yang=\"\">&lt;span border-box;=&quot;&quot; font-family:=&quot;&quot; tahoma;&quot;=&quot;&quot;&gt;Wakil Walikota Bekasi, Ahmad Syaikhu bersama Muspida lainnya mengikuti rute terpanjang yakni 200 KM sedangkan Walikota Bekasi, Dr. Rahmat Effendi hanya melepas para peserta karena akan berlanjut ke acara berikutnya. (Ndoet)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:33:00', '2016-12-12 03:33:00', NULL),
('eb3bdf71-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'BNI Gandeng Pemkot Bekasi dengan Rumah Kreatif Kota Bekasi BUMN', 'bni-gandeng-pemkot-bekasi-dengan-rumah-kreatif-kota-bekasi-bumn', 'Kota Bekasi - Program Rumah Kreatif Bank Negara Indonesia (BNI) merupakan program&nbsp;CSR nya (Corporate Social Responsibility) dengan Pemerintah Kota Bekasi melalui Rumah Kreatif BUMN, rencana progr', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\"><span id=\"yui_3_16_0_ym19_1_1480943974111_2599\"  border-box; -webkit-padding-start: 0px;\">Kota Bekasi - Program Rumah Kreatif Bank Negara Indonesia (BNI) merupakan program&nbsp;</span><span id=\"yui_3_16_0_ym19_1_1480943974111_2989\"  border-box; -webkit-padding-start: 0px;\">CSR nya (Corporate Social Responsibility) dengan Pemerintah Kota Bekasi melalui Rumah Kreatif BUMN, rencana program tersebut&nbsp;</span><span id=\"yui_3_16_0_ym19_1_1480943974111_2998\"  border-box; -webkit-padding-start: 0px;\">program pemberdayaan para Usaha Kecil Mikro dan Menengah (UMKM) yang berada di Kota Bekasi yang terbentuk di Dinas Perindustrian, Perdagangan dan Koperasi.</span></span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\"><span id=\"yui_3_16_0_ym19_1_1480943974111_3144\"  border-box; -webkit-padding-start: 0px;\">Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas&nbsp;</span><span id=\"yui_3_16_0_ym19_1_1480943974111_3080\"  border-box; -webkit-padding-start: 0px;\">Perindustrian, Perdagangan dan Koperasi, Aceng Solahudin bersama Petinggi dari PT Bank Negara Indonesia Tbk membuat Kerjasama dan kesepakatan dengan ditandatangani pada saat apel pagi, Senin (05/12).</span></span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div id=\"yui_3_16_0_ym19_1_1480943974111_3016\"  border-box; -webkit-padding-start: 0px; font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">\n<div  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Menurutnya, Rumah Kreatif ini merupakan salah satu upaya BNI Bekasi dalam pemberdayaan masyarakat, uang akan mengembangkan usaha kecilnya untuk berbuah kredit, Nantinya, program ini akan dikelola secara kreatif untuk memaksimalkan potensi masyarakat. Yang nantinya, produk-produk yang dihasilkan bisa bernilai ekonomi lebih tinggi.</span></span></div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Tepat di Gedung 10 Lantai Pemerintah Kota Bekasi, sudah terbentuk ruangan yang bertuliskan &quot;Rumah Kreatif Kota Bekasi BUMN&quot; dan akan segera dibentuk untuk rencana kedepannya sesuai kesepakatan dengan Dinas Perindagkop Kota Bekasi.</span></span></div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Menurut Walikota Bekasi pada saat berbincang dengan salah satu dari pihak BNI, yang sebelumnya Pemerintah Kota Bekasi dengan Bank Jabar Banten (BJB), kedepannya juga bisa membentuk kerjasama dengan Bank BNI untuk pengkreditan maupun untuk usaha dari pegawai ataupun masyarakat luas di Kota Bekasi.&nbsp;</span></span></div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Di harapkan kepada Bank Swasta lainnya juga ikut memprogramkan kepada Pemerintah Kota Bekasi,&quot;.(ndoet)</span></span></div>\n</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:34:00', '2016-12-12 03:34:00', NULL),
('eb3bdfc3-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gala Diner Peserta Coop Expo 2016', 'gala-diner-peserta-coop-expo-2016-2', 'Kota Bekasi -&nbsp;Panitia Coop Expo 2016 dalam puncak peringatan Hari Koperasi Ke-69 menggelar gala dinner atau jamuan makan malam bagi duta pengusaha dan koperasi se-Jabar serta perwakilan negara As', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kota Bekasi -&nbsp;Panitia Coop Expo 2016 dalam puncak peringatan Hari Koperasi Ke-69 menggelar gala dinner atau jamuan makan malam bagi duta pengusaha dan koperasi se-Jabar serta perwakilan negara Asean-Asia di Ballroom Hotel Santika Medan Satria, Kota Bekasi, Selasa, (2/8).</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Coop Expo 2016 telah dibuka Menteri UMKM dan Koperasi Puspa Yoga dan menjadi bagian dari pengenalan produk dan ajang promosi usaha daerah dan negara asean-asia.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Saat jamuan, Wakil Walikota Bekasi H Ahmad Syaikhu&nbsp;didampingi Ketua Dekopinda Jabar Mustofa Jamaludin dan Kepala Dinas Perindustrian, Perdagangan dan Koperasi (Disperindagkop) Kota Bekasi Aceng Solehudin, Ketua Dekopinda Kota Bekasi Anim Imanudin.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Gala diner juga sekaligus menambah kehangatan hubungan baik para usahawan daerah maupun dari negara asean dalam ajang Coop Expo 2016 di Kota Bekasi, selaku tuan rumah kali ini.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Wawali Ahmad Syaikhu di awal sambutannya mengatakan Kota Bekasi berkembang juga berkat peran serta para pengusaha dalam membantu pemerintah. Selain itu Pemkot Kota Bekasi terus mewujudkan iklim investasi agar semakin menjanjikan dan kondusif di mata investor.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Keikutsertaan perwakilan negara Asean dan Asia dalam gelaran Coop Expo 2016 di Kota Bekasi salah satu upaya agar Kota Bekasi lebih diminari Investor. Coop Expo 2016 digelar dari tanggal 2-9 Agustus 2016 di Bekasi Town Square, Bekasi Timur.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Dalam perjalanannya para investor mempercepat proses pembangunan dan&nbsp; ekonomi di Kota Bekasi. Kerjasama ini kita optimis yakin membawa keuntungan bagi semua. Intinya agar masyarakat lebih maju dan sejahtera sebagai bagian dari negeri yang diidamkan bersama,&quot; ungkap Wawali Ahmad Syaikhu didepan para undangan dari negara luar.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Terkait peningkatan investasi kedepan, menjadi perhatian pemerintahan Walikota Bekasi Dr H Rahmat Effendi dan legislatif bersama dirinya yang telah menetapkan di 2017 Kota Bekasi sebagai tahun Investasi dan Perekonomian Daerah.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Semoga Investasi terus bergeliat guna mendorong perekonomian daerah,&quot; katanya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Lanjut dia, seperti halnya keinginan Pemkot Bekasi mewujudkan moda transportasi kereta angin aeromovel yang menghubungkan beberapa perumahan dengan pusat perbelanjaan. Rencana ini bahkan inisasi dari pengusaha atau investor dari Malaysia.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kata dia bentang jalur aeromovel sejauh 10 Km dan menjadi bagian dari upaya mengatasi kemacetan.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Inisiasi aeromovel juga inisasi dari temen-temen Malaysia dan kerjasama lain dengan Kanada dalam inisasi pembentukan water treatmen plan di Pondok Gede. Kita optimis kerjasama bisa dilakukan untuk pembangunan masyarakat,&quot; kata Ahmad Syaikhu langsung disambut tepuk tangan dari para undangan.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dalam jamuan kali ini juga dihadirkan hiburan musik bahkan perwakilan peserta juga ikut bernyanyi. Di sela jamuan juga ditampilkan para penari tari topeng dari sanggar Koppas Kranggan.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Diakhir sambutannya, Ahmad Syaikhu atas nama Walikota Bekasi H Rahmat Effendi mengucapkan harapannya agar suasana para tamu setelah sekembalinya ke daerah maupun negara asal, lebih berbahagia. Dengan pengalaman yang didapat di Kota Bekasi. (goeng)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:38:00', '2016-12-12 03:38:00', NULL),
('eb3be00e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kemen-PPPA Gelar Pelatihan Lansia Berkebun Organik di Kota Bekasi', 'kemen-pppa-gelar-pelatihan-lansia-berkebun-organik-di-kota-bekasi-3', 'Kota Bekasi -&nbsp;Sebanyak 100 lansia di Perumahan Bumi Nasio Indah RW 15, Kelurahan Jatikramat Kecamatan Jati Asih&nbsp;mengikuti pelatihan pemberdayaan ekonomi lansia Dahlia Senja melalui program p', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kota Bekasi -&nbsp;Sebanyak 100 lansia di Perumahan Bumi Nasio Indah RW 15, Kelurahan Jatikramat Kecamatan Jati Asih&nbsp;mengikuti pelatihan pemberdayaan ekonomi lansia Dahlia Senja melalui program pertanian berkebun organik, Sabtu, (15/10).</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kemen Pemberdayaan Perempuan dan Perlindungan Anak (Kemen-PPA) menggelar pelatihan ini dan disuport Kelompok Petani Organik (KePo), Pusat Program Pelatihan Nasio, dan Posdaya Nasio.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Ratusan lansia ini selama beberapa hari mengikuti pelatihan berkebun agar nantinya menghasilkan produk pertanian dan dapat mencukupi kebutuhan ekonomi keluarga dan pemenuhan gizi lansia itu sendiri.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Ketua Lansia Perumahan Nasio, Ratna mengaku senang mendapatkan pelatihan terutama berkaitan dengan program lingkungan. Selain guna mewujudkan lansia produktif dan mandiri, kata dia, kegiatan berkebun sayur organik sangat menyenangkan dan menyehatkan.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Produk ekonomi yang dihasilkan berupa sayur mayur organik seperti sawi, seledri, tomat, dan ada pula produk madu murni. Hasilnya kata dia dipasarkan kepada warga Nasio bahkan hingga warga di kecamatan Jati Asih lainnya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Program lingkungan seperti berkebun ini telah dijalankan di perumahan Nasio. Kita terus beraktifitas, tetap sehat dan bahagia serta tidak hanya mengandalkan keluarga. Lansia Dahlia ingin terus berpartisipasi dalam program ini,&quot; kata Ratna saat ditemui di tempat pelatihan di Balai Pertemuan RW 15 Perum Bumi Nasio.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Program pemberdayaan lansia yang digelar di Perumahan Nasio ternyata mendapatkan perhatian lebih dari Kementerian Pemberdayaan Perempuan dan Perlindungan Anak (Kemen-PPA).</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Deputi Bidang Perlindungan Hak Perempuan (Kemen PPA) Prof Vennetia Danes secara langsung hadir serta membuka pelatihan kali ini.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Prof Vennetia mengatakan banyak mendengar berbagai prestasi telah ditorehkan warga perum Nasio seperti juara III Posdaya Nasio tingkat Nasional dan giat melakukan program lingkungan seperti bank Sampah. Dan hal ini membuat dirinya mengusahakan untuk datang ke tempat pelatihan lansia berkebun sayur organik secara langsung.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Kita harap program pemberdayan perempuan terutama lansia dapat menular ke wilayah lain. Dan menjadikan lansia sehat, produktif dan mandiri. Ini juga kampanye mengenai hak perempuan yang didalamnya hak lansia tetap berusaha dan beraktifitas,&quot; kata Prof Vennetia.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kita ketahui bersama, Lingkungan perumaham Bumi Nasio kerap dilanda banjir seperti beberapa wilayah lainnya di Kota Bekasi. Namun hal ini tidak menyurutkan niat warga lebih berprestasi dan bermanfaat bagi lingkungan dan kota Bekasi pada umumnya. Terbukti beberapa posdaya dari kecamatan lain di Kota Bekasi dan luar kota melakukan studi banding mengenai program di posdaya Nasio.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Selain Deputi Kemen PPA, hadir Wakil Walikota Bekasi H Ahmad Syaikhu didampingi Camat Jati Asih Nesan Sujana, Lurah Jati Kramat Ferdinan serta Kapolsek dan Danramil Jatiasih.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&nbsp;</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Wawali Ahmad Syaikhu selaku Ketua Komda Lansia Kota Bekasi mengucapkan terimakasih kepada Deputi Kemen PPA Prof Vennetia dan jajaran melakukan pelatihan berkebun organik kepada lansia di Perumahan Bumi Nasio.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Ekonomi produktif bagi lansia ini sangat membanggakan Pemerintah dan warga Kota Bekasi. Kita harap lansia tetap sehat dan produktif. Ini bukti harapan untuk berubah dan bermanfaat bagi yang lain.&nbsp;</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><br  border-box; -webkit-padding-start: 0px;\" />\n<span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dan pelatihan ini semoga lebih banyak lagi dilakukan hingga percepatan kegiatan diikuti Posbindu yang lain,&quot; kata Wawali Ahmad Syaikhu.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Selaku Ketua Komda Lansia Kota Bekasi, Wawali Ahmad Syaikhu juga mengatakan aktifitas program lansia diantaranya senam lansia setiap bulannya di rumah dinas Wakil Walikota. Selain itu juga dilakukan pemeriksaan kesehatan gula darah dan tensi darah bagi peserta.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Usai acara pembukaan simbolis Ketua&nbsp; Prof Vennetia dan Wawali Ahmad Syaikhu menerima hasil peranian kebun dari Kelompok Petani Organik (KePo) Perum Bumi Nasio Indah. (goeng)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:39:00', '2016-12-12 03:39:00', NULL);
