('eb3be059-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'KOTA BEKASI TERIMA ANUGRAH DANA RAKCA 2016,ATAS PENGELOLAAN KEUANGAN YANG BERKINERJA BAIK', 'kota-bekasi-terima-anugrah-dana-rakca-2016-atas-pengelolaan-keuangan-yang-berkinerja-baik', '&nbsp; \n\nSementara itu walikota Bekasi mengaku sangat bangga atas prestasi yang diraih Kota Bekasi .&quot; Syukur Alhamdulillah,Kota Bekasi merupakan salah satu dari 86 pemerintah &nbsp;kabupaten / ko', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span -=\"\" 0px=\"\" anugerah=\"\" bekasi=\"\" bekasi.walikota=\"\" berkinerja=\"\" daerah=\"\" dana=\"\" dari=\"\" diraih=\"\" diundang=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" hari=\"\" istana=\"\" jakarta=\"\" ke=\"\" kembali=\"\" kementerian=\"\" keuangan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menerima=\"\" nasi negara=\"\" p=\"\" pemerintah=\"\" prestasi=\"\" rakca=\"\" republik=\"\" sebagai=\"\" tahun=\"\" text-align:=\"\" tingkat=\"\" torehan=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp;<span .=\"\" 0px=\"\" adalah=\"\" ahmad=\"\" apbd=\"\" baik=\"\" bekasi=\"\" berprestasi.=\"\" daerah=\"\" dalam=\"\" dan=\"\" dana=\"\" dinilai=\"\" dipimpin=\"\" disamping=\"\" diterima=\"\" div=\"\" dr.rahmat=\"\" effendi=\"\" ek font-family:=\"\" font-size:=\"\" hal=\"\" indikotornya=\"\" ini=\"\" kementerian=\"\" keuangan=\"\" kinerja=\"\" margin:=\"\" melihat=\"\" oleh=\"\" open=\"\" opini=\"\" pasangan=\"\" pelayanan=\"\" pemerintah=\"\" pemkot=\"\" pengelolaan=\"\" pengendalian=\"\" pengesahan=\"\" pusat=\"\" rakca=\"\" ri=\"\" sangat=\"\" sejak=\"\" serta=\"\" setelah=\"\" tepat=\"\" text-align:=\"\" ustad=\"\" wtp=\"\" yang=\"\"> </span></span></span>\n<div -webkit-font-smoothing:=\"\" 0px=\"\" antialiased=\"\" border:=\"\" div=\"\" font-size:=\"\" font-stretch:=\"\" font-variant-numeric:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" text-align:=\"\" vertical-align:=\"\">\n<div div=\"\" text-align:=\"\"><span -=\"\" 0px=\"\" anugerah=\"\" bekasi=\"\" bekasi.walikota=\"\" berkinerja=\"\" daerah=\"\" dana=\"\" dari=\"\" diraih=\"\" diundang=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" hari=\"\" istana=\"\" jakarta=\"\" ke=\"\" kembali=\"\" kementerian=\"\" keuangan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menerima=\"\" nasi negara=\"\" p=\"\" pemerintah=\"\" prestasi=\"\" rakca=\"\" republik=\"\" sebagai=\"\" tahun=\"\" text-align:=\"\" tingkat=\"\" torehan=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span .=\"\" 0px=\"\" adalah=\"\" ahmad=\"\" apbd=\"\" baik=\"\" bekasi=\"\" berprestasi.=\"\" daerah=\"\" dalam=\"\" dan=\"\" dana=\"\" dinilai=\"\" dipimpin=\"\" disamping=\"\" diterima=\"\" div=\"\" dr.rahmat=\"\" effendi=\"\" ek font-family:=\"\" font-size:=\"\" hal=\"\" indikotornya=\"\" ini=\"\" kementerian=\"\" keuangan=\"\" kinerja=\"\" margin:=\"\" melihat=\"\" oleh=\"\" open=\"\" opini=\"\" pasangan=\"\" pelayanan=\"\" pemerintah=\"\" pemkot=\"\" pengelolaan=\"\" pengendalian=\"\" pengesahan=\"\" pusat=\"\" rakca=\"\" ri=\"\" sangat=\"\" sejak=\"\" serta=\"\" setelah=\"\" tepat=\"\" text-align:=\"\" ustad=\"\" wtp=\"\" yang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Sementara itu walikota Bekasi mengaku sangat bangga atas prestasi yang diraih Kota Bekasi .&quot; Syukur Alhamdulillah,Kota Bekasi merupakan salah satu dari 86 pemerintah &nbsp;kabupaten / kota dan provinsi yang berhasil mendapatkan anugrah ini dari 548 kabupaten Kota yang ada,ini bukti kerja tepat,cepat dan cerdas yang saya dan Ustad Syaikhu canangkan.Masih banyak yang harus kita raih,untuk itu saya dan Ustad Syaikhu berharap kinerja Aparatur Pemkot Bekasi lebih baik lagi kedepannya &quot;tegas Rahmat Efffendi.</span></span></span></span></div>\n</div>\n<span -=\"\" 0px=\"\" anugerah=\"\" bekasi=\"\" bekasi.walikota=\"\" berkinerja=\"\" daerah=\"\" dana=\"\" dari=\"\" diraih=\"\" diundang=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" hari=\"\" istana=\"\" jakarta=\"\" ke=\"\" kembali=\"\" kementerian=\"\" keuangan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menerima=\"\" nasi negara=\"\" p=\"\" pemerintah=\"\" prestasi=\"\" rakca=\"\" republik=\"\" sebagai=\"\" tahun=\"\" text-align:=\"\" tingkat=\"\" torehan=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"> </span></span></div>\n\n<div font-size:=\"\" span=\"\"><span -=\"\" 0px=\"\" anugerah=\"\" bekasi=\"\" bekasi.walikota=\"\" berkinerja=\"\" daerah=\"\" dana=\"\" dari=\"\" diraih=\"\" diundang=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" hari=\"\" istana=\"\" jakarta=\"\" ke=\"\" kembali=\"\" kementerian=\"\" keuangan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menerima=\"\" nasi negara=\"\" p=\"\" pemerintah=\"\" prestasi=\"\" rakca=\"\" republik=\"\" sebagai=\"\" tahun=\"\" text-align:=\"\" tingkat=\"\" torehan=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\"><span div=\"\" font-family:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&ldquo;Berdasarkan undangan yang diterima, penerimaan Anugerah Dana Rakca Tahun 2016 tersebut,hanya 36 Kepala Daerah Bupati / Walikota se &ndash; Indonesia yang menerima Anugerah Dana Rakca Tahun 2016, Kota Bekasi Salah satunya dan pada kegiatan tersebut juga akan dilaksanakan penerimaan Daftar Isian Pelaksanaan Anggaran(DIPA) Tahun 2017, dan Dana Transfer ke daerah dan Dana Desa Tahun 2017,&rdquo; jelas Kepala Badan Pengelolaan Keuangan Dan Aset Daerah (BPKAD) Kota Bekasi Widodo Indrijantoro SH MM.</span></span></span></span></div>\n\n<div 0px=\"\" font-family:=\"\" font-size:=\"\" margin:=\"\" span=\"\" text-align:=\"\"><span -=\"\" 0px=\"\" anugerah=\"\" bekasi=\"\" bekasi.walikota=\"\" berkinerja=\"\" daerah=\"\" dana=\"\" dari=\"\" diraih=\"\" diundang=\"\" dr.rahmat=\"\" effendi=\"\" font-family:=\"\" font-size:=\"\" hari=\"\" istana=\"\" jakarta=\"\" ke=\"\" kembali=\"\" kementerian=\"\" keuangan=\"\" kota=\"\" line-height:=\"\" margin:=\"\" menerima=\"\" nasi negara=\"\" p=\"\" pemerintah=\"\" prestasi=\"\" rakca=\"\" republik=\"\" sebagai=\"\" tahun=\"\" text-align:=\"\" tingkat=\"\" torehan=\"\" untuk=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&lt;span border-box;=&quot;&quot; font-family:=&quot;&quot; tahoma;&quot;=&quot;&quot;&gt;Seperti diketahui, sepanjang tahun ini Walikota Bekasi juga baru saja menerima 2a (dua) penghargaan tingkat Nasional dari Pemerintah pusat, yaitu Predikat Wajar Tanpa Pengecualian dan Piagam Adipura dari Kementerian Lingkungan Hidup dan Kehutanan Republik Indonesia.</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:48:00', '2016-12-12 03:48:00', NULL),
('eb3be0ad-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Akan Dibuat Puskesmas, 8 Bangli di Teluk Pucung Dibongkar', 'akan-dibuat-puskesmas-8-bangli-di-teluk-pucung-dibongkar', 'Kota Bekasi &ndash; Sebanyak 8 bangunan liar (bangli) di wilayah Kelurahan Teluk Pucung, Kecamatan Bekasi Utara dibongkar oleh tim penertiban bangunan, Rabu (7/12/2016).&nbsp;\n\n&nbsp;\n\n&nbsp;\n\n&nbsp;\n', '<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\"><span font-family:=\"\" span=\"\">Kota Bekasi &ndash; Sebanyak 8 bangunan liar (bangli) di wilayah Kelurahan Teluk Pucung, Kecamatan Bekasi Utara dibongkar oleh tim penertiban bangunan, Rabu (7/12/2016).</span>&nbsp;</div>\n\n<p>&nbsp;</p>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n\n<div font-family:=\"\" font-size:=\"\" o=\"\" p=\"\" text-align:=\"\"><span akan=\"\" bangunan=\"\" dibangun=\"\" dib font-family:=\"\" karena=\"\" kota=\"\" o=\"\" oleh=\"\" p=\"\" pemerintah=\"\" puskesmas=\"\" rencananya=\"\" tersebut=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp;</span></span></div>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n\n<div font-family:=\"\" font-size:=\"\" o=\"\" p=\"\" text-align:=\"\"><span 1000=\"\" 8=\"\" bangunan=\"\" bidang=\"\" diatas=\"\" dinas=\"\" fasos=\"\" fasum=\"\" font-family:=\"\" itu=\"\" kata=\"\" kepala=\"\" kota=\"\" krisman=\"\" lahan=\"\" merupakan=\"\" meter=\"\" milik=\"\" o=\"\" p=\"\" pemkot=\"\" pengawasan=\"\" pengendalian=\"\" seluas=\"\" tanah=\"\" tata=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp;</span></span></div>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n\n<div font-family:=\"\" font-size:=\"\" o=\"\" p=\"\" text-align:=\"\"><span aman=\"\" bangunan=\"\" berjalan=\"\" dan=\"\" dimana=\"\" font-family:=\"\" kata=\"\" krisman=\"\" lancar=\"\" melibatkan=\"\" o=\"\" p=\"\" pelaksanaan=\"\" pemb polri=\"\" proses=\"\" satpol=\"\" sendiri=\"\" unsur=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">&nbsp;</span></span></div>\n\n<div font-family:=\"\" font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n\n<div font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n\n<ol font-family:=\"\" font-size:=\"\" li=\"\" margin-bottom:=\"\" margin-top:=\"\">\n <li div=\"\" text-align:=\"\"><span atas=\"\" bangunan=\"\" dasar=\"\" dilaksanakan=\"\" font-family:=\"\" ini=\"\" liar=\"\" o=\"\" p=\"\" pemb><span 17=\"\" 2011=\"\" bekasi=\"\" daerah=\"\" font-family:=\"\" ijin=\"\" kota=\"\" nomor=\"\" o=\"\" p=\"\" pemanfaatan=\"\" penyelenggaraan=\"\" peraturan=\"\" tahun=\"\" tentang=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Peraturan Daerah Kota Bekasi Nomor 15 Tahun 2012 tentang Retribusi Ijin Mendirikan Bangunan</span></span><o li=\"\" p=\"\">\n <div font-size:=\"\" span=\"\" text-align:=\"\">&nbsp;</div>\n </o><span 2014=\"\" 42=\"\" bekasi=\"\" dan=\"\" font-family:=\"\" lahan=\"\" nomor=\"\" o=\"\" p=\"\" pemanfaatan=\"\" pengawasan=\"\" pengendalian=\"\" penyelenggaraan=\"\" peraturan=\"\" tahun=\"\" tentang=\"\" walikota=\"\"> </span></span></li>\n <li div=\"\" text-align:=\"\"><span atas=\"\" bangunan=\"\" dasar=\"\" dilaksanakan=\"\" font-family:=\"\" ini=\"\" liar=\"\" o=\"\" p=\"\" pemb><span 2014=\"\" 42=\"\" bekasi=\"\" dan=\"\" font-family:=\"\" lahan=\"\" nomor=\"\" o=\"\" p=\"\" pemanfaatan=\"\" pengawasan=\"\" pengendalian=\"\" penyelenggaraan=\"\" peraturan=\"\" tahun=\"\" tentang=\"\" walikota=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">Keputusan Walikota Bekasi Nomor 640/Kep.330-Distako/VII/2012 tentang Pembentukan Tim Penertiban dan Pembongkaran Bangunan Liar Yang Melanggar Perijinan di Kota Bekasi</span></span><o div=\"\" font-family:=\"\" font-size:=\"\" p=\"\" text-align:=\"\"><span font-family:=\"\" font-size:=\"\" span=\"\">(ronz)</span></o></span></li>\n</ol>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:51:00', '2016-12-12 03:51:00', NULL),
('eb3be0f9-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gebyar HKSN 2016 Tingkatkan Kepedulian Warga Kota Bekasi Terhadap Sesama', 'gebyar-hksn-2016-tingkatkan-kepedulian-warga-kota-bekasi-terhadap-sesama', 'Kota Bekasi, --&nbsp;Sebanyak ratusan peserta mengikuti gebyar Hari Kesetiakawanan Sosial Nasional (HKSN) 2016 tingkat Kota Bekasi di Hall Gor Basket Kota Bekasi, Kamis, (8/12).\n\n&nbsp;\n\n&nbsp;Gebyar ', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Kota Bekasi, --&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Sebanyak ratusan peserta mengikuti gebyar Hari Kesetiakawanan Sosial Nasional (HKSN) 2016 tingkat Kota Bekasi di Hall Gor Basket Kota Bekasi, Kamis, (8/12).</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Gebyar HKSN kali ini diiringi dengan pemberian sejumlah bantuan kepada warga dan penyandang cacat di Kota Bekasi. Selain itu disediakan pemeriksaan kesehatan gratis dari Dinas Kesehatan bekerjasama dengan RS Bhakti Kartini dan Yayasan Tri Dharma Bekasi.</span></p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Disuguhkan penampilan kosidahan dari ibu-ibu majlis taklim dan musikalisasi puisi dari komunitas Sastra Kalimalang.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Wakil Walikota Bekasi H Ahmad Syaikhu membuka acara gebyar HKSN 2016. Dalam sambutannya ia berharap HKSN menjadi momentum seluruh masyarakat meningkatkan rasa kesetiakawanan sosial terhadap sesama.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Lewat HKSN menjadi momentum kerja nyata kita demi kota Bekasi yang Maju, Sejahtera dan Ihsan,&quot; ungkap Wawali Ahmad Syaikhu.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Menurutnya, kompleksitas masyarakat&nbsp; perkotaan tidak melupakan rasa kepedulian sosial terhadap sesama. Sebab ia meyakini betul bila semangat kebersamaan muncul dan berkembang di tengah masyarakat bisa menyelesaikan berbagai persoalan dengan cepat dan tuntas.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Kompleksitas akan semakin tinggi kalau tidak memiliki rasa sosial kesesama. Sikap egoisme atau tidak peduli. Jangan sampai sikap ini terus muncul dalam kehidupan. Justru semangat HKSN jadi triger kedepan agar kita lebih peduli sesama,&quot; ungkapnya</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Wujud nyata pihak pemkot sendiri, lanjut dia dengan menyumbangkan sebagian kecil pendapatan para pegawai lewat koordinasi Badan Zakat Nasional (Baznas). Baznas mendistribusikan bantuan tersebut kepada yang membutuhkan. Pendapatan Baznas tahun 2015 sebanyak Rp 7 Miliar.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Mulai bulan ini, dan seterusnya secara otomatis pegawai pemkot menyisihkan sebagian hartanya pendapatan ke Baznas. Ini agar pendapatan baznas meningkat guna membantu program pemkot yang tidak teranggarkan guna bersama mengentaskan kemiskinan, membantu masjid, maupun dalam bentuk beasiswa. Pendapatan tahun lalu sebesar Rp 7 Miliar,&quot; kata Wawali Ahmad Syaikhu. (goeng)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 03:55:00', '2016-12-12 03:55:00', NULL),
('eb3be145-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ahmad Syaikhu: Generasi Muda Harus Berprestasi dan Melek IT', 'wawali-ahmad-syaikhu-generasi-muda-harus-berprestasi-dan-melek-it', 'Kota Bekasi , --&nbsp;Wakil Walikota Bekasi H Ahmad Syaikhu berharap generasi muda terutama kalangan pelajar terus berprestasi dan mampu mengikuti perkembangan dan tantangan zaman termasuk di dunia te', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Kota Bekasi , --&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Wakil Walikota Bekasi H Ahmad Syaikhu berharap generasi muda terutama kalangan pelajar terus berprestasi dan mampu mengikuti perkembangan dan tantangan zaman termasuk di dunia teknologi Informasi.&nbsp;</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&quot;Menjadi SDM unggul dibidangnya masing-masing dan mampu bersaing dimasa depan. Tidak ada blank spot. Untuk itu Pemerintah dan sekolah mempersiapkan para pelajar generasi muda agar membawa tatanan kehidupan kedepan lebih baik lagi,&quot; kata Wawali Ahmad Syaikhu.&nbsp;</span><br  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\" />\n<br  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\" />\n<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Hal ini ia katakan saat bertemu puluhan siswa Yayasan Patriot Kelurahan Kali Baru Kecamatan Medan Satria, Selasa, (25/10). Yayasan Pendidikan Patriot meliputi pendidikan dari tingkat SMP, SMK, dan SMEA.&nbsp;</span><br  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\" />\n<br  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\" />\n<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Lebih lanjut, dalam kesempatan itu, Ahmad Syaikhu juga menjelaskan mengenai Bekasi Smart City.&nbsp;</span><span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 13px;\">Kata dia, program ini dijalankan pemerintah melalui layanan berbasis Teknologi Informasi (IT) juga harus diketahui para pelajar generasi muda.&nbsp;</span></p>\n\n<div  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px;\"><span  border-box; font-size: 13px;\">Program Bekasi Smart City diataranya guna mengajak partisipasi warga masyarakat agar berperan aktif disemua sektor pembangunan di Kota Bekasi. Termasuk profram ini untuk peningkatan layanan publik.&nbsp;</span></p>\n\n<div dir=\"auto\"  border-box; text-align: justify;\"><br  border-box;\" />\n&quot;Untuk mewujudkan Bekasi Smart City dibangun dengan suasana kebersamaan<br  border-box;\" />\nagar mendidik masyarakat dan pemerintah untuk lebih perhatian terhadap masalah di lingkungan. Bila tidak ada partisipasi pelajar dan masyarakat lebih susah mewujudkannya,&quot; sambungnya.&nbsp;<br  border-box;\" />\n<br  border-box;\" />\nSekarang ini, lanjut dia, Pemkot Bekasi tengah gencar menggulirkan aplikasi aduan yang diberi nama Pengaduan Online Terpadu (POT). Jenis aplikasi berbasis teknologi informasi ini dapat diperoleh masyarakat di play store android. Lewat kemudahan aplikasi ini warga bisa berperan aktif dalam pembangunan dengan memanfaatkan smartphone di era IT yang semakin maju.&nbsp;<br  border-box;\" />\n<br  border-box;\" />\n&quot;Melalui aplikasi POT infomasi maupun keluhan warga akan sampai kepihak dinas terkait. Permasalahan titik sampah misalnya ambil fotonya dan berilokasi. Ini diketahui Dinas Kebersihan dan segera ditindaklanjuti dengan mengirim petugas dan truk kebersihan,&quot; kata Ahmad Syaikhu memberi sedikit contoh dari banyak kegunaan aplikasi ini.&nbsp;<br  border-box;\" />\n<br  border-box;\" />\n&quot;Aplikasi POT telah ada di play store android, kalian bisa menginstalnya, registrasi dan manfaatkan dengan sebaik-baiknya. Sampaikan juga kepada keluarga dan masyarakat lainnya,&quot; ungkap dia.&nbsp;<br  border-box;\" />\n<br  border-box;\" />\nUsai paparan Bekasi Smart City, Wawali Ahmad Syaikhu menerima pertanyaan dari sejumlah siswa. Ada yang menanyakan mengenai program Bekasi Smart City lainnya, sistem penanggulangan kegawatdaruratan terpadu (SPGDT), profram mengatasi kemacetan dan mengubah mindset agar berfikir maju dan bisa mengatasi tantangan zaman.&nbsp;</div>\n\n<div dir=\"auto\"  border-box; text-align: justify;\"><br  border-box;\" />\nSemua siswa yang bertanya diberikan hadiah flask disk sebagai bentuk apresiasi keingintahuan mereka terhadap Bekasi Smart City.&nbsp;<br  border-box;\" />\n<br  border-box;\" />\n&quot;Bagus-bagus pertanyaannya dan saya hadiahi flask disk semoga bermanfaatkan untuk pendidikan kalian&quot; kata Wawai Ahmad Syaikhu. (goeng)</div>\n</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:37:00', '2016-12-12 04:37:00', NULL),
('eb3be197-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kota Bekasi akan Menggunakan Aplikasi SOROT', 'kota-bekasi-akan-menggunakan-aplikasi-sorot', 'Kota bekasi,-- &nbsp;Pemerintah kota Bekasi akan gunakan Aplikasi &quot;SOROT&quot;, Program Smart Online Reporting and Observation Tools (SOROT) merupakan aplikasi untuk menyampaikan pengaduan-pengad', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: 16px; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Kota bekasi,-- &nbsp;Pemerintah kota Bekasi akan gunakan Aplikasi &quot;SOROT&quot;, Program Smart Online Reporting and Observation Tools (SOROT) merupakan aplikasi untuk menyampaikan pengaduan-pengaduan masyarakat Kota Bekasi. hal ini disampaiakn oleh&nbsp;</span><span  border-box; font-size: 16px; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">kepala bidang perencanaan dinas tata Kota Bekasi, Erwim Guwinda, jumat (23/09) bertempat di Prees Room.</span></div>\n\n<p>&nbsp;</p>\n\n<div dir=\"ltr\"  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\"><span  border-box; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Kita tahu bahwa masyarakat saat ini sudah sangat mudah untuk menyampaikan keluhan ataupun pengaduan , perlu diketahui bahwa keluhan/ pengaduan lewat twiiter ke Pemerintah kota bekasi bisa mencapai lebih kurang &nbsp;10 ribu an pengaduan .dimana yang sering disampaikan yang paling banyak adalah tentang jalan rusak,saluran mampat, sampah, dan tentang kesehatan.&nbsp;</span></div>\n\n<div dir=\"ltr\"  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div dir=\"ltr\"  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\"><span  border-box; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Dalam bekasi smart city terdapat program Smart Online Reporting and Observation Tools (SOROT) yang merupakan aplikasi untuk menyampaikan pengaduan-pengaduan masyarakat Kota Bekasi . &nbsp;</span></div>\n\n<div dir=\"ltr\"  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\"><span  border-box; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Dijelaskan bahwa dalam proses pembentukkan smart city, Kota Bekasi baru sampai ditahap kedua yaitu roadmap bekasi smart city, dan di tahun 2018 diharapkan bekasi smart city sudah terealisasikan 100%, terang Erwin.&nbsp;</span></div>\n\n<div  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\"><br  border-box;\" />\n&nbsp;</div>\n\n<div  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">\n<div  border-box; font-family: HelveticaNeue, \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">\n<div dir=\"ltr\"  border-box;\">\n<div  border-box;\">&nbsp;</div>\n\n<div  border-box;\">Tahun ini Pemerintah Kota Bekasi menyiapkan anggaran sekitar 800 juta untuk mendukung program bekasi smart city, dengan bekerjasama dengan salah satu provider komunikasi serta dengan &nbsp;Institut Teknologi Bekasi (ITB) dalam merancang Bekasi Smart City.&nbsp;</div>\n\n<div  border-box;\">&nbsp;</div>\n\n<div dir=\"ltr\"  border-box;\">Selain Kota Bekasi, sudah ada beberapa kota di Indonesia sudah yang menjalankan konsep smart city, salah satunya adalah Kota Jakarta, yang menggunakan Qlue sebagai aplikasi Smart citynya. berbeda dengan Jakarta, Kota Bekasi tidak menggunakan Qlue, karena Qlue merupakan aplikasi berbayar.</div>\n\n<div  border-box;\">&nbsp;</div>\n\n<div  border-box;\">&quot;Kita tidak menggunakan Qlue, karena Qlue merupakan aplikasi berbayar, setahun awal memang gratis, tetapi selanjutnya akan dikenakan charge, maka dari itu kita bentuk SOROT agar masyarakat dapat menggunakan aplikasi untuk menyampaikan pengaduan secara gratis, SOROT tidak dikenakan biaya, dan tahun ini akan diadakan Brand Launching SOROT.&quot; jelas Erwin.<br  border-box;\" />\n&nbsp;</div>\n\n<div  border-box;\">Untuk sosialisasi Bekasi Smart City ini, pemerintah kota bekasi sudah terus mensosialisasikan ke kecamatan dan kelurahan, dengan melakukan Forum Group Discussion (FGD) bersama camat dan lurah.&nbsp;</div>\n\n<div  border-box;\">&nbsp;</div>\n\n<div  border-box;\">Dirinya juga berharap peran media sangat diperlukan dalam mensukseskan program smart city ini, sehingga dapat cepat dirasakan masyarakat hasil, pungkasnya. (yas)</div>\n</div>\n</div>\n</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:41:00', '2016-12-12 04:41:00', NULL),
('eb3be1e3-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota bersama Kadis Disbangkim Pantau Pengerjaan 8 Lantai RSUD Kota Bekasi', 'walikota-bersama-kadis-disbangkim-pantau-pengerjaan-8-lantai-rsud-kota-bekasi', 'Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pembangunan dan Pemukiman Kota Bekasi, Dadang Ginanjar memantau dan melihat pekerjaan Pembangunan Lanjutan 8 Lantai Rumah Sakit U', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kota Bekasi - Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pembangunan dan Pemukiman Kota Bekasi, Dadang Ginanjar memantau dan melihat pekerjaan Pembangunan Lanjutan 8 Lantai Rumah Sakit Umum Daerah (RSUD) Kota Bekasi di Mayor Oking, Ex Proyek pada hari Rabu (01/06).</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Pembangunan Gedung 8 Lantai RSUD Kota Bekasi khusus paru dan rehabilitasi narkoba yang sedang tahap pengerjaannya sudah mencapai 37%,&nbsp;dan akan perencanaannya selesai dan rampung pada bulan Desember 2016 ini.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&quot;Bulan desember akan sudah terlihat, dan akan rampung seperti setara gedung 8 lantai RSUD yang telah dibangun&quot; Jelas Kepala Dinas Pembangunan dan Pemukiman</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dari pihak PT. Sasmito yang mengerjakan pembangunan tersebut, bahwa akses jalan keluar nanti bisa tembus melalui Gedung RSUD yang berada di Jalan Veteran (RSUD lama) dan bisa juga melalui Mayor Oking karena jembatan penghubung antar RSUD Kota Bekasi ke Jalan Mayor Oking sudah jadi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Walikota Bekasi, menjelaskan bahwa kedepannya akan direncanakan jalan tembus dari Jalan Juanda menuju Jalan Veteran yang akan memudahkan akses pengguna jalan terhindar dari macet di perempatan Bekasi Junction, yang akan direncanakan akan ditahun 2018 mendatang setelah selesai pengerjaan semua rencana pembangunan di Kota Bekasi. (Ndoet)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:45:00', '2016-12-12 04:45:00', NULL),
('eb3be22e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Pimpin Kunker Kominda Kota Bekasi Ke Kota Makassar', 'wawali-pimpin-kunker-kominda-kota-bekasi-ke-kota-makassar', 'Wakil Walikota Bekasi H Ahmad Syaikhu memimpin kunjungan kerja Komunitas Intelijen Daerah (Kominda) Kota Bekasi ke Kominda Kota Makassar, Selasa, (6/12).\n\n&nbsp;\n\nRombongan Kominda Kota Bekasi diterim', '<p --=\"\" 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" kota=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Wakil Walikota Bekasi H Ahmad Syaikhu memimpin kunjungan kerja Komunitas Intelijen Daerah (Kominda) Kota Bekasi ke Kominda Kota Makassar, Selasa, (6/12).</p>\n\n<p>&nbsp;</p>\n\n<p 0px=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">Rombongan Kominda Kota Bekasi diterima Staf Ahli Walikota Makassar Bidang Hukum Ir H Kusaiyyin, Dandim Kota Makassar Letkol Kav Oto Sulu, Kepala Kesbangpol Kota Makassar Rompi Gading, jajaran Kominda Makassar di Kantot Walikota Makassar jalan Balai Kota, Ujung Pandang Kota Makassar.</p>\n\n<div 0px=\"\" 15px=\"\" 5px=\"\" class=\"a3s aXjCH m158d427fb077ff9d\" color:=\"\" direction:=\"\" div=\"\" font-family:=\"\" font-size:=\"\" id=\":m8\" margin:=\"\" overflow:=\"\" padding-bottom:=\"\" position:=\"\">\n<p 0px=\"\" ahmad=\"\" anggota=\"\" bekasi=\"\" didampingi=\"\" dinar=\"\" dir=\"ltr\" faisal=\"\" font-size:=\"\" itu=\"\" kabid=\"\" kepala=\"\" kesbangpol=\"\" kominda=\"\" kota=\"\" line-height:=\"\" margin:=\"\" muhammad=\"\" p=\"\" saat=\"\" serta=\"\" staf=\"\" syaikhu=\"\" text-align:=\"\" wasnas=\"\" wawali=\"\">Wawali Ahmad Syaikhu yang juga Ketua Kominda Kota Bekasi mengatakan berterima kasih atas kerjasama dalam kunjungan kerja Kota Bekasi ke Kota Makassar. Kedatangan mereka dalam rangka berbagi pengetahuan dan pengalaman masing-masinh terkait peran kominda daerah demi pembangunan dan kamtibmas dimasyarakat.</p>\n\n<p 0px=\"\" ahmad=\"\" bagi=\"\" baik=\"\" bekasi=\"\" berbagai=\"\" dan=\"\" di=\"\" dir=\"ltr\" font-size:=\"\" guna=\"\" ini=\"\" kami=\"\" kota=\"\" line-height:=\"\" makassar=\"\" margin:=\"\" masyarakat=\"\" menjadi=\"\" mewujudkan=\"\" p=\"\" pembelajaran=\"\" pengalaman=\"\" sejahtera=\"\" silaturahmi=\"\" text-align:=\"\" ucap=\"\" wawali=\"\" yang=\"\">Hal lain untuk dijadikan pembelajaran di Kota Bekasi, kata dia terkait bagaimana peran Kominda Kota Makassar, terkait dengan banyaknya tenaga kerja asing apalagi ia melihat Makassar mempunyai akses lebih besar masuknya pekerja asing lewat jalur Bandara dan Pelabuhan.</p>\n\n<p 0px=\"\" anggota=\"\" antar=\"\" aparatur=\"\" asing=\"\" dan=\"\" dir=\"ltr\" font-size:=\"\" kominda=\"\" koordinasi=\"\" kota=\"\" lewat=\"\" line-height:=\"\" makassar=\"\" margin:=\"\" p=\"\" pekerja=\"\" pengawasan=\"\" text-align:=\"\">Sementara itu, Staf Ahli Walikota Makassar Bidang Hukum Kusaiyyin mengatakan Walikota Makassar dan Wakil Walikota Makassar dan DPRD mencanangkan Kota Makassar dalam periode 2014-2019 mewujudkan masyarakat yang nyaman dan berkelas dunia.</p>\n\n<p 0px=\"\" agar=\"\" bebas=\"\" berkelas=\"\" dan=\"\" dicanangkan=\"\" dir=\"ltr\" dunia=\"\" font-size:=\"\" infrastruktur=\"\" kepada=\"\" kesejahteraan=\"\" line-height:=\"\" margin:=\"\" masyarakat=\"\" mewujudkannya=\"\" misi=\"\" p=\"\" pelayanan=\"\" pembangunan=\"\" pencapaian=\"\" text-align:=\"\" tiga=\"\" untuk=\"\" yakni=\"\" yang=\"\">&quot;Makassar 5 tahun kita ingin akan menjadi kota tinggal lebih nyaman untuk tinggal dan berusaha. Doakan kami juga mendapatkan Piala Adipura ketigakalinya&quot; ungkap Kusaiyyin.</p>\n\n<p 0px=\"\" baik=\"\" baru=\"\" berjalan=\"\" berkomunikasi=\"\" dan=\"\" di=\"\" dilakukan=\"\" diolah=\"\" dipindahkan=\"\" dir=\"ltr\" font-size:=\"\" gading=\"\" ke=\"\" kemudian=\"\" kepala=\"\" kesbangpol=\"\" kominda=\"\" korfominda=\"\" kota=\"\" line-height:=\"\" makassar=\"\" margin:=\"\" mengatakan=\"\" p=\"\" penanganan=\"\" permasalahan=\"\" rumpi=\"\" sangat=\"\" tempat=\"\" text-align:=\"\" yang=\"\">&quot;Kominda di Makassar akan membentuk sampai tingkat Kecamatan, dengan dasar Perwal. Hal ini akan menambah sinergitas antar anggota agar terjalin kamtibmas dimasyarakat,&quot; ungkap Rompi Gading.</p>\n\n<p 0px=\"\" aduan=\"\" aman=\"\" bagi=\"\" di=\"\" dir=\"ltr\" font-size:=\"\" guna=\"\" hotline=\"\" lanjut=\"\" line-height:=\"\" makassar=\"\" margin:=\"\" masyarakat=\"\" melouncing=\"\" memberikan=\"\" no=\"\" p=\"\" pemkot=\"\" penggunaan=\"\" rasa=\"\" telep text-align:=\"\">&quot;Di Kota Makassar ada nomor telepon terpusat, sehingga ketika aduan masyarakat akan langsung terpusat dengan nomor call 112, ini adalah salah satu program unggulan walikota Makassar,&quot; tambahnya.</p>\n&lt;p dir=&quot;ltr&quot; border-box;=&quot;&quot; margin:=&quot;&quot; 0px=&quot;&quot; 10px;=&quot;&quot; text-align:=&quot;&quot; justify;=&quot;&quot; font-size:=&quot;&quot; 14px;=&quot;&quot; line-height:=&quot;&quot; 22px;&quot;=&quot;&quot;&gt;Usai dialog, kegiatan kunker kali ini ditutup dengan tukar menukar cinderamata antara Wakil Walikota Bekasi H Ahmad Syaikhu dengan Staf Ahli Walikota Makassar Ir H Kusaiyyin. Ahmad Syaikhu pun mengundang jajaran Pemkot Makassar bila berkenan berkunjung ke Kota Bekasi. (goeng)</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:49:00', '2016-12-12 04:49:00', NULL),
('eb3be279-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kota Bekasi, - -Badan Pemberdayaan Perempuan Perlindungan Anak dan Keluarga Berencana dalam rangka p', 'kota-bekasi-badan-pemberdayaan-perempuan-perlindungan-anak-dan-keluarga-berencana-dalam-rangka-p', 'Kota Bekasi, -&nbsp;-Badan Pemberdayaan Perempuan Perlindungan Anak dan Keluarga Berencana dalam rangka peningkatan mutu petugas lapangan KB serta memupuk kebersamaa dalam suasana gembira di lokasi ya', '<p>Kota Bekasi, -&nbsp;-Badan Pemberdayaan Perempuan Perlindungan Anak dan Keluarga Berencana dalam rangka peningkatan mutu petugas lapangan KB serta memupuk kebersamaa dalam suasana gembira di lokasi yang memang memerlukan penggarapan KB.</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;Kegiatan dilaksanakan di Kelurahan Kalibaru dan Harapan Mulya Medan Satria Kota Bekasi selaku wilayah yang yang terintegrasi dengan Kampung KB, salah satu keuntungan pola penggarapan seperti ini yang akan diperoleh adalah petugas dapat bersinergi dengan sesama petugas KB dan dapat menerapkan ilmu yang diperoleh di wilayah garapan/Kecamatan masing-masing demikian harapan Ir. Hj Riswanti M.Si selaku Kepala BP3AKB.</p>\n\n<p>Adapun peserta diikuti dari 12 Kecamatan se-Kota Bekasi dan dilaksanakan dari tanggal 23 &ndash; 24 Nopember 2016 dimana hari pertama diberikan pencerahan oleh Pemerhati Demografi dan kependudukan Jawa Barat Drs. Rukman dan Ice Breaking dari bagian Dukungan Psikososial Dinas Sosial Provinsi Jawa Barat dimana nantinya di hari ke 2 dapat diimplementasikan di lapangan yaitu di 9 RW dari 2 Kelurahan yaitu Kelurahan Kalibaru dan Kelurahan Harapan Mulya, dimana dalam penggarapan KB dan Program Ketahanan Keluarga melalui pembentukan kelompok kegiatan serta identifikasi akseptor KB Baru dari peserta poktan demikian penjelasan Kabid Ketahanan Keluarga Dra. Rita Hartati. MM.</p>\n\n<p>Dalam kegiatan tersebut diberikan reward oleh Kepala BP3AKB Kota Bekasi kepada para Petugas KB yang dapat memsukseskan Program KB dengan membawa aseptor KB terbanyak selama tahun 2016 dengan pembagian Juara I Rp 3.000.000 Juara II Rp 2.000.000 dan Juara III Rp 1.000.000 semua itu untuk menciptakan keluarga di Kota Bekasi yang Maju, Sejahtera dan Ihsan. (swd)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:51:00', '2016-12-12 04:51:00', NULL),
('eb3be2cc-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Program Amnesti Pajak, Walikota Bekasi Serahkan Surat Pernyataan Harta', 'program-amnesti-pajak-walikota-bekasi-serahkan-surat-pernyataan-harta', 'Kota Bekasi --- Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pendapatan Kota Bekasi, H. Aan Suhanda hadir di Kantor Pelayanan Pajak Direktorat Jenderal Pajak Pratama Bekasi Selatan untuk m', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Kota Bekasi --- Walikota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Pendapatan Kota Bekasi, H. Aan Suhanda hadir di Kantor Pelayanan Pajak Direktorat Jenderal Pajak Pratama Bekasi Selatan untuk menyerahkan Surat Pernyataan Harta (SPH) WNI yang diserahkan dari pribadi Walikota Bekasi pada hari Selasa (29/11).</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; color: rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Pembangunan nasional Indonesia yang bertujuan memakmurkan seluruh rakyat Indonesia memerlukan sumber pendanaan besar yang bersumber dari pajak untuk menyadarkan kepatuhan masyarakat guna mengoptimalkan semua potensi dan sumberdaya yang ada.</span></p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Dalam rangka Amnesti Pajak, yakni penghapusan pajak yang seharusnya terhutang dan tidak dikenai sanksi administrasi perpajakan serta sanksi pidana di bidang perpajakan dengan cara mengungkap harta dan membayar uang tebusan, program tersebut untuk mempercepat pertumbuhan ekonomi rekstruturisasi ekonomi melalui repatriasi harta, reformasi pajak berkelanjutan dalam jangka pendek maupun panjang. Diharatlpkan, Amnesti Pajak ini meningkatkan investasi dan likuidasi domestik, perbaikan nilai tukar rupiah dan penurunan suku bunga data perpajakan yang valid.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Walikota berpesan agar lapisan masyarakat termasuk aparatur Pemerintah Kota Bekasi menyambut baik dan harus mengerti mengenai pentingnya amnesti pajak</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Pelaksanaan amnseti pajak yang ebrlangsung selama 9 bulan&nbsp; terhitung dari Juli 2016 hingga Maret 2017 ialah program nasional, jika telah berperan aktif dalam program tersebut para wajib pajak tersebut akan mendapatkan Surat Keterangan Pengampunan Pajak akan diberi fasilitas penghapusan pajak terutang dan sanksi</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&quot;Sebagai masyarakat peduli pembangunan kota nya masing masing, sadar akan wajib pajak melalui program nasional terkait amnesti pajak, Selaku pribadi saya menyerahkan surat pernyataan harta (SPH) untuk mengikuti kewajiban program dari pusat&quot; tegas Rahmat Effendi.</p>\n\n<p dir=\"ltr\"  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 12.8px; line-height: 22px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">Rencananya, Pemerintah Kota Bekasi akan mengadakan kerjasama dan tandatangan MoU dengan Kantor Wilayah Dirjen Pajak di Kota Bekasi, terkait dengan Validasi SSP dan BPHTB di Pemerintah Kota Bekasi. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:53:00', '2016-12-12 04:53:00', NULL),
('eb3be317-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '2017, Tunjangan Daerah ASN Kota Bekasi Naik 66 persen', '2017-tunjangan-daerah-asn-kota-bekasi-naik-66-persen', 'kota bekasi, Wakil Walikota Bekasi, Ahmad Syaikhu mengatakan bahwa tahun 2017, tunjangan Daerah ASN Pemkot Bekasi naik 66 persen, hal ini disampaikanya dalam sambutan pada peringatan HUT KORPRI ke 45 ', '<p 0px=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" line-height:=\"\" lucida=\"\" margin:=\"\" segoe=\"\" span=\"\" text-align:=\"\">kota bekasi, Wakil Walikota Bekasi, Ahmad Syaikhu mengatakan bahwa tahun 2017, tunjangan Daerah ASN Pemkot Bekasi naik 66 persen, hal ini disampaikanya dalam sambutan pada peringatan HUT KORPRI ke 45 tingkat Kota Bekasi, bertempat di Lapangan Alun-alun Kota Bekasi. selasa ( 29/11).&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p 0px=\"\" font-family:=\"\" font-size:=\"\" helvetica=\"\" line-height:=\"\" lucida=\"\" margin:=\"\" segoe=\"\" span=\"\" text-align:=\"\">kenaikan ini merupakan wujud pemerintah kota bekasi dalam memberikan kesejahteraan kepada aparatur Sipil Negara Pemkot Bekasi. &quot; kesejahteraan meningkat, harus juga ditunjang dengan kinerja yang meningkat dan mampu memberikan pelayanan yang maksimal kepada masyarkat&quot;, terangnya.&nbsp;</p>\n\n<div dir=\"ltr\" div=\"\" font-family:=\"\" helvetica=\"\" id=\"m_-1050480583823969081yui_3_16_0_1_1480413544372_14523\" lucida=\"\" segoe=\"\" text-align:=\"\">Sementara itu, Walikota Bekasi, Dr.Rahmat Effendi menuturkan hal yang sama usai mengikuti apel, &quot; tahun 2017 , tunjangan ASN Pemkot Bekasi akan naik mencapai 66 persen&quot;, katanya.</div>\n\n<div dir=\"ltr\" div=\"\" font-family:=\"\" helvetica=\"\" id=\"m_-1050480583823969081yui_3_16_0_1_1480413544372_14523\" lucida=\"\" segoe=\"\" text-align:=\"\">Selain itu, dirinya juga mengatakan telah berdiskusi &nbsp;dengan pimpinan PT Taspen &nbsp;membahas tentang kesejahteraan bagi para aparatur TKK yang telah sama-sama berperan membangun Kota Bekasi untuk memperoleh hak perlindungan kesejahteraan,&quot; katanya.</div>\n\n<div div=\"\" font-family:=\"\" helvetica=\"\" id=\"m_-1050480583823969081yui_3_16_0_1_1480413544372_14735\" lucida=\"\" segoe=\"\" text-align:=\"\">Walikota mencatat, jumlah ASN di lingkup pemerintah kota Bekasi saat ini berjumlah sekitar 5.000 orang dengan rata-rata kenaikan honor di atas 66 persen.</div>\n\n<p>&nbsp;</p>\n\n<p>&lt;div dir=&quot;ltr&quot; id=&quot;m_-1050480583823969081yui_3_16_0_1_1480413544372_14736&quot; border-box;=&quot;&quot; font-family:=&quot;&quot; &quot;helvetica=&quot;&quot; neue&quot;,=&quot;&quot; &quot;segoe=&quot;&quot; ui&quot;,=&quot;&quot; helvetica,=&quot;&quot; arial,=&quot;&quot; &quot;lucida=&quot;&quot; grande&quot;,=&quot;&quot; sans-serif;=&quot;&quot; text-align:=&quot;&quot; justify;&quot;=&quot;&quot;&gt;&quot;Saat ini honor untuk TKK rata-rata meningkat 66 persen untuk kita usahakan bisa setara dengan upah minimum yang berlaku di Kota Bekasi,&quot; tandasnya. (yas).</p>\n\n<p>&nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 04:55:00', '2016-12-12 04:55:00', NULL),
('eb3be362-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'SMK 3 Gelar Seminar dan Resmikan Sarana Perhotelan', 'smk-3-gelar-seminar-dan-resmikan-sarana-perhotelan', 'Kota Bekasi - SMK 3 Kota Bekasi mengadakan seminar pemanfaatan teknologi komputer dan jaringan kepada puluhan siswanya, Selasa, (23/8). Kegiatan tersebut menurut Kepala Sekolah SMK 3, Sugiyoyo untuk m', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Kota Bekasi - SMK 3 Kota Bekasi mengadakan seminar pemanfaatan teknologi komputer dan jaringan kepada puluhan siswanya, Selasa, (23/8). Kegiatan tersebut menurut Kepala Sekolah SMK 3, Sugiyoyo untuk membekali mereka agar menjadi SDM yang unggul dibidangnya.</p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&quot;Para siswa dan guru pengajar dibekali pemanfaatan teknologi untuk meningkatkan mutu pendidikan di SMK 3 Kota Bekasi,&quot; kata Sugiyono.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Dalam seminar kali ini juga dihadiri oleh Wakil Walikota Bekasi H Ahmad Syaikhu. Ia berkesempatan memaparkan fokus kedepan Pemkot Bekasi dalam menunju Kota Bekasi Smart City dalam meningkatkan pelayanan kepada masyarakat.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Pemkot Bekasi pun bekerjasama dengan beberapa pihak seperti PT. Telkom dan ITB dalam mendukung Smart City.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Lebih lanjut Ahmad Syaikhu berharap para siswa SMK terutama yang bergelut dibidang teknologi komputer dan jaringan, agar berupaya meningkatkan ilmu dan pengalamannya agar kedepan mampu memperkaya teknologi di Indonesia.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&quot;Para siswa mampu meningkatkan skill dalam IT dan membuat aplikasi yang memudahkan kita. Bukan hanya menjadi komsumen tapi juga produsen aplikasi maupun perangkat teknologi untuk menjawab tantangan kedepan. Kita ajak pemuda-pemudi lainnya agar peduli teknologi sebagai jalan menguasai dunia dan bermanfaat bagi masyarakat,&quot; harap Ahmad Syaikhu.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Selain memberikan motivasi terhadap para siswa mengenai pemanfaatan teknologi, Wawali Ahmad Syaikhu sekaligus meresmikan penggunaan sarana sekolah bidang perhotelan yakni ruang front office hotel dan kamar hotel sekelas pelayanan hotel bintang 4.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&quot;Ini sarana untuk meningkatkan kemampuan di bidang perhotelan bagi para siswa. Dan setelah lulus pun nantinya para siswa mampu merambah di bidang perhotelan di Indonesia,&quot; harap Wawali Ahmad Syaikhu.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Selain itu ia mengatakan mengenai kerjasama antara pemerintah dengan hotel-hotel di Bekasi untuk menyerap para lulusan SMK bukan hal yang mustahil dilakukan.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&quot;Ya kedepan bisa dilakukan untuk menambah pengalaman kerja para siswa. Kita tau beberapa tahun ini telah berdiri hotel-hotel baru di Kota Bekasi untuk menunjang pariwisata di Kota Bekasi,&quot; kata Wawali Ahmad Syaikhu.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Diketahui SMK 3 memiliki 4 program kejuruan seperti Teknik Komputer dan Jaringan, Akuntansi, Tata Boga dan Perhotelan dengan jumlah 1375 siswa/i dan terbagi dalam 40 kelas. (goeng)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-11 20:01:00', '2016-12-11 20:01:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3be3ad-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'SMAN 2 Kembali Didaulat Jadi paduan Suara Pada Upacara HUT RI ke 71Tingkat Kota Bekasi', 'sman-2-kembali-didaulat-jadi-paduan-suara-pada-upacara-hut-ri-ke-71tingkat-kota-bekasi', 'Bekasi &ndash; Pada &nbsp;Peringatan Hari Ulang Tahun (HUT) Kemerdekaan RI Ke-71, 17 Agustus 2016 &nbsp;di Alun-Alun Kota Bekasi, Rabu(17/08) sudah menjadi sesuatu yang biasa dan menjadi kebanggaan ba', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Bekasi &ndash; Pada &nbsp;Peringatan Hari Ulang Tahun (HUT) Kemerdekaan RI Ke-71, 17 Agustus 2016 &nbsp;di Alun-Alun Kota Bekasi, Rabu(17/08) sudah menjadi sesuatu yang biasa dan menjadi kebanggaan bagi SMAN 2 Kota Bekasi , khususnya Tim Paduan Suara SMAN 2 Kota Bekasi yang kerap mengisi acara-acara penting Pemerintah Kota Bekasi.</span></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;<span  border-box; font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Bukan hanya itu segudang prestasi juga diraih para anak didiknya, seperti sudah 6 kali berturut-turut meraih juara I paduan suara tingkat kota bekasi, ujar &nbsp;Hj.Eko Wati kepala sekolah SMAN 2 Kota Bekasi.ditemui&nbsp;</span></p>\n\n<div class=\"ii gt adP adO\" id=\":mj\"  border-box; font-size: 12.8px; direction: ltr; margin: 5px 15px 0px 0px; padding-bottom: 5px; position: relative; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">\n<div class=\"a3s aXjCH m1569b98a5bd2deca\" id=\":mi\"  border-box; overflow: hidden;\">\n<div  border-box; color: rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\">&ldquo; saya bangga &nbsp; dengan team paduan suara &nbsp; SMAN 2 , Alhamdulillah dalam setiap lomba &ndash; lomba selalu juara terutama tingkat Kota Bekasi selalu Juara satu.</div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\">Semua berkat kedisilpinan dan kekompokan baik pelatihnya maupun team paduan suaranya mereka selalu disiplin dalam setiap latihan.</div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; text-align: justify;\">Ekskul paduan suara SMAN 2 merupakan ekskul unggulan SMAN 2 sekali lagi saya bangga karena melalui senipun SMAN 2 dapat menujukan pretasinya,&rdquo; kata Hj.Eko Wati.</div>\n\n<div  border-box; text-align: justify;\">Dirinya menambahkan ini merupakan suatu kesempatan yang sangat membanggakan bagi mereka dapat tampil diacara-acara penting, karena dapat mebambah pengalaman dan juga meningkatkan kepercayaan diri karena tampil dihadapa ratusan bahkan ribuan orang.&nbsp;</div>\n\n<div  border-box; text-align: justify;\">&nbsp;</div>\n\n<div dir=\"ltr\"  border-box; text-align: justify;\">&rdquo;selain mengisi pada upacara HUT RI, paduan suara sman 2 juga mengisi pada upaca HUT Pramuka ke 55 tingkat kota Bekasi serta saat pengukuhan paskibra pun juga ikut andil , tandasnya.(yas)</div>\n</div>\n</div>\n</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 05:03:00', '2016-12-12 05:03:00', NULL),
('eb3be3ff-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'SMAN 2 Kota Bekasi Raih Juara 3 Lomba HAM Tingkat Jabar', 'sman-2-kota-bekasi-raih-juara-3-lomba-ham-tingkat-jabar', 'Kota Bekasi -. Tim Lomba Cerdas Cermat (LCC) Hak Asasi Manusia (HAM) SMAN 2 Kota Bekasi berhasil merebut juara 3 pada ajang Lomba Cerdas Cermat (LCC) Hak Asasi Manusia (HAM)&nbsp;&nbsp;tingkat Provins', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Kota Bekasi -. Tim Lomba Cerdas Cermat (LCC) Hak Asasi Manusia (HAM) SMAN 2 Kota Bekasi berhasil merebut juara 3 pada ajang Lomba Cerdas Cermat (LCC) Hak Asasi Manusia (HAM)&nbsp;&nbsp;tingkat Provinsi Jawa Barat (Jabar) tahun 2016 yang diselenggarakan di Kantor Kabupaten Karawang.</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">Penyerahan penghargaan diberikan kepada siswi SMAN 2 Kota Bekasi oleh Gubernur Jawa Barat, Ahmad Heryawan di sela-sela Apel Hari Pendidikan &nbsp;Nasional tingkat Jawa Barat tahun 2016 bertempat di Halaman Gedung Sate, beberapa waktu lalu.&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">Ekowati, Kepala Sekolah SMAN 2 Kota Bekasi mengatakan keberhasilan tersebut merupakan hasil kerja keras siswa/i yang membuahkan hasil baik, yang dapat mengharumkan nama sekolah serta nama Kota Bekasi.&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">Dirinya berharap para siswa/i ini tidak cepat puas. namun terus meningkatkan juaranya di tahun depan, katanya.&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div dir=\"ltr\"  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">Terlepas dari juara, Ekowati berupaya terus menerus memberikan pemahaman kepada siswa/i SMAN 2 Kota Bekasi agar bisa mengetahui tentang HAM. Para siswa/i juara &nbsp;tersebut nantinya bisa memberikan pengetahuan kepada teman-teman sekolah ataupun masyarakat sekitar. (yas/ronz)</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 05:30:00', '2016-12-12 05:30:00', NULL),
('eb3be44c-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '5 Pelajar SMA Kota Bekasi Raih Medali Olimpiade Sains Nasional', '5-pelajar-sma-kota-bekasi-raih-medali-olimpiade-sains-nasional', 'Kota Bekasi -&nbsp;Sebanyak 5 siswa Kota Bekasi menerima penghargaan diajang Olimpiade Sains Nasional (OSN) tingkat Nasional dan tingkat Internasional tahun 2016. Diajang Olimpiade Sains Nasional 2016', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kota Bekasi -&nbsp;Sebanyak 5 siswa Kota Bekasi menerima penghargaan diajang Olimpiade Sains Nasional (OSN) tingkat Nasional dan tingkat Internasional tahun 2016. Diajang Olimpiade Sains Nasional 2016 Kota Bekasi, meraih medali dua emas, satu perak, dan satu perunggu.</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Sementara satu siswa lainnya, masuk tahap olimpiade tingkat internasional yakni Nalendra Fajar dari SMA 2 Kota Bekasi. Ia mengikuti lomba bidang astronomi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dalam Apel pagi aparatur Pemkot Bekasi, Senin, (30/5), Wakil Walikota Bekasi Ahmad Syaikhu, bersama jajaran Pejabat Pemkot memberikan ucapan selamat atas diraihnya penghargaan kepada lima siswa berprestasi ini.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&ldquo;Selamat atas diraihnya penghargaan yang membuat bangga Kota Bekasi, Ini baru permulaan dan terus bersemangat meraih cita-cita. Dan penghargaan ini semoga memacu siswa lainnya agar meraih prestasi yang sama,&rdquo; ungkap Ahmad Syaikhu.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Peraih mendali emas di ajang Olimpiade Sain Nasional (OSN), yakni Adella Izdhihardana siswa SMA 2 Kota Bekasi bidang lomba geografi, dan M Dino Wibisono siswa SMA 5 Kota Bekasi pada bidang astronomi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Sementara diajang yang sama untuk mendali perak diraih Dwika Alam Indrajati Siswa SMA 2 Kota Bekasi pada bidang Geografi. Dan mendali perunggu diraih Rahma Ramadhanti siswa SMA 1 Kota Bekasi pada bidang ekonomi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Kepala Sekolah SMA 2 Ekowati saat mendampingi para siswa ini menerima penghargaan berharap siswa Kota Bekasi lebih berprestasi lagi dari waktu ke waktu.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Dalam kesempatan ini, 4 orang siswa SMA 2 mendapatkan penghargaan dan menjadi kebanggan bagi dia selaku kepala sekolah SMA 2.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&ldquo;Perjuangan untuk mendapatkan prestasi ini berkat kerja keras para siswa dan guru-guru pembimbing. Ini patut kita syukuri dan mendapatkan prestasi lagi di tahun akan datang,&rdquo; ungkap Ekowati.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Diinformasilan juga dalam kesempatan itu, Kepsek&nbsp; SMA 2 Kota Bekasi Ekowati seimbolis menerima piala penghargaan sebagai sekolah berbasis lingkungan atau kategori Green School diajang Indonesia Green Awatd 2016.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Penghargaan ini diberikan oleh Kementerian Lingkungan Hidup dan Kehutanan RI beberapa waktu lalu.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">Ekowati mengatakan SMA 2 Kota Bekasi terus berupaya mewujudkan sekolah ramah lingkungan sebab menjadi kewajiban pihaknya menciptakan lingkungan belajar yang nyaman bagi para siswanya.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Tahoma;\">&ldquo;Jika lingkungan sekolah bersih maka siswa akan nyaman saat belajar,&rdquo; kata Kepsek SMA 2 Ekowati.(goeng)</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 05:32:00', '2016-12-12 05:32:00', NULL),
('eb3be506-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pemkot Bekasi Segel 15 Bangunan Tak Berijin', 'pemkot-bekasi-segel-15-bangunan-tak-berijin', 'Kota Bekasi - Pemerintah Kota Bekasi melalui Dinas Tata Kota melakukan penyegelan terhadap 15 bangunan berupa warung remang-remang, cafe, lapo dan panti pijat yang berlokasi di Jalan Baru Cipendawa - ', '<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\"><span  border-box;\">Kota Bekasi - Pemerintah Kota Bekasi melalui Dinas Tata Kota melakukan penyegelan terhadap 15 bangunan berupa warung remang-remang, cafe, lapo dan panti pijat yang berlokasi di Jalan Baru Cipendawa - Jatiasih, Kelurahan Bojong Menteng, Kecamatan Rawalumbu, Selasa, 6 Desember 2016.&nbsp;</span>&nbsp;</span></span></div>\n\n<p>&nbsp;</p>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Penyegelan itu dilakukan karena kelima belas bangunan tersebut belum memiliki Ijin Mendirikan Bangunan (IMB).</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Setelah berita acara penyegelan dibacakan oleh Bagian Hukum Setda, petugas menyegel menara tersebut dengan memasang papan bertuliskan penyegelan &ldquo;bagunan ini disegel berdasarkan Perda Nomor 17 Tahun 2011 dan Perda Nomor 15 Tahun 2012&rdquo;.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">&ldquo;15 bangunan itu di segel karena sudah melanggar Peraturan Daerah (Perda) Nomor 17 Tahun 2011 tentang penyelengaraan izin pemanfaatan Ruang, Perda Nomor 15 Tahun 2012 Tentang Retribusi Izin Mendirikan Bagunan dan Peraturan Walikota Bekasi Nomor 42 Tahun 2014 tentang Pengendalian dan Pengawasan Penyelenggaraan Pemanfaatan Lahan dan Bangunan&rdquo; ujar Bilang Nauli Harahap,ST,MSE selaku Kasie Pengawasan, Pengendalian dan Pembongkaran Bagunan Pada Bidang Pengawasan Dan Pengendalian Pemanfaatan Lahan Dan Bangunan Dinas Tata Kota Kota Bekasi.</span></span></div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</div>\n\n<div  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Bilang juga mengatakan upaya penyegelan bangunan tersebut berlangsung kondusif yang melibatkan sejumlah instansi terkait dari Dinas Tata Kota, BPPT, Dinas Perhubungan, Satpol PP, bagian hukum, unsur TNI dan Polri, kecamatan dan kelurahan setempat. (ronz) &nbsp;</span></span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 05:36:00', '2016-12-12 05:36:00', NULL),
('eb3be559-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Peraturan Daerah Tahun 2005', 'peraturan-daerah-tahun-2005', 'PERDA NOMOR 15 TAHUN 2005&nbsp;&nbsp;&nbsp; Tentang Perubahan Atas Peraturan Daerah Kota Bekasi Nomor 06 Tahun 2004 Tentang Kedudukan Protokoler Dan Keuangan Pimpinan Dan Anggota Dewan Perwakilan Raky', '<p><a href=\"http://bekasikota.go.id/files/fck/file/LD PERDA 15 Tahun 2005.pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><u  border-box;\">PERDA NOMOR 15 TAHUN 2005</u></a><span  Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;&nbsp;&nbsp; Tentang Perubahan Atas Peraturan Daerah Kota Bekasi Nomor 06 Tahun 2004 Tentang Kedudukan Protokoler Dan Keuangan Pimpinan Dan Anggota Dewan Perwakilan Rakyat Daerah Kota Bekasi</span><br  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\" />\n<br  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\" />\n<a href=\"http://bekasikota.go.id/files/fck/file/LD PERDA 14 Tahun 2005.pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\"><u  border-box;\">PERDA NOMOR 14 TAHUN 2005</u></a><span  Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;&nbsp;&nbsp; Tentang Perda Nomor 02 Tahun 2005 Anggaran Pendapatan Dan Belanja Daerah Tahun Anggaran 2006</span><br  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\" />\n<br  border-box; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\" />\n<a href=\"http://bekasikota.go.id/files/fck/file/LD PERDA 13 Tahun 2005.pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none; font-family: Muli, sans-serif; font-size: 14px; text-align: justify;\