('eb3bebc1-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Daftar Penerima Hibah pada Perubahan APBD TA 2015', 'daftar-penerima-hibah-pada-perubahan-apbd-ta-2015', 'DAFTAR PENERIMA HIBAH PADA PERUBAHAN ANGGARAN PENDAPATAN DAN BELANJA DAERAH TAHUN ANGGARAN 2015\n\nKlik&nbsp; 2. Lampiran IV Peraturan Walikota Nomor 43 Tahun 2015 &nbsp;&nbsp;\n', '<p 0px=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" line-height:=\"\" margin:=\"\" span=\"\" text-align:=\"\">DAFTAR PENERIMA HIBAH PADA PERUBAHAN ANGGARAN PENDAPATAN DAN BELANJA DAERAH TAHUN ANGGARAN 2015</p>\n\n<p .=\"\" 0px=\"\" 1.=\"\" 2015=\"\" 43=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" iii=\"\" lampiran=\"\" line-height:=\"\" margin:=\"\" nomor=\"\" peraturan=\"\" span=\"\" tahun=\"\" walikota=\"\"><a href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/DAFTAR PENERIMA HIBAH PADA PERUBAHAN ANGGARAN PENDAPATAN DAN BELANJA DAERAH TA 2015 lamp 3.pdf\">Klik</a><a href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/DAFTAR PENERIMA HIBAH PADA PERUBAHAN ANGGARAN PENDAPATAN DAN BELANJA DAERAH TA 2015 lamp 3.pdf\"><span 0px=\"\" font-family:=\"\" font-size:=\"\" font-weight:=\"\" line-height:=\"\" margin:=\"\" p=\"\" text-align:=\"\">&nbsp; 2. Lampiran IV Peraturan Walikota Nomor 43 Tahun 2015 &nbsp;<span a=\"\" font-weight:=\"\" href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/DAFTAR PENERIMA BANTUAN SOSIAL PADA PERUBAHAN ANGGARAN PENDAPATAN DAN BELANJA DAERAH TA 2015 lamp IV.pdf\" span=\"\">&nbsp;</span></span></a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 08:05:00', '2016-12-12 08:05:00', NULL),
('eb3bec12-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Daftar Penerima Hibah pada APBD TA 2016', 'daftar-penerima-hibah-pada-apbd-ta-2016-2', '1. Lampiran III Peraturan Walikota Bekasi Nomor 01 Tahun 2016&nbsp;Klik&nbsp;\n\n&nbsp;2. Lampiran IV Peraturan Walikota Bekasi Nomor 01 Tahun 2016&nbsp;Klik&nbsp;\n', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">1. Lampiran III Peraturan Walikota Bekasi Nomor 01 Tahun 2016&nbsp;<span  border-box; font-weight: 700;\"><a href=\"http://apps.bekasikota.go.id/simda/download/2016/DAFTAR_PENERIMA_HIBAH_TA_2016.pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none;\">Klik</a></span>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: 12px;\">&nbsp;2. Lampiran IV Peraturan Walikota Bekasi Nomor 01 Tahun 2016&nbsp;</span><a href=\"http://bekasikota.go.id/files/uploaded/Penyerapan Anggaran/DAFTAR PENERIMA BANTUAN SOSIAL TA 2016 lamp IV.pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none;\"><span  border-box; font-weight: 700; font-size: 12px;\">Klik</span><span  border-box; font-size: 12px;\">&nbsp;</span></a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 08:07:00', '2016-12-12 08:07:00', NULL),
