er-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><a href=\"http://bekasikota.go.id/files/fck/kep No 313 th 2013_(1).pdf\"  border-box; background: 0px 0px; color: rgb(0, 68, 153); text-decoration: none;\"><u  border-box;\"><span  border-box; color: rgb(0, 0, 0);\"><span  border-box; font-weight: 700; color: rgb(50, 50, 50); font-family: arial, helvetica, verdana; line-height: 20px;\">Keputusan Walikota Bekasi No. 488/Kep. 313-Hum/VI/2013</span><span  border-box; font-family: arial, helvetica, verdana; line-height: 20px;\">&nbsp;Tentang&nbsp;</span><font face=\"arial, helvetica, verdana\"  border-box;\"><span  border-box; line-height: 20px;\">Kerangka Acuan Pengelolan Pelayanan Informasi dan Dokumentasi di Lingkungan Pemerintah Kota Bekasi</span></font></span></u></a></p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;.<em  border-box;\">Sumber : rdo_humas / Bagus Kuncuro Jati</em></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 08:15:00', '2016-12-12 08:15:00', NULL),
('eb3becaa-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Laporan Permintaan Informasi', 'laporan-permintaan-informasi', 'Laporan Permintaan Informasi Tahun 2011 Download / Lihat\n\nLaporan Permintaan Informasi Tahun 2013 &nbsp;Download / Lihat\n\nLaporan Permintaan Informasi Tahun 2014 &nbsp;&nbsp;Download / Lihat\n', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Laporan Permintaan Informasi Tahun 2011 <a href=\"http://bekasikota.go.id/files/fck/Lap Permintaan Informasi 2011.pdf\">Download / Lihat</a></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Laporan Permintaan Informasi Tahun 2013 &nbsp;<a href=\"http://bekasikota.go.id/files/fck/Laporan Informasi 2013.pdf\"  Muli, sans-serif; font-size: 14px; text-align: justify;\">Download / Lihat</a></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-size: 12px;\">Laporan Permintaan Informasi Tahun 2014 &nbsp;</span><span  Muli, sans-serif; font-size: 14px; text-align: justify;\">&nbsp;</span><a href=\"http://bekasikota.go.id/files/fck/Laporan_Setda_2014.pdf\"  Muli, sans-serif; font-size: 14px; text-align: justify;\">Download / Lihat</a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 08:19:00', '2016-12-12 08:19:00', NULL),
('eb3becf6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Tenaga Kerja', 'dinas-tenaga-kerja', '', '', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:35:00', '2016-12-12 09:35:00', NULL),
('eb3bed41-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Perhubungan', 'dinas-perhubungan', 'Deskripsi Dinas Perhubungan\n\n\n Terwujudnya Transportasi yang mantap guna mempercepat dan mendukung masyarakat yang kompetitif.\n Meningkatkan kualitas pelayanan bidang transportasi yang memenuhi standa', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; color: rgb(0, 0, 255);\"><span  border-box; font-weight: 700;\"><span  border-box; font-size: small;\">Deskripsi Dinas Perhubungan</span></span></span></p>\n\n<ul  border-box; margin: 0px; list-style: none; padding-right: 0px; padding-left: 0px; font-family: Muli, sans-serif; font-size: 14px;\">\n <li  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Terwujudnya Transportasi yang mantap guna mempercepat dan mendukung masyarakat yang kompetitif.</span></span></li>\n <li  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Meningkatkan kualitas pelayanan bidang transportasi yang memenuhi standar pelayanan dengan memprioritaskan peningkatan prasarana dan sarana transportasi serta pengembangan sistem angkutan umum yang menyediakan aksesibilitas tinggi, tepat waktu dan efisien.</span></span></li>\n <li  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Menjadikan operator dan penyedia jasa transportasiyang ada untuk lebih handal dan berdaya saing serta mampu memberikan pelayanan yang prima kepada masyarakat.</span></span></li>\n <li  border-box; text-align: justify;\"><span  border-box; font-size: small;\"><span  border-box; font-family: Arial;\">Meningkatkan keselamatan dan kenyamanan berlalu lintas di jalan dengan menitik beratkan pada kelancaran, ketertiban, keselamatan pengguna jasa angkutan jalan dan pejalan kaki</span></span></li>\n</ul>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:37:00', '2016-12-12 09:37:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3bed95-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Kependudukan dan Catatan Sipil', 'dinas-kependudukan-dan-catatan-sipil', 'PEMERINTAH KOTA BEKASI\n\nDINAS KEPENDUDUKAN DAN CATATAN SIPIL\n\n&nbsp;Alamat : Jl.Ir.H Juanda no.100 Telp. 88342729\n\nemail &nbsp;Ppidcasip.kotabekasi@yahoo.co.id\n\nVISI DAN MISI\n\nVISI :&nbsp;PROFESIONAL ', '<p>PEMERINTAH KOTA BEKASI</p>\n\n<h2>DINAS KEPENDUDUKAN DAN CATATAN SIPIL</h2>\n\n<p><big>&nbsp;Alamat : Jl.Ir.H Juanda no.100 Telp. 88342729</big></p>\n\n<p><small>email &nbsp;</small><a href=\"mailto:Ppidcasip.kotabekasi@yahoo.co.id\"><small>Ppidcasip.kotabekasi@yahoo.co.id</small></a></p>\n\n<p>VISI DAN MISI</p>\n\n<p>VISI :&nbsp;PROFESIONAL DALAM PELAYANAN ADMINISTRASI KEPENDUDUKAN DAN CATATAN SIPIL YANG BERBASIS TEKNOLOGI DAN INFORMASI.</p>\n\n<p>MISI :</p>\n\n<ol>\n <li>MENINGKATKAN KELANCARAN PELAYANAN KANTOR</li>\n <li>MENINGKATKAN PELAYANAN ADMINISTRASI KEPENDUDUKAN</li>\n <li>MEMBANGUN DATABASE KEPENDUDUKAN YANG BERBASIS TEKNOLOGI DAN INFORMASI</li>\n</ol>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>A.&nbsp;&nbsp;&nbsp;&nbsp; VISI DAN MISI</p>\n\n<p>1.&nbsp;&nbsp;&nbsp;&nbsp;Visi</p>\n\n<p>Visi berkaitan dengan pandangan jauh kedepan menyangkut kemana instansi pemerintah harus dibawa dan diarahkan agar dapat berkarya secara konsisten, tetap eksis, antisipatif dan inovatif serta produktif.</p>\n\n<p>Visi adalah suatu gambaran menantang tentang keadaan masa depan yang berisikan cita dan citra yang ingin diwujudkan.</p>\n\n<p>&ldquo;Profesional dalam Pelayanan Administrasi yang Berbasis&nbsp;Teknologi dan Informasi&quot;</p>\n\n<p>penjelasan dari visi tersebut adalah:</p>\n\n<p>Yang dimaksud dengan &quot;Profesional dalam Pelayanan Administrasi yang Berbasis Informasi dan Teknologi&quot; adalah memberikan pelayanan prima kepada masyarakat dengan menggunakan teknologi sebagai sumber pengaksesan data serta dapat dilaksanakannya pemberian informasi yang cepat, tepat dan akurat kepada masyarakat ataupun pihak lainnya.</p>\n\n<p><br />\n2.&nbsp;&nbsp;&nbsp;Misi</p>\n\n<p>Misi adalah sesuatu yang diemban atau dilaksanakan oleh instansi pemerintah, sebagai penjabaran dari visi yang telah ditetapkan.</p>\n\n<p>Dengan pernyataan misi diharapkan seluruh aparatur Dinas Kependudukan dan Catatan Sipil dan pihak-pihak yang berkepentingan dapat mengetahui dan mengenal keberadaan dan peran Dinas Kependudukan dan Catatan Sipil.</p>\n\n<p>Misi suatu instansi harus jelas dan sesuai dengan tugas pokok dan fungsinya serta terkait dengan kewenangan yang dimiliki dari peraturan perundangan.Adapun misi dari Dinas Kependudukan dan Catatan Sipil Kota Bekasi.</p>\n\n<p>Untuk merealisasikan visi sebagaimana tersebut diatas, maka telah ditetapkan misi yaitu :</p>\n\n<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Meningkatkan Kelancaran Pelayanan Kantor</p>\n\n<p>Dalam upayanya Dinas Kependudukan dan Catatan Sipil selain melaksanakan pelayanan kepada masyarakat juga membutuhkan sarana dan prasarana seperti alat tulis ataupun yang lainnya guna mendukung terlaksananya pelayanan Good&nbsp;<em>Governance.</em></p>\n\n<p>.&nbsp;</p>\n\n<p>.2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Meningkatkan Pelayanan Administrasi Kependudukan</p>\n\n<p>Tugas utama sektor kependudukan dan pencatatan sipil adalah memberikan pelayanan kependudukan dan pencatatan sipil untuk seluruh masyarakat. Oleh karena itu upaya kependudukan dan pencatatan sipil yang harus diutamakan adalah tertib administrasi kependudukan disetiap tingkatan wilayah pemerintahan. Selain itu upaya melaksanakan pembinaan, pengawasan dan pengendalian dibidang kependudukan dan pencatatan sipil diprioritaskan.</p>\n\n<p>3.&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;Membangun Database Kependudukan yang Berbasis Informasi dan Teknologi.</p>\n\n<p>Keberhasailan pembangunan kependudukan tidak semata-mata ditentukan oleh hasil kerja keras sektor kependudukan dan pencatatan sipil, tapi sangat dipengaruhi oleh hasil kerja keras serta kontribusi positif pelbagai sektor pembangunan lainnya. Untuk optimalisasi hasil serta kontribusi positif tersebut, harus dapat diupayakan masuknya wawasan kependudukan, sebagai azas pokok program pembangunan kota Bekasi.</p>\n\n<p>Dengan perkataan lain untuk dapat terwujudnya tertib administrasi kependudukan dan catatan sipil dalam rangka meningkatkan pelayanan, para penanggungjawab pembangunan harus memasukkan pertimbangan-pertimbangan kependudukan dan pencatatan sipil dalam semua kebijakan pembangunan. Selain daripada itu sektor informasi yang berbasis pada teknologi dalam hal ini pelaksanaan program Sistem Informasi Administrasi Kependudukan (SIAK) sangatlah berpengaruh dalam pencapaian Visi Dinas Kependudukan dan Catatan Sipil.</p>\n\n<p>B.&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;TUJUAN</p>\n\n<p>&nbsp;Tujuan yang ingin dicapai Dinas Kependudukan dan Catatan Sipil sebagaimana tersebut diatas adalah sebagai berikut:</p>\n\n<ol>\n <li>Meningkatnya sarana prasarana dan aparatur yang memadai.</li>\n <li>Memenuhi Pemahaman Masyarakat tentang Pentingnya Kepemilikan&nbsp;&nbsp;&nbsp;&nbsp; Administrasi Kependudukan dan Catatan Sipil</li>\n <li>Mengoptimalkan Database Kependudukan di Kota Bekasi secara &nbsp; &nbsp;&nbsp; berkesinambungan</li>\n</ol>\n\n<p>&nbsp;</p>\n\n<p>C.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;SASARAN</p>\n\n<ol>\n <li>Tersedianya Data Kependudukan yang lengkap, akurat terpadu dan terbaharui &nbsp; berbasis IT</li>\n <li>Terselenggaranya pelayanan administrasi kependudukan dan catatan sipil yang optimal</li>\n <li>Tersedianya Dokumen Perkembangan Kependudukan</li>\n <li>Lancarnya pelayanan adnministrasi kependudukan yang optimal</li>\n</ol>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:38:00', '2016-12-12 09:38:00', NULL),
('eb3bede0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Tata Kota', 'dinas-tata-kota', 'Kota adalah tempat konsentrasi penduduk lebih padat dari wilayah sekitarnya karena terjadi pemusatan kegiatan fungsional yang berkaitan dengan kegiatan atau aktivitas penduduknya, dan dengan ungkapan ', '<p>Kota adalah tempat konsentrasi penduduk lebih padat dari wilayah sekitarnya karena terjadi pemusatan kegiatan fungsional yang berkaitan dengan kegiatan atau aktivitas penduduknya, dan dengan ungkapan berbeda kota adalah permukiman yang berpenduduk relatif besar, luas, areal terbatas, pada umumnya bersifat non agraris, kepadatan penduduk relatif tinggi, tempat sekelompok orang dalam jumlah tertentu dan bertempat tinggal dalam suatu wilayah geografis tertentu yang cenderung berpola hubungan rasional, ekonomis dan individualistis.</p>\n\n<p>Perencanaan dalam suatu definisi yang sederhana&nbsp;adalah&nbsp;menetapkan suatu tujuan dan memilih langkah-langkah yang diperlukan untuk mencapai tujuan tersebut.</p>\n\n<p>Perencanaan&nbsp;&nbsp;tata ruang kawasan perkotaan dapat diartikan sebagi kegiatan merencanakan pemanfaatan potensi dan ruang perkotaan serta pengembangan. Perencanaan tata ruang kota secara prosedural mengacu pada UU No.24 Tahun 1992 tentang Penataan ruang. dan perencanaan tata ruang perkotaan secara sederhana dapat diartikan sebagai kegiatan perencanaan pemanfaatan potensi dan ruang perkotaan serta pengembangan infrastruktur pendukung yang dibutuhkan untuk mengakumulasi kegiatan social ekonomi yang diinginkan.</p>\n\n<p>Menurut Undang-undang Nomor 26 Tahun 2007 tentang Penataan Ruang, penataan ruang adalah suatu sistem proses perencanaan tata ruang, pemanfaatan ruang dan pengendalian pemanfaatan ruang, merupakan satu kesatuan yang tidak terpisahkan antara yang satu dan yang lain dan harus dilakukan sesuai dengan kaidah penataan ruang sehingga diharapkan :</p>\n\n<ol>\n <li>Dapat mewujudkan pemanfaatan ruang yang berhasil guna dan berdaya guna serta mampu mendukung pengelolaan lingkungan hidup yang berkelanjutan.</li>\n <li>Tidak terjadi pemborosan pemanfaatan ruang.</li>\n <li>Tidak menyebabkan terjadinya penurunan kualitas ruang.</li>\n</ol>\n\n<p>Dengan dibentuknya Dinas Tata&nbsp;Kota&nbsp;Kota Bekasi yang telah ditetapkan berdasarkan Peraturan Daerah Nomor 6 Tahun 2010, maka Dinas Tata Ruang Kota Bekasi berkewajiban menjadi &ldquo;<em>leader&rdquo;</em>&nbsp;untuk melaksanakan penataan ruang di wilayah Kota Bekasi yang meliputi kegiatan perencanaan, pemanfaatan, pengawasan dan pengendalian.</p>\n\n<p>Pengendalian pemanfaatan ruang dilakukan&nbsp;&nbsp;melalui perizinan pemanfaatan ruang, pemberian insentif dan disinsentif, serta pengenaan sanksi. Perizinan pemanfaatan ruang dimaksudkan sebagai upaya penertiban pemanfaatan ruang sehingga setiap pemanfaatan ruang harus dilakukan sesuai dengan Rencana Tata Ruang. Izin pemanfaatan ruang diatur dan diterbitkan oleh pemerintah dan pemerintah daerah sesuai dengan kewenangannya masing-masing. Pemanfaatan ruang yang tidak sesuai dengan rencana tata ruang, baik yang dilengkapi dengan izin maupun yang tidak memiliki izin, dikenai sanksi administratif, sanksi pidana penjara, dan atau sanksi pidana denda.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:40:00', '2016-12-12 09:40:00', NULL),
('eb3bee2d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Bangunan dan Permukiman Kota Bekasi', 'dinas-bangunan-dan-permukiman-kota-bekasi', 'Dinas Bangunan dan Permukiman Kota Bekasi (Disbangkim Kota Bekasi)\n\nDinas ini telah mengalami beberapa kali perubahan nama, dari mulai P2B/Distawasbang (Dinas Penataan dan Pengawasan Bangunan) Kota Be', '<p>Dinas Bangunan dan Permukiman Kota Bekasi (Disbangkim Kota Bekasi)</p>\n\n<p>Dinas ini telah mengalami beberapa kali perubahan nama, dari mulai P2B/Distawasbang (Dinas Penataan dan Pengawasan Bangunan) Kota Bekasi menjadi Dinas Bangunan dan Pemadam Kebakaran Kota Bekasi (Disbangker) dan terakhir pada tahun 2014 berganti nama menjadi Dinas Bangunan dan Permukiman Kota Bekasi (Disbangkim Kota Bekasi)</p>\n\n<p>Perubahan nama berdasarkan :</p>\n\n<ol>\n <li>Peraturan Daerah Kota Bekasi Nomor 10 Tahun 2014 Tentang Peraturan Daerah Tentang Perubahan Ketiga Atas Peraturan Daerah Kota Bekasi Nomor 06 Tahun 2008 Tentang Dinas Daerah Kota Bekasi.</li>\n <li>Peraturan Walikota Bekasi Nomor 57 Tahun 2014 Tentang Tugas, Fungsi dan Tata Kerja Serta Rincian Tugas Jabatan Pada Dinas Bangunan dan Permukiman Kota Bekasi.</li>\n</ol>\n\n<p>Tugas Pokok&nbsp;</p>\n\n<p>Dinas Bangunan Dan Permukiman mempunyai tugas pokok melaksanakan sebagian urusan Pemerintahan Daerah bidang bangunan dan pemukiman berdasarkan asas otonomi dan tugas pembantuan meliputi bidang perencanaan teknis, bidang bangunan gedung, bidang perumahan dan permukiman serta bidang pengawasan dan pengendalian</p>\n\n<p>Fungsi</p>\n\n<ol >\n <li>Perumusan kebijakan teknis keciptakaryaan di Daerah;&nbsp;</li>\n <li>Penyelenggaraan urusan pemerintahan dan pelayanan umum di bidang perencanaan teknis, bidang bangunan gedung, bidang perumahan dan permukiman serta bidang pengawasan dan pengendalian sesuai dengan lingkup tugasnya;&nbsp;</li>\n <li>Pembinaan dan pelaksanaan tugas teknis operasional di bidang perencanaan teknis, bidang bangunan gedung, bidang perumahan dan permukiman serta bidang pengawasan dan pengendalian sesuai dengan lingkup tugasnya;&nbsp;</li>\n <li>pelaksanaan tugas lain yang diberikan oleh Walikota sesuai dengan tugas dan fungsinya.</li>\n</ol>\n\n<p>&nbsp;</p>\n\n<p>Alamat Dinas Bangunan dan Permukiman Kota Bekasi</p>\n\n<p>Jl. Jend. A. Yani No. 1 Bekasi (Lt. 3 Gd. 10 Lt)</p>\n\n<p>Telp. 021- 28088805 Fax. 021- 28088804</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:40:00', '2016-12-12 09:40:00', NULL),
('eb3bee79-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'DINAS PERTAMANAN PEMAKAMAN DAN PENERANGAN JALAN UMUM', 'dinas-pertamanan-pemakaman-dan-penerangan-jalan-umum', 'Alamat&nbsp;:&nbsp;Jl. Lapangan Bekasi Tengah No. 2 Bekasi Telp : (021) 88349645\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n\n', '<p>Alamat&nbsp;:&nbsp;Jl. Lapangan Bekasi Tengah No. 2 Bekasi Telp : (021) 88349645</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>PROFILE DINAS&nbsp;&nbsp;PERTAMANAN PEMAKAMAN DAN</p>\n\n<p>PENERANGAN JALAN UMUM KOTA BEKASI</p>\n\n<p>&nbsp;</p>\n\n<p>Dinas Pertamanan Pemakaman dan Penerangan Jalan Umum merupakan bagian dari Pemerintah Kota Bekasi dengan fungsinya sebagai Dinas yang menangani masalah-masalah maupun setiap kebutuhan dan kepentingan yang menyangkut bidang pelayanan pertamanan, pemakaman maupun penerangan jalan umum.</p>\n\n<p>Berdasarkan Peraturan Daerah No. 6 Tahun 2008 tentang Dinas Daerah Kota Bekasi&nbsp; (Lembaran Daerah Tahun 2008 Nomor 6 seri D) serta Peraturan Walikota Nomor 72 Tahun 2008 tentang Tugas, Fungsi dan Tata Kerja serta rincian Tugas Jabatan pada Dinas Pertamanan Pemakaman dan Penerangan Jalan Umum. Dinas Pertamanan Pemakaman dan Penerangan Jalan Umum membawahi Bidang Pertamanan, Bidang Pemakaman, Bidang Penerangan Jalan Umum, Bidang Sarana dan Prasarana dan Bagian Sekretariat yang membawahi Subag Perencanaan, Subag Umum dan Kepegawaian dan Subag Keuangan serta UPTD TPU Perwira dan UPTD TPU Pedurenan sebagaimana dirubah dengan Peraturan Walikota Bekasi Nomor 14 Tahun 2015 tentang Perubahan Kedua atas Peraturan Walikota Bekasi Nomor 72 Tahun 2008 tentang Tugas dan Tata Kerja Serta Rincian Tugas Jabatan pada Dinas Pertmanan Pemakaman dan Penerangan Jalan Umum Kota Bekasi.</p>\n\n<p>&nbsp;</p>\n\n<p>Kedudukan Dinas Pertamanan&nbsp;Pemakaman dan Penerangan Jalan Umum sebagai unsur dinas yang bertanggung jawab langsung kepada Walikota melalui Sekretaris Daerah memiliki&nbsp;tugas-tugas pokok yang meliputi : urusan bidang pertamanan, bidang pemakaman, bidang penerangan jalan umum serta bidang sarana dan prasarana.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:42:00', '2016-12-12 09:42:00', NULL),
('eb3beede-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Perindustrian, Perdagangan dan Koperasi Kota Bekasi', 'dinas-perindustrian-perdagangan-dan-koperasi-kota-bekasi', 'Tugas Pokok Dan Fungsi Dinas Perindustrian, Perdagangan dan Koperasi Kota Bekasi\n\n&nbsp;\n\n&nbsp;\n\nTugas pokok dan fungsi Dinas Perindustrian Perdagangan dan Koperasi Kota Bekasi dititik beratkan pada ', '<p>Tugas Pokok Dan Fungsi Dinas Perindustrian, Perdagangan dan Koperasi Kota Bekasi</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>Tugas pokok dan fungsi Dinas Perindustrian Perdagangan dan Koperasi Kota Bekasi dititik beratkan pada pelayanan publik dalam bidang pelayanan perindustri perdagangan dan koperasi serta UMKM dalam memperlancar roda perekonomian, mendorong pertumbuhan kota melalui kegiatan jasa dan perdagangan. Pentingnya pelayanan tersebut untuk meningkatkan sentra-sentra industri perdagangan dan koperasi serta UMKM dalam menunjang Visi Kota Bekasi,&nbsp;yaitu&nbsp;<em>BEKASI MAJU, SEJAHTERA DAN IHSAN.</em></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;A.&nbsp;&nbsp;&nbsp;&nbsp;Gambaran Singkat Organisasi</p>\n\n<p><br />\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Organisasi Dinas Perindustrian, Perdagangan dan Koperasi Kota Bekasi :</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1. Pimpinan adalah Kepala Dinas;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2.&nbsp;Pembantu Pimpinan adalah&nbsp;Sekretariat&nbsp;dan Kepala Subag;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 3.&nbsp;Pelaksana adalah Kepala Bidang,&nbsp;Kepala Seksi, UPTD dan&nbsp;Kelompok&nbsp;&nbsp;&nbsp;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Jabatan Fungsional.</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Susunan Organisasi Dinas Perindustrian, Perdagangan dan Koperasi :</p>\n\n<p>&nbsp;1.&nbsp;&nbsp;&nbsp;&nbsp;Kepala Dinas;</p>\n\n<p>&nbsp;2.&nbsp;&nbsp;&nbsp;&nbsp;Sekretariat, membawahi :</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a.&nbsp;Sub Bagian Perencanaan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b.&nbsp;Sub Bagian Umum&nbsp;dan Kepegawaian dan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; c.&nbsp;Sub Bagian Keuangan.</p>\n\n<p>&nbsp;3.&nbsp;&nbsp;&nbsp;&nbsp;Bidang Industri, membawahi&nbsp;:</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a.&nbsp;Seksi Industri Agro Hasil Hutan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b.&nbsp;Seksi Industri&nbsp;Logam, Mesin dan Elektronika dan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; c.&nbsp;Seksi Industri Kimia, Tekstil dan Aneka.</p>\n\n<p>&nbsp;4.&nbsp;&nbsp;&nbsp;&nbsp;Bidang&nbsp;Perdagangan, membawahi&nbsp;:</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a.&nbsp;Seksi&nbsp;Wajib Daftar Perusahaan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b.&nbsp;Seksi&nbsp;Bina Usaha Perdagangan dan;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; c.&nbsp;Seksi Ekspor Impor.</p>\n\n<p>&nbsp;5.&nbsp;&nbsp;&nbsp;&nbsp;Bidang&nbsp;Koperasi, membawahi&nbsp;:</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a.&nbsp;Seksi Bina&nbsp;Lembaga dan Sumber Daya Manusia;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b.&nbsp;Seksi&nbsp;Bina Usaha;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; c.&nbsp;Seksi Bina Program, Monitoring, Evaluasi dan Fasilitasi.</p>\n\n<p>&nbsp;6.&nbsp;&nbsp;&nbsp;&nbsp;Bidang&nbsp;Usaha Mikro, Kecil dan Menengah, membawahi&nbsp;:</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a.&nbsp;Seksi Bina&nbsp;Lembaga dan Sumber Daya Manusia;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b.&nbsp;Seksi&nbsp;Bina Usaha;</p>\n\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; c.&nbsp;Seksi Bina Program, Monitoring, Evaluasi dan Fasilitasi.</p>\n\n<p>&nbsp;</p>\n\n<p>B. Informasi Layanan&nbsp;&nbsp;:</p>\n\n<p>&nbsp; &nbsp; &nbsp;&nbsp;a.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Izin Usaha Industri (IUI)</p>\n\n<p>b.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Izin Usaha Toko Medern (IUTM)</p>\n\n<p>c.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Surat Izin Usaha Perdagangan (SIUP)</p>\n\n<p>d.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tanda Daftar Perusahaan (TDP)</p>\n\n<p>e.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tanda Daftar Gudang (TDG)</p>\n\n<p>f.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Izin Gangguan (HO)</p>\n\n<p>g.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Pendirian Koperasi</p>\n\n<p>h.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Penyuluhan Koperasi</p>\n\n<p>i.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Izin Usaha Simpan Pinjam</p>\n\n<p>j.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Pemberian Rekomendasi Koperasi</p>\n\n<p>k.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Fasilitasi Sertifikasi Halal</p>\n\n<p>&nbsp;</p>\n\n<p>Alamat Kantor Dinas Perindustrian, Perdagangan dan Koperasi :</p>\n\n<p>JL. Jend. A. Yani No. 1 Kota Bekasi</p>\n\n<p>Telepon : (021) 28088801&nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:43:00', '2016-12-12 09:43:00', NULL),
('eb3bef2b-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Perekonomian Rakyat', 'dinas-perekonomian-rakyat', 'Dinas Perekonomian Rakyat merupakan salah satu Satuan Kerja Pemerintah Daerah Kota Bekasi berdasarkan Peraturan Pemerintah Nomor :41 Tahun 2007 tentang Organisasi Perangkat Daerah serta ditetapkannya ', '<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Dinas Perekonomian Rakyat merupakan salah satu Satuan Kerja Pemerintah Daerah Kota Bekasi berdasarkan Peraturan Pemerintah Nomor :41 Tahun 2007 tentang Organisasi Perangkat Daerah serta ditetapkannya Peraturan Walikota Bekasi No. 74 Tahun 2008 tentang Tugas, Fungsi dan Tata Kerja serta Rincian Tugas Jabatan pada Dinas Perekonomian Rakyat (Dispera) Kota Bekasi</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Peran dan fungsi Dispera Kota Bekasi dalam pembangunan daerah cukup strategis berkaitan dengan perkembangan peningkatan pembangunan perekonomian kerakyatan, terutama pada sektor-sektor riil seperti pedagang. Sembako, pedagang Kaki Lima (PKL) dan sebagainya. Pada umumnya Dispera Kota Bekasi dibentuk dalam rangka menumbuhkembangkan sektor-sektor riil dengan ditunjang oleh kewenangan yang dimilikinya. Sehingga Dispera Kota Bekasi sebagaimana SKPD lainnya memiliki peranan perencanaan, pelaksanaan, monitoring dan evaluasi atau tugas, pokok dan fungsinya dengan tetap menerapkan profesionalitas dan akuntabilitas kinerja.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Dispera Kota Bekasi berdasarkan keempat aspek organisasi dan perannnya tersebut menjadikannya salah satu SKPD yang memiliki kewajiban peningkatan kekuatan keuangan daerah dari sisi Pendapatan Asli Daerah (PAD). oleh karenannya Dispera Kota Bekasi sering pula disebut sebagai SKPD penghasil pendapatan daerah.</p>\n\n<p>&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Namun demikian Dispera Kota Bekasi senantiasa berupaya memberikan pelayanan terbaik terhadap para pelaku ekonomin di sektor riil tersebut. Sehingga apa yang dilakukan oleh Dispera Kota Bekasi benar-benar bermanfaat bagi masyarakat pada umumnya dan termasuk bagi Pemerintah Kota Bekasi sendiri.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">Dengan demikian sinergitas dalam pembangunan darah benar-benar dapat dijadikan sebagai salah satu modal pembangunan. Dispera Kota Bekasi dibentuk guna menunjang capaian Visi dan Misi Kota Bekasi, menumbuh kembangkan pembangunan ekonomi daerah dan kesejahteraan masyarakat Kota Bekasi.</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-weight: 700;\">VISI</span></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: justify; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-weight: 700;\"><img alt=\"\" src=\"http://bekasikota.go.id/files/uploaded/image/Dispera/5.jpg\"  border-box; border: 0px; vertical-align: middle; width: 615px; height: 459px;\" /></span></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-weight: 700;\">MISI</span></p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\">&nbsp;</p>\n\n<p  border-box; margin: 0px 0px 10px; text-align: center; font-size: 14px; line-height: 22px; font-family: Muli, sans-serif;\"><span  border-box; font-weight: 700;\"><img alt=\"\" src=\"http://bekasikota.go.id/files/uploaded/image/Dispera/4.jpg\"  border-box; border: 0px; vertical-align: middle; width: 615px; height: 464px;\" /></span></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:44:00', '2016-12-12 09:44:00', NULL),
('eb3bef78-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas Pendapatan Daerah', 'dinas-pendapatan-daerah', 'DINAS PENDAPATAN DAERAH\n\n&nbsp;\n\n&nbsp;Jl. Ir. H. Juanda No.100\n\nKel. Margahayu, Kec. Bekasi Timur\n\nNo Tlp. (021) 88397963, 88397965&nbsp;\n\nB E K A S I\n', '<p><big>DINAS PENDAPATAN DAERAH</big></p>\n\n<h1>&nbsp;</h1>\n\n<p>&nbsp;Jl. Ir. H. Juanda No.100</p>\n\n<p>Kel. Margahayu, Kec. Bekasi Timur</p>\n\n<p>No Tlp. (021) 88397963, 88397965&nbsp;</p>\n\n<p>B E K A S I</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-12 09:46:00', '2016-12-12 09:46:00', NULL),
('eb3befc6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'BP3KB Kota Bekasi Mengadakan Sosialisasi  Undang - undang Nomor 44 Tahun 2008 Tentang Pornografi', 'bp3kb-kota-bekasi-mengadakan-sosialisasi-undang-undang-nomor-44-tahun-2008-tentang-pornografi', '&nbsp;\n\nPemda Kota Bekasi dalam hal ini oleh BP3AKB Kota Bekasi bersama Kementrian Pemberdayaan Perempuan dan Perlindungan Anak Republik Indonesia megadakan Sosialisasi dengan tema &ldquo; Upaya Melin', '<p>&nbsp;</p>\n\n<p>Pemda Kota Bekasi dalam hal ini oleh BP3AKB Kota Bekasi bersama Kementrian Pemberdayaan Perempuan dan Perlindungan Anak Republik Indonesia megadakan Sosialisasi dengan tema <em>&ldquo; Upaya Melindungi anak Dari Pengaruh Pornografi dan mencegah Akses anak Terhadap Informasi Pornografi Dilingkungan Sekolah&rdquo;.</em></p>\n\n<p>&nbsp;</p>\n\n<p>Salah satu pengaruh pornografi dan mencegah akses anak terhadap gadjet yang semakin merajalela tentu saja tidak lepas dari peran orang orang tua, orang tua harus bekerja sama dengan berbagai pihak sesama anggota keluarga, guru disekolahnya dan organisasi serta masyarakat, Pemerintah dan organisasi kemasyarakatan perlu meningkatkan koordinai dan kemitraan antar pemangku kepentingan dalam mendidik anak serta meningkatkan upaya pencegahan dan perlindungan terhadap anak dan remaja, demikian Sekretaris Daerah Dra. H. Rayendra Sukarmadji, M.Si saat membuka kegiatan dimaksud.</p>\n\n<p>&nbsp;</p>\n\n<p>Kegiatan sosialisai yang dilaksanakan 13/12/2016 di Hotel Aston Imperial Bekasi diikuti kurang lebih 500 orang dihadiri dari unsur Kepala Sekolah SD, SMP, SMA , SMK Negri dan Swasta Se-Kota Bekasi, Kepala Sekolah MI, MTs, MA Negri dan Swasta se-Kota Bekasi, Guru-Guru Bina Konseling se-Kota Bekasi perwakilan siswa- siswi SMP, SMA, SMK, MTs, MA Negri dan swasta se-Kota Bekasi para Ka. UPTB PPLKB, PLKB se-Kota Bekasi, narasumber kegiatan dihadirkan dari Kementrian PP &amp; PA RI dan Pemerintah Kota Bekasi.</p>\n\n<p>&nbsp;</p>\n\n<p>Dengan adanya sosialisasi ini Kota Bekasi yang juga sudah menjadi &nbsp;&nbsp;Kota Layak anak semakin terlindungi anak-anaknya, sehingga akan berkurang kejadian-kejadian yang meresahkan keluarga dan masyarakat akibat pergaulan bebas dan narkoba akibat dampat dari kebebasan penggunaan gadjet minimal bisa ditekan dampat negatifnya, Kota Bekasi tidak melarang penggunaan Tekhnologi untuk anak bahkan mensuport namun bisa diawasi oleh semua kalangan demikian Ir. Hj. Riswanti menjelaskan selaku Kepala BP3AKB Kota Bekasi, sehingga anak yang cerdas berakhlak baik akan tercipta, sesuai dengan visi Kota Bekasi, Maju, Sejahtera dan Ihsan. (swd)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2016-12-13 06:05:00', '2016-12-13 06:05:00', NULL),
