INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d0d35-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'HUT ke -35 Harian SENTANA , WAli Kota diberi penghargaan', 'hut-ke-35-harian-sentana-wali-kota-diberi-penghargaan', 'Kota Bekasi, 4/5/2017. Wali Kota Bekasi, Dr.Rahmat Effendi mendapat penghargaan&nbsp;\n\nsebagai &quot; tokoh Kebebasan beragama&quot; dari Koran Harian Sentana.\n\npiagam penghargaan tersebut diberikan l', '<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_2999\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kota Bekasi, 4/5/2017. Wali Kota Bekasi, Dr.Rahmat Effendi mendapat penghargaan&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3000\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">sebagai &quot; tokoh Kebebasan beragama&quot; dari Koran Harian Sentana.</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3001\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">piagam penghargaan tersebut diberikan langsung oleh Pemimpn redaksi Harian Sentana</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3002\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">, Rukiah Rosalyna Siahaan kepada Pemerintah kota Bekasi yang diwakili</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3003\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">oleh Kepala bagian humas Setda Kota Bekasi, Dr.MHD Jufri&nbsp;<a data-saferedirecturl=\"https://www.google.com/url?hl=id&q=http://SH.MH&source=gmail&ust=1491555257477000&usg=AFQjCNG0YI47BF0mQM51w1RGWYU6VE0EdQ\" href=\"http://sh.mh/\"  rgb(17, 85, 204);\" target=\"_blank\">SH.MH</a>. pada peryaan</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3004\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">HUT ke 35 Harian Sentana, bertempat di Wisma Mabes POLRI, Jakarta ( 4/5).&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3005\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3007\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Selain Wali Kota Bekasi yang mendapat penghargaan, Pemred Harian Sentana juga memberikan</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3008\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">penghargaan Kepada Gubernur DKI Jakarta, serta Tokoh Wanita, Sukmawati Soekarno Putri.</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3009\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3011\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Dalam perayaan tersebut selain pemberian penghargaan juga dilakukan Diskusi Publik&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3012\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">mengangkat tema &quot; INTEGRITAS PERS UNTUK NKRI&quot; dengan menghadirkan 3 narsumber</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3013\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">seperti Menteri KOMINFO RI, Rudiantara, Ketua Dewan Pers Pusat, Yosep Adi Prasetyo,&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3014\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kepala Biro Penerangan Masyarakat POLRI, Brigjen (Pol) Rikwanto serta pengamat Pers Nasional, Kamsul</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3015\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Hasan. Diskusi ini juga dihadiri oleh perwakilan pemerintah&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3016\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">yang ada di wilayah jabodetabek serta beberapa insan pers.&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3017\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3019\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Wali Kota Bekasi, Dr. Rahmat effendi menuturkan apresiasi terhadap Harian Sentana</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3020\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">atas penghargaan yang sudah diberikan kepadanya.&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3020\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3020\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">setiap penghargaan yang diberikan kepada Pemerintah kota bekasi, akan menambah semangat untuk terus meningkatkan</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3022\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">kinerja yang lebih baik terutama dalam melayani masyarakat, ujarnya.&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3022\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-2493435543705888585yui_3_16_0_ym19_1_1491393486995_3023\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&quot; saya berterimakasih atas penghargaan yang sudah diberikan oleh harian sentana&quot;, katanya. &nbsp;</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-06 09:11:00', '2017-04-06 09:11:00', NULL),
('eb3d0d86-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Subuh kelili, Wali Kota Lantik PC DMI Bekasi Utara dan Tegaskan Perijinan Rumah Ibadah di Inventaris', 'subuh-kelili-wali-kota-lantik-pc-dmi-bekasi-utara-dan-tegaskan-perijinan-rumah-ibadah-di-inventaris', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara Subuh Keliling di Masjid Al-Hijrah, Perum Titian Kencana Rw 06 Kelurahan Marga Mulya, Kecamatan Bekasi Utara bersama Kepala Satu', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara Subuh Keliling di Masjid Al-Hijrah, Perum Titian Kencana Rw 06 Kelurahan Marga Mulya, Kecamatan Bekasi Utara bersama Kepala Satuan Kerja Perangkat Daerah (SKPD) di lingkup Pemerintah Kota Bekasi.</p>\n\n<p><br />\nMasjid Al-Hijrah yang masih dalam proses pembangunan 50% dengan budget pembangunan hampir mencapai 4 Milyar namun baru bisa mencapai 50% sudah hampir 2 Milyar, Wali Kota menyampaikan Pemerintah Kota Bekasi yang telah membantu sebesar 50 juta, akan menambahkan lagi sebanyak 500 juta agar bisa membantu melanjutkan pembangunan masjid tersebut.</p>\n\n<p><br />\nKegiatan tersebut juga dirangkaikan dengan Pelantikan Pengurus Cabang Dewan Masjid Indonesia (DMI) Kecamatan Bekasi Utara yang resmi di lantik oleh Wali Kota Bekasi pada Jumat 07/04.</p>\n\n<p><br />\nKetua Dewan Masjid Idonesia (DKM) Kota Bekasi Masjid Al-Hijrah, Ahmad Sidiq yang membacakan surat keputusan dan resmi menjabat untuk DMI Bekasi Utara dengan pimpinan cabang, dr. Zairun Mustopa&nbsp;</p>\n\n<p><br />\nWali Kota Bekasi, saat menyampaikan sambutannya usai melantik DMI Bekasi Utara bahwa pembangunan sarana prasaran rumah ibadah baik Masjid, Gereja, Klenteng maupun Pura yang ada di wilayah di Kota Bekasi untuk Lurah sebagai pimpinan wilayah harus segera menginvertarisir mengenai data tanah PSU maupun izin IMB nya.</p>\n\n<p><br />\n&quot;Proses mendirikan izin mengenai di tanah fasos fasum harus segera di data agar kuat di payung hukumi oleh Pemerintah, Untuk Lurah agar segera di data jangan ada yang tertinggal untuk rumah ibadah&quot; tegas Wali Kota.</p>\n\n<p><br />\nWali Kota menambahkan bahwa hak warga Kota Bekasi dari Wali Kota, Wakil Wali Kota haru mempunyai sikap toleransi untuk setiap pemeluk agama, dinyatakan tidak hanya proses masalah gereja seperti di Bekasi Utara dan lainnya, Proses mendirikan Masjid di Wilayah Pondok Melati yang menolak hampir 7 tahun telah tuntas, di Jakasampurna Bekasi Barat terbengkalainya pendirian masjid selama 17 tahhmun juga telah tuntas.</p>\n\n<p><br />\n&quot;Ini merupakan komitmen antara kepemimpinan Rahmat Effendi dan Ahmad Syaikhu dan bantuan para aparatur serta dirongan dari warga untuk tetap menjaga toleransi umat beragama&quot; tegas Wali Kota. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-07 03:18:00', '2017-04-07 03:18:00', NULL),
('eb3d0dd6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Resmikan Peletakan Batu Pertama Pendirian Masjid Nurul Hikmah', 'wali-kota-resmikan-peletakan-batu-pertama-pendirian-masjid-nurul-hikmah', 'Kota Bekasi ---- Usai kegiatan Subuh Keliling di Perumahan Titian Kencana Kecamtmatan Bekasi Utara, Wali Kota Bekasi, Dr. Rahmat Effendi langsung bergegas ke acara berikutnya masih di Kecamatan Bekasi', '<p>Kota Bekasi ---- Usai kegiatan Subuh Keliling di Perumahan Titian Kencana Kecamtmatan Bekasi Utara, Wali Kota Bekasi, Dr. Rahmat Effendi langsung bergegas ke acara berikutnya masih di Kecamatan Bekasi Utara untuk meresmikan dan meletakan Batu pertama pembangunan Masjid Nurul Hikmah di Kelurahan Harapan Jaya pada hari Jumat (07/04/2017).</p>\n\n<p><br />\nDi dampingi Camat Bekasi Utara, Lukmanuk Hakim, Sekretaris Baznas, Ismail dan Kepala Bagian Kesos Pemerintah Kota Bekasi, Ahmad Yani untuk mengikuti proses pembangunan masjid tersebut.</p>\n\n<p><br />\nPembangunan Masjid yang mencapai budget proposal sekitar 600 juta ini akan diajukan proposal ke Pemerintah Kota Bekasi untuk menganggarkan dalam APBD mengenai dana pengerjaannya, Wali Kota Bekasi yang mengintruksikan Kepala Bagian Kessos untuk menganggarkan sebesar 200 juta Rupiah untuk bantuan pembangunan dari pemerintah.</p>\n\n<p><br />\nWali Kota juga menambahkan secara pribadi untuk membantu dana bantuan untuk pembangunan tersebut dengan tidak mengucapkan nominalnya tapi nanti akan segera di kirim.</p>\n\n<p><br />\nWali Kota dalam sambutannya menjabarkan bahwa agama yang telah di setujui undang undang negara harus di lindungi baik dari segi rumah ibadah, toleransi, dan apapun asal tidak melewati dasar hukum, dalam perjalananya pada masa jabatan Wali Kota Bekasi pernah menutup kegiatan dasar Ahmadiyah yang daei fatwa MUI telah dikeluarkan larangan mengenai ibadahnya, sesuai dengan arahan dan fatwa MUI. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-07 03:22:00', '2017-04-07 03:22:00', NULL),
('eb3d0e27-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '                        DPPPA Kota Bekasi Lakukan Konseling Terhadap Korban Kekerasan Anak', 'dpppa-kota-bekasi-lakukan-konseling-terhadap-korban-kekerasan-anak', 'Kota Bekasi, -- Kepala Bidang Penangan dan Pencegahan Kekerasan Terhadap Perempuan dan Anak Dinas Pemberdayaan Perempuan Dra. Mein Aminah, M.Si dan Komisi Perlindungan Anak Kota Bekasi, Sugeng Wijaya ', '<p>Kota Bekasi, -- Kepala Bidang Penangan dan Pencegahan Kekerasan Terhadap Perempuan dan Anak Dinas Pemberdayaan Perempuan Dra. Mein Aminah, M.Si dan Komisi Perlindungan Anak Kota Bekasi, Sugeng Wijaya melakukan konseling psikologi kepada korban pelecehan seksual terhadap anak dibawah umur yang terjadi di Kelurahan Bojong Menteng Kecamatan Rawalumbiu Kota Bekasi, Kamis (6/4) siang.</p>\n\n<p>Konseling psikologi ini dilakukan setelah adanya laporan terkait terjadinya pelecehan seksual terhadap anak dibawah umur yang terjadi di wilayah Kelurahan Bojong Menteng Kecamatan Rawalumbu dan kegiatan ini merupakan konseling kedua setelah sebelumnya Senin (3/4) kemarin juga telah dilakukan konseling terhadap para korban di wilayah yang sama.</p>\n\n<p>Kejadian Pelecehan seksual kali ini merupakan kejadian pelecehan seksual kedua setelah sebelumnya beberapa minggu lalu kasus pelecehan terhadap anak terjadi di wilayah Kelurahan Bojong Menteng Kecamatan Rawalumbu ini.</p>\n\n<p>Namum atas kesigapan masyarakat dan aparatur Kelurahan Bojong Menteng kasus pelecehan dapat dihindari karena ada tetangga yang memergoki &nbsp;dan meneriaki pelaku yang diduga akan melakukan pelecehan seksual sehingga mengundang warga sekitar untuk keluar dan melaporkan kepada pihak RT, RW dan Kelurahan sehingga pelaku dapat segera diaman ke Polsek terdekat.</p>\n\n<p>Terhadap kejadian ini Bidang Penangan dan Pencegahan Kekerasan Terhadap Perempuan dan Anak Dinas Pemberdayaan Perempuan dan Perlindungan Anak Kota Bekasi Mein Aminah bekerjasama dengan Komisi Perlindungan Anak Kota Bekasi Sugeng Wijaya langsung melakukan penanganan.</p>\n\n<p>&ldquo;Penanganan yang dilakukan berupa koordinasi dua arah dengan cara pertama melakukan konseling psikologi terhadap anak yang hampir saja menjadi korban dengan melakukan wawancara bersama dengan tim psokolog dari DPPPA dan alhamdulillah korban tidak terindikasi&rdquo; ungkapnya.</p>\n\n<p>&ldquo;Kedua menemui aparatur pemerintah mulai dari kecamatan, kelurahan, RW dan RT setempat untuk melakukan koordinasi terhadap kejadian ini dan melakukan serta mendorong untuk dapat menjaga agar kejadian seupa tidak terulang lagi.&rdquo; tambahnya</p>\n\n<p>&ldquo;Kami berharap bahwa yang namanya anak itu rentan terhadap tindak kekerasan oleh orang dewasa yang artinya anak-anak memang menjadi incaran untuk tidak kekerasan dan pelakunya bisa dilingkungan keluarga, lingkungan sekitar bisa juga lingkungan komunitas&rdquo; ujarnya.</p>\n\n<p>&ldquo;Oleh karenannya kedepan para orang tua harus lebih meningkatkan pengawasa dan perhatiannya kepada anak, lingkup kepedualian lingkungan juga sangat diperlukan untuk menjaga anak kekerasan kerhadap anak bisa dicegak bahkan tidak terjadi. Sekali lagi bahwa tanggung jawab anak memang tanggung jawab orang tua namun lingkungan juga punya andil besar untuk tumbuh kembang yang lebih baik.&rdquo; (swd/gie)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-07 03:26:00', '2017-04-07 03:26:00', NULL),
('eb3d0e7e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '  Bertoleransi Adalah Sebuah Kebutuhan Nyata Di Kota Bekasi', 'bertoleransi-adalah-sebuah-kebutuhan-nyata-di-kota-bekasi-2', 'Bagian : 3\n\n&nbsp;\n\nOleh :Dr.Rahmat Effendi (Wali Kota Bekasi)\n\n&nbsp;\n\nPeriode 2015- 2017 : Bangun Kedamaian Dalam Kebersamaan\n\n2015 merupakan tahun yang penuh tantangan bagi Pemerintah Kota Bekasi d', '<p>Bagian : 3</p>\n\n<p>&nbsp;</p>\n\n<p>Oleh :Dr.Rahmat Effendi (Wali Kota Bekasi)</p>\n\n<p>&nbsp;</p>\n\n<p>Periode 2015- 2017 : Bangun Kedamaian Dalam Kebersamaan</p>\n\n<p>2015 merupakan tahun yang penuh tantangan bagi Pemerintah Kota Bekasi dalam mejaga kerukunan beragama yang ada . Kasus muhammadiyah,adanya sekelompok massa yang berujuk rasa atas ijin Santa Clara dan pada akhir tahun 2015 Pemerintah Kota Bekasipun diganjar oleh SETARA Institute yang meluncurkan indeks kota toleran 2015, yang merupakan hasil penelitian 94 kota dari total 98 kota di seluruh Indonesia dari 3 Agustus hingga 13 November 2015 dengan &nbsp;menyebutkan bahwa Bogor, Bekasi, Banda Aceh, Depok, dan Tangerang merupakan kota yang sangat intoleran. Hal itu menurut SETARA Institut karena banyak kasus yang menyangkut kebebasan beragama dan berkeyakinan di kota itu serta banyaknya peraturan daerah (Perda) yang dikeluarkan oleh pemerintah setempat yang diskriminatif terhadap kelompok minoritas.</p>\n\n<p>Saya tidak mempermasalahkan penilaian tersebut &nbsp;,bagi saya semua harus melalui proses dan tahapan yang baik sehingga sikap toleransi mutlak dikedepankan di Kota Bekasi mengingat warganya datang dari latar belakang yang heterogen.Meskipun heterogen, saya harap semua warga sama-sama memiliki semangat membangun kota yang kita cintai ini,bukan justru mempertentangkan perbedaan tersebut. Dahulu di Kota Bekasi hampir 95 persen warganya umat muslim. Akan tetapi pada saat itu di Kota Bekasi sudah mempunyai hampir 260 ribu lebih umat kristiani , pemeluk agama Katolik mencapai 65.000 orang, Buddha 12.000 orang, Kristen Protestan 195.000 orang, Hindu 47.000 orang, dan Konghucu 196 orang. Selebihnya, merupakan pemeluk agama Islam,warga asli Bekasi Cuma 28 persen,mayoritas 33 persen &nbsp;adalah orang etnis jawa,tidak salah kalau kita mengedepankan sikap toleran di era global ini.</p>\n\n<p>&nbsp;<br />\nMajelis Umat Beragama</p>\n\n<p>Pemerintah Kota Bekasi pada tanggal 16 April 2016 menggelar &nbsp;Apel akbar yang dimotori oleh Forum Kerukunan Umat Beragama (FKUB) Kota Bekasi serta Badan Kesatuan Bangsa dan Politik (Kesbangpol) Kota Bekasi, yang mengambil tema, &quot;Kami tinggal, hidup dan berkarya di Bumi Patriot, nyok wujudkan kerukunan, mengasihi, bertoleran terhadap perbedaan keyakinan dalam memperkokoh persatuan dan kesatuan bangsa&quot;.</p>\n\n<p>Sekitar 62.000 masyarakat Kota Bekasi waktu itu mengikuti apel akbar dan membacakan deklarasi kerukunan umat beragama di Stadion Patriot Candrabhaga.Momentum ini adalah ajang mempererat kerukunan antarumat yang berbeda suku,ras &nbsp;dan agama bagi masyarakat Kota Bekasi yang majemuk.</p>\n\n<p>Untuk lebih menguatkan kelangsungan hidup berdampingan antar umat &nbsp;beragama ,Pemerintah Kota Bekasi membentuk kepengurusan Majelis Umat Beragama di tingkat kecamatan dan kelurahan. Tujuan pembentukan Majelis Umat Beragama ini untuk mendeteksi konflik antarumat beragama dan menyelesaikannya secara dini sebelum meluas ke daerah lain. Pembentukan Majelis Umat Beragama tidak akan tumpang tindih dengan kepengurusan Forum Kerukunan Umat Beragama (FKUB) Kota Bekasi yang sudah terbentuk terlebih dahulu.</p>\n\n<p>FKUB Kota Bekasi akan berkonsentrasi dalam menengahi masalah kerukunan umat beragama di tingkat kota, sedangkan kepengurusan Majelis Umat Beragama menyelesaikan konflik di tingkat kecamatan agar tidak meluas ke daerah lain.</p>\n\n<p>Keduanya, sama-sama memiliki perwakilan agama masing-masing dalam menjaga toleransi umat bergama di kecamatan tersebut. Dan saling bersinergi menjaga kerukunan umat beragama di Kota Bekasi.Pembentukan Majelis Umat Beragama telah direncanakan sejak deklarasi Forum Kerukunan Umat Beragama di Kota Bekasi, &nbsp;dilanjutkan dengan deklarasi Akbar Kerukunan Umat Beragama yang juga dilaksanakan pada 16 April 2016 lalu di Stadion Patriot Candrabhaga.</p>\n\n<p>Isi deklarasi kerukunan umat beragama yang dibacakan oleh perwakilan umat beragama ormas se-Kota Bekasi antara lain:</p>\n\n<p>Satu, bertekad membangun dan menjaga suasana kerukunan hidup antarumat beragama di Kota Bekasi.</p>\n\n<p>Dua, bertekad membangun dialog di antara para pemuka agama dan umat beragama dengan mengedepankan prinsip-prinsip musyawarah dan mufakat demi terciptanya suasana kedamaian dan kerukunan umat beragama.</p>\n\n<p>Tiga, bertekad membangun kesadaran masing-masing pada umat beragama untuk menjalankan ibadah dengan baik sesuai dengan keyakinan dan kepercayaan masing-masing dan tidak akan menyebarkan agama kepada orang yang telah beragama serta tidak terpengaruh oleh bentuk provokasi yang dapat memecah belah persatuan dan kesatuan bangsa.</p>\n\n<p>Empat, bertekad memerangai lesbian, gay, biseksual, dan transgender (LGBT) agar tidak berkembang di Kota Bekasi.</p>\n\n<p>Lima, bertekad untuk berperan aktif dan menyukseskan program pembangunan Pemerintah Kota Bekasi yang maju, sejahtera, dan ihsan.</p>\n\n<p>Deklarasi tersebut ditandatangani oleh Ketua Majelis Ulama Indonesia (MUI) Kota Bekasi, Soekandar Ghozali, Ketua PC Nahdatul Ulama (NU) Kota Bekasi, KH Mir&#39;an Syamsuri, Ketua Persis KH Beben Mubarok, Tokoh Kristen Protestan Pdt Syamsir Deli Sinaga, Tokoh Kong Hu Cu Suhendar SN, Ketua PP Muhammadiyah KH S Syamsul Bahri, Tokoh Katolik Romo Sarto, Ketua Perisada Hindu Nengah Sumba, Tokoh Budha dr Sosiadi Darma Oenah S.</p>\n\n<p>Juga pada September 2016 saya memilih Kota Manado sebagai tempat percontohan kerukunan beragama dengan membawa tokoh agama melalui Forum Komunikasi Umat Beragama (FKUB) Kota Bekasi ,tingginya angka kerukunan antar umat beragama di Kota Manado adalah nilai keberagamaan yang patutu ditiru.</p>\n\n<p>Kota Bekasi sebagai miniaturnya Indonesia, harus terus mengumandangkan kerukunan antar pemeluk agama, berbagai permasalahan isu keagamaan hendaknya dapat diselesaikan di tingkat kecamatan dan kelurahan melalui kepengurusan Majelis Umat Beragama yang &nbsp;dibentuk ini.Saya dan Wakil Wali Kota, Ustadz Syaikhu tentunya harus berada di tengah-tengah umat beragama. Karena kami disumpah harus berlaku adil kepada seluruh umat. Majelis Umat Beragama inilah yang menjadi garda terdepan dalam menjaga toleransi dan kerukunan umat beragama di Kota Bekasi.</p>\n\n<p>Saya tidak membedakan suku, agama, ras dan golongan masyarakat, kita semua adalah anak bangsa. Keyakinan yang berbeda-beda dan sikap toleran merupakan anugerah bagi Kota Bekasi.</p>\n\n<p>Secara historis-sosiologis, agama sebenarnya hadir belakangan setelah sebuah realitas sosial terbentuk. Kehadiran sebuah agama dalam realitas masyarakat seringkali dikaitkan oleh pembawanya, yaitu para Nabi yang dikenal sebagai utusan Tuhan. Agama kemudian hadir ditengah-tengah realitas umat yang didalamnya telah terekam beragam fakta sosial, baik dalam bentuk tradisi, budaya, nilai-nilai yang dianut bahkan seperangkat kepercayaan yang sudah ada dan membentuk sebuah entitas masyarakat. Maka tak jarang, bahwa kehadiran sebuah agama dalam realitas sosial tidak serta merta merubah tatanan nilai, tradisi dan budaya yang sudah ada, tetapi agama lebih bersifat memperbaharui, mengarahkan atau mengisi setiap ruang kosong sosialitas dalam upaya membangun peradaban manusia ke arah yang lebih baik. Ajaran-ajaran agama pada umumnya lebih mengarahkan dan membentuk keberadaban manusia melalui penguatan sisi moral yang diaktualisasikan oleh setiap individu dalam masyarakat. Adapun persoalan ritualitas keagamaan yang kemudian dijalankan oleh setiap individu atau kelompok dalam masyarakat berfungsi sebagai kekuatan pengikat solidaritas sosial diantara para penganutnya.</p>\n\n<p>Jika agama berfungsi dan dapat mempererat solidaritas sosial apalagi jika hubungan-hubungan sosial kemasyarakatan yang tercipta dari unsur keyakinan keagamaan dapat membentuk komunitas masyarakat yang inklusif berdasarkan &ldquo;ikatan iman&rdquo;, maka agama semestinya memiliki pengaruh yang besar untuk mengikat Kebersamaan Dalam Merajut Kedamaian.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-07 07:56:00', '2017-04-07 07:56:00', NULL),
('eb3d0ece-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Kukuhkan Karang Taruna Kecamatan Medan Satria', 'wali-kota-bekasi-kukuhkan-karang-taruna-kecamatan-medan-satria', 'Kota Bekasi ----- Minggu Pagi, (09/04/2017), Wali Kota Bekasi, Dr. Rahmat Effendi mengukuhkan Karang Taruna Kecamatan Mean Satria serta juga melantik para Ketua Karang Taruna se Kelurahan Medan Satria', '<p>Kota Bekasi ----- Minggu Pagi, (09/04/2017), Wali Kota Bekasi, Dr. Rahmat Effendi mengukuhkan Karang Taruna Kecamatan Mean Satria serta juga melantik para Ketua Karang Taruna se Kelurahan Medan Satria dengan serentak di Kelurahan Harapan Mulya, H. Ahmad, Ketua Karang Taruna Medan Satria terpilih periode 2017-2022.</p>\n\n<p><br />\nWali Kota Bekasi mengutarakan bahwa Pemuda adalah titipan bangsa yang akan meneruskan dan melanjutkan pergerakan perubahan Kota yang di singgahinya, maka dari itu Pemuda harus ikut andil dalam proses pembangunan di Kota Bekasi, dan menjadi pemacu semangat membangun dan mewujudkan Visi Kota Bekasi.</p>\n\n<p><br />\nRencananya kedepan jika Karang Taruna se Kota Bekasi telah rampung mempunyai Ketua di 12 Kecamatan se Kota Bekasi, Karang Taruna akan di berikan Motor Dinas untuk Karang Taruna dan akan bersinegritas dengan Pemerintah Kota Bekasi di tiap tiap Kecamatan maupun Kelurahan.</p>\n\n<p><br />\nPeran 3 pilar wilayah, haru ikut serta menggaet Karang Taruna di wilayahnya agar aktif ikut mendorong dan membantu para 3 Pilar dalam membangun koordinasi.</p>\n\n<p><br />\nDalam sambutannya, Wali Kota membahas event besar yang ada di Kota Bekasi pada pekan ini seperti Pertandingan Persija Jakarta dengan PSSI U-22 dan baru semalam event Ceramah umum Dr. Zakir Naik di Stadion Patriot Candrabhaga yang di hadiri beribu ribu warga ya g datang untuk menyaksikan, sampai ada ya g mengeluh tidak bisa masuk.</p>\n\n<p><br />\n&quot;Khusus Karang Taruna, jika ada event besar di Stadion kebanggaan Kota Bekasi, jika bayar nanti akan diberi potongan setengah harga, untuk biaya kebersihannya, dan harus memberi informasi di wilayah agar datang dalam event event di Kota Bekasi&quot; Jelas Rahmat Effendi. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-10 06:13:00', '2017-04-10 06:13:00', NULL),
('eb3d0f23-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Penandatanganan  kesepakatan bersama antara Pemkot Bekasi DENPOM Jaya/2-1, Kantor Kementerian Agama', 'penandatanganan-kesepakatan-bersama-antara-pemkot-bekasi-denpom-jaya-2-1-kantor-kementerian-agama', 'Kota Bekasi (10/4)- Wali Kota Bekasi Dr.Rahmat Effendi hari ini bertempat di plasa Kantor Wali Kota Bekasi menandatangani kesepakatan bersama antara Pemerintah Kota Bekasi dengan DENPOM Jaya/2-1,Kanto', '<p>Kota Bekasi (10/4)- Wali Kota Bekasi Dr.Rahmat Effendi hari ini bertempat di plasa Kantor Wali Kota Bekasi menandatangani kesepakatan bersama antara Pemerintah Kota Bekasi dengan DENPOM Jaya/2-1,Kantor Kementerian Agama,Ikatan Apoteker Indonesia.</p>\n\n<p><br />\nDidampingi Wakil Wali Kota Bekasi H.Ahmad Syaikhu ,Sekretaris Daerah Kota Bekasi Drs.Rayendra Sukarmadji M.Si dan aparatur pemkot Bekasi,Rahmat Effendi mengatakan bahwa penandatangan ini merupakan bagian dari upaya Pemerintah Kota Bekasi dalam me membefikan pelayanan kepada masyarakat.Salah satunya adalah dengan ikatan Apoteker Indonesia sebagai peningkatan pelayanan kefarmarsian yang baik pada rumah sakit se-Kota Bekasi dengan ruang lingkup peyediaan SDM yang profesional secara kuantitas dan kualitas , perluasan cakupan desiminasi program yang dihasilkan.Kesepatan ini berlaku selama 12 bulan .&quot;Begitu juga &nbsp;kerjasama dengan DENPOM Jaya/2-1,Kantor Kementerian Agama,semua dilakukan untuk perbaikan tata kelola pemerintah yang baik nyaman dan mampu memberikan pelayanan terbaik bagi masyarakat Kota Bekasi&quot;jelas Rahmat Effendi dalam arahannya di Apel pagi.</p>\n\n<p><br />\nSementara Kepala Bagian Kerjasama Setda Kota Bekasi Drs.Hanan mengatakan bahwa kerja sama ini meliputi renovasi dan pembangunan kantor instansi-instansi tersebut yang akan dilaksanakan dalam waktu dekat ini.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-10 06:15:00', '2017-04-10 06:15:00', NULL),
('eb3d0f74-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Jadi Narasumber Kuliah Umum di Universitas Krisnadwipayana', 'wali-kota-bekasi-jadi-narasumber-kuliah-umum-di-universitas-krisnadwipayana', 'Kota Bekasi ----- Wali Kota Bekasi, Dr. Rahmat Effendi diundang oleh Universitas Krisnadwipayana untuk menjadi Narasumber Kuliah Umum mengenai Pembangunan Kota yang Berwawasan Lingkungan pada hari sek', '<p>Kota Bekasi ----- Wali Kota Bekasi, Dr. Rahmat Effendi diundang oleh Universitas Krisnadwipayana untuk menjadi Narasumber Kuliah Umum mengenai Pembangunan Kota yang Berwawasan Lingkungan pada hari sekaligus melaunching Mobil Patriot Tenaga Surya yang buah hasil dari Universitas tersebut pada Sabtu, (08/04/2017),&nbsp;</p>\r\n\r\n<p><br />\r\nHadir Kepala Dinas PUPR, Tri Adhianto, Kepala Bapedda, Koswara dan Camat Pondok Gede, Mardani.</p>\r\n\r\n<p><br />\r\nDalam kuliah umum yang di jelaskan oleh Wali Kota Bekasi tentang Pembangunan Kota yang berwawasan lingkungan, Wali Kota memaparkan bahwa kini Kota Bekasi berkembang pesat dan bebeda dengan dulu, yang kini telah memiliki Indeks Perkemembangan Manusia (IPM) terbaik kefua di Provinsi Jawa Barat dengan nikai 79,09 yang pertama yakni di Kota Bandung karena telah memiliki beberapa Universitas Negeri, Kota Bekasi hanya tidak memiliki Universitas Negeri.</p>\r\n\r\n<p><br />\r\nUniversitas Krisnadwipayana telah menyepakati kerja sama dan menandarangani MoU dengan Pemerintah Kota Bekasi yakni berupa Bantuan sarana prasarana untuk Universitas, juga utmntuk pembangunan Puskesmas di area Jatiwaringin, rencana pendirian Masjid, juga pembetulan jalan di dalam kampus, selain itu Wali Kota juga meniapkan 100 beasiswa untuk mahasiswa terbaik di universitas tersebut yang ber KTP Kota Bekasi.</p>\r\n\r\n<p><br />\r\nDi tegaskan Kepada Dekan di Unkris yang di harapkan bisa ikut kontribusi mengenai jaga kebersihan, dari Pemerintah Kota Bekasi tidak menargetkan plakat adipura tapi yang harus di benahi megenai budaya disiplin buang sampah untuk warga kota bekasi yang harus ditanamkan takut oleh sistem bukan lagi adanya pengawas.</p>\r\n\r\n<p><br />\r\nDi dalam Kuliah umun tersebut juga dilaksanakan dialog antar Dosen, Dekan dan mahasiswa kepafa Walikota, masing masing menanyakan mengenai perkembangan Kota, salah satunya mengenai penegasan depan Mall Metropolitan yakni Jembatan Penyebrangan Orang (JPO) yang tidak kondusif dan masih tidak menggunakannya, Wali Kota menjawab bahwa penegasan mengenai JPO sudahh dipasang Satpol PP, Dishub, bahkan Polisi akan tetapi dari warga nya sendiri mengenai ubah perilaku disiplinnya. (Ndoet)</p>', 'images/20170823073915-2017-08-23post073914.jpg', NULL, NULL, 1404, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-10 06:17:00', '2017-04-10 06:17:00', NULL),
('eb3d0fca-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Anugerah Inovasi & Prakarsa Jabar 2017', 'anugerah-inovasi-prakarsa-jabar-2017', 'Formulir Pendaftaran Anugerah Inovasi dan Prakarsa Jabar 2017 dapat diunduh pada tautan di bawah ini :\n\n1. Formulir Pendaftaran Anugerah Inovasi\n\n2.&nbsp;Formulir Pendaftaran Anugerah Prakarsa\n\nLeafle', '<p 0px=\"\" atau=\"\" background:=\"\" bagi=\"\" baik=\"\" barat=\"\" berbagai=\"\" bermanfaat=\"\" biasa=\"\" border:=\"\" daerah=\"\" dan=\"\" di=\"\" font-family:=\"\" font-size:=\"\" jawa=\"\" karya=\"\" kehidupan=\"\" kemajuan=\"\" kepada=\"\" line-height:=\"\" luar=\"\" margin:=\"\" masyarakat=\"\" maupun=\"\" melakukan=\"\" memacu=\"\" memberikan=\"\" mengharumkan=\"\" menghasilkan=\"\" mereka=\"\" nama=\"\" nasi=\"\" nyata=\"\" outline:=\"\" p=\"\" padding:=\"\" pemerintah=\"\" penghargaan=\"\" perlu=\"\" position:=\"\" provinsi=\"\" serta=\"\" telah=\"\" tingkat=\"\" untuk=\"\" upaya=\"\" vertical-align:=\"\" yang=\"\">Formulir Pendaftaran Anugerah Inovasi dan Prakarsa Jabar 2017 dapat diunduh pada tautan di bawah ini :</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/FORMULIR INOVASI 2017.docx\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">1. Formulir Pendaftaran Anugerah Inovasi</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/FORMULIR PRAKARSA 2017.doc\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">2.&nbsp;Formulir Pendaftaran Anugerah Prakarsa</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/Leaflet inovasi dan prakarsa 1.jpg\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">Leaflet 1</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/Leaflet inovasi dan prakarsa 2.jpg\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">Leaflet 2</p>\n\n<p 0px=\"\" background:=\"\" border:=\"\" font-family:=\"\" font-size:=\"\" informasi=\"\" line-height:=\"\" link=\"\" margin:=\"\" outline:=\"\" p=\"\" padding:=\"\" position:=\"\" vertical-align:=\"\">Melalui link :</p>\n\n<p 0px=\"\" background:=\"\" border:=\"\" font-family:=\"\" font-size:=\"\" informasi=\"\" line-height:=\"\" link=\"\" margin:=\"\" outline:=\"\" p=\"\" padding:=\"\" position:=\"\" vertical-align:=\"\">http://jabarprov.go.id/index.php/pages/id/1406</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 05:06:00', '2017-04-11 05:06:00', NULL),
('eb3d101c-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Anugerah Pelopor Pemberdayaan Masyarakat 2017', 'anugerah-pelopor-pemberdayaan-masyarakat-2017', 'Formulir Pendaftaran Anugerah Pelopor Pemberdayaan Masyarakat Jawa Barat 2017 dapat diunduh pada tautan di bawah ini :\n\nFormulir Pendaftaran Anugerah Pelopor Pemberdayaan Masyarakat Jawa Barat 2017\n\nL', '<p 0px=\"\" 2017=\"\" anugerah=\"\" arah=\"\" atau=\"\" background:=\"\" baik=\"\" barat=\"\" bentuk=\"\" border:=\"\" daerah=\"\" dalam=\"\" dan=\"\" dari=\"\" di=\"\" font-family:=\"\" font-size:=\"\" jawa=\"\" ke=\"\" kehidupan=\"\" kelompok=\"\" kepada=\"\" lebih=\"\" line-height:=\"\" margin:=\"\" masyarakat=\"\" membuat=\"\" merupakan=\"\" outline:=\"\" p=\"\" padding:=\"\" pelopor=\"\" pemberdayaan=\"\" pemrintah=\"\" pengakuan=\"\" perbedaan=\"\" position:=\"\" provinsi=\"\" telah=\"\" vertical-align:=\"\" wujud=\"\" yang=\"\">Formulir Pendaftaran Anugerah Pelopor Pemberdayaan Masyarakat Jawa Barat 2017 dapat diunduh pada tautan di bawah ini :</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/FORMULIR PELOPOR 2017.docx\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">Formulir Pendaftaran Anugerah Pelopor Pemberdayaan Masyarakat Jawa Barat 2017</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/Leaflet pelopor 1.jpg\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">Leaflet 1</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/Leaflet pelopor 2.jpg\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">Leaflet 2</p>\n\n<p 0px=\"\" a=\"\" background:=\"\" border:=\"\" color:=\"\" font-family:=\"\" font-size:=\"\" href=\"http://www.jabarprov.go.id/assets/data/menu/Leaflet pelopor 2.jpg\" line-height:=\"\" margin:=\"\" outline:=\"\" padding:=\"\" position:=\"\" text-decoration-line:=\"\" vertical-align:=\"\">melalui link dibawah ini :</p>\n\n<p 0px=\"\" background:=\"\" border:=\"\" font-family:=\"\" font-size:=\"\" line-height:=\"\" link=\"\" margin:=\"\" melalui=\"\" outline:=\"\" p=\"\" padding:=\"\" position:=\"\" vertical-align:=\"\">http://jabarprov.go.id/index.php/pages/id/1405</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 05:11:00', '2017-04-11 05:11:00', NULL),
('eb3d106e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'DPRD Brebes Kunjungi Kota Bekasi, Bahas LKPJ', 'dprd-brebes-kunjungi-kota-bekasi-bahas-lkpj', '\n\n\nKota&nbsp;Bekasi, 4-11-2017. Sebanyak 25 orang Anggota DPRD Kabupaten brebes\n\nmelakukan kunjungan kerja ke Pemerintah kota Bekasi untuk mempelajari&nbsp;\n\nsoal Laporan Keterangan Pertanggungjawaban', '<div class=\"ii gt adP adO\" id=\":lu\"  12.8px; direction: ltr; margin: 5px 15px 0px 0px; padding-bottom: 5px; position: relative; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">\n<div class=\"a3s aXjCH m15b5c08f3ffa80ee\" id=\":lt\"  hidden;\">\n<div  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3045\">Kota&nbsp;Bekasi, 4-11-2017. Sebanyak 25 orang Anggota DPRD Kabupaten brebes</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3046\">melakukan kunjungan kerja ke Pemerintah kota Bekasi untuk mempelajari&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3047\">soal Laporan Keterangan Pertanggungjawaban (LKPJ) Kota Bekasi.</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3048\">&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3050\">Rombongan yang diketuai oleh Ketua Komisi I DPRD Kabupaten brebes,</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3051\">Pamor Wicaksono diterima langusng oleh Asda 3 Setda Kota Bekasi, Dadang Hidayat,</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3052\">Kepala Bagian Humas Setda Kota Bekasi, MHD.Jufri. kabid PMM Bappeda.&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3053\">&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3055\">Terdapat dua pertanyaan inti yang dipertanyakan oleh anggota DPRD Kab Brebes,&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3056\">diantaranya, berapa anggaran yang dikeluarkan pemerintah kota Bekasi</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3057\">tahun 2017 dalam rangka menyusun LKPJ 2016, pertanyaan kedua, apakah dalam mealkukan</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3058\">penyusunan LKPJ Pemerintah kota Bekasi melibatkan Akademisi.</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3059\">&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3061\">Menanggapi pertanyaan tersebut, Kasubag OTDA Bagian Tapem Setda Kota Bekasi, Hari Hendarman&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3062\">menjelaskan bahwa &nbsp;Pemerintah kota Bekasi dalam melakukan penyusunan LKPJ pda tahun 2017 ini</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3063\">menggarkan Rp.700 juta. Tahun ini meningkat, karna pada tahun 2016 kemarin kami menganggarkan</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3064\">Rp.200 juta, terang Harri.</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3065\">&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3067\">Ditambahkannya, untuk saat ini Kota bekasi tidak melibatkan Akademisi dalam melakukan penyusunan&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3068\">LKPJ, dirinya juga berharap kedepan dapat melibatkan pihak ketiga dalam menyusun LKPJ ini, karena</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3069\">akan lebih maksimal lagi. Ujarnya.&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3070\">&nbsp;</div>\n\n<div id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3072\">Dirinya menjelaskan butuh komitmen dari setiap OPD agar dalam melakukan penyusunan LKPJ dapat maksimal</div>\n\n<div dir=\"ltr\" id=\"m_-5454892400343344953yui_3_16_0_ym19_1_1491897630235_3073\">dan tepat waktu.tandasnya. (yas)</div>\n\n<div>&nbsp;</div>\n</div>\n</div>\n\n<div class=\"yj6qo\">&nbsp;</div>\n</div>\n\n<div class=\"hq gt\" id=\":n2\"  both; margin: 15px 0px; font-size: 12.8px; color: rgb(34, 34, 34); font-family: arial, sans-serif;\">&nbsp;</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 11:46:00', '2017-04-11 11:46:00', NULL),
('eb3d10bf-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Membuka Festival Anak Takwa Kota Bekasi', 'wakil-wali-kota-membuka-festival-anak-takwa-kota-bekasi', 'Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu membuka Festival Anak Taqwa yang diselenggarakan oleh Pimpinan Daerah Ikatan Guru Raudhatul Athfal (PD IGRA) Kota Bekasi bertempat di Taman Impian Jay', '<p>Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu membuka Festival Anak Taqwa yang diselenggarakan oleh Pimpinan Daerah Ikatan Guru Raudhatul Athfal (PD IGRA) Kota Bekasi bertempat di Taman Impian Jaya Ancol, Selasa (11/4) pagi.</p>\n\n<p>Hadir pula pada kesempatan ini Kepala Kantor Kementrian Agama Kota Bekasi, Ketua PD IGRA Provinsi Jawa Barat, Ketua PD IGRA Kabupaten Bekasi, Kepala Seksi Pendidikan Madarasah Kemenag Kota Bekasi, Ketua PGTK Kota Bekasi.</p>\n\n<p>Dalam sambutannya Wakil Wali Kota mengatanakan bahwa hari ini banyak melihat wajah-wajah ceria, wajah-wajah bahagia, wajah-wajah yang memang akan menjadi tumpuan masa depan Kota Bekasi dan Negeri kita tercinta ini.</p>\n\n<p>&ldquo;Saya maklumi acara Festival anak Taqwa ini tidak diselenggarakan di Kota Bekasi karena fasilitas yang terbatas, tapi mudah-mudahan pada kesempatan kedepan stadion dan sekelilingnya dapat dimanfaatkan untuk pertemuan anak-anak yang ceria, karena kemarin kita sudah bisa menyelenggarakan acara Dr. Zakir Naik &nbsp;sekitar 40 ribu penonton yang menyaksikan&rdquo; ungkapnya.</p>\n\n<p>&ldquo;Kita patut berterima kasih kepada guru di Raudhatul Athfal yang sedemikian sabar membimbing anak-anak kita yang memang mungkin tingkat kesulitan untuk membimbing jauh lebih sulit dari anak-anak yang sudah mengerti&rdquo; ujarnya</p>\n\n<p>&ldquo;Karena memang ini masih awal dan masih belum mengerti apa-apa, padahal kita menyadari betul bahwa anak-anak kita hari ini adalah aset masa depan dan hari ini Allah SWT telah memberikan karunia kepada kota kita, negeri kita dengan banyaknya anak-anak ini orang sering menyebutnya Bonus Demografi&rdquo; tambahnya.</p>\n\n<p>&ldquo;Jadi didalam setiap perkembangan dan pergerakan kemajuan yang terjadi pada sebuah bangsa, bangsa yang mampu memanfaatkan bonus demografi ini bisa bangkit dan menjadi bangsa yang besar. Bonus demografi ini adalah sebuah keberkahan, dan keberkahan akan kita dapatkan bila kita bisa mempersiapkan anak-anak kita siap untuk menyongsong masa depan&rdquo; imbuhnya</p>\n\n<p>&ldquo;Saya terharu dan yakin betul setelah tadi mendengar sedemikian banyak anak-anak yang membaca Surat An-Naba sedemikian lancar dan hafal dan saya yakin ketika mereka menjadi pemimpin nanti akan menjadi aset-aset pemimpin masa depan yang hafiz Qur&rsquo;an, baik Wali Kota, Gubernur bahkan Presiden&rdquo; uangkapnya.</p>\n\n<p>&ldquo;Jadi Jangan kemudian diparadokskan bahwasannya ketika kita mengaji kita tidak bisa berprestasi, justru kedepan harus kita yakinkan betul kepada seluruh penduduk negeri ini bahwa kita yang memiliki kemampuan, baik menguasai nilai-nilai agama itulah yang berhak menjadi pemimpin-pemimpin di negeri yang mayoritas umat islam ini, karena itulah Sunnatulloh &ldquo;Sesungguhnya Allah SWT mewariskan bumi nini kepada hamba-hambanya yang sholeh&rdquo; ungkapnya.</p>\n\n<p>&ldquo;Tentu sekali lagi saya ingatkan untuk mempersiapkan aset-aset masa depan, saya yakin kalau ini dipersiapkan dengan sebaik-baiknya oleh bapak ibu sekalian &nbsp;khusunya guru-guru raudhatul atfhal, anak-anak kita akan bisa tampil menyongsong masa depan yang lebih baik, negeri ini akan bisa berubah dan itulah namanya keberkahan&rdquo; tambahnya</p>\n\n<p>&ldquo;Ini tentunya akan memotivasi kita semua sebagai orang tua untuk mempersiapkan anak-anak kita di masa depan, akan tetapi jika kita tidak mempersiapkan generasi sekarang dengan baik, kita abaikan anak-anak ini jangan harap kita mendapatkan keberkahan, justru yang kita khawatirkan yang terjadi adalah bencana kemanusian&rdquo; ujarmnya.</p>\n\n<p>&ldquo;Kenapa bencana karena anak-anak kita tidak siap menyongsong masa depan, mereka akhirnya hanya menjadi penonton, bahkan menjadi konsumen atau mungkin hanya nongkrong-nongkong dipinggir jalan dan akhirnya terkena narkoba bahkan menjadi konsumen.&rdquo; tambahnya</p>\n\n<p>&ldquo;Oleh karena itu Festival Anak Taqwa ini kita jadikan tempat untuk menampilkan bagaimana kualitas fisik, kualitas kemampuan akal dan kualitas akhlak anak-anak kita dan saya yakin anak-anak ini akan menjadi anak-anak nyang sholeh dan taqwa sesuai dengan namanya Festival Anak Taqwa&rdquo; imbuhnya</p>\n\n<p>Dalam akhir sambutannya beliau menyampaikan ucapan terimakasih dari Pemkot Bekasi kepada pengurus PD. IGRA Kota Bekasi atas diselenggarakan acara yang luar biasa ini dan permohonan maaf karena belum seluruhnya hal pada IGRA bisa di fasilitasi dengan baik dan juga guru-guru mungkin baru 800 lebih dengan insentif masih sangat jauh dari upah Kota Bekasi, tapi akan terus kita tingkatkan dari waktu ke waktu sesuai dengan kemapuan keuangan daerah kita (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 11:53:00', '2017-04-11 11:53:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d1117-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakill Wali Kota Bekasi Lantik 24 Pejabat Eselon III Di Lingkungan Pemkot Bekasi', 'wakill-wali-kota-bekasi-lantik-24-pejabat-eselon-iii-di-lingkungan-pemkot-bekasi', 'Kota Bekasi, -- Wakil Wali Kota Bekasi Ahmad Syaikhu melantik dan pengambilan sumpah/janji &nbsp;24 orang Pejabat Struktural Eselon III di Lingkungan Pemerintah Kota Bekasi bertempat di Aula Nonon Son', '<p>Kota Bekasi, -- Wakil Wali Kota Bekasi Ahmad Syaikhu melantik dan pengambilan sumpah/janji &nbsp;24 orang Pejabat Struktural Eselon III di Lingkungan Pemerintah Kota Bekasi bertempat di Aula Nonon Sontanie Gedung 10 Lantai Jl. A. Yani no. 1 Bekasi, Selasa (11/4).</p>\n\n<p>Didamping oleh Sekretaris Daerah Kota Bekasi Drs. Rayendra Sukarmadji, M.Si, Asisten Administrasi Umum Setda Kota Bekasi Dadang Hidayat, SE, M.Si dan Kepala BKPPD Kota Bekasi serta dihadiri oleh Pejabat Eselon 2 dan 3 di lingkungan Pemerintah Kota Bekasi.</p>\n\n<p>Dalam sambutannya Wakil Wali Kota Bekasi menyampaikan bahwa pejabat struktural yang telah diambil sumpah dan dilantik dalam jabatan struktural adalah orang-orang yang telah melalui &nbsp;proses penilaian, pemikiran dan pertimbangan yang dalam sesuai dengan aturan dan mekanisme pengangkatan dalam jabatan struktural</p>\n\n<p>&ldquo;Ingatlah bahwa jabatan hanyalah sebuah amanah dan apabila kita tidak mampu menjaga amanah dengan baik maka bisa diambil setiap saat. Ketika dalam evaluasi yang telah dilakukan pejabat tidak mampu mempertanggungjawabkan kepemimpinan, dalam hal ini mencapai target kinerja yang telah ditetapkan, maka janganlah berkecil hati bila harus meninggalkan jabatan yang diamanahkan saat ini&rdquo; uangkapnya</p>\n\n<p>&ldquo;Saat ini kita sudah memasuki triwulan ke dua &nbsp;tahun anggaran 2017 masih banyak pekerjaan rumah Pemkot Bekasi yang harus bersama-sama kita selesaikan dalam rangka memberikan pelayanan terbaik kepada warga masyarakat Kota Bekasi, antara lain pembangunan infrastruktur pemenuhan fasilitas umum masyarakat, membangun budaya bersih masyarakat dan juga mengimplementasikan pakta integritas bagi seluruh aparatur Pemkot Bekasi&rdquo; tambahnya</p>\n\n<p>&ldquo;Kita juga harus berfikir kreatif dan inovatif harus berani melakukan sesuatu yang berbeda dan jangan lagi membiasakan penumpukan kegiatan di Triwulan IV sehingga berakibat pada terkendalanya penyerapan anggaran karena telah melewati batas waktu yang telah ditentukan&rdquo; ujarnya.</p>\n\n<p>&ldquo;Perlu saya sampaikan beberapa hal untuk menkadi perhatian pertama terapkan dan manfaatkan Teknologi Informasi dan Komunikasi (TIK) dimana sekarang ini kita sudah memasuki era teknologi Informasi kiranya konsep yang berkaitan dengan smart city harus dapat terimplementasikan di seluruh jajaran Pemerintah Kota Bekasi&rdquo; imbuhnya.</p>\n\n<p>&ldquo;Kedua mari mengubah mainset kita, kita tanamkan bahwa seorang aparatur badi negara dan abdi masyarakat sehingga kita bisa membarikan kontribusi terbaik sebagai bagian dari rangkaian ibadah yang bisa menjadi lading amal bagi kita semuanya&rdquo; ungkapnya</p>\n\n<p>&ldquo;Saya juga ingin ingatkan kepada seluruh pejabat srtuktural dan ASN di lingkungan Pemkot Bekasi untuk bersama-sama menciptakan Good Governace dan Clean Goovernance, menciptakan budaya kerja dengan senatiasa bekerja jujur, benar dan tertib dalam administrasi serta tuntas&rdquo; tambahnya.</p>\n\n<p>Pada akhir sambutannya Wakil Wali Kota meminta untuk dapat mengoptimalkan jabatan, sehingga akan terjadi perubahan-perubahan dalam tatanan birokrasi Pemerintah Kota Bekasi, tidak perlu bekerja sendirian lakukanlah kerjasama dengan seluruh jajaran dibawahnya atau juga berkoordinasi dengan jajaran perangkat daerah lainnya sehingga dengan kebersamaan yang kita bangun maka akan tercapai visi misi Kota Bekasi Maju, Sejahtera dan Ihsan. (gie)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 22:25:00', '2017-04-11 22:25:00', NULL),
('eb3d1169-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'PUPR Turunkan Mobil Pompa Untuk Kurang Debit Air', 'pupr-turunkan-mobil-pompa-untuk-kurang-debit-air', 'Kota Bekasi, Kepala UPTD PUPR Kecamatan Bekasi Barat Teddy Malik Insani menurunkan mobil pompa air untuk membantu mengurangi debit air yang membuat banjir jalan KH. Noer Alie tepatnya di bawah Tol Jor', '<p>Kota Bekasi, Kepala UPTD PUPR Kecamatan Bekasi Barat Teddy Malik Insani menurunkan mobil pompa air untuk membantu mengurangi debit air yang membuat banjir jalan KH. Noer Alie tepatnya di bawah Tol Jorr pada Selasa (11/4) sore.</p>\n\n<p>Menurut Kepala UPTD PUPR Kecamatan Bekasi Barat penyebab terjadinya banjir bukan hanya disebabkan oleh hujan saja tetapi juga dikarenakan meluapnya kali cakung yang ada sebelah barat jalan ini, selain itu juga adanya Back water serta adanya rembesan dari kali cakung melalui pintu air, selain itu tersumbatnya crossing kearah kali cakung yang disebabkan oleh lumpur dan sampah</p>\n\n<p>&quot;Ketinggian air yang mencapai 40-50 cm mulai menggenangi jalan sejak pukul 18.00 sore tadi dan sempat juga mengganggu lalu lintas yang akan menuju kearah &nbsp;kawasan MM Bekasi Selatan kurang lebih selama 30 menit, kemacetan juga sempat terjadi karena jalan tidak dapat dilalui oleh kendaraan roda dua dan roda empat Karen atakut mogok kecuali Truk dan Bus&quot; ungkapnya.</p>\n\n<p>&quot;Untuk mengatasi hal tersebut kami langsung melaporkan dan berkoordinasi dengan Kepala Dinas PUPR untuk meminta bantuan agar mengirimkan mobil pompa, yang akan kami gunakan untuk membantu mengurangi debit air yang ada, selain dengan mesin pompa yang sudah ada&quot; tambahnya.</p>\n\n<p>&quot;Tidak lama setelah mobil pompa difungsikan air berangsur-angsur surut dan akhirnya jalan dapat kembali dilalui oleh kendaraan roda dua dan roda empat meskipun merayap&quot; ujarnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-11 22:28:00', '2017-04-11 22:28:00', NULL),
('eb3d11b5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kepala Bidang BKPPD Mengevaluasi Absen Apel Pegawai Setda', 'kepala-bidang-bkppd-mengevaluasi-absen-apel-pegawai-setda', 'Kota Bekasi, Kepala Bidang Penilaian Kinerja Badan Kepegawaian Pendidikan dan Pelatihan Daerah Kota Bekasi Sajekti Rubiah melakukan pengecekan ulang absen usai apel pagi pada Perangkat Daerah Sekretar', '<p>Kota Bekasi, Kepala Bidang Penilaian Kinerja Badan Kepegawaian Pendidikan dan Pelatihan Daerah Kota Bekasi Sajekti Rubiah melakukan pengecekan ulang absen usai apel pagi pada Perangkat Daerah Sekretariat Daerah Kota bekasi, Rabu (12/4).</p>\n\n<p>&nbsp;</p>\n\n<p>Pengecekan dilakukan dalam rangka implementasi Perwal 11 Tahun 2013 tentang Kode Etik Aparatur di Lingkungan Pemerintah Kota Bekasi dan dalam rangka menyelenggarakan fungsi penunjang urusan Pemerintah bidang kepegawaian, pendidikan dan pelatihan sehingga visi terwujudnya aparatur Yang lebih profesional, bertanggung jawab dan bermoral dapat terwujud.</p>\n\n<p>&nbsp;</p>\n\n<p>Kabid Penilaian Kinerja BKPPD mengatakan Tugas dan fungsi Sekretariat Daerah yang melekat pada pimpinan meminta kita untuk selalu bekerja jujur, benar dan tertib dalam administrasi serta tuntas termasuk didalamnya apel pagi yang merupakan awal dari rutinitas kerja kita.</p>\n\n<p><br />\n&quot;Kami akan tegas bila memang tidak hadir dalam apel maka akan kami coret juga bila memang ada dinas luar maka surat tugas harus dilampirkan sebagai bukti bahwa memang yang bersangkutan tidak dapat mengikuti apel pagi&quot; ungkapnya.</p>\n\n<p><br />\n&quot;Tidak hanya itu penggunaan pakaian dinas juga harus di patuhi sebagaimana surat edaran Nomor 025/2124.SETDA.Org tentang Penggunaan Pakaian Dinas PNS yang mulai berlaku pada tanggal 3 April 2017 kemarin, juga kelengkapan atribut seperti lambang korpri, papan nama, PIN Pakta Integritas harus ada&quot; tambahnya</p>\n\n<p>&nbsp;</p>\n\n<p>&quot;Saya mengajak rekan-rekan Pegawai baik PNS ataupun TKK di lingkungan Pemkot Bekasi untuk bersama-sama menciptakan Good Governance dan Clean Governance sehingga akan terjadi perubahan-perubahan dalam tatanan birokrasi Pemkot Bekasi terutama di Perangkat Daerah Sekretariat Daerah Kota Bekasi dengan begitu maka akan tercapai visi misi Kota Bekasi Maju, Sejahtera dan Ihsan&quot; imbuhnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-12 04:55:00', '2017-04-12 04:55:00', NULL),
('eb3d1207-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Satpol PP akan adakan Baksos Jelang HUT Satpol PP ke 67', 'satpol-pp-akan-adakan-baksos-jelang-hut-satpol-pp-ke-67', 'Kota Bekasi,12/04/2017. Satpol PP Kota Bekasi akan mengadakan Bakti Sosial (Baksos) yang akan dilaksanakan\n\npada tanggal 22 april 2017 nanti.&nbsp;\n\n&nbsp;\n\nPelaksanaan Bakti sosial ini dalam rangka m', '<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3864\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kota Bekasi,12/04/2017. Satpol PP Kota Bekasi akan mengadakan Bakti Sosial (Baksos) yang akan dilaksanakan</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3865\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">pada tanggal 22 april 2017 nanti.&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3865\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3865\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Pelaksanaan Bakti sosial ini dalam rangka menyambut HUT Satpol PP ke-67 dan Satlinmas ke 55 yang akan diadakan pelaksanaan hari puncaknya pada tanggal 26 April 2017 mendatang.&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3867\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3869\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Hal ini disampaikan oleh Sekretaris Satpol PP, Lindon saat memimpin rapat persiapan HUT Satpol dan HUT Linmas Tingkat Kota Bekasi, pada hari Rabu (12/4) bertempat di Ruang Rapat Kantor Satpol PP kota Bekasi.&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3871\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3873\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Dalam rapat tersebut turut hadir perwakilan Polresta Bekasi Kota, Kodim 0507/ Bekasi, Dinas PUPR, Dinas LH, Dinas Perhubungan, Kecamatan Jatiasih, Bagian Humas, dan Bagian TU Pim.</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3875\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3877\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Direncanakan terdapat dua kegiatan yang akan dilaksanakan pada tanggal 22 April nanti, diantaranya Bakti Sosial Pemberian 200 Sembako di wilayah kecamatan Jatiasih dan melakukan kerja bakti normalisasi saluran di wilayah jatiasih.</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3880\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3882\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Untuk Baksos pembemberian 200 sembako akan di bagi 33 sembako per kelurahan, ujar Lindon.&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3883\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3885\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Sementara itu, pada pelaksanaan peringatan HUT Satpol PP pada tanggal 26 April mendatang, akan dilaksanakan di Lapangan alun-alun Kota Bekasi, menampilkan tari-tarian dan atraksi oleh Anggota Satpol PP Kota Bekasi. Diperkirakan akan hadir &nbsp;sebanayak 1500 orang sebagai peserta pada peringatan tersebut, terangnya.&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3888\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-3854819935667391700yui_3_16_0_ym19_1_1491986726883_3890\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Saya berharap dukungan dari semua pihak agar, pelaksanaan Baksos dan peringatan HUT Sapol PP nanti akan berjalan dengan sukses dan meriah, tandasnya. (yas)</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-12 09:41:00', '2017-04-12 09:41:00', NULL),
('eb3d1256-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sekda Buka Lomba Tari Tradisional Tingkat SMP Negeri dan Swasta Se - Kota Bekasi', 'sekda-buka-lomba-tari-tradisional-tingkat-smp-negeri-dan-swasta-se-kota-bekasi', 'Kota Bekasi. 13-04-2017. Sekretaris Daerah Kota Bekasi, Rayendra Sukarmadji membuka\n\nsecara resmi Lomba Tari Tradisional yang diikuti oleh para pelajar SMP Negeri dan Swasta Se Kota Bekasi, bertempat ', '<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2703\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kota Bekasi. 13-04-2017. Sekretaris Daerah Kota Bekasi, Rayendra Sukarmadji membuka</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2704\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">secara resmi Lomba Tari Tradisional yang diikuti oleh para pelajar SMP Negeri dan Swasta Se Kota Bekasi, bertempat di&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2706\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Bekasi Cyber Park, Kamis (13/04).&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2707\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2709\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Dalam sambutannya, Sekretaris Daerah, Rayendra Sukarmadji mengapresiasi dengan adanya kegiatan seperti ini. dijelaskannya dalam upaya meningkatkan</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2711\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">kecintaan generasi muda terhadap kesenian daerah, perlu terus diadakan kegiatan seperi ini, terangnya.&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2713\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2715\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">selain untuk melestarikan budaya, juga dapat mengembangkan bakat dari para peljar-pelajar di kota Bekasi khususnya dari kesenian.&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2717\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2719\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Ditengah-tengah terpaan budaya asing yang masuk ke tanah air, kekayaan budaya bangsa kita harus menjadi pilar utama dalam menangkal pengaruh negatif.&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2721\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_5113385221751633895yui_3_16_0_ym19_1_1492066016866_2723\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">saya berpesan agar para peserta dapat berlomba secara sportif dan jadikan ajang ini untuk meningkatkan bakat seni di masing-masing diri para anak-anaku sekalian, pungkasnya. (yas)</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-13 07:31:00', '2017-04-13 07:31:00', NULL),
('eb3d12ad-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Asda I Buka Sosialisasi Pemilukada Kota Bekasi', 'asda-i-buka-sosialisasi-pemilukada-kota-bekasi', 'Kota Bekasi - Asisten Pemerintah Kota Bekasi Dinas Faisal Badar membukanya kegiatan Sosialisasi Pemilihan Umum Kepala Daerah dan Wakil Kepala Daerah Kota Bekasi Tahun 2018 bertempat di Gedung Mustikas', '<p>Kota Bekasi - Asisten Pemerintah Kota Bekasi Dinas Faisal Badar membukanya kegiatan Sosialisasi Pemilihan Umum Kepala Daerah dan Wakil Kepala Daerah Kota Bekasi Tahun 2018 bertempat di Gedung Mustikasari Convention Hall, Mustika Jaya, Rabu (12/4) pagi.</p>\n\n<p>Hadir dalam kegiatan ini Kepala Kepala Badan Kesbang, Bagian Humas, Kepala Bagian Tata Pemerintahan, Camat, Lurah, Tokoh Masyarakat, PKK, Ketua LPM, Karang Taruna dan Para Ketua RT dan RW di Kecamatan Rawalumbu, Bantargebang dan Mustika Jaya.</p>\n\n<p>Dalam sambutannya Asda I mengatakan Pemilu Kepala dan Wakil Kepala Daerah Kota Bekasi Tahun 2018 merupakan sarana kedaulatan rakyat yang diselenggarakan secara demokratis dengan tujuan untuk memilih Wali Kota dan Wakil Wali Kota Bekasi periode 5 tahun ke depan.</p>\n\n<p>&quot;Hal ini tentu sejalan dengan prinsip demokrasi dari rakyat, oleh rakyat dan untuk rakyat tentu saja dilaksanakan secara langsung, umum, bebas, rahasia, jujur dan adil&quot; ungkapnya.</p>\n\n<p>&quot;Keberhasilan Pemilukada tidak hanya dilihat dari hasil akhir terpilihnya Wali Kota dan Wakil Wali Kota Bekasi yang memiliki kredibilitas, legitimasi dan representatif, namun dengan adanya tingkat partisipasi masyarakat dalam antusiasme dalam menggunakan hak pilihnya&quot; ujarnya.</p>\n\n<p>&quot;Kita berharap bahwa pagelaran Pemilukada tahun 2018 dapat berjalan sukses dan memberikan dukungan yang positif dalam membangun Kota Bekasi sesuai dengan cita-cita dan harapan kita bersama serta dapat menumbuhkan persepsi dan sudut pandang serta keinginan yang sama antara pemerintah dengan seluruh komponen masyarakat dalam mensukseskan pelaksanaan pemilukada Kota Bekasi&quot;&nbsp;</p>\n\n<p>Diakhir sambutannya beliau megharapkan kegiatan ini juga dapat menjadi pendidikan politik bagi masyarakat serta penyampaian informasi atas proses pelaksanaan pesta demokrasi di Kota Bekasi dan marilah kita gunakan hak pilih yang dimiliki untuk mendapatkan pemimpin yang legitimate serta sesuai dengan cita-cita dan harapan kita bersama.</p>\n\n<p>Usai dibuka, kegiatan sosialisasi ini dilanjutkan dengan pemaparan dari narasumber KPU Kota Bekasi dan Badan Kesatuan Bangsa dan Politik Kota Bekasi, Abdillah Hamka (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-14 09:28:00', '2017-04-14 09:28:00', NULL),
('eb3d1300-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Tiga Mobil Pompa Didatangkan ke Nasio Untuk Bantu Sedot Air', 'tiga-mobil-pompa-didatangkan-ke-nasio-untuk-bantu-sedot-air', 'Kota Bekasi -&nbsp;Banjir yang merendam Perumahan Bumi Nasio Indah sejak selasa (11/4) &nbsp;disebabkan kerana curah hujan yang tinggi di wilayah Bekasi dan Bogor serta kiriman air dari hulu yang meng', '<p>Kota Bekasi -&nbsp;Banjir yang merendam Perumahan Bumi Nasio Indah sejak selasa (11/4) &nbsp;disebabkan kerana curah hujan yang tinggi di wilayah Bekasi dan Bogor serta kiriman air dari hulu yang mengakibatkan debit air Kali Cakung yang tinggi dan meluap sehingga merendam pemukiman warga.</p>\n\n<p>Kepala UPTD PUPR Kecamatan Jatiasih Mahir, ST mengatakan banjir terjadi juga karena banyaknya rembesan tanggul kali, di tambah lagi hujan dengan durasi 1 jam lebih juga kontur nasio yang berada di daerah cekungan membuat banjir agak lama surut.</p>\n\n<p>&quot;Oleh karenanya kemarin kita sudah berkoordinasi dan melaporkan kepada Kepala Dinas PUPR dan langsung memerintahkan untuk mendatangkan tiga mobil pompa untuk membantu menguragi Debit air yang merendam perumahan ini, baik milik Dinas PUPR dan mobil pinjaman dari Balai Besar Wilayah Sungai Cisadane Ciliwung (BBWSCC) ungkapnya.</p>\n\n<p>&ldquo;Selain dari Dinas PUPR bantuan berupa perahu karet dari BPBD dan Damkar Kota Bekasi telah datang sejak selasa (11/4) malam dan telah bersiaga untuk mengevakuasi dan mengankut warga yang ingin keluar dari rumahnya dibantu oleh Taruna Siaga Bencana (Tagana)&rdquo; ujarnya.</p>\n\n<p>&ldquo;Mobil pompa sudah standbay sejak jam 2 siang (13/4) dan memang belum melakukan penyedotan karena Kali Cakung masih meluap, sebenarnya Rabu (12/4) kemarin kami juga telah melakukan penyedotan, tapi karena hujan turun kembali dan menyebabkan Kali Cakung meluap, maka baru kamis (13/4) sore kami mulai melakukan penyedotan lagi&rdquo; tambahnya.&nbsp;</p>\n\n<p>&ldquo;Tapi alhamdulillah kondisi pagi (14/4) ini sudah tidak banjir lagi, kemungkinan di hulu Kali Cakung curah hujan sudah berkurang sehingga Kali Cakung tidak mendapat kiriman air dan warga sudah kembali ke rumahnya untuk melakukan aktifitasnya&quot; pungkasnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-14 09:32:00', '2017-04-14 09:32:00', NULL),
('eb3d1350-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Atasi Banjir, Dinas PUPR Akan Benahi Tanggul dan Buat Long Storage Perum Bumi Nasio Indah', 'atasi-banjir-dinas-pupr-akan-benahi-tanggul-dan-buat-long-storage-perum-bumi-nasio-indah', 'Kota Bekasi -&nbsp;Banjir yang kerap terjadi di Perumahan Bumi Nasio Indah beberapa pekan kemarin terjadi kerana curah hujan yang tinggi di wilayah Bekasi dan Bogor serta kiriman air dari hulu yang me', '<p>Kota Bekasi -&nbsp;Banjir yang kerap terjadi di Perumahan Bumi Nasio Indah beberapa pekan kemarin terjadi kerana curah hujan yang tinggi di wilayah Bekasi dan Bogor serta kiriman air dari hulu yang mengakibatkan debit air Kali Cakung yang tinggi sehingga merendam pemukiman warga.</p>\r\n\r\n<p>Menanggapi hal ini Kepala Bidang Sumbar Daya Air Dicky Irawan ST. MT dalam pesan singkatnya (14/4) beliau menjelaskan bahwa banjir di nasio disebabkan karena dua hal, pertama adanya beberapa titik rembesan dari tanggul, karena usia tanggung yang sudah cukup lama.</p>\r\n\r\n<p>&ldquo;Kedua karena run off atau limpasan air hujan yang tidak meresap ke tanah, serta tidak dapat mengalir secara gravitasi karena tinggi muka air Kali Cakung lebih tinggi dan posisi perum Nasio yang berada didaerah cekungan&rdquo; ujarnya.</p>\r\n\r\n<p>&ldquo;Untuk mengatasi hal tersebut kami Dinas PUPR akan melakukan penanganan pertama akan segera melakukan penambalan (cement grouting) setelah secara teknis dan kondisi memungkinkan&rdquo; uangkapnya</p>\r\n\r\n<p>&ldquo;kedua kami juga akan mengupayakan melalui usulan anggaran ke APBN-Perubahan 2017 untuk membuat kolam tampungan, berupa tampungan memanjang (long storage) di bawah tanah&rdquo; tambahnya.</p>\r\n\r\n<p>&ldquo;Kejadian banjir kemarin di perum nasio ini, kami berupaya untuk mendatangkan tiga mobil pompa baik milik Dinas PUPR atau dengan bekerjasama melalui pinjaman dari Balai Besar Wilayah Sungai Ciliwung Cisadane (BBWSCC) untuk mengurangi debit air agar lebih cepat surut karena ketinggian &nbsp;air yang mencapai 100-150 sentimeter&rdquo; imbuhnya.</p>\r\n\r\n<p>&ldquo;Dilaporkan juga pada saat kejadian banjir kemarin, pompa di perum nasio, yang sudah disediakan oleh pemerintah dan diserah terimakan ke warga, dalam kondisi mati dan baru diketahui saat kejadian, tapi langsung dilakukan upaya perbaikan&rdquo; ujarnya (gie).</p>', 'images/20170823082521-2017-08-23post082519.jpeg', NULL, NULL, 2621, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-14 09:38:00', '2017-04-14 09:38:00', NULL),
('eb3d13a1-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Silahturami ke RW 030 Kaliabang,Wali Kota Bekasi minta Warga Aktif K3', 'silahturami-ke-rw-030-kaliabang-wali-kota-bekasi-minta-warga-aktif-k3', 'Kota Bekasi-(16/4)- Wali Kots Bekasi Dr.Rahmat Effendi minggu pagi mendatangi sekretariat RW 030 Kaliabang Bekasi Utara uktuk bersilahturahmi dengan warga sekitar dalam terus mengajak masyarakat untuk', '<p>Kota Bekasi-(16/4)- Wali Kots Bekasi Dr.Rahmat Effendi minggu pagi mendatangi sekretariat RW 030 Kaliabang Bekasi Utara uktuk bersilahturahmi dengan warga sekitar dalam terus mengajak masyarakat untuk senantiasa hidup bersih,menggalakkan K3 dilingkungannya serta menumbuh kembangkan masyarakat yang kreatif,mandiri dalam ekonomi dan sadar akan kebersihan lingkungan.</p>\r\n\r\n<p><br />\r\nDidampingi Kepala Dinas Lingkungan Hidup Kota Bekasi &nbsp;Jumhana Lutfi ,Wali Kota Bekasi tersebut mengatakan bahwa K3 harus terus di galakkan,dan menjadi tugas RT dan RW sebagai kepanjang tanganan pemerintah daerah dalam membantu melayani masyarakat.&quot;RW memiliki kewajiban untuk melayani masyarakat dan melindungi masyarakatnya,RW harus berdiri di semua golongan tidak memandang warna,golongan atau agama, ini diperlukan agar masyarakst Kota Bekasi terasa ter ayomi dan merasa aman hidup di Kota Bekasi.K3 ini juga sebagai wadah membangun kebersamaan dalam merangkai persaudaraan &nbsp;sebagai umat manusia.Disini juga ada bank sampah,terus di kelola sebagai wadah kreativitas dalam menjaga kebersihan lingkungan.Momentum ini harus terus dijaga dan membudaya untuk kebaikan kita semua,lingkungan bersih,masyarakat akan sehat kehidupannya&quot;jelas Dr.Rahmat Effendi.</p>\r\n\r\n<p><br />\r\nSementara itu Ketua RW 030 Kelurahan Kaliabang,Bekasi Utara Yusuf &nbsp;menyampaikan rasa terima kasihnya atas perhatian Wali Kota Bekasi ia mengatakan dirinya sering mendengar bahwa Rahmat Effendi selalu turun ke masyarakat,bahwa disaat hari libur.&quot;Beliau hadir pukul 8 sebelum masyarakat datang,saya apresiasi pemimpin Kota Bekasi yang satu ini&quot; jelas Yusuf.</p>', 'images/20170823082948-2017-08-23post082946.jpeg', NULL, NULL, 769, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-17 01:51:00', '2017-04-17 01:51:00', NULL),
('eb3d13f0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Hadiri Perayaan Paskah Tiberias,Wali Kota Bekasi Tegaskan Berdiri Di Semua Umat Beragama.', 'hadiri-perayaan-paskah-tiberias-wali-kota-bekasi-tegaskan-berdiri-di-semua-umat-beragama', 'Kota Bekasi (16/4) - Wali Kota Bekasi Dr.Rahmat Effendi kembali menegaskan komitmennya untuk selalu bersikap adil serta berdiri disetiap umat beragama yang ada di Kota Bekasi.Hal ini disampaikan Wali ', '<p>Kota Bekasi (16/4) - Wali Kota Bekasi Dr.Rahmat Effendi kembali menegaskan komitmennya untuk selalu bersikap adil serta berdiri disetiap umat beragama yang ada di Kota Bekasi.Hal ini disampaikan Wali Kota Bekasi saat menghadiri perayaan Paskah Gereja Tiberias Kota Bekasi yang bertempat di Lounge XXI Bekasi Hypermal,Bekasi Selatan.</p>\r\n\r\n<p><br />\r\nDalam sambutannya Wali Kota Bekasi mengatakan bahwa &nbsp;dirinya tidak hanya mendatangi acara-acara keagamaan umat kristiani saja,tetapi juga acara keagamaan hindu,budha,terlebih acara-acara seperti maulid maupun zikir bersama.Ini dilakukan &nbsp;karena dirinya selaku Kepala Daerah harus mengayomi semua umat beragama yang ada .Untuk itu ia menegaskan akan selalu menjaga dan mengajak seluruh umat beragama untuk hidup bertoleran.&quot; Kota Bekasi sebagai miniaturnya NKRI menjamin umat beragama yang diakui negara untuk melaksanakan ibadahnya,saling menjaga dan bertoleran merupakan budaya masyarakat kita,pluralisme harus terus kita pupuk bukan mempertentangkan perbedaaan&quot;jelas Wali Kota Bekasi tersebut.</p>\r\n\r\n<p><br />\r\nSementara itu Ketua Panitia Paskah Gereja Tiberias Kota Bekasi DR. Yesaya Pariadji mengatakan bahwa perayaan paskah tahun ini begitu meriah,mayoritas merupakan warga ber- KTP Kota Bekasi.&quot;Hadirnya bapak Wali Kota disini karena kami menganggap beliau adalah orang tua kami,orangtuanya semua agama,saya berterima kasih bahwa perbedaan agama di Kota Bekasi merupakan satu kekuatan dalam bersama-sama membangun Kota Bekasi kearah yang lebih baik lagi&quot;jelas DR.Yesaya.</p>', 'images/20170927073754-2017-09-27post073752.jpg', NULL, NULL, 2188, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-17 01:53:00', '2017-04-17 01:53:00', NULL),
('eb3d143f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Ingatkan Untuk Tumbuhkan  Kesadaran Tinggi.', 'wakil-wali-kota-ingatkan-untuk-tumbuhkan-kesadaran-tinggi', 'Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu memimpin Apel Hari Kesadaran Nasional yang jatuh pada tanggal 17 setiap bulannya, bertempat di Plaza Kantor Pemerintah Kota Bekasi, Senin (17/4) pagi.', '<p>Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu memimpin Apel Hari Kesadaran Nasional yang jatuh pada tanggal 17 setiap bulannya, bertempat di Plaza Kantor Pemerintah Kota Bekasi, Senin (17/4) pagi.</p>\r\n\r\n<p>Hadir saat apel bersama ini Sekretaris Daerah Kota Bekasi Drs. H. Rayendra Sukarmadji, M.Si, pejabat eselon II, III dan IV serta Pegawai Negeri Sipil dan Tenaga Kerja Kontrak di Lingkungan Pemerintah Kota Bekasi.</p>\r\n\r\n<p>Dalam sambutannya Wakil Walikota Bekasi bahwa mengatakan hari ini merupakan hari kesadaran dan tentunya kita harus canangkan bersama kesadaran ini dengan sikap tanggung jawab kita.</p>\r\n\r\n<p>&ldquo;Pencangan yang kita lakukan dengan semangat yang ada pada diri kita masing-masing, kita semakin tumbuhkan kesadaran dalam diri kita, kesadaran untuk memperbaikin diri, kesaradaran untuk kita berprestasi, kesadaran untuk kita mampu mengimplementasikan tugas dan tupoksi kita serta kesadaran untuk mempertahankan kehidupan bernegara Republik Indonesia&rdquo; ungkapnya.</p>\r\n\r\n<p>&ldquo;Semuanya berpulang kepada diri kita masing-masing, dimanapun kita ditempatkan tapi kesadaran kita tidak pulih dan tidak muncul maka prilaku-prilaku yang buruk akan tetap terjadi, walaupun di roling berkali-kali para pemangku jabatan tapi tanpa ada kesadaran seperti ini saya yakin juga hanya akan memindahkan masalah dari Dinas A ke Dinas B dan begitulah seterusnya&rdquo;,tambahnya.</p>\r\n\r\n<p>&ldquo;Saya mengingatkan kepada diri saya dan kepada Kepala Perangkat Daerah mari kita coba untuk insropeksi diri untuk meningkatkan upaya-upaya untuk menyadarkan dirikita masing-masing&rdquo; ujarnya.</p>\r\n\r\n<p>&ldquo;Oleh karena itulah saya berharap bahwa kesadaran ini muncul dari diri kita semua, saya yakin kalau pemangku jabatannya semuanya sudah tersadarkan, maka mulai dari pemangku jabatan hingga kebawahnya akan menjadi baik&rdquo; imbuhnya. (gie)</p>', 'images/20170927073944-2017-09-27post073943.jpg', NULL, NULL, 2004, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-17 10:58:00', '2017-04-17 10:58:00', NULL),
('eb3d1490-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'DPRD Kabupaten Demak Kunjungi Kota Bekasi.', 'dprd-kabupaten-demak-kunjungi-kota-bekasi', 'Kota Bekasi, 17-04-2017. DPRD Kabupaten Demak kunjungi Kota Bekasi, untuk mempelajari penyusunan\r\n\r\nLaporan Keterangan Pertanggungjawaban (LKPJ) Kepala Daerah. Rombongan anggota DPRD tersebut yang dip', '<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14794\" rgb=\"\">Kota Bekasi, 17-04-2017. DPRD Kabupaten Demak kunjungi Kota Bekasi, untuk mempelajari penyusunan</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14795\" rgb=\"\">Laporan Keterangan Pertanggungjawaban (LKPJ) Kepala Daerah. Rombongan anggota DPRD tersebut yang dipimpin</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14796\" rgb=\"\">oleh Wakil Ketua Komisi B, Rozikhan Anwar diterima oleh kepala Bagian Humas Setda Kota Bekasi, MHD Jufri.</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14797\" rgb=\"\">didampingi perwakilan Bagian Tapem dan Perwakilan BPKAD kota Bekasi, senin( 17/04) bertempat di Press Room Humas Kota Bekasi.&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14798\" rgb=\"\">&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14800\" rgb=\"\">Dijelaskan oleh Ketua rombongan, untuk Kabupaten Demak, sudah menyelenggarakan paripurna LKPJ tahun 2016. dan untuk tahun 2017&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14801\" rgb=\"\">sedang dilakukan penyusunan oleh Tim. Namun masih banyak yang harus disempurnakan dalam penyusunan LKPJ di Kabupaten Demak , untuk itu</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14802\" rgb=\"\">dirinya dan juga beberapa anggota DPRD Kabupaten Demak perlu banyak belajar dari Pemerintah Kota Bekasi</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14803\" rgb=\"\">dalam hal penyusunan LKPJ.&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14804\" rgb=\"\">&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14806\" rgb=\"\">&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14807\" rgb=\"\">Sementara itu, Kabag Humas Setda Kota Bekasi, MHD Jufri menuturkan bahwa dalam penyusunan LKPJ</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14808\" rgb=\"\">berbagai hal dan kendala dihadapi. terutama kesulitan dari TIm untuk meminta data di tiap-tiap SKPD</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14809\" rgb=\"\">. untuk itu perlu komitmen dari tia[-tiap kepala SKPD dalam penyusunan LKPJ ini. sehingga diharapkan&nbsp;</div>\r\n\r\n<div id=\"m_-1871602995550260433yui_3_16_0_ym19_1_1492420016915_14810\" rgb=\"\">LKPJ dapat tersusun tepat waktu , ujarnya. (yas)</div>', 'images/20170927074121-2017-09-27post074120.jpg', NULL, NULL, 2579, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-17 11:01:00', '2017-04-17 11:01:00', NULL),
('eb3d14e7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Komisi D DPRD Kota Malang Belajar ke Kota Bekasi', 'komisi-d-dprd-kota-malang-belajar-ke-kota-bekasi', '\r\n\r\n\r\nKota bekasi, 17-04-2017. Komisi D DPRD Kota Malang, hari Senin mengunjungi Kota Bekasi untuk tukar informasi masalah Perda Tentang Perempuan dan anak.&nbsp;\r\n\r\nDi Kota bekasi, rombongan Komisi D', '<div 12.8px=\"\" class=\"ii gt adP adO\" id=\":l2\">\r\n<div class=\"a3s aXjCH m15b7b6dd9200d499\" hidden=\"\" id=\":l3\">\r\n<div rgb=\"\">\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19227\">Kota bekasi, 17-04-2017. Komisi D DPRD Kota Malang, hari Senin mengunjungi Kota Bekasi untuk tukar informasi masalah Perda Tentang Perempuan dan anak.&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19235\">Di Kota bekasi, rombongan Komisi D DPRD Kota Malang diterima oleh &nbsp;Staf Ahli Wali Kota Bidang Pembangunan, Teddy Hafni, ketua KPAID Kota Bekasi, Rony serta&nbsp;<span id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_21295\" rgb=\"\">&nbsp;Kepala Badan Perlindungan Perempuan dan Perlindungan Anak Kota Bekasi (KPPPA) Riswanti</span>&nbsp;beserta jajarannya di ruang press room.</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19237\">&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19239\">Dalam kunjungannya, Ketua Komisi D DPRD Kota Malang, Imam Fauzi menuturkan tujuan kedatangannya ke Kota Bekasi, untuk berkonsultasi perihal perda perlindungan Perempuan dan anak yang ada di kota bekasi.&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19243\">&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19245\">dijelaskannya bahwa kota bekasi sudah banyak mendapat penghargaan-penghargaan yang kaitannya &nbsp;tentang perlindungan perempuan dan anak.&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19247\">&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19249\">Dikatakannya bahwa maraknya kasus kekerasan &nbsp;pada perempuan dan anak menjadi salah satu problem yang harus &nbsp;diselesaikan secara komprehensif, salah satu realita yang terjadi di Kota malang yaitu maraknya eksploitasi anak dibawah umur &nbsp;oleh pihak-pihak yang tidak bertanggung jawab, dengan beberapa &nbsp;kejadian yang ada para anak-anak tersebut dijadikan alat penghasil &nbsp;uang dengan menjadikan mereka pengamen dan pengemis. untuk itu perlu adanya aturan yang mengatur hal-hal tersebut.&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19259\">&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19261\">sementara itu, Kadis PPPA, Riswanty, menjelaskan bahwa Kota bekasi berupaya dengan gencar untuk melakukan perlindungan perempuan dan anak. Salah</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19263\">satunya melakukan sosialisasi di RT/RW serta mmembentuk satgas-satgas perlindungan perempuan dan anak. dengan begitu masyarakat dapat memahami kemana dan bagaimana mereka harus melapor apabila dilingkungan seitarnya terjadi kekerasan, terang Riswanty.&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19266\">&nbsp;</div>\r\n\r\n<div id=\"m_7858414132704928751yui_3_16_0_ym19_1_1492420016915_19268\">Kita berharap di semua kota /kabupaten untuk masalah kekerasan ini agar tidak ada lagi, tandasnya, &nbsp;(yas)</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div class=\"yj6qo\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div both=\"\" class=\"hq gt\" id=\":lv\">&nbsp;</div>', 'images/20170927074306-2017-09-27post074305.jpg', NULL, NULL, 2292, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-17 11:04:00', '2017-04-17 11:04:00', NULL),
('eb3d1538-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Hadiri Penilaian Lomba Kelurahan Tingkat Nasional Di kec Medan Satria', 'wali-kota-hadiri-penilaian-lomba-kelurahan-tingkat-nasional-di-kec-medan-satria', 'ota Bekasi --- Wali Kota Bekasi, Dr. Rahmat Effendi mengucapkan selamat datang kepada para tim verifikasi lapangan dan penilaian lomba lingkungan bersih dan sehat tingkat nasional Tahun 2017, Keluraha', '<p>ota Bekasi --- Wali Kota Bekasi, Dr. Rahmat Effendi mengucapkan selamat datang kepada para tim verifikasi lapangan dan penilaian lomba lingkungan bersih dan sehat tingkat nasional Tahun 2017, Kelurahan Pejuang Kecamatan Medan Satria akan mengikuti Lomba tersebut mewakili Kota Bekasi di Provinsi Jawa barat.&nbsp;</p>\r\n\r\n<p><br />\r\nWali Kota Bekasi dalam sambutannya mengupayakan dalam bidang kesehatan di Pemerintah Kota Bekasi telah melakukan kerja sama bersama Rumah Sakit Swasta sebanyak 39 Rumah Sakit untuk tidak menolak warga Kota Bekasi yang membutuhkan, dengan Kartu Sehat berbasis NIK serupa dengan BPJS bisa masuk ke Rumah sakit manapun dengan komitmen melayani di Kota Bekasi. Ditambahkan, 39 Pusekesmas dengan 10 Puskesmas Poned beserta klinik yang tersebar di Kecamatan serta dilengkapu tenaga kesehatan profesional.&nbsp;</p>\r\n\r\n<p><br />\r\nDi bidang Kebersihan, Kelurahan di Kota Bekasi telah menyepakati komitmen menuju Kelurahan bebas buang Air besar sembarangan atau ooen defecation Free (odf) dan secara umum warga Kota Bekasi sudah menggunakan jamban sehat yang dimulai dari Kelurahan Pejuang.&nbsp;</p>\r\n\r\n<p><br />\r\nPemerintah kota Bekasi juga menguoayakan pembiasan perilaku bersih dan sehat Serra memotivasi pemberdayaan masyarakat seperti Gerakan Bank sampah, Sanitasi total berbasis masyarakat, kawasan bebas asap rokok, program Kotaku (KotaTanpa Kumuh).</p>\r\n\r\n<p><br />\r\nWali Kota Juga menegaskan untuk insentif yang telah diterima bagi para kader tim pengerak PKK, PLKB, dan para Kader yang ikut berperan di wilayah wilayah untuk penerimaan insentif tersebut harus perbulan sekali tidak lagi per tiga bulan, juga menyebutkan insentif para Kader aktif di wilayah akan naik dari 200 ribu rupiah menjadi 400 ribu rupiah, yang akan membuat motivasi kerja harus semakin meningkat.&nbsp;</p>\r\n\r\n<p><br />\r\nWali Kota mengharapkan perwakilan dari Kota Bekasi diharapkan memegang juara umum, dan pulang menghasilkan tambahan prestasi yang bisa menambahkan penghargaan di Kota Bekasi, karena selama pemerintahan INI sudah meraih 34 penghargaan termasuk 14 dari tingkat Provinsi Jawabarat dan Sisa nya dari tingkat Nasional. &nbsp;(Ndoet)&nbsp;</p>', 'images/20170929143654-2017-09-29post143648.jpg', NULL, NULL, 3625, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-18 06:50:00', '2017-04-18 06:50:00', NULL),
('eb3d1587-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Lomba Desain Maskot Boneka Kota Bekasi', 'lomba-desain-maskot-boneka-kota-bekasi', 'Kota Bekasi merupakan kota penghasil boneka terbesar di Indonesia. Banyak pengrajin boneka di Kota Bekasi dengan berbagai kreativitas dan kualitas yang sudah mendapat pengakuan dari pasar nasional dan', '<p>Kota Bekasi merupakan kota penghasil boneka terbesar di Indonesia. Banyak pengrajin boneka di Kota Bekasi dengan berbagai kreativitas dan kualitas yang sudah mendapat pengakuan dari pasar nasional dan internasional. Boneka produksi pengusaha Kota Bekasi banyak di ekspor ke mancanegara. Tujuan utama ekspor boneka yaitu Korea Selatan dan Amerika Serikat.</p>\r\n\r\n<p>Pelaku industri kecil menengah boneka Kota Bekasi mendapat perhatian khusus dari pemerintah daerah. Berbagai upaya telah dilakukan Pemerintah Kota Bekasi untuk mengangkat daya saing industri kecil menengah seperti pelaku usaha boneka. Bentuk perhatian Pemerintah Kota Bekasi dalam hal kemudahan akses permodalan, kemudahan dalam perizinan dan membantu promosi.</p>\r\n\r\n<p>Sebagai upaya memasarkan industri kecil menengah boneka, Pemerintah Kota Bekasi menggelar Lomba Desain Maskot Boneka Kota Bekasi. Lomba ini bertujuan untuk memasarkan boneka produksi Kota Bekasi. Dengan event ini diharapkan industri boneka Kota Bekasi makin dikenal dan diminati pasar nasional dan internasional.</p>\r\n\r\n<p>Disamping itu, Lomba Desain Maskot Boneka Kota Bekasi ini sebagai upaya menciptakan ikon kota patriot. Boneka layak dijadikan salah satu ikon Kota Bekasi. Ini sebagai bentuk apresiasi tertinggi Pemerintah Kota Bekasi terhadap pelaku industri kecil menengah.</p>\r\n\r\n<p>Kota Bekasi sebagai produsen terbesar boneka di Indonesia. Dengan bangga mempersembahkan:</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p align=\"center\">Lomba Desain Maskot Boneka Kota Bekasi</p>\r\n\r\n<p>Syarat &amp; Ketentuan</p>\r\n\r\n<p>-Peserta berasal dari kalangan pelajar, mahasiswa, praktisi, dan masyarakat umum, baik perorangan maupun kelompok.</p>\r\n\r\n<p>-Warga Negara Indonesia.</p>\r\n\r\n<p>-Peserta bisa mengirimkan lebih dari 1 desain.</p>\r\n\r\n<p>-Asli, Merupakan hasil karya orisinil atau pemikiran/kreasi sendiri, bukan merupakan tiruan atau jiplakan dari desain yang telah ada sebelumnya.</p>\r\n\r\n<p>-Desain memiliki unsur elegan dan kreatif serta memiliki unsur kearifan lokal Kota Bekasi.</p>\r\n\r\n<p>-Wajib memberi nama pada desain maskot.</p>\r\n\r\n<p>-Desain dapat diaplikasikan pada bentuk boneka.</p>\r\n\r\n<p>-Desain memiliki karakter, modern, dan bermakna.</p>\r\n\r\n<p>-Karya yang terpilih menjadi hak milik Pemerintah Kota Bekasi.</p>\r\n\r\n<p>-Keputusan dewan juri tidak bisa diganggu gugat.</p>\r\n\r\n<p>-Peserta mengirim desain maskot ke:</p>\r\n\r\n<p><a href=\"mailto:lombamaskotboneka@bekasikota.go.id\">lombamaskotboneka@bekasikota.go.id</a></p>\r\n\r\n<p>-Bersamaan dengan mengirim desain maskot boneka, peserta menyertakan surat penyataan bahwa karya tersebut merupakan karya asli peserta. Surat pernyataan dapat diunduh di web ini.</p>\r\n\r\n<p>-Hasil desain dikirim dalam format file JPG, PNG, dan PSD atau CDR</p>\r\n\r\n<p>-Desain diterima panitia paling lama Hari Sabtu 20 Mei 2017 jam 24:00.&nbsp;</p>\r\n\r\n<p>Hadiah</p>\r\n\r\n<p>Pemenang lomba mendapat hadiah berupa uang sebesar Rp. 15.000.000 (Lima Belas Juta Rupiah). Pajak ditanggung pemenang.</p>\r\n\r\n<p>&nbsp;Download&nbsp;==&gt;&gt;&nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/4PjbNpgoqV4BCCU\">Surat Pernyataan Lomba Desain Maskot&nbsp;</a></p>', 'images/20170929144615-2017-09-29post144601.jpg', NULL, NULL, 5332, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-18 15:20:00', '2017-04-18 15:20:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d15d9-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi dengan Gubernur DKI Jakarta Tandatangani MoU Peningkatan  TPST Bantargebang', 'wali-kota-bekasi-dengan-gubernur-dki-jakarta-tandatangani-mou-peningkatan-tpst-bantargebang', 'DKI Jakarta ---- Wali Kota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Terkait hadir di Balai Kota DKI Jakarta, pada hari Selasa (18/04/2017) untuk menghadiri Penandatanganan Adendum Perjanjian Ke', '<p>DKI Jakarta ---- Wali Kota Bekasi, Dr. Rahmat Effendi bersama Kepala Dinas Terkait hadir di Balai Kota DKI Jakarta, pada hari Selasa (18/04/2017) untuk menghadiri Penandatanganan Adendum Perjanjian Kerjasama antara Pemerintah Kota Bekasi dengan Pemerintah Provinsi DKI Jakarta tentang peningkatan pemanfaatan lahan tempat pembuangan Akhir (TPA) Sampah Menjadi Tempat Pengolahan Sampah Terpadu (TPST) Bantargebang Kota Bekasi, Wali Kota Bekasi dengan Gubernur DKI Jakarta, Basuki Tjahaya Purnama menandatangani MoU tersebut.</p>\r\n\r\n<p><br />\r\nPemerintah Provinsi DKI Jakarta juga menyatakan kesepakatannya untuk menyediakan kebutuhan air bersih di sekitar kawasan Tempat Pengelolaan Sampah Terpadu Bantargebang mulai 2017.</p>\r\n\r\n<p><br />\r\n&quot;Kesepakatan itu tertuang dalam Addendum atau perjanjian perubahan Pemprov DKI dan Pemkot Bekasi terkait dengan peningkatan pemanfaatan lahan di TPST Bantargebang yang kita lakukan hari ini,&quot; kata Wali Kota Bekasi Rahmat Effendi.</p>\r\n\r\n<p>&nbsp; &nbsp;</p>\r\n\r\n<p>Menurut Wali Kota, dalam addendum itu terdapat salah satu poin kesepakatan bahwa Pemprov DKI bersedia mengeluarkan dana penyertaan Rp25 miliar pada 2017 untuk pengembangan jaringan sumur artesis di tiga kawasan TPST Bantargebang.</p>\r\n\r\n<p><br />\r\n&quot;Sumur artesis itu akan dibangun di Kelurahan Ciketing Udik, Kelurahan Cikuwul dan Kelurahan Sumurbatu. Totalnya akan ada 8 ribu jaringan distribusi air bersih yang bersumber dari sumur artesis tersebut,&quot; katanya.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Air bersih ini gratis, Sebab masyarakat di sana masih kesulitan mengakses air bersih akibat limbah sampah yang mengotori air tanah.</p>\r\n\r\n<p><br />\r\nDilain itu, Kepala Dinas Lingkungan Hidup DKI Jakarta Isnawa Adji menambahkan, poin addendum tersebut berisi tiga hal yang berkaitan dengan peningkatan kinerja pelayanan sampah serta penataan lingkungan Bantargebang.</p>\r\n\r\n<p><br />\r\n&quot;Poin pertama, berkaitan dengan kompensasi yang dipergunakan untuk penanggulangan kerusakan lingkungan, perbaikan infrastruktur, kesehatan dan pengobatan,&quot; katanya.</p>\r\n\r\n<p><br />\r\nPoin kedua, terkait dengan bantuan langsung tunai kepada 18 ribu warga yang terdampak sampah DKI di Bantargebang dan poin ketiga berkaitan dengan pembentukan Tim Monitoring Evaluasi Sampah yang terdiri atas perangkat daerah, pelibatan tenaga ahli dan tokoh masyarakat berdasarkan persetujuan Wali Kota Bekasi.</p>\r\n\r\n<p><br />\r\nSementara itu, dalam sambutannya Gubernur DKI Jakarta Basuki Tjahaja Purnama &nbsp;mengapresiasi kerja sama yang baik antara kedua pemerintahan itu.</p>\r\n\r\n<p><br />\r\n&quot;DKI senang punya daerah tetangga yang punya respons cepat terhadap persoalan warganya. Komunikasi saya dengan Wali Kota Bekasi cukup lewat Whatsaap. Hubungan ini sangat baik,&quot; katanya.</p>\r\n\r\n<p><br />\r\nDasar pembuatan addendum tersebut, kata dia, merupakan tindak lanjut atas keputusan pihaknya untuk melakukan swakelola TPST Bantargebang sejak 2016.</p>\r\n\r\n<p><br />\r\n&quot;Buat apa bayar swasta untuk mengelola TPST Bantargebang, lebih baik uangnya kita serahkan kepada Pemkot Bekasi untuk dikelola dengan baik,&quot; tegas Gubernur DKI Jakarta. (Ndoet/congki)</p>', 'images/20171004224055-2017-10-04post224048.jpg', NULL, NULL, 3496, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-18 23:08:00', '2017-04-18 23:08:00', NULL),
('eb3d1632-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Bekasi Buka Pelatihan dan Sertifikasi Pengadaan Barang dan Jasa', 'wakil-wali-kota-bekasi-buka-pelatihan-dan-sertifikasi-pengadaan-barang-dan-jasa', 'Kota Bekasi, Wakil Walikota Bekasi Ahmad Syaikhu membuka Pelatihan dan Setifikasi Pengadaan Barang dan Jasa Pemerintah Tahun 2017 bagi para pemangku jabatan di lingkungan Pemerintah Kota Bekasi bertem', '<p>Kota Bekasi, Wakil Walikota Bekasi Ahmad Syaikhu membuka Pelatihan dan Setifikasi Pengadaan Barang dan Jasa Pemerintah Tahun 2017 bagi para pemangku jabatan di lingkungan Pemerintah Kota Bekasi bertempat di Hotel Merapi Merbabu, Jl. Cut Mutia No. 91, Sepanjang Jaya, Rawa Lumbu, Selasa (18)/4) pagi.</p>\r\n\r\n<p>Kegiatan ini dilaksanakan oleh Bidang Diklat Badan Kepegawaian Pendidikan dan Pelatihan Daerah Kota Bekasi selama 3 (tiga) hari mulai tanggal 18 &ndash; 20 April 2017, untuk meningkatan Sumber Daya Manusia dalam rangka peningkatan kompetensi pengelola pengadaan barang dan jasa di lingkungan Pemerintah Kota Bekasi.</p>\r\n\r\n<p>Dalam sambutannya beliau menyampaikan bahwa salah satu kendala yang kita hadapi dalam peserta sertifikasi barang dan jasa adalah pola pikir kita yang kadang-kadang ingin melepaskan tanggung jawab yang lebih besar.</p>\r\n\r\n<p>&ldquo;Terkadang berfikirnya bila kita sudah punya sertifikasi maka harus melakukan proses pengadaan barang dan jasa, kalau ada sesuatu yang beresiko maka akan menyangkut kepada pejabat barang dan jasa, kalau masih berfikir seperti itu maka &nbsp;tidak ada yang akan ada mendapat sertifikat atau lulus sertifikasi&rdquo; ungkapnya</p>\r\n\r\n<p>&ldquo;Kenapa saya dan Wali Kota mendorong dan mendorong kepada para pemangku jabatan untuk dapat lulus sertifikasi pengadan barang dan jasa, karena ingin proses pengadan barang dan jasa berjalan lancar pada triwulan-triwulan awal dan pada akhirnya tidak ada permasalahan-permasalahan hokum di kemudian hari serta agar kita juga memahami betul ruang tugas dan tanggung jawab kita dalam proses barang dan jasa&rdquo; ujarnya</p>\r\n\r\n<p>&ldquo;Saya mengganggap Sertifikasi Pengadaan Barang dan Jasa ini sangat penting karena volume APBD kita dari tahun ke tahun mengalami peningkatan dan pada tahun 2018 sudah melampaui 6 Triliun, dengan angka yang sebesar itu maka akan diperlukan banyak pejabat pengadaan barang dan jasa serta memahami ketentuan perundanga-undangan dan seyogyanya kita dapat melakukan proses pengadaan barang dan jasa ini dengan baik dan lancar&rdquo; imbuhnya</p>\r\n\r\n<p>Saya sangat berharap dengan kegiatan ini akan bisa lulus semuanya, &nbsp;sehingga proses barang dan jasa kedepan tidak mengalami kendala, prosesnya akan berjalan lancar dan tidak menimbulkan permasalahan hukum dikemudian hari. (gie)</p>', 'images/20171004224137-2017-10-04post224135.jpg', NULL, NULL, 2311, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-18 23:11:00', '2017-04-18 23:11:00', NULL),
('eb3d168d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Menerima kunjungan Delegasi Forsilap', 'wali-kota-bekasi-menerima-kunjungan-delegasi-forsilap', 'Kota Bekasi - Forum Silaturahmi Masyarakat Betawi (Forsilab) beraudiensi dengan Wali Kota Bekasi DR.Rahmat Effendi, di kantor Wali kota Bekasi Rabu, 19/4.\r\n\r\nDalam audiensinya pengurus Forsilab mengat', '<p>Kota Bekasi - Forum Silaturahmi Masyarakat Betawi (Forsilab) beraudiensi dengan Wali Kota Bekasi DR.Rahmat Effendi, di kantor Wali kota Bekasi Rabu, 19/4.</p>\r\n\r\n<p>Dalam audiensinya pengurus Forsilab mengatakan forum silahturahmi ini didirikan untuk meningkatkan sumber daya manusia dan pemberdayaan masyarakat Betawi hingga mempertahankan nilai nilai &nbsp;luhur masyarakat Betawi baik budaya dan falsafah kehidupan masyarakat Betawi khususnya.</p>\r\n\r\n<p>Wali Kota Bekasi mengungkapkan bahwa forum pemberdayaan masyarakat baik itu berbentuk LSM atau forum silahturahmi haruslah bersinergi dengan Pemerintah, &quot;Saling menopang antara Pemerintah dengan LSM itu sangat dibutuhkan untuk menciptakan masyarakat yang Maju, Sejahtera, sehingga menciptakan masyarakat yang Ihsan.</p>\r\n\r\n<p>Dalam kesempatan ini Ia juga mensosialisasikan tentang Kartu Sehat yang telah diluncurkan oleh Pemerintah Kota Bekasi yang fungsi dan kegunaannya sama dengan BPJS kesehatan,&quot; jadi kalau sudah ada Kartu Bekasi Sehat tidak perlu lagi menggunakan bPJS kesehatan karna fungsi dan kegunaannya sama.</p>\r\n\r\n<p>Bedanya, ia menambahkan Kartu Bekasi Sehat sepenuhnya dibayarkan oleh Pemerintah daerah dalam hal ini Pemerintah Kota Bekasi dan dapat dipergunakan di seluruh rumah sakit swasta yang ada di Kota Bekasi.</p>\r\n\r\n<p>Walikota Kota berharap semoga visi dan misi kota bekasi yang Maju, Sejahtera dan Ihsan dapat dirasakan oleh seluruh elemen masyarakat kota bekasi.(Tody)</p>', 'images/20170823073848-2017-08-23post073846.jpg', NULL, NULL, 3712, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-19 12:04:00', '2017-04-19 12:04:00', NULL),
('eb3d16dd-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Lakukan Sidak di SMP 1 dan SMP 2', 'wali-kota-bekasi-lakukan-sidak-di-smp-1-dan-smp-2', 'Kota Bekasi - Dalam upaya meningkatkan budaya tertib administrasi Wali Kota Bekasi DR. Rahmat Effndi lakukan Inspeksi Mendadak (sidak) di Sekolah Menengah Pertama 1 dan &nbsp;2 Kota Bekasi, Rabu , 19/', '<p>Kota Bekasi - Dalam upaya meningkatkan budaya tertib administrasi Wali Kota Bekasi DR. Rahmat Effndi lakukan Inspeksi Mendadak (sidak) di Sekolah Menengah Pertama 1 dan &nbsp;2 Kota Bekasi, Rabu , 19/4.</p>\r\n\r\n<p>Sidak yang dilaksanakan dalam menegakkan tertib Administrasi di tingkat sekolah adalah sebagian kecil upaya Pemerintah dalam mempertahankan opini Wajar Tampa Pengecualian (WTP) yang telah diberikan oleh Pemerintah pusat.</p>\r\n\r\n<p>Wali Kota Bekasi DR. Rahmat Effendi dalam sidak di Sekolah Menengah Pertama Negri 1 Kota Bekasi mengatakan bahwa banyak barang pengadaan yang tidak sesuai dengan peruntukannya,&quot; sebagai contoh sarana dan Prasana meubelair lebih di butuhkan dibanding pengadaan barang yang lain&quot;, ucap nya .</p>\r\n\r\n<p>Ditempat lain ia menyayangkan sarana perpustakaan yang Terbengkalai karna kurang nya sarana dan prasarana yang tidak mendukung sehingga perpustakaan tersebut terlihat tidak terawat.</p>\r\n\r\n<p>Diakhir sidak ia berharap agar seluruh elemen pemerintahan agar tertib administrasi dan tertib perencanaan, &quot; perencanaan pembelanjaan harus lah disesuaikan oleh kondisi dan kebutuhan,&quot; harapnya.(Tody )</p>', 'images/20171004224246-2017-10-04post224242.jpg', NULL, NULL, 3662, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-19 12:07:00', '2017-04-19 12:07:00', NULL),
('eb3d1737-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sharing E-Government ke Kota Bekasi, DPRD Kabupaten Kediri Bahas Kajian Kebijakan Tentang Pengembang', 'sharing-e-government-ke-kota-bekasi-dprd-kabupaten-kediri-bahas-kajian-kebijakan-tentang-pengembang', '\r\n\r\n\r\nBekasi Kota &ndash;Ketua Komisi A DPRD Kabupaten Kediri Edy Suprapto S. Tp beserta beberapa orang anggota DPRD Kab Kediri mengunjungi Kota Bekasidalam rangka untuk mempelajari pengembangan E-Gov', '<div 12.8px=\"\" class=\"ii gt adP adO\" id=\":lu\">\r\n<div class=\"a3s aXjCH m15b84c7b8487f482\" hidden=\"\" id=\":lt\">\r\n<div rgb=\"\">\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8981\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8982\">Bekasi Kota &ndash;Ketua Komisi A DPRD Kabupaten Kediri Edy Suprapto S. Tp beserta beberapa orang anggota DPRD Kab Kediri mengunjungi Kota Bekasidalam rangka untuk mempelajari pengembangan E-Govertment di kota Bekasi</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9075\">. Rombongan di terima oleh&nbsp;</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9092\">Kepala Bagian Humas Sekretariat Daerah Kota Bekasi , Dr. Mhd. Jufri SH. MH,&nbsp;</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9093\">Kepala Dinas Komunikasi Informatika, Statistika dan Persandian Dr. dr. Hj. TitiMasrifahati,</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9094\">&nbsp;Kepala Seksi E-Government Dadi Jaya Kusumadan, Mkm beserta jajarannya.</span><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9095\">diruang Press Room Humas Setda Kota Bekasi, Selasa (18/4/2017).</span></div>\r\n\r\n<div id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8981\" justify=\"\">&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8984\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8985\">Kedatangan anggota DPRD Kediri membahas mengenai kajian kebijakan tentang pengembangan E-Government yang diterapkan di Kota Bekasi.&nbsp;</span></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8988\"><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9151\">Diterangkan Kepala Dinas Komunikasi Informatika, Statistika dan Persandian Dr. dr. Hj. TitiMasrifahati,&nbsp;</span>Kota Bekasi masuk dalam target Tata Kelola Pemerintahan Berbasis E-Government yang nantinya pada tahun 2018 akan mencapai target 100%.&nbsp;</span></div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\">&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_9148\">Saat ini pencapaian kami baru 60% sedangkan harus menyelesaikan dalam waktu 2017 sampai 2018.&nbsp;</span></div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_10826\">&nbsp;Kami memiliki beberapa persiapan-persiapan , tahun lalu kami memiliki Kota Cerdas atau Smart City yang sekarang berjalan 1tahun. Diskominfo di jadikan Tim Kota Cerdas Bekasi.&nbsp;</span></div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\">&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\"><span 12pt=\"\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_10827\">Ada 2 skenario yang pertama skenario yang tercantum di RPJMD dan juga skenario akselerasi dengan menggandeng yang namanya Smart City.&nbsp; ujar Titi.&nbsp;</span></div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\">&nbsp;</div>\r\n\r\n<div dir=\"ltr\" id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_8987\" justify=\"\"><span 12pt=\"\">Diharapkan kedepan</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_10835\" rgb=\"\">&nbsp;</span><span id=\"m_-1495747679529919282yui_3_16_0_ym19_1_1492580639817_10836\" rgb=\"\">konsep yang mulai dirintis pada 2015 ini bermanfaat bagi kota metropolitan, seperti Bekasi. Pasalnya, dalam dunia yang semakin digital, Pemkot Bekasi dengan jumlah penduduk 2,6 juta jiwa harus cerdas, smart, dan berkarakter, mampu memanfaatkan arus informasi masalah perkotaan.tandasnya. (yas).</span></div>\r\n\r\n<div>&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"yj6qo\">Sharing E-Government ke Kota Bekasi, DPRD Kabupaten Kediri Bahas Kajian Kebijakan Tentang Pengembang</div>\r\n</div>\r\n\r\n<div both=\"\" class=\"hq gt a10\" id=\":mn\">&nbsp;</div>', 'images/20171004224356-2017-10-04post224354.jpg', NULL, NULL, 2662, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-19 12:10:00', '2017-04-19 12:10:00', NULL),
('eb3d1787-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'DPRD Tanah Datar Kunjungi Kota Bekasi Bahas Tentang Infrastruktur', 'dprd-tanah-datar-kunjungi-kota-bekasi-bahas-tentang-infrastruktur', 'Kota Bekasi, 19-04-2017. Anggota DPRD Tanah Datar melakukan kunjungan kerjanya ke Pemerintah Kota Bekasi untuk belajar tentang proses-proses pembangunan Infratruktur yang ada di Kota Bekasi.&nbsp;\n\n&n', '<div dir=\"ltr\" id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8891\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kota Bekasi, 19-04-2017. Anggota DPRD Tanah Datar melakukan kunjungan kerjanya ke Pemerintah Kota Bekasi untuk belajar tentang proses-proses pembangunan Infratruktur yang ada di Kota Bekasi.&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8891\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8891\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Rombongan yang dipimpin oleh Wakil Ketua Komisi 3 DPRD Tanah Datar Irman diterima oleh Staf ahli Wali Kota Bidang Pembangunan, Tedy Hafni, didampingi Kabag Humas Setda Kota Bekasi, MHD Jufri, Kabid PUPUR, bertempat di Press Room &nbsp;Humas Kota Bekasi, Rabu (19/04).</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8895\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8897\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Diterangkan oleh Staff Ahli Wali Kota, bahwa untuk tahun infrastruktur Kota Bekasi mencanangkannya di tahun 2016 lalu, berbagai insfrastruktur dibangun seperti,&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8898\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Jalan, Pedistrian, Folder , Jembatan dan Gedung-gedung.&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8899\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8900\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Sementara itu, untuk tahun 2017 ini Kota Bekasi mencanangkan Tahun Investasi dan Inovasi.&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8901\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8903\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Didalam kunjungan ini dilakukan juga diskusi, berbagai pertanyaan disampaikan oleh Anggota DPRD Kab. Tanah Datar, seperti anggaran yang dialokasikan untuk infrastruktur serta aturan seperti apa yang dibuat oleh Pemerintah Kota Bekasi dalam membangun gedung-dedung instansi vertikal seperti membangun gedung Polres, Gedung Imgirasi dan Gedung Lapas.&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8905\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_-4365520710710607529yui_3_16_0_ym19_1_1492596128028_8907\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Dikatakan Wakil Ketua Komisi 3 DPRD Tanah Datar, Irman, bahwa pihaknya datang ke Kota Bekasi untuk dapat mempelajari regulasi atau aturan seperti apa yang digunakan kota bekasi dalam proses pembangunan gedung-gedung istansi vertikal tersebut, ujarnya. &quot; saya apresiasi apa yang dilakukan oleh Kota Bekasi terutama terhadap perkembangan infrastruktur ada saat ini&quot;, pungkasnya. (yas). &nbsp; &nbsp;</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-19 12:13:00', '2017-04-19 12:13:00', NULL),
('eb3d17d7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kabag Humas Terima Kunker Kabupaten Nias Utara.', 'kabag-humas-terima-kunker-kabupaten-nias-utara', 'Kota Bekasi,-- Kepala Bagian Humas Setda Kota Bekasi Dr. H. MHD Jufri, SH, MH menerima Kunjungan Kerja DPRD Kabupaten Nias Utara bertempat di Ruang Presroom Bagian Humas, Kamis (20/4) pagi.\n\nKunjungan', '<p>Kota Bekasi,-- Kepala Bagian Humas Setda Kota Bekasi Dr. H. MHD Jufri, SH, MH menerima Kunjungan Kerja DPRD Kabupaten Nias Utara bertempat di Ruang Presroom Bagian Humas, Kamis (20/4) pagi.</p>\n\n<p>Kunjungan kerja ini dilakukan dalam rangka studi banding terkait pembentukan dan penerapan peraturan daerah di Kota Bekasi untuk dapat di aplikasikan di Kabupaten Nias Utara.</p>\n\n<p>Kepala Bagian Humas dalam sambutannya mengucapkan terima kasih karena telah menunjuk Kota Bekasi sebagai kota studi dari DPRD Kabupaten.Nias Utara terkait pembentukan dan penerapan peraturan daerah.</p>\n\n<p>&ldquo;Di Kota Bekasi, Wali Kota kami telah memberikan contoh pimpinan yang baik yaitu dengan meminta setiap bagian untuk memberikan laporan kinerja setiap harinya untuk dilaporkan melalui website masing-masing perangkat daerah, selain itu kebujakan Wali Kota memberikan kartu sehat kota Bekasi bagi masyarakat Kota Bekasi untuk dapat digunakan di 38 Rumah Sakit Swasta dan RSUD Kota Bekasi&rdquo; tambahnya.</p>\n\n<p>Ketua Badan Legislatif Yamanto &nbsp;mengatakan bahwa dalam rangka meningkatkan kapasitas Kabupaten.Nias dalam hal Peraturan Daerah dan Peningkatan Ekonomi masih &ldquo;setengah jalan&rdquo; karena kesulitan dalam melakukan mengimplementasi.</p>\n\n<p>&nbsp;&ldquo;Dari segi ekonomi , Kota Bekasi memiliki nilai inflasi diatas nasional sehingga membuat banyak investor tertarik untuk menanamkan modalnya di sini sehingga terlihat Kota Bekasi dapat berkembang secara pesat&rdquo; ujarnya</p>\n\n<p>&ldquo;Kami melihat Kota Bekasi lebih maju dalam implementasi peraturan daerah dan &nbsp;peningkatan ekonomi, dalam kunjungan hari ini kami ingin meminta kiat-kiat dalam hal implementasi Peraturan Daerah dan peningkatan ekonomi untuk dapat &nbsp;menyusun ulang strategi sehingga akan lebih efektif dan efisien&rdquo; tambahnya</p>\n\n<p>Acara diakhiri dengan tukar-menukar cinderamata dari Humas Pemkot Kota Bekasi dengan DPRD Nias Utara. Kota Bekasi juga memberikan oleh-oleh Khas Bekasi berupa bingkisan Mpo Ninik yang berisi Bir Pletok, Kue Akar Kelapa dan Kembang Goyang serta Dodol Khas Betawi. (gie). &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-20 08:58:00', '2017-04-20 08:58:00', NULL),
('eb3d182d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', ' Wali Kota Bekasi DR.Rahmat Effendi Lakukan Sidak Titik Investasi Di Kota Bekasi', 'wali-kota-bekasi-dr-rahmat-effendi-lakukan-sidak-titik-investasi-di-kota-bekasi', 'Kota Bekasi- Pemerintah Kota Bekasi akan mengevaluasi perizinan baik yang sudah diterbitkan maupun yang belum hal ini disampaikan oleh Wali Kota Bekasi DR.Rahmat Effendi pada saat melaksanakan Inspeks', '<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Kota Bekasi- Pemerintah Kota Bekasi akan mengevaluasi perizinan baik yang sudah diterbitkan maupun yang belum hal ini disampaikan oleh Wali Kota Bekasi DR.Rahmat Effendi pada saat melaksanakan Inspeksi Mendadak (Sidak) disejumlah titik investasi di Kota Bekasi, Kamis, 20/4.</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Sidak yang dilakukan ini adalah bentuk kewajiban pemerintah terhadap pengakkan aturan yang ada yang dampak dari rekomendasi tersebut langsung dirasakan oleh masyarakat.</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&quot; Evaluasi bukan berarti kita main saklek - saklekan tetapi kita tetap harus melakukan law enforcement yang dikaji dari aspek teknisnya, amdalnya, banjirnya jika bangun ditempat tersebut ada dampak nya tidak ke masyarakat, &quot; Jelasnya.</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Ia menuturkan perizinan diterbitkan pada saat tata ruang dan detail nya sudah ada, jika ada masyarakat yang tidak setuju atau menolak apa yang telah diterbitkan oleh pemerintah silahkan ke Pengadilan Tata Usaha Negara .</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Orang berinvestasi, Ia menambahkan, memerlukan jaminan hukum pada saat mereka menanamkan uangnya disini diperlukan jaminan sehingga tidak berimplikasi negative terhadap image kota bekasi.</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">2.6 juta apa bila ada implikasi image rush yang tidak baik itu implikasi sosialnya sangat luar biasa,&quot; kestabilan ekonomi harus dijaga,&quot; pungkasnya. Apabila jaminan hukum dan kepastian nya dapat dipertanggung jawabkan, otomatis ekonomi naik, lapangan pekerjaan terbuka lebar.</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">&nbsp;</div>\n\n<div  rgb(34, 34, 34); font-family: arial, sans-serif; font-size: 12.8px;\">Di akhir sidak Wali Kota Bekasi mengatakan, haruslah ada penegakan hukum yang jelas jika tidak memenuhi rekomendasi cabut izinnya jika memenuhi haru lah diberikan penghargaan, &quot;kalau perlu kita akan lombakan ke tingkat nasional,&quot; pungkasnya. (tdy)</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-20 09:16:00', '2017-04-20 09:16:00', NULL),
('eb3d1880-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '                        Wawali Lakukan Silaturahim Dengan Pemuka Agama Kelurahan Jakasampurna', 'wawali-lakukan-silaturahim-dengan-pemuka-agama-kelurahan-jakasampurna', 'Kota Bekasi, -- Wakil Wali Kota Bekasi Ahmad Syaikhu melakukan Silaturahim dengan para Pemuka agama se- Kelurahan Jakasampurna Kecamatan Bekasi Barat bertempat di Rumah Makan Kenanga, Jakapermai, Beka', '<p>Kota Bekasi, -- Wakil Wali Kota Bekasi Ahmad Syaikhu melakukan Silaturahim dengan para Pemuka agama se- Kelurahan Jakasampurna Kecamatan Bekasi Barat bertempat di Rumah Makan Kenanga, Jakapermai, Bekasi, Kamis (20/4) siang.</p>\n\n<p>Hadir pada kegiatan ini Lurah Jakasampurna Nurdin, S.Sos beserta jajarannya serta para ketua DKM dan pimpinan rumah ibadah se-Kelurahan Jakasamurna Kecamatan Bekasi Barat Kota Bekasi.</p>\n\n<p>Dalam sambutannya beliau mengatakan Visi Misi Kota Bekasi Maju, Sejahtera dan Ihsan terlihat pada kemajuan Kota Bekasi dari sisi fisik dari pembangunan, kesejahteraan dilihat dari adanya peningkatan penghasilan, roda ekonomi berjalan karena investasi berjalan, serta terwujudnya suasanan yang ihsan dan harmonis ditengah kehidupan.</p>\n\n<p>Forum Umat Beragama dibentuk dalam rangka untuk sarana komunikasi, kita ingin dalam penataan kehidupan beragama terus melakukan komunikasi, diantaranya dengan melakukan banyak silahturahim antar umat beragama ujarnya.</p>\n\n<p>\"Silahturahim juga dapat dikemas dalam suasana-suasana yang santai, jangan nantinya masuk kedalam suasana formal keagaman, seperti peringatan Hari Raya Idhul Fitri atau Peringatan Perayaan Natal karena nantinya akan mengganggu keyakinan yang satu dengan yang lain, kita tidak ingin masuk kedalam ranah yang sudah menjadi ranahnya keagaman masing-masing, biarlah dikemas sendiri-sendiri, mungkin di Agama Islam sudah menegaskan “Lakum dinukum Waliyadin”\" tambahnya.</p>\n\n<p>:Bahwa kaitan keyakinan keagamaan silahkan masing-masing tetapi bukan berarti ketika kita sudah menganut suatu agama, kita jadi tertutup untuk semuanya, kita masih saling berhubungan dan berkomunikasi menjalin ekonomi, ini yang harus kita kembangkan dibandingkan sisi seremonial keagamaan kita\" ungkapnya</p>\n\n<p>Sehingga, tambahnya kita akan saling mengenal dan saling berusaha menyelesaiakan persoalan-persoalan ekonomi, lingkungan dan sosial yang sesungguhnya kegiatan ini merupakan ruang lingkup kita yang bernilai ibadah di agama kita masing-masing. Ini semua usaha untuk membangun suasana tasa’mu, toleransi dan kebersamaan yang bisa dikembangkan.</p>\n\n<p>Pada kesempatan ini Wakil Wali Kota menyampaikan juga dalam hal penataan banjir pemerintah sudah mencoba hal-hal yang struktural misalnya pembuatan penanggulan, normalisasi atau infrastruktur pengerasan jalan dan sebagainya.</p>\n\n<p>\"Namun warga juga dapat melakukan hal-hal yang bersifat non struktural dengan membuat sumur resapan untuk mendukung kebijakan pemerintah kota “zero run off” yaitu tidak ada aliran air yang keluar bangunan, sehingga air dari rumah tidak langsung ke saluran air akan tetapi akan masuk ke tampungan air melalui sumur resapan\" uangkapnya.</p>\n\n<p>\"Sekali lagi saya ingatkan peran rumah ibadah juga penting dalam masalah lingkungan untuk menyampaikan kepada jama’ahnya masing-masing, sehingga banyak jama’ah yang tersadarkan bahwa itu adalah pesan religius untuk menjaga lingkunganmaka saya yakin konsep “zero run off” atau program lainnya akan mudah si sosialisasikan\" Imbuhnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-20 14:11:00', '2017-04-20 14:11:00', NULL),
('eb3d18d0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Lakukan Sosialisasi Pembinaan Kualitas Perumahan Pemukiman Bagi Warga Jatimekar', 'wawali-lakukan-sosialisasi-pembinaan-kualitas-perumahan-pemukiman-bagi-warga-jatimekar', 'Kota Bekasi, --- Wakil Walikota Bekasi melakukan Sosialisasi Pembinaan Kualitas Perumahan Permukiman di Kota Bekasi yang dilaksanakan oleh Dinas Permukiman, Pemukiman dan Pertanahan Kota Bekasi bertem', '<p>Kota Bekasi, --- Wakil Walikota Bekasi melakukan Sosialisasi Pembinaan Kualitas Perumahan Permukiman di Kota Bekasi yang dilaksanakan oleh Dinas Permukiman, Pemukiman dan Pertanahan Kota Bekasi bertempat di Aula Kelurahan Jatimekar Kecamatan Jatiasih, Kamis (20/4).</p>\n\n<p>Hadir pada kegiatan ini, Kepala Bidang Imas Asiah Dinas Perkimtan, Lurah Jatimekar Abdul Rohim, SE dan jajarannya, RT, RW, Karang Taruna, LPM, Kader PKK dan Tokoh Masyarakat di Kelurahan Jati Mekar Kecamatan Jatiasih Kota Bekasi.</p>\n\n<p>Dalam sambutannya Wawali Syaikhu Ahmad mengatakan sosialisasi ini sangat penting karena ini diperlukan agar kita merasa saling memiliki, kalau kita sudah sama-sama memiliki bahwa ini adalah pemukiman kita tentu bila ada kendala-kendala maka kita &nbsp;akan coba untuk menyelesaikannya bersama.</p>\n\n<p>&ldquo;Misalnya ada orang yang beringinan membangun, tetapi kemampuan orang untuk membangun tidak ada, kalau diinformasikan dan dengan kebersamaan kemudian kita bisa urunan untuk membantu membangun tetangganya ini adalah sikap gotong royong yang merupakan budaya kita di negeri ini&rdquo; ujarnya</p>\n\n<p>&ldquo;Tetapi bila memang tidak memungkinkan untuk membangun sendiri maka kewajiban pemerintah untuk melakukan penataan pemukiman, sehingga program-program yang lahir seperti Rutilahu dapat menjadi solusi untuk memberikan bantuan kepada masyarakat&rdquo; tambahnya</p>\n\n<p>Beliau juga menyampaikan bahwa cita-cita kami pemerintah kota adalah melakukan upaya penataan kota, dengan mulai berbenah di kawasan-kawan pusat perkotaannya seperti di Jalan Ahmad Yani, Jalan KH. Noer Ali terus menjalar sampai dengan permasalahan-permasalahan sekitar perkotaan ini termasuk sampai dengan kelurahan-kelurahandapat terselesaikan.</p>\n\n<p>Selain pemukiman, tambahnya dalam Penanggulangan banjir ternyata Pemkot Bekasi sudah mempunyai success story yang harus piloting (dicontoh) seperti penanggulangan baniir di Aren Jaya yang dapat tertangani dan hampir &nbsp;tidak ada saran dan keluhan dari Aren Jaya, padahal sebelumnya hujan sedikit 1 &ndash; 2 jam saja Aren Jaya yang kebanjiran.</p>\n\n<p>&ldquo;Drainase perkotaannya di wilayah Aren Jaya sudah bagus, tertata sedemikian rupa dengan standarisasi dari ujung ke ujung dengan menggunakan dusaspun, air mengalir sedemikian lancar dan adanya tendon air di aren jaya yang lebih memungkinkan untuk daya tampung air, Ini juga juga dapat dijadikan percontohan bagaimana upaya untuk menanggulangi banjir pada daerah-daerah yang lain&rdquo; ujarnya.</p>\n\n<p>&ldquo;Seperti di Kelurahan Jatimekar ini masih ada titik-titk banjir, dimana daerah-daerah yang banjir dahulunya merupakan pusaran air, namun bila penataan air kita baik maka hal itu bisa kita atasi, memang ada solusi lain seperti melakukan relokasi tetapi relokasi ini bukan tanpa masalah, seperti bagaimana orang mau direlokasi jika sudah tinggal sejak nenek moyangnya. Maka Solusi lain adalah bagaimana manajemen air bisa berjalan dengan baik, sehingga bisa dikelola dan tidak menimbulkan dampak seperti sekarang ini.&rdquo; Tambahnya.</p>\n\n<p>Pada akhir sambutannya beliau menegaskan bahwa kuncinya adalah kebersamaan karena rasa kepemilikan terhadap kota kita, saya yakin kalau kita memiliki rasa kepemilikan bahwa inilah kota kita, inilah milik kita maka kita akan bersama-sama menyelesaikan permasalahan kota, tidak hanya pemerintah saja tapi seluruh warganya akan sama-sama membangun dan menciptakan lingkungan yang lebih baik dan lebih asri. (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-20 22:27:00', '2017-04-20 22:27:00', NULL),
('eb3d1920-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pemkot Bekasi Rencanakan Beri Penghargaan Bagi Investor yang Patuh Terhadap Aturan', 'pemkot-bekasi-rencanakan-beri-penghargaan-bagi-investor-yang-patuh-terhadap-aturan', 'Kota Bekasi- Pertumbuhan ekonomi Kota Bekasi yang meningkat sebanyak 300% dari tahun 1999-2017 memacu Pemerintah kota Bekasi untuk terus menegakkan peraturan yang berlaku untuk menjaga stabilitas ekon', '<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28459\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Kota Bekasi- Pertumbuhan ekonomi Kota Bekasi yang meningkat sebanyak 300% dari tahun 1999-2017 memacu Pemerintah kota Bekasi untuk terus menegakkan peraturan yang berlaku untuk menjaga stabilitas ekonomi dan ketentraman dan kenyamanan bagi seluruh masyarakat Kota Bekasi.</div>\n\n<div dir=\"ltr\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28460\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Berbagai macam problematika kota&nbsp; metropolitan menjadi pekerjaan rumah yang harus segera diselesaikan secara berkesinambungan tetapi tidak dengan cara instan, hal ini diungkap kan oleh Wali Kota Bekasi DR. Rahmat Effendi pada saat melaksanakan Sidak di Apartemen Grand Kamala Lagoon, Jum&#39;at, 21/4.</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28461\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28462\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Sidak Analisis Dampak Lingkungan (Andal) dilakukan langsung oleh Wali Kota Bekasi untuk melihat sejauh mana kepatuhan para investor atas rekomendasi yang telah diberikan oleh Pemerintah Daerah.</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28463\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28464\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&quot; jadi kota ini maju dan nilai ekonominya tinggi diatas standar nasional tingkat inflasinya rendah semua karna adanya nilai investasi para investor yang menanamkan dana ke kota bekasi, karena kota bekasi tidak mengandalkan apa apa, selain dari perdangangan, jasa dan pajak&quot;, ucap nya.</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28465\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28466\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Tetapi, tambahnya, pembangunan yang dilakukan harus lah beriringan dengan rekomendasi yang kita berikan untuk tidak menimbulkan dampak bagi masyarakat sekitar yang terdahulu mendiami sebelum pembangunan dimulai.</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28467\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28472\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&quot; Oleh sebab itu saya mengecek langsung sejauh mana kepatuhan pengembang terhadap rekomendasi kita, kalo dilaksanakan secara baik akan kita beri penghargaan tetapi jika tidak akan kita beri sangsi sesuai dengan peraturan yang berlaku&quot;, tegasnya.</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28471\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"yui_3_16_0_ym19_1_1492780254116_28470\"  0px; color: rgb(0, 0, 0); font-family: \"Helvetica Neue\", \"Segoe UI\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">Ia menjelaskan perlu di ingatkan kepada pengembang bahwa ada peraturan yang mengikat tentang amdal yaitu denda sebesar 5 miliar rupiah dan kurungan selama dua tahun.</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-21 14:59:00', '2017-04-21 14:59:00', NULL),
('eb3d1975-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ingatkan Kebersamaan Dan Berbuat Baik Kepada Semua', 'wawali-ingatkan-kebersamaan-dan-berbuat-baik-kepada-semua', 'Kota Bekasi, -- Wakil Walikota Bekasi Ahmad Syakhu menhadiri pengajian rutin Majelis Ta&rsquo;lim Al-Istiqomah Dinas Penenaman Modal Pelayanan Terpadu Satu Pintu Kota Bekasi di Gedung Patriot Kantor W', '<p>Kota Bekasi, -- Wakil Walikota Bekasi Ahmad Syakhu menhadiri pengajian rutin Majelis Ta&rsquo;lim Al-Istiqomah Dinas Penenaman Modal Pelayanan Terpadu Satu Pintu Kota Bekasi di Gedung Patriot Kantor Walikota Bekasi Jl. Jend. A. Yani No. 1 Bekasi, Jum&rsquo;at (21/4) pagi.</p>\n\n<p>Dalam &nbsp;tausiahnya Wakil Walikota Bekasi mengatakan tujuan kita semua pasti menginginkan kebahagiaan tapi bukan hanya sesaat atau kebahagiaan duniawi tetapi kita sebagai seorang muslim meyakini betul akan adanya dunia akhirat dan kita ingin kebahagiaan diduania sampai ke kehidupan akhirat, sukses di dunia dan sukses diakhirat.</p>\n\n<p>Allah SWT telah memberikan tuntunan kepada kita, kalau kita mau sukses di dunia ini pada Surat Al-Haj Ayat 77, kunci yang pertama adalah kedekatan kita kepada Allah SWT sang Khalik, maka perintahnya adalah Hai orang-orang yang beriman ruku&rsquo; lah kamu bersama-sama, sujud bersama-sama, abdikan diri kamu bersama-sama, ini dalam sebuah &nbsp;kerangka kebersamaa, karena dengan bersama-sama akan lebih besar pahalanya.</p>\n\n<p>Kerangka kebersamaan inilah yang harus kita kemas dan bila di implementasikan dalam kehidupan kita, bersosial, bermasyarakat dan bernegara maka sikap kebersamaan inilah yang harus dibangun, karena tidak ada yang namanya sukses pribadi kalau ada atasan tanpa ada bawahan tidak mungkin akan sukses.</p>\n\n<p>Kesempurnaan dapat diraih ketika kita saling topang, saling bantu dan saling tolong menolong dalam kebersamaan sehingga menjadi spirit kita untuk memberikan pelayanan secara bersama-sama maka DPMPST akan menjadi tim work yang betul-betul solid, yang hebat dan dapat menyelesaikan berbagai permasalahan-permasalahan sepelik apapun.</p>\n\n<p>Jadi dalam sebuah kerangka kebersamaan dengan mendekatkan diri kita kepada sang pencipta kita Allah SWT inilah yang kita sadarkan bersama.</p>\n\n<p>Kunci kedua berbuat baik kepada orang-orang disekitar kita, kepada keluarga kita, tetangga kita, teman sejawat dan kepada masyarakat bahkan bukan hanya berbuat baik kepada orang-orang saja tetapi kepada makhluk-makhluk yang lain, kepada alam semesta , terhadap lingkungan.</p>\n\n<p>Sangat luar biasa ketika kita mengimplementasikan, bagaimana kita memberikan pelayanan terbaik apa yang kita punya kepada masyarakat sehingga inilah yang disebut dengan pelayanan prima.</p>\n\n<p>Contoh implementasinya seperti yang disabdakan Nabi Muhammad SAW adalah memberikan mengucapkan salam diantara kita, memberikan makanan apa yang kita punya dan menjalin silahturahim serta sholatlah dimalam hari ketika orang banyak yang tertidur nyenyak.</p>\n\n<p>Empat point inilah yang harus kita camkan untuk dapat memberikan pelayanan terbaik kepada masyarakat, dan ini akan menjadi kontribusi kita untuk mendapatkan pahala disisi Allah SWT, serta mari kita sama-sama bersambut mewujudkan satu DPMPST yang solid, yang memberikan pelayanan terbaik bagi masyarakat Kota Bekasi. (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-22 00:43:00', '2017-04-22 00:43:00', NULL),
('eb3d19c7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Harapkan Masjid Sebagai Pusat Pergerakan Nilai-Nilai Religiutas', 'wawali-harapkan-masjid-sebagai-pusat-pergerakan-nilai-nilai-religiutas', 'Kota Bekasi, &nbsp;-- Wakil Wali Kota Bekasi Ahmad Syaikhu melakukan kegiatan Jum&rsquo;at Keliling (Jumling) dan Peletakan Batu Pertama pembanguan perluasan Masjid Jami Al-Awwabin Kp. Bojongsari Rt 0', '<p>Kota Bekasi, &nbsp;-- Wakil Wali Kota Bekasi Ahmad Syaikhu melakukan kegiatan Jum&rsquo;at Keliling (Jumling) dan Peletakan Batu Pertama pembanguan perluasan Masjid Jami Al-Awwabin Kp. Bojongsari Rt 04/01 Kelurahan Jatisari Kecamatan Jatiasih Kota Bekasi, Jum&rsquo;at (21/4) siang.</p>\n\n<p>Hadir pada kegiatan tersebut pejabat eselon dua, tiga dan empat dilingkungan Pemerintah Kota Bekasi, Camat Jatiasih dan Lurah se-Kecamatan Jatiasih dan jajarannya serta tokoh masyarakat Jati Asih Kota Bekasi.</p>\n\n<p>Dalam sambutannya Wakil Wali Kota menyampaikan bahwa kegiatan Jum&rsquo;at Keliling dilaksanakan satu bulan dua kali, bergantian dengan Pak Wali Kota dengan harapan berbagai hal-hal yang ada, persoalan-persoalan yang ada dapat langsung dikomunikasikan dan diselesaikan karena semua SKPD hadir di kegiatan ini.</p>\n\n<p>&quot;Saya sangat apresiasi masjid ini karena makmur, sehingga perlu menambah tempat untuk menampung jama&rsquo;ah, sehingga masjid ini akan menjadi pusat pembelajaran juga dapat menjadi pusat untuk menggerakkan masyakat dengan nilai-nilai religiusitas&quot; ungkapnya.</p>\n\n<p>&quot;Masjid ini juga dekat dengan SMKN 7, saya titip anak-anak untuk dapat dibimbing dan dilibatkan dalam kegiatan masjid seperti kegiatan keagamaan dan Tilawah Qur&rsquo;an, karena ini sebagai upaya kita membentengi anak-anak kita dari hal-hal negatif&quot; ujarnya</p>\n\n<p>&quot;Kalau masjid-masjidnya nyaman, makmur Insya Allah anak-anak akan betah diberada disini, kumpul-kumpul di sini dan tentunya yang dibicarakan adalah kebaikan, karena Allah SWT menjamin bahwa di masjid akan ada orang-orang yang senatiasa cinta, senang kepada kesucian&quot; tambahnya</p>\n\n<p>&quot;Namun kalau anak kita kumpul dimasjid kita tidak khawatir, tetapi kalau anak-anak tidak kumpul disini kita was-was takut narkoba atau hal negatif lainnya. Kalau anak-anak muda kumpul di masjid, masjid akan bergairan dan makmur dan anka muda akan terlindungi dari hal-hal negative&quot; imbuhnya.</p>\n\n<p>Wakil Wali Kota mengatakan Pemerintah Kota akan mensupport pembangunan disebelah kiri masjid ini, dengan bantuan dana kurang lebih 100 juta rupiah dan mudah-mudahan dapat bermanfaat bagi jama&rsquo;ah masjid ini.</p>\n\n<p>Usai melakukan sholat Jum&rsquo;at Wakil Wali Kota Bekasi Ahmad Syaiku didampingi Kepala Bagian Kessos Ahmad Yani dan Camat Jatiasih Nesan Sujana, ST, MT, dan Ketua serta pengurus Masjid Jami Awwabin, meletakkan &nbsp;batu pertama pembangunan perluasan Masjid ini (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-22 00:47:00', '2017-04-22 00:47:00', NULL),
('eb3d1a18-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Walikota Pimpin Apel Persiapan Baksos Menyambut HUT Satpol PP ke 67 dan Satlinmas ke 55 Kota Bekasi', 'walikota-pimpin-apel-persiapan-baksos-menyambut-hut-satpol-pp-ke-67-dan-satlinmas-ke-55-kota-bekasi', 'Kota Bekasi, 22/04/2017. Dalam rangka menyambut HUT Satpol PP ke 67 dan Satlinmas ke 55 Kota Bekasi yang jatuh pada tanggal 26 April 2017, Satpol PP Kota Bekasi melaksanakan berbagai macam kegiatan di', '<p>Kota Bekasi, 22/04/2017. Dalam rangka menyambut HUT Satpol PP ke 67 dan Satlinmas ke 55 Kota Bekasi yang jatuh pada tanggal 26 April 2017, Satpol PP Kota Bekasi melaksanakan berbagai macam kegiatan diantaranya Bakti sosial seperti bersih-bersih di wilayah Kecamatan Jatiasih, serta pembagian sembako kepada warga yang ada di wilayah kecamatan jatiasih . Kegiatan yang berlangsung pada sabtu (22/04) itupun berlangsung meriah.</p>\n\n<p>&nbsp;<br />\nWali Kota Bekasi, Dr.Rahmat Effendi secara langsung memberi arahan pada apel persiapan pelaksanaan Baksos kepada ratusan anggota satpol PP dan Anggota Sat Linmas Kota Bekasi di halaman kantor Kecamatan Jatiasih. diikuti oleh ratusan anggota satpol PP dan Anggota Sat linmas Kota Bekasi bersama warga masyarakat sekitar kecamtan jatiasih.&nbsp;</p>\n\n<p>Dalam arahannya disampaikan beberapa hal tentang peran dari satpol PP dan Satlinmas Kota Bekasi, sebagai penegak peraturan daerah, para petugas Satpol PP serta Satlinmas harus senantiasa menjaga ketertiban serta mengayomi masyarakat dengan lugas dan tegas, ujarnya.&nbsp;</p>\n\n<p>Ditambahkan Wali Kota Bekasi, bahwa dirinya akan menaikan besaran Tungkir untuk satpol PP Kota Bekasi mencapai 65%, dimana sebelumnya sapol PP berstatus PNS&nbsp;<br />\nmendapatkan tungkir Rp. 1.5 juta dan untuk Satpol PP berstatus TKK mendapatkan tungkir Rp.1.2 juta. &quot; selasa depan usulan kenaikan tersebut harus sudah ada di meja saya&quot; tegas Wali Kota Bekasi. &nbsp;</p>\n\n<p>Kenaikan tunjangan ini sebanding dengan pola kerja yang satpol PP laksanakan sehari-hari, karena memliki resiko yang tinggi. Dengan kenaikan tunkir ini nantinya dapat memberi semangat kepada anggota satpol PP Kota Bekasi dalam menjalankan tugas. &ldquo; saya berharap Kehadiran kalian semua memberikan rasa bangga bagi Kota Bekasi&rdquo;, ungkapnya.</p>\n\n<p>Selain itu Wali Kota juga akan memberikan Kartu Sehat berbasis NIK kepada Anggota Satpol PP dan Sat Linmas Kota Bekasi, dimaana kartu tersebut dapat di gunakan utnuk kesehatan, pendidikan dan bantuan &nbsp;sosial.&nbsp;</p>\n\n<p>Terakhir Wali Kota berpesan agar satpol PP Kota Bekasi terus meningkatkan kerja keras dan pengabdiannya untuk mewujudkan Kota Bekasi yang maju, sejahtera dan ihsan.</p>\n\n<p>Sementara itu, Salah satu anggota Satpol PP Kota Bekasi, Pahala Sihombing, mengatakan bahwa kegiatan ini dilakukan untuk memberikan motivasi dalam rangka memupuk kebersamaan dan solidaritas dilingkup Satpol PP Kota Bekasi.</p>\n\n<p>&quot;Kebersamaan yang ada selama ini sudah baik dalam menunjang pelaksaan tugas selama ini, namun harus terus ditumbuh<br />\n&nbsp;kembangkan sesuai dengan arahan bapak Walikota Bekasi yang menginginkan agar solidaritas terus ditingkatkan ,pungkasnya. (yas).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-22 03:57:00', '2017-04-22 03:57:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d1a67-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Lakukan Suling Di Masjid Daarul Muttaqien Bekasi Barat', 'wawali-lakukan-suling-di-masjid-daarul-muttaqien-bekasi-barat', 'Bekasi, Wakil Walikota Bekasi Ahmad Syaikhu melakukan kegiatan Subuh Keliling (Suling) di Masjid Daarul Muttaqien Perum Harapan Baru, Jl. Taman Oscar Raya, &nbsp;Kelurahan Kota Baru Kecamatan Bekasi B', '<p>Bekasi, Wakil Walikota Bekasi Ahmad Syaikhu melakukan kegiatan Subuh Keliling (Suling) di Masjid Daarul Muttaqien Perum Harapan Baru, Jl. Taman Oscar Raya, &nbsp;Kelurahan Kota Baru Kecamatan Bekasi Barat Kota Bekasi, Sabtu (22/4) pagi.</p>\r\n\r\n<p>Hadir pula para kepala SKPD di lingkungan Pemerintah Kota Bekasi, perwakilan dari Kodim 0507, perwakilan Polres Metro Bekasi Kota, Ketua dan Pengurus DKMI Kota Bekasi, Camat Bekasi &nbsp;Bunyamin dan seluruh jajarannya, Ketua Baznas Kota Bekasi, serta Tokoh Masyarakat dilingkungan Kecamatan Bekasi Barat.</p>\r\n\r\n<p>Dalam sambutan dan tausiahnya Wakil Waikota Bekasi mengatakan kita pautu bersyukur karena dapat mengawali kegiatan kita dengan kebaikan, yaitu dengan melakukan subuh keliling berjama&rsquo;ah.</p>\r\n\r\n<p>&ldquo;Seharusnya kegiatan-kegiatan seperti sudah seharusnya dilaksanakan, karena visi Kota Bekasi yang ingin menjadikan Kota yang Ihsan, yaitu kota dengan nilai-nilai religiusitas yang tumbuh dan hidup subur di tengah masyarakat.&rdquo; Ujarnya</p>\r\n\r\n<p>&ldquo;Masyarakat dengan semangat keagamaannya tinggi, bukan hanya ditandai dengan masjid-masjid yang bagus dan indah, tetapi masjid itu juga sedemikian makmur dan banyak jama&rsquo;ahnya karena dari masjid yang makmur itulah akan banyak orang-orang yang cinta akan kesucian&rdquo; tambahnya</p>\r\n\r\n<p>&ldquo;Jadi kalau ada anak-anak muda yang kumpul dimasjid tentunya tidak mungkin ada yang mengkonsumsi narkoba atau orang-oarang tua yang kumpul di masjid akan minum-minuman keras karena Allah SWT menjamin bahwa di masjid akan ada orang-orang yang senatiasa cinta, senang kepada kesucian&rdquo; imbuhny.</p>\r\n\r\n<p>&ldquo;Kalau masjidnya makmur seperti ini maka secara kolektif akan muncul masyarakat-masyarakat yang bertaqwa dan berkarakter, sesuai dengan nama masjidnya Daarul Muttaqien sehingga orang-orang yang keluar dari sini akan membawa nilai ketaqwaan yang akan dibawa bekerja, ketika dikantor, ketika di pasat sehingga nilai-nilai keagamaan seperti sifat jujur aka nada dimana-mana&rdquo; ungkapnya.</p>\r\n\r\n<p>&ldquo;Subuh Keliling dan Jum&rsquo;at Keliling ini merupakan pendorong karena kita ingin masjid-masjid menjadi makmur dan banyak jama&rsquo;ahnya sehingga mendorong untuk terbiasa ke masjid melaksanakan sholat berjama&rsquo;ah tidak hanya itu pertolongan Allah SWT pun akan datang untuk membantu permasalahan-permasalahan yang kita hadapi&rdquo; ujarnya</p>\r\n\r\n<p>&ldquo;Seperti Negara Turki bisa maju karena setelah diteliti disana menggalakkan sholat subuh berjama&rsquo;ah, gambaran Inilah &nbsp;sesungguhnya nilai-nilai religiusitas akan mendorong umatnya memiliki etos kerja yang tinggi dan seharusnya tumbuh di dalam diri kita semuanya&rdquo; imbuhnya</p>\r\n\r\n<p>Di akhir sambutannya beliau menampaikan terkait dengan Baznas ini saya dan Wali Kota ingin aparatur dilingkungan Pemerintah Kota Bekasi terus melakukan peningkatan insentif dan tunjangan daerah sehingga baznas akan mendapatkan zakat dari para pejabat dan pegawai dan dapat di gunakan untuk aktifitas seperti bantuan pemabangunan masjid, kaum dhuafa &nbsp;sampai perhatian kepada para guru-guru yang mengajar diluar pemerintah. (gie)</p>', 'images/20170823073819-2017-08-23post073818.jpg', NULL, NULL, 1663, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-22 03:59:00', '2017-04-22 03:59:00', NULL),
('eb3d1abe-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Lakukan Suling Di Masjid Daarul Muttaqien Bekasi Barat', 'wawali-lakukan-suling-di-masjid-daarul-muttaqien-bekasi-barat-2', 'Kota Bekasi, -- Wakil Walikota Bekasi Ahmad Syaikhu melakukan kegiatan Subuh Keliling (Suling) di Masjid Daarul Muttaqien Perum Harapan Baru, Jl. Taman Oscar Raya, &nbsp;Kelurahan Kota Baru Kecamatan ', '<p>Kota Bekasi, -- Wakil Walikota Bekasi Ahmad Syaikhu melakukan kegiatan Subuh Keliling (Suling) di Masjid Daarul Muttaqien Perum Harapan Baru, Jl. Taman Oscar Raya, &nbsp;Kelurahan Kota Baru Kecamatan Bekasi Barat Kota Bekasi, Sabtu (22/4) pagi.</p>\n\n<p>Hadir pula para kepala SKPD di lingkungan Pemerintah Kota Bekasi, perwakilan dari Kodim 0507, perwakilan Polres Metro Bekasi Kota, Ketua dan Pengurus DKMI Kota Bekasi, Camat Bekasi &nbsp;Bunyamin dan seluruh jajarannya, Ketua Baznas Kota Bekasi, serta Tokoh Masyarakat dilingkungan Kecamatan Bekasi Barat.</p>\n\n<p>Dalam sambutan dan tausiahnya Wakil Waikota Bekasi mengatakan kita pautu bersyukur karena dapat mengawali kegiatan kita dengan kebaikan, yaitu dengan melakukan subuh keliling berjama&rsquo;ah.</p>\n\n<p>&ldquo;Seharusnya kegiatan-kegiatan seperti sudah seharusnya dilaksanakan, karena visi Kota Bekasi yang ingin menjadikan Kota yang Ihsan, yaitu kota dengan nilai-nilai religiusitas yang tumbuh dan hidup subur di tengah masyarakat.&rdquo; Ujarnya</p>\n\n<p>&ldquo;Masyarakat dengan semangat keagamaannya tinggi, bukan hanya ditandai dengan masjid-masjid yang bagus dan indah, tetapi masjid itu juga sedemikian makmur dan banyak jama&rsquo;ahnya karena dari masjid yang makmur itulah akan banyak orang-orang yang cinta akan kesucian&rdquo; tambahnya</p>\n\n<p>&ldquo;Jadi kalau ada anak-anak muda yang kumpul dimasjid tentunya tidak mungkin ada yang mengkonsumsi narkoba atau orang-oarang tua yang kumpul di masjid akan minum-minuman keras karena Allah SWT menjamin bahwa di masjid akan ada orang-orang yang senatiasa cinta, senang kepada kesucian&rdquo; imbuhny.</p>\n\n<p>&ldquo;Kalau masjidnya makmur seperti ini maka secara kolektif akan muncul masyarakat-masyarakat yang bertaqwa dan berkarakter, sesuai dengan nama masjidnya Daarul Muttaqien sehingga orang-orang yang keluar dari sini akan membawa nilai ketaqwaan yang akan dibawa bekerja, ketika dikantor, ketika di pasat sehingga nilai-nilai keagamaan seperti sifat jujur aka nada dimana-mana&rdquo; ungkapnya.</p>\n\n<p>&ldquo;Subuh Keliling dan Jum&rsquo;at Keliling ini merupakan pendorong karena kita ingin masjid-masjid menjadi makmur dan banyak jama&rsquo;ahnya sehingga mendorong untuk terbiasa ke masjid melaksanakan sholat berjama&rsquo;ah tidak hanya itu pertolongan Allah SWT pun akan datang untuk membantu permasalahan-permasalahan yang kita hadapi&rdquo; ujarnya</p>\n\n<p>&ldquo;Seperti Negara Turki bisa maju karena setelah diteliti disana menggalakkan sholat subuh berjama&rsquo;ah, gambaran Inilah &nbsp;sesungguhnya nilai-nilai religiusitas akan mendorong umatnya memiliki etos kerja yang tinggi dan seharusnya tumbuh di dalam diri kita semuanya&rdquo; imbuhnya</p>\n\n<p>Di akhir sambutannya beliau menampaikan terkait dengan Baznas ini saya dan Wali Kota ingin aparatur dilingkungan Pemerintah Kota Bekasi terus melakukan peningkatan insentif dan tunjangan daerah sehingga baznas akan mendapatkan zakat dari para pejabat dan pegawai dan dapat di gunakan untuk aktifitas seperti bantuan pemabangunan masjid, kaum dhuafa &nbsp;sampai perhatian kepada para guru-guru yang mengajar diluar pemerintah. (gie)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-22 04:03:00', '2017-04-22 04:03:00', NULL),
('eb3d1b10-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ajak Bersama-sama Siapkan Generasi Untuk Masa Depan', 'wawali-ajak-bersama-sama-siapkan-generasi-untuk-masa-depan', 'Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri Open House dan 11 th Anniversary Of Al-Firdaus Integrated Islam Schol Jl. Duta Boulevard Barat Blok B1 No.20, Kelurahan Harapan Baru Kecamatan B', '<p>Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri Open House dan 11 th Anniversary Of Al-Firdaus Integrated Islam Schol Jl. Duta Boulevard Barat Blok B1 No.20, Kelurahan Harapan Baru Kecamatan Bekasi Utara, Sabtu (22/4) siang.</p>\r\n\r\n<p>Dalam sambutannya belaiu menyampaikan rasa bangganya bisa hadir di Al-Firdaus Islami School dan terhadap prestasi sekolah ini yang telah diraih sampai tingkat nasional &nbsp;karena meraih prestasi bukan perkara yang mudah, tidak seperti membalikkan telapak tangan.</p>\r\n\r\n<p>&ldquo;Saya bersama Wali Kota juga pernah merasakan ketika beberapa tahun yang lalu Kota Bekasi pernah di Bully. Karena macet, panas ,alah ada yang berlebihan sampai dipeta &nbsp;tidak ada katanya, tapi dengan kebersamaan dan berbagai usaha-usaha yang serius untuk melakukan hal itu akhirnya, kita dapat melihat berbagai perubahan-perubahan yang sekarang ini justru menjadi kebanggaan kita&rdquo; ujarnya</p>\r\n\r\n<p>&ldquo;Prestasi demi prestasi diraih, bukan hanya pada tingkat regional Jawa Barat, tingkat nasional bahkan sampai diakui sampai tingkat Internasional, karena belaum lama ini &nbsp;saya menerima penghargaan Open Gov Asia terkait apresiasi penerapan Smart City di Kota Bekasi&rdquo; tambanhnya</p>\r\n\r\n<p>&ldquo;Jadi kalau ada adik-adik yang di olok-olok jangan menjadi minder atau putus asa kalau saya, prinsipnya seperti pantun &ldquo;nasi kembuli sangatlah nikmat, walaupun di bully tetap semangat&rdquo; ujarnya</p>\r\n\r\n<p>&ldquo;Selain itu, berkat kebersamaan seluruh elemen masyarakat, yang dulunya Kota Bekasi di bully sekarang ini menjadi &ldquo;BEKASI&rdquo; kepanjangan dari &ldquo;Bersama-sama Kita Meraih Prestasi&rdquo;, ini yang kemudian Kota Bekasi mendapat berbagai prestasi membanggakan&rdquo; ungkapnya</p>\r\n\r\n<p>&ldquo;Selain itu juga sudah banyak event-event internasional yang diselenggarakan di Kota Bekasi seperti One Day One Juz (ODOJ) yang mendatangkan hafiz dari lima benua dan kemarin terakhir ada event ceramah umum dzakir naik&rdquo; imbuhnya</p>\r\n\r\n<p>Wakil Walikota juga meyakini bahwa prestasi yang diraih anak-anak kita berkat kebersamaan dari semua pihak, bukan hanya semangat anak-anak saja, tapi juga ada pembekalan dari bapak ibu gurunya serta upaya kondusifitas dari pihak sekolah, komite dan pihak pengawas serta yang tidak kalah penting adalah pihak orang tua</p>\r\n\r\n<p>Beliau juga mengatakan upaya membangun kebersamaan di sekolah ini harus dilanjutkan terus dan juga di tumbuh kembangkan karena memang ini akan menjadi kata kunci, segala hal yang terasa berat untuk perorangan akan menjadi ringan bila dilakukan bersama-sama.</p>\r\n\r\n<p>Pak Ustadz panggilan akrabnya, &nbsp;juga menyampaikan anak-anak yang kita lahirkan dan anak-anak yang di Kota Bekasi menjadi tanggung jawab kita bersama, selain itu juga menjadi tanggung jawab saya, Wali Kota dan Pememrintah Kota untuk membekali mereka dengan hal-hal yang signifikan.</p>\r\n\r\n<p>&ldquo;Mengapa karena mereka adalah generasi penerus yang akan menyongsong masa depan, dan kita tau bahwa negeri ini sedang diberikan bonus demograsi dimana usia-usia produktif 15-35 tahun lebih banyak dari usia tidak produktif&rdquo; ujarnya</p>\r\n\r\n<p>&ldquo;Dan ini adalah sebuah keberkahan yang Allah SWT berikan kepada kita, dan nantinya negara yang maju adalah negara yang dapat menfaatkan bonus demografi sehingga SDMnya unggul karena dipersiapkan untuk menyongsong masa depan&rdquo; tambahnya.</p>\r\n\r\n<p>&ldquo;Yang kita takutkan adalah kalau kita tidak tidak mempersiapkan ana-anak kita dan membiarkan terbengkalai dengan pendidikannya, maka bonus demograsi tidak akan menjadi keberkahan tapi yang terjadi justru bencana kemanusiaan, jumlahnya banyak tapi tidak berkualitas dan akhirnya kita hanya jadi penonton di negeri kitta sendiri&rdquo; pungkasnya</p>\r\n\r\n<p>Pada akhir sambutannya beliau menyampaikan bahwa kedepan kita harus betul-betul mempersiapkan bersama-sama, bagaimana anak-anak dilahirkan oleh kita, anak-anak yang tinggal di Bekasi dibekali sesempurna mungkin sehingga anak-anak kita mampu menyongsong masa depannya menjadi lebih baik lagi.(gie)</p>', 'images/20170823073759-2017-08-23post073758.jpg', NULL, NULL, 1013, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-24 08:59:00', '2017-04-24 08:59:00', NULL),
('eb3d1b60-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Resmikan Islamic Center Masjid Al-Wafa Jati Cempaka', 'wawali-resmikan-islamic-center-masjid-al-wafa-jati-cempaka', 'Bekasi, Usai melakukan kegiatan Car Free Day, Wakil Wali Kota Bekasi melanjutkan kegiatannya dengan meresmikan Ismalic Center Masjid Al-Wafa Jl. Setia I, Kelurahan Jati Cempaka Kecamatan Pondok Gede, ', '<p>Bekasi, Usai melakukan kegiatan Car Free Day, Wakil Wali Kota Bekasi melanjutkan kegiatannya dengan meresmikan Ismalic Center Masjid Al-Wafa Jl. Setia I, Kelurahan Jati Cempaka Kecamatan Pondok Gede, Minggu (23/4).</p>\r\n\r\n<p>Hadir pada kegiatan ini Forum Komunikasi Pimpinan Daerah Kota Bekasi, Ketua PB MUhammadiyah Kota Bekasi Soekandar Ghazali, Wakil Ketua PBNU Kota Bekasi, Ketua MUI Kecamatan Pondok Gede, Camat Pondok Gede H. Mardani, SE, M.Si dan Lurah serta tokoh masyarakat se-Kecamatan Pondok Gede.</p>\r\n\r\n<p>Wakil Wali Kota Bekasi dalam sambutannya mengatakan bahwa sesuai dengan nama Masjidnya Al-Wafa tentunya masjid ini akan membawa jama&rsquo;ahnya agar selalu setia, setia kepada Alalh SWT sehingga tertambat hatinya untuk segera ke masjid untuk menunaikan shalat berjama&rsquo;ah.</p>\r\n\r\n<p>&quot;Sehingga dengan demikian masjid ini akan makmur dan menjadi pemersatu umat bukan malah menjadi masalah atau trouble maker ditengah-tengah kita, karena kita ingin masjid kita ini dapat menyatukan umat&quot; uangkapnya</p>\r\n\r\n<p>&quot;Karena saya yakin bahwa kita akan mengahadapi tantangan dan kesulitan yang luar biasa, seperti pengedaran Narkoba melalui permen-permen yang sengaja dibagikan secara gratis kepada anak kecil yang belum memiliki penghasilan&quot; tanbahnya</p>\r\n\r\n<p>&quot;Oleh karena itu mari kita bersama-sama membentengi melalui masjid, karena Allah menjamin dalam Al-Qur&rsquo;an bahwa di masjid itu senantiasa ada orang-orang yang cinta akan kesucian&quot; imbuhnya</p>\r\n\r\n<p>&quot;Kalau anak-anak bapak ibu banyak berkumpul di masjid tentunya bapak ibu tidak khawatir, karena mereka akan ada dalam kebaikan dan tentu akan melakukan hal-hal yang positif tentunya karena tidak mungkin juga ketika anak-anak kita berkumpul dimasjid lalu mengkonsumsi Narkoba, tidak mungkin juga minum-minuman keras atau ikut gank motor&quot; imbuhnya</p>\r\n\r\n<p>&quot;Anak-anak ini merupakan generasi masa depan yang kalau mereka senang ke masjid, mudah-mudahan akan mebawa kota kita menjadi lebih baik lagi, mewujudkan Visi Kota Bekasi yang Maju, Sejahtera dan Ihsan&quot; ujarnya</p>\r\n\r\n<p>&quot;Ihsan inilah bagaimana nilai-nilai religiusitas, nilai-nilai keislaman betul-betul tertancap dalan diri kita dan pada umumnya di kehidupan bermasyarakat, bernegara sehingga tatanan masyarakat kita menjadi masyarakat Baldatun Thayyibatun wa Rabbun Ghafur (negeri yang subur dan makmur, adil dan aman)&quot; pungkasnya.</p>\r\n\r\n<p>Pada akhir sambutannya beliau menyampaikan selamat dan apresiasi atas di resmikannya Masjid Al-Wafa ini dan beliau mengajak untuk bersama-sama memakmurkan masjid ini dan beliau yakin dampak-dampak positifnya nanti akan muncul di kemudian hari. (gie)</p>', 'images/20170823073741-2017-08-23post073740.jpg', NULL, NULL, 3701, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-24 09:00:00', '2017-04-24 09:00:00', NULL),
('eb3d1bb1-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Resmikan Islamic Center Masjid Al-Wafa Jati Cempaka', 'wawali-resmikan-islamic-center-masjid-al-wafa-jati-cempaka-2', 'Bekasi, Usai melakukan kegiatan Car Free Day, Wakil Wali Kota Bekasi melanjutkan kegiatannya dengan meresmikan Ismalic Center Masjid Al-Wafa Jl. Setia I, Kelurahan Jati Cempaka Kecamatan Pondok Gede, ', '<p>Bekasi, Usai melakukan kegiatan Car Free Day, Wakil Wali Kota Bekasi melanjutkan kegiatannya dengan meresmikan Ismalic Center Masjid Al-Wafa Jl. Setia I, Kelurahan Jati Cempaka Kecamatan Pondok Gede, Minggu (23/4).</p>\r\n\r\n<p>Hadir pada kegiatan ini Forum Komunikasi Pimpinan Daerah Kota Bekasi, Ketua PB MUhammadiyah Kota Bekasi Soekandar Ghazali, Wakil Ketua PBNU Kota Bekasi, Ketua MUI Kecamatan Pondok Gede, Camat Pondok Gede H. Mardani, SE, M.Si dan Lurah serta tokoh masyarakat se-Kecamatan Pondok Gede.</p>\r\n\r\n<p>Wakil Wali Kota Bekasi dalam sambutannya mengatakan bahwa sesuai dengan nama Masjidnya Al-Wafa tentunya masjid ini akan membawa jama&rsquo;ahnya agar selalu setia, setia kepada Alalh SWT sehingga tertambat hatinya untuk segera ke masjid untuk menunaikan shalat berjama&rsquo;ah.</p>\r\n\r\n<p>&quot;Sehingga dengan demikian masjid ini akan makmur dan menjadi pemersatu umat bukan malah menjadi masalah atau trouble maker ditengah-tengah kita, karena kita ingin masjid kita ini dapat menyatukan umat&quot; uangkapnya</p>\r\n\r\n<p>&quot;Karena saya yakin bahwa kita akan mengahadapi tantangan dan kesulitan yang luar biasa, seperti pengedaran Narkoba melalui permen-permen yang sengaja dibagikan secara gratis kepada anak kecil yang belum memiliki penghasilan&quot; tanbahnya</p>\r\n\r\n<p>&quot;Oleh karena itu mari kita bersama-sama membentengi melalui masjid, karena Allah menjamin dalam Al-Qur&rsquo;an bahwa di masjid itu senantiasa ada orang-orang yang cinta akan kesucian&quot; imbuhnya</p>\r\n\r\n<p>&quot;Kalau anak-anak bapak ibu banyak berkumpul di masjid tentunya bapak ibu tidak khawatir, karena mereka akan ada dalam kebaikan dan tentu akan melakukan hal-hal yang positif tentunya karena tidak mungkin juga ketika anak-anak kita berkumpul dimasjid lalu mengkonsumsi Narkoba, tidak mungkin juga minum-minuman keras atau ikut gank motor&quot; imbuhnya</p>\r\n\r\n<p>&quot;Anak-anak ini merupakan generasi masa depan yang kalau mereka senang ke masjid, mudah-mudahan akan mebawa kota kita menjadi lebih baik lagi, mewujudkan Visi Kota Bekasi yang Maju, Sejahtera dan Ihsan&quot; ujarnya</p>\r\n\r\n<p>&quot;Ihsan inilah bagaimana nilai-nilai religiusitas, nilai-nilai keislaman betul-betul tertancap dalan diri kita dan pada umumnya di kehidupan bermasyarakat, bernegara sehingga tatanan masyarakat kita menjadi masyarakat Baldatun Thayyibatun wa Rabbun Ghafur (negeri yang subur dan makmur, adil dan aman)&quot; pungkasnya.</p>\r\n\r\n<p>Pada akhir sambutannya beliau menyampaikan selamat dan apresiasi atas di resmikannya Masjid Al-Wafa ini dan beliau mengajak untuk bersama-sama memakmurkan masjid ini dan beliau yakin dampak-dampak positifnya nanti akan muncul di kemudian hari. (gie)</p>', 'images/20170823073717-2017-08-23post073715.jpg', NULL, NULL, 3701, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-24 09:00:00', '2017-04-24 09:00:00', NULL),
('eb3d1bfe-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Ajak Masyarakat Maknai Isro dan Mira\'j ', 'wali-kota-bekasi-ajak-masyarakat-maknai-isro-dan-mira-j', 'Kota Bekasi- Peringatan Isro dan Mira&#39;j yang dilakukan Nabi Muhammad SAW merupakan momentum bersejarah dalam khazanah keilmuan dan menujukkan salah satu identitas kenabian beliau.\n\nPeringatan Isro', '<p>Kota Bekasi- Peringatan Isro dan Mira&#39;j yang dilakukan Nabi Muhammad SAW merupakan momentum bersejarah dalam khazanah keilmuan dan menujukkan salah satu identitas kenabian beliau.</p>\n\n<p>Peringatan Isro dan Mi&#39;raj yang dilaksanakan di masjid agung Kota Bekasi AL Barkah di hadiri oleh seluruh kepala Satuan Kepala Perangkat Daerah (SKPD) Kota Bekasi, kepala Kantor kementrian Agama Kota bekasi, Selasa, 25/4.</p>\n\n<p>Dalam momentum ini, Wali Kota Bekasi Rahmat Effendi mengajak seluruh masyarakat Kota Bekasi untuk memaknai peristiwa tersebut.</p>\n\n<p>Isra dan Mi&#39;raj yang kita peringati, lanjutnya bukan hanya sebagai kisah religi, melainkan makna dan penghayatan keagamaan kita yang mulai menjauh dari nilai nilai yang digemakan oleh Nabi.</p>\n\n<p>Wali Kota Bekasi berharap kepada seluruh elemen masyarakat Kota Bekasi untuk senantiasa menjaga dan mempererat solidaritas ukhuwah Islamiyah untuk menjadikan Kita Bekasi yang Maju, Sejahtera, dan Ihsan .( tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 04:47:00', '2017-04-26 04:47:00', NULL),
('eb3d1c54-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kaukus Perempuan Politik Indonesia Lakukan Seminar Guna Mecerdasakan Perempuan ', 'kaukus-perempuan-politik-indonesia-lakukan-seminar-guna-mecerdasakan-perempuan', 'Kota Bekasi - Dalam menyambut hari Kartini Kaukus perepuan politik Indonesia (KPPI) Kota Bekasi &nbsp;melaksanakan seminar politik yang dilaksanakan di asrama haji jalan kemakmuran kita bekasi, Rabu, ', '<p>Kota Bekasi - Dalam menyambut hari Kartini Kaukus perepuan politik Indonesia (KPPI) Kota Bekasi &nbsp;melaksanakan seminar politik yang dilaksanakan di asrama haji jalan kemakmuran kita bekasi, Rabu, 26/4.</p>\n\n<p>Dengan mengusung tema meciptakan ketertarikan generasi muda untuk berpolitik yang sehat, dihadiri oleh seluruh wanita yang berpartisipasi di partai politik Indonesia.</p>\n\n<p>Hj Titin Supriati Ketua KPPI Kota Bekasi mengatakan perkumpulan &nbsp;yang sudah terhimpun sejak 2014 memiliki misi untuk mencerdaskan hingga meningkatkan partisipasi wanita dalam kancah politik Indonesia.</p>\n\n<p>Wali Kota Bekasi DR. Rahmat Effendi dalam sambutannya membuka seminar mengatakan perkumpulan KPPI diharapkan mampu menciptakan peradaban dalam keterwakilan perempuan berpolitik yang ada di kota bekasi.</p>\n\n<p>Pencerdasan perempuan dalam berpolitik, lanjut nya, sangat berperan penting dalam kemajuan dan pembangunan yang ada di Kota Bekasi.</p>\n\n<p><br />\nIa melanjutkan bahwa tugas KPPI adalah membantu Pemerintah dalam mencerdaskan perempuan dalam kancah perpolitikan. &quot;Tidak boleh ada oposisi didalam KPPI kalau ingin maju,&quot; tandasnya.</p>\n\n<p>Walikota juga meminta agar Orientasi Program disusun rapi agar maksud dan tujuan &nbsp;terlaksana kan dan sesuai dengan aturan, &quot; harusnya pabila menilik dari tujuannya KPPI harusnya masuk kedalam kelembagaan kesbangpol bukan pada badan pemberdayaan perempuan, &quot; ucapnya.</p>\n\n<p>&quot; Jadi tidak boleh mendiskriminasi dalam hidup berbangsa dan bernegara terutama di Kota Bekasi untuk menjadi kota yang Maju, Sejahtera dan Ihsan.(tdy) &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 04:48:00', '2017-04-26 04:48:00', NULL),
('eb3d1ca5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota  Bekasi Pimpin Apel Hari Jadi Sat Pol PP', 'wali-kota-bekasi-pimpin-apel-hari-jadi-sat-pol-pp', 'Kota Bekasi- Wali Kota Bekasi DR. Rahmat Effendi pimpin Hari jadi Satuan Polisi Pamong Praja ( Sat Pol PP) yang berlangsung di alun alun Kota Bekasi, Jl. Veteran, Kota Bekasi, Rabu , 26/4.\n\nDalam apel', '<p>Kota Bekasi- Wali Kota Bekasi DR. Rahmat Effendi pimpin Hari jadi Satuan Polisi Pamong Praja ( Sat Pol PP) yang berlangsung di alun alun Kota Bekasi, Jl. Veteran, Kota Bekasi, Rabu , 26/4.</p>\n\n<p>Dalam apel yang dihadiri oleh ribuan personel gabungan yang terdiri dari unsur TNI, Polri, Sat Pol PP, Dinas Perhubungan dan Aparatur Sipil Negara (ASN) Wali Kota Bekasi menegaskan bahwa Sat Pol PP adalah sebagai penegak Perda.</p>\n\n<p>Dalam sambutan Mentri Dalam Negri yang di bacakan oleh WaliKota Bekasi mengambil tema Peningkatan Peran Satuan Polisi Pamong Praja dan Satuan Perlindungan Masyarakat dalam Menjaga Kemajemukan Masyarakat di daerah.</p>\n\n<p>Kemajemukan, lanjutnya, bukan lah hal asing dalam kehidupan berbangsa dan bernegara, Indonesia lahir dari keberagaman suku agama budaya dan bahasa yang tersebar luas dalam ribuan pulau Indonesia.</p>\n\n<p>Mendagri juga menghijau kepada segenap komponen pemerintahan untuk bekerja sama yang masif dan kondusif agar ancaman gangguan hambatan dan tantangan yang dapat memecah belah bangsa ini teratasi serta merubah paradigma dan meninggalkan pola pikir dari dilayani ke melayani.</p>\n\n<p>Undang undang nomor 23 Tahun 2014 tentang pemerintahan daerah memberikan keleluasaan kepada Pemerintah daerah untuk membentuk Perda. Hal ini harus dimanfaatkan sebaik baiknya agar menghasilkan Perda yang inovatif kreatif dan implementasinya tetap berpedoman pada ketentuan beraturan perundangan dan tidak berbenturan dengan prinsip Negara Kesatuan Republik Indonesia.</p>\n\n<p>&quot; Jumlah Sat Pol PP akan Kita tambah menjadi 1700 orang atau minimal sama dengan personel kepolisian resort metro kota bekasi demi menjaga keamanan dan kedamaian masyarakat yang tinggal dikota bekasi, &quot; ucapnya.<br />\nLinmas, lanjutnya, kalau bisa seragamnya akan kita tambah menjadi 2 kali dalam setahun yang sebelumnya 1kali dalam setahun.</p>\n\n<p>Wali Kota Bekasi juga menambahkan bahwa pada tahun 2018 nanti kita akan tambah kepada seluruh ASN di Kota Bekasi untuk ditambah tunjangannya.</p>\n\n<p>&quot; Kemajuan yang telah dicapai saat ini penyelenggara Pemerintah nya pun harus menikmatinya yaitu dengan cara menambah tunjangannya , &quot; ucapnya.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 07:00:00', '2017-04-26 07:00:00', NULL),
('eb3d1cf4-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'BPBD Gelar Apel Peringatan HKBN', 'bpbd-gelar-apel-peringatan-hkbn', 'Kota Bekasi - Pemerintah Kota Bekasi melalui Badan Penanggulangan Bencana Daerah Kota Bekasi (BPBD) menggelar apel peringatan Hari Kesiapsiagaan Bencana Nasional (HKBN) ,Rabu ( (26) &nbsp;bertempat di', '<p>Kota Bekasi - Pemerintah Kota Bekasi melalui Badan Penanggulangan Bencana Daerah Kota Bekasi (BPBD) menggelar apel peringatan Hari Kesiapsiagaan Bencana Nasional (HKBN) ,Rabu ( (26) &nbsp;bertempat di Plaza Kantor Walikota Bekasi.&nbsp;</p>\n\n<p>Rangkaian acara kegiatan dimulai dengan upacara dan dilanjutkan dengan pertunjukan simulasi penanggulangan bencana di Kota Bekasi.&nbsp;</p>\n\n<p>Kegiatan ini dihadiri oleh Sekretaris Daerah Kota Bekasi, Rayendra Sukarmadji, bertindak selaku Pembina Upacara serta peserta upacara dari TNI, POLRI, Relawan BPBD Kota Bekasi serta komunitas Suzuki Jimmy Indonesia (SJI) Kota Bekasi.&nbsp;</p>\n\n<p>&nbsp;Dalam peringatan Hari Kesiapsiagaan Bencana Nasional (HKBN) mengusung tema &ldquo;Membangun Kesadaran, Kewaspadaan dan Kesiapsiagaan Menghadapi Bencana di Kota Bekasi&rdquo;. BPBD Kota Bekasi melaksanakan rangkaian peringatan Hari Kesiapsiagaan Bencana Nasional (HKBN) dengan mempertunjukan simulasi penanggulangan bencana di Plaza Kantor Walikota Bekasi.</p>\n\n<p>Dalam sambutan Kepala Badan Nasional Penanggulangan Bencana (BNPB), H.E.Willem Rampangilei, yang dibacakan oleh Sekretaris Daerah Kota Bekasi, Rayendra Sukarmadji, terkait berbagai kendala dan tantangan yang pada umumnya dihadapi pemangku kepentingan dalam rangka meningkatkan kesiapsiagaan antara lain kurangnya pemahaman dan kesadaran masyarakat terhadap karakteristik bencana dan resikonya, kurangnya kewaspadaan dan kesiapsiagaan masyarakat dalam menghadapi ancaman yang ada di sekitarnya serta belum adanya pelatihan secara terpadu dan periodik karena kewaspadaan serta kesiapsiagaan belum menjadi kebiasaan rutin yang menjadi budaya.</p>\n\n<p>Jenis latihan kesiapsiagaan yang akan dilaksanakan antara lain uji tanda peringatan dini, uji tempat evakuasi se Indonesia dan lapang evakuasi mandiri. Selain itu seluruh jenis kegiatan utama didorong untuk melibatkan partisipasi masyarakat, lembaga usaha/swasta, lembaga swadaya masyarakat, dan seluruh pemangku kepentingan bencana terkait. &nbsp;</p>\n\n<p>Membangun kewaspadaan dan kesiapsiagaan dalam menghadapi bencana di Kota Bekasi, seyogyanya menjadi kesadaran bersama, guna mengantisipasi terjadi bencana di Kota Bekasi. Kegiatan peringatan Hari Kesiapsiagaan Bencana Nasional (HKBN) bejalan lancar dan meriah yang mana telah ditutup dengan dilakukannya pertunjukan simulasi penanggulangan bencana di Kota Bekasi.&nbsp;</p>\n\n<p>Semoga acara ini mendapatkan masukan yang efektif guna menyempurnakan latihan kesiapsiagaan bencana.&nbsp;</p>\n\n<p>Sekretaris Daerah Kota Bekasi, Rayendra Sukarmadji, mengimbau kepada masyarakat Kota Bekasi agar dapat mewujudkan kesadaran, kewaspadaan dan kesiapsiagaan dalam menghadapi bencana di Kota Bekasi dan berharap dalam memperingati Hari Kesiapsiagaan Bencana Nasional (HKBN) pada tahun berikutnya dapat diselenggarakan lebih meriah dari tahun ini.(yas/bar)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 16:16:00', '2017-04-26 16:16:00', NULL),
('eb3d1d44-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Peringati Hari Otonomi Daerah Ke-XXI Tingkat Kota Bekasi', 'wawali-peringati-hari-otonomi-daerah-ke-xxi-tingkat-kota-bekasi', 'Kota Bekasi - Wakil Wali Kota BekasiAhmad Syaikhu menjadi Inspektur Upacara pada Peringatan Hari Otonomi Daerah Ke-XXI Tingkat Kota Bekasi bertempat di Plaza Kantor Wali Kota Bekasi Jl. Jend. A. Yani ', '<p>Kota Bekasi - Wakil Wali Kota BekasiAhmad Syaikhu menjadi Inspektur Upacara pada Peringatan Hari Otonomi Daerah Ke-XXI Tingkat Kota Bekasi bertempat di Plaza Kantor Wali Kota Bekasi Jl. Jend. A. Yani No. 1 Bekasi, Selasa (25/4) pagi.</p>\n\n<p>Hadir pada apel Peringatan Hari Otonomi Daerah ini, Kepala Perangkat Daerah, Sekretaris Badan/Dinas, Camat dan Lurah serta Aparatur Sipil Negara di lingkungan Pemerintah Kota Bekasi.</p>\n\n<p>Wakil Wali Kota Bekasi pada sambutannya mengatakan peringatan yang dilaksanakan merupakan momentum untuk mengevaluasi perkembangan kinerja pelaksanaan otonomi daerah pada masing-masing daerah otonom.</p>\n\n<p>&quot;Bahwa dalam pelaksanaan otonomi daerah Pemerintah Daerah harus senantiasa fokus pada upaya peningkatan kesejahteraan masyarakat, melalui peningkatan kualitas pelayanan publik, peningkatan pemberdayaan masyarakat, dan peningkatan daya saing perekonomian daerah&quot; ungkapnya.</p>\n\n<p>&quot;Peringatan Hari Otonomi Daerah ke-21 bertema &ldquo;Dengan semangat Otonomi Daerah, Kita Tingkatkan Kinerja Pelayanan Publik Melalui E-Government&rdquo;, memiliki 4 empat makna pokok, pertama Pelaksanaan Otonomi Daerah mampu meningkatkan kinerja pelayanan publik sesuai dengan kepentingan masyarakat&quot; ujarnya</p>\n\n<p>&quot;Kedua Upaya peningjkatan kinerja pelayanan publik harus dikelola berbasis teknologi informasi dan komunikasi atau electronic-govermment, agar masyarakat dapat memperoleh informasi secara mudah, cepat dan tepat tentang prosedur pelayanan publik yang disediakan Pemerintah Daerah&quot; imbuhnya.</p>\n\n<p>&quot;Ketiga ketepatan penyediaan pelayanan public berbasis electronic-govermment membutuhkan kemampuan dan integritas yang tinggi dari setiap aparatur Pemerintah Daerah dan yang keempat, upaya peningkatan kinerja pelayanan publik berbasis electronic-govermment akan dapat mewujudkan tata kelola pemerintahan daerah yang baik (good lokal govermance) dan aparatur pemerintah daerah yang bersih (clean local govermment)&quot; tambahnya.</p>\n\n<p>Wakil Wali Kota menegaskan bahwa Pemerintah Daerah dapat memanfaatkan teknologi informasi dalam pelayanan publik, karena sejalan dengan kemajuan teknologi informasi dan komunikasi saat ini dan juga senantiasa berinisiatif untuk mengelola pelayanan publik berbasis electronic-govermment.</p>\n\n<p>&quot;Saat ini Kementrian Dalam Negeri sedang mengembangkan Program Smart City untuk mendorong setiap pememrintah daerah agar mengembangkan electronic-govermment dalam penyediaan pelayanan publik, selain itu Program City Branding juga dikembangkan untuk mendorong setiap pemda kota untuk memprioritaskan program pembanguna pada sector tertentu sesuai dengan karakteristik daerah dan kebutuhan masyarakat yang berbasis electronic-government&quot; ujarnya.</p>\n\n<p>Pada akhir sambutannya ada lima poin arahan yang disampaikan, pertama senatiasa terjalin hubungan yang harmonis antara Kepala Daerah, DPRD dan Unsur Komunikasi Pimpinan Daerah, kedua meningkatkan kualitas tata kelola pemerintahan daerah.</p>\n\n<p>&quot;Poin ketiga memprioritaskan program pembangunan daerah, keempat meningkatkan daya saing perekonomian daerah dan yang kelima meningkatkan keterbukaan informasi publik melalui pelayanan PPID secara efektif, efisien dan dapat dipertanggungjawabkan&quot; pungkasnya. (gie)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 16:20:00', '2017-04-26 16:20:00', NULL),
('eb3d1d95-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'HUT Satpol PP, Walikota Bekasi Beri Kado Kenaikan Tunjangan ', 'hut-satpol-pp-walikota-bekasi-beri-kado-kenaikan-tunjangan', 'Kota Bekasi, 26-04-2017. Wali Kota Bekasi, Dr.Rahmat Effendi akan menaikan tunjungan kepada seluruh anggota Satpol PP Kota Bekasi tahun depan. &quot; Januari 2018 kita akan naikan tunjangan untuk selu', '<p id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12467\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; margin-top: 0px; margin-bottom: 5px; border: 0px; vertical-align: baseline; clear: both; line-height: 1.3;\">Kota Bekasi, 26-04-2017. Wali Kota Bekasi, Dr.Rahmat Effendi akan menaikan tunjungan kepada seluruh anggota Satpol PP Kota Bekasi tahun depan. &quot; Januari 2018 kita akan naikan tunjangan untuk seluruh angggota satpol PP &nbsp;Kota Bekasi&quot;, hal ini disampaikan oleh Wali Kota, dalam sambutannya dihadapan ratusan anggota Satpol PP Kota Bekasi pada Peringatan &nbsp;HUT Satuan Polisi Pamong Praja (Satpol PP) ke-67 dan Sat Linmas ke-55 Kota Bekasi yang dilaksanakan Rabu (26/04) bertempat di Lapangan Alun-alun Kota Bekasi.&nbsp;</p>\n\n<p  4.2pt; line-height: normal; vertical-align: baseline;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12484\"  Arial, sans-serif; font-size: 10pt;\">Diungkapkan &nbsp;Wali Kota, dirinya akan menaikan besaran tunjangan kerja bagi Satpol PP Kota Bekasi hingga 65 persen dimana sebelumnya Satpol PP yang berstatus PNS mendapatkan tunjangan sebesar Rp 1,5 juta dan untuk Satpol PP berstatus TKK mendapatkan tunjangan Rp 1,2 juta. &quot; Kenaikan tunjangan ini sebanding dengan pola kerja yang satpol PP laksanakan sehari-hari, karena memliki resiko yang tinggi.</span></p>\n\n<p  4.2pt; line-height: normal; vertical-align: baseline;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12486\"  10pt; font-family: Arial, sans-serif;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12487\"  10pt;\">Dengan kenaikan tungkir ini nantinya dapat memberi semangat kepada anggota satpol PP Kota Bekasi dalam menjalankan tugas. &ldquo; saya berharap Kehadiran kalian semua memberikan rasa bangga bagi Kota Bekasi&rdquo;, ungkapnya.</span></span></p>\n\n<p  4.2pt; line-height: normal; vertical-align: baseline;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12492\"  10pt; font-family: Arial, sans-serif;\">Dirinya juga akan menambah anggota satpol PP mencapai 1700, setidaknya anggota satpol PP kota Bekasi dapat sama personelnya &nbsp;dengan personel yang ada di kepolisian resort metro kota bekasi, katanya.&nbsp;</span><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12493\"  Arial, sans-serif; font-size: 10pt;\">&nbsp;Hal ini dimaksudkan demi kenyamanan dan keamanan masyarakat Kota Bekasi, ujar &nbsp;Wali Kota.&nbsp;</span></p>\n\n<p  4.2pt; line-height: normal; vertical-align: baseline;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12501\"  10pt; font-family: Arial, sans-serif;\">Peringatan &nbsp;HUT Satuan Polisi Pamong Praja (Satpol PP) ke-67 dan Sat Linmas ke-55 Kota Bekasi &nbsp;di Hadiri Wakil Wali Kota Bekasi, Ahmad Syaikhu, Sekretaris Daerah Kota Bekasi, Wakapolresta Metro Bekasikota, Kasatpol PP Jakarta Timur, Kasatpol PP Kabupaten Bekasi, Kasatpol PP Kab Karawang. &nbsp;</span></p>\n\n<p dir=\"ltr\"  4.2pt; line-height: normal; vertical-align: baseline;\"><span id=\"m_-629853198831086368yui_3_16_0_ym19_1_1493262423950_12509\"  10pt; font-family: Arial, sans-serif;\">Acara Peringatan tersebut di mulai dengan dengan penampilan &nbsp;Tari-tarian daerah yang disuguhkan oleh anggota satpol PP Putri dan diakhiri simulasi demonstrasi oleh anggota satpol PP Kota Bekasi . Diakhir sambutannya Wali Kota berpesan agar Satpol PP kota Bekasi terus Meningkatkan Pelayanan Terhadap Masyarakat,tandasnya. (yas).</span></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-26 22:30:00', '2017-04-26 22:30:00', NULL),
('eb3d1ded-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Asda II Hadiri Muskomwil III APEKSI di Bogor', 'asda-ii-hadiri-muskomwil-iii-apeksi-di-bogor', 'Bogor, 27/4/2017. Asisten Perekonomian, Pembangunan &amp; Kesejahteraan Masyarakat&nbsp; (Asda II), Kariman hadir mewakili Wali Kota Bekasi dalam Musyawarah Komisariat&nbsp; Wilayah (Muskomwil) III As', '<p>Bogor, 27/4/2017. Asisten Perekonomian, Pembangunan &amp; Kesejahteraan Masyarakat&nbsp; (Asda II), Kariman hadir mewakili Wali Kota Bekasi dalam Musyawarah Komisariat&nbsp; Wilayah (Muskomwil) III Asosiasi Pemerintah Kota Seluruh Indonesia (Apeksi) tahun 2017, di Balai Kota, Rabu (27/04) Kota Bogor.</p>\n\n<p>Dalam Muskomwil tersebut dihadiri&nbsp; sebanyak 15 wali Kota dari perwakilan wilayahDKI Jakarta, Banten, Jawa Barat, dan DIY Yogyaakrta.</p>\n\n<p>Kepala Badan Koordinasi Pemerintahan dan Pembangunan Wilayah (Bakorwil) I Jawa Barat Eddy I.M. Nasution turut hadir untuk&nbsp; membacakan sambutan Gubernur Jawa Barat Ahmad Heryawan pada penyambutan dan gala dinner Muskomwil III Apeksi tahun 2017.</p>\n\n<p>Dalam sambutannya, dijelaskan bahwa Musyawarah Komisariat Wilayah (Muskomwil) III Asosiasi Pemerintah Kota Seluruh Indonesia (Apeksi) tahun 2017 merupakan momentum berbagi pengalaman dan menyampaikan berbagai permasalahan yang dihadapi, sehingga muncul terobosan-terobosan pembangunan serta inovasi pelayanan publik di daerah yang mampu mendukung peningkatan kinerja penyelengaraan pemerintahan, pelaksanaan pembangunan, dan pelayanan masyarakat di wilayahnya masing-masing.</p>\n\n<p>&quot;Sesuai dengan Permenpan Nomor 30 Tahun 2014 bahwa tujuan pelayanan publik yaitu mendorong pembangunan inovasi pelayanan publik, mendorong pengembangan dan transfer inovasi pelayanan publik, mempercepat peningkatan kualitas pelayanan publik, dan meningkatkan kepuasan masyarakat terhadap pelayanan publik,&quot; terang Eddy.</p>\n\n<p>Sementara itu, Wali Kota Bogor, Bima Arya dalam sambutan selamat datanggnya dihadapan peserta APEKSI menuturkan walaupun peserta yang hadir pada APEKSI ini<br />\nhadir berasal dari berbagai latar belakang, namun diyakini jika semua hati para wali kota ini hatinya merah putih dan menjadikan Negara Kesatuan Republik Indonesia (NKRI) sebagai harga mati.</p>\n\n<p>Oleh karena itu, menjadi kepedulian seluruh wali kota agar bagaimana kesemuanya dapat bersama-sama dan berkolaborasi dalam bingkai NKRI.ujarnya. (yas)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-27 07:20:00', '2017-04-27 07:20:00', NULL),
('eb3d1e3e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Membuka Acara Citizen Jurnalis yang diadakan Diskominfostandi', 'wakil-wali-kota-membuka-acara-citizen-jurnalis-yang-diadakan-diskominfostandi', 'Kota Bekasi, -(27/4) Acara Pelatihan citizen jurnalis yang diadakan oleh diskominfostandi di laksanakan di Hotel Harris Bandung dari tanggal 27 sampai 28 April 2017 yang para pesertanya dari semua SMA', '<p>Kota Bekasi, -(27/4) Acara Pelatihan citizen jurnalis yang diadakan oleh diskominfostandi di laksanakan di Hotel Harris Bandung dari tanggal 27 sampai 28 April 2017 yang para pesertanya dari semua SMA dan SMK Negeri yang ada di Kota Bekasi yang dibuka langsung oleh Wakil Wali Kota Bekasi H.Akmad Syaikhu dalam sambutannya Wakil Wali Kota Menyatakan sebagaimana yang kita ketahui bahwa Kota Bekasi dulu sering di &ldquo;bully&rdquo; tapi sekarang dengan seiringnya kemajuan teknologi dan sinergitas Antara Masyarakat dan Pemerintah Kota Bekasi,kita Mampu Memperbaiki menjadi lebih baik lagi.sekarang Kota Bekasi &nbsp;banyak prestasi- prestasi yang telah diterima baik nasional maupun internasional saya juga melihat potensi &ndash; potensi jurnalistik ada pada diri anak &ndash; anak muda karena di usia seperti mereka aktif di dunia media social kalau semua ini di &ldquo;kemas&rdquo; dalam konten &ndash; konten informasi yang benar dan sinergi dengan pemerintah maka tercipta informasi yang positif terhadap masyarakat ungkapnya.</p>\n\n<p>Sementara itu hadir pula Kepala Diskominfostandi Kota Bekasi DR.dr Titi Masrifahati.MKM menyatakan bahwa dasar penyelenggaraan adalah peraturan daerah Kota Bekasi No 3 Tahun 2008 dan Perda no 18 tahun 2009 tentang keterbukaan informasi publik .tujuannya diadakannya pelatihan citizen jurnalis ini adalah terciptanya SDM yang siap menjadi kontributor jurnalistik media informasi publik dimasing masing sekolah yang akan dikordinir oleh diskominfostandi.</p>\n\n<p>Peserta yang hadir adalah perwakilan siswa &ndash; siswi &nbsp;dari semua SMA dan SMK Negeri yang Ada Di Kota Bekasi Yang berjumlah 64 orang.selama di pelatihan ini mereka di bekali ilmu &ndash; ilmu jurnalistik dari narasumber wartawan senior Hamludin .Msi.(gege)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-27 11:47:00', '2017-04-27 11:47:00', NULL),
('eb3d1e8d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Datangi Rumah Warga Pengasinan Penderita Tumor', 'wali-kota-datangi-rumah-warga-pengasinan-penderita-tumor', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadiri kegiatan temu warga RT 01/01 Kelurahan Pengasinan Kecamatan Rawalumbu, di dampingi Asisten Pemerintahan, Dinar Fahrizal, Camat Rawalumbu se', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadiri kegiatan temu warga RT 01/01 Kelurahan Pengasinan Kecamatan Rawalumbu, di dampingi Asisten Pemerintahan, Dinar Fahrizal, Camat Rawalumbu serta Lurah setempat.</p>\n\n<p><br />\nWali Kota Bekasi saat sambutan menceritakan mengenai pentingnya memiliki Kartu Sehat Berbasis NIK di Kota Bekasi, yang mempunyai sinegritas dengan pihak rumah sakit swasta lainnya yang berdiri di Kota Bekasi, Wali Kota menegaskan bahwa tidak ada yang berani menolak baik dari rumah sakit pemerintah ataupun rumah sakit swasta, jika memang ada yang menolaknya, Wali Kota tidak segan segan menutup Rumah sakit tersebut.</p>\n\n<p><br />\nDijelaskan, Kartu tersebut berbeda dengan Kartu keluaran dari Pemerintah pusat seperti BPJS, KIS serta lainnya, Kartu Sehat berbasis NIK tersebut sudah mencakup satu keluarga di dalam Kartu Keluarga kalau kartu dari pemerintah hanya perorangan, dan selain itu Kartu Sehat Berbasis NIK tersebut tidak perlu membayar, karena kartu tersebut terbayarkan melalui pajak yang warga bayar.</p>\n\n<p><br />\nUsai acara, Wali Kota langsung menemui salah satu warga dengan mengunjugi kediamannya lantaran menurut hasil laporan warga, Ibu Ersih penderita tumor telah pulang dari rumah sakit setelah di rawat di Rumah Sakit Hermina dengan menggunakan Surat Keterangan Tidak Mampu (SKTM) dari Kecamatan, mendengar laporan tersebut Walikota mendatangi kediaman ibu tersebut dan menegaskan Lurah agar segera dibuatkan kartu sehat tersebut.</p>\n\n<p><br />\nWali Kota Bekasi juga menwgaskan kepada lurah berikut Ketua RW 01 Kelurahan Pengasinan dalam seminggu diberi waktu untuk mengumpulkan Kartu Keluarga dan KTP untuk dibuatkan Kartu Sehat Berbasis NIK dan akan segera diproses dengan cepat, agar warga tidak kesusahan dalam penanganan mengenai kesehatan. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-28 12:11:00', '2017-04-28 12:11:00', NULL),
('eb3d1ee9-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Temui Para Kepala Sekolah SMP Negeri Kota Bekasi', 'wali-kota-bekasi-temui-para-kepala-sekolah-smp-negeri-kota-bekasi', 'Kota Bekasi ---- Jumat, (28/04/2017), Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara pertemuan dengan Kepala Sekolah SMP Negeri se Kota Bekasi di Bandar Jakarta Sumareccon Bekasi untuk diberik', '<p>Kota Bekasi ---- Jumat, (28/04/2017), Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara pertemuan dengan Kepala Sekolah SMP Negeri se Kota Bekasi di Bandar Jakarta Sumareccon Bekasi untuk diberikan arahan mengenai kesiapan Ujian Nasional SMP yang akan terselenggara pada selasa tanggal 02 Mei 2017 hingga selesai serta pembahasan mengenai persiapan Penerimaan Siswa Baru melalui Penerimaan Peserta Didik Baru (PPDB) Online di Kota Bekasi.</p>\n\n<p><br />\nBersama Kepala Dinas Pendidikan, Cucu Syamsudin dan Sekretaris Dinas Pendidikan, Inayatullah, Wali Kota Bekasi mengarahkan kepada Kepala Sekolah untuk mengamankan berkas ujian yang telah turun dan akan dibagikan ke sub rayon masing masing sekolah, agar terhindar dari kebocoran hingga sampai ke sekolah masing masing pada saat berlangsung ujian nanti. Menurut Sekretaris Dinas Pendidikan yang telah berkoordinasi dengan pengawas sekolah pada hari ini, ujian telah masuk dan dikumpulkan di masing-masing rayon dan akan tersebar pada saat tanggal 1 Mei nanti.</p>\n\n<p><br />\nMenurut Wali Kota permasalahan permasalahan besar di Dinas yakni berada di Dinas Pendidikan terutama pada saat penerimaan siswa baru baik dari SMP maupun SMA, sangat krusial dan harus segera diperbaiki, dan harus sejalan pada tahun 2016 yang bisa terkordinir dengan membuka Pelayanan mengenai PPDB Online di masing-masing Kecamatan se Kota Bekasi.</p>\n\n<p><br />\nSelain itu, Wali Kota menegaskan kepada para Kepsek agar Dana Bantuan Operasional Sekolah (BOS) sampai ke tangan yang menerima tidak lagi per tiga bulan, harus satu bulan sekali seperti insentif yang diterima oleh para Kader PKK, Posyandu, Linmas dan lainnya. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-28 12:32:00', '2017-04-28 12:32:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d1f3f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Tatap Muka dengan Warga Perumahan Pulo Permatasari Kecamatan Bekasi Selatan', 'wali-kota-tatap-muka-dengan-warga-perumahan-pulo-permatasari-kecamatan-bekasi-selatan', 'Kota Bekasi ---- Jumat Malam (28/04/2017) Wali Kota Bekasi, Dr. Rahmat Effendi hadiri acara silaturahmi dengan RW 19 Perumahan Pulo Permatasari, Kecamatan Bekasi Selatan bersama Asisten Pemerintahan, ', '<p>Kota Bekasi ---- Jumat Malam (28/04/2017) Wali Kota Bekasi, Dr. Rahmat Effendi hadiri acara silaturahmi dengan RW 19 Perumahan Pulo Permatasari, Kecamatan Bekasi Selatan bersama Asisten Pemerintahan, Dinar Faizal Badar, Kepala Dinas PUPR, Tri Adhianto, Silaturahmi ini juga sekaligus dikarenakan adanya keluhan warga yakni mengenai dampak banjir akibat pembangunan Apartemen Grand Kamala Lagoon.</p>\n\n<p><br />\nAudiensi dengan warga Perumahan Pulo Permatasari ini menjadi temu warga kedua yang sebelum yang dilakukan dengan warga Perumahan Taman Cikas yang juga sama mengeluh karena terjadi dampak banjir dari pembangunan tersebut,</p>\n\n<p><br />\nPada kesempatannya Wali Kota yang memberikan sambutan menjelaskan bahwa pembangunan Grand Kamala Lagoon telah berdiskusi mengenai dampak wilayah, tidak hanya di Perumahan Pulo Permatasari, di sekitar nya juga ada taman cikas, serta area villa Galaxy, berikut juga Pondok Timur Mas yang juga terkena dampak banjir, menurut keluhan warga saat berdiskusi memang perumahan cikas sudah menjadi langganan banjir hampr satu minggu 3 kali banjir namun menurut warga setelah adanya pembangunan Apartemen GKL hujan sedikit saja sudah menggenangi perumahan tersebut.</p>\n\n<p><br />\nWalau di Grand Kamala Lagoon ada waduk yang menampung air, akan tetapi resapan air nya tidak sampai dan telah dibangun Poulder air Cikas akan tetapi tetap tidak menjadi solusi.</p>\n\n<p><br />\nWali Kota Bekasi juga menyampaikan solusi yang akan membentuk tim dari Pemerintah Kota Bekasi, Perwakilan dari Grand Kamala Lagoon dan 2 orang warga baik dari Perumahan Cikas, PTM, PPS dan Taman Galaxy yang ada di sekitar area tersebut, dari terbentuknya tim tersebut akan menghasilkan hasil terbaik.</p>\n\n<p><br />\n&quot;Jangan memikirkan diri sendiri dengan pendirian apartemen yang telah di ijinkan, namun saya harus juga mendengarkan keluhan warga di sekitar tersebut&quot; tegas Wali Kota.</p>\n\n<p>Perumahan Pulo Permata Mas akan mendapatkan 2 buah mobil dump truck dan 2 mobil lagi untuk Perumahan Taman Cikas yang akan berguna untuk mengangkut sampah seminggu 3 kali karena di wilayah tersebut hanya sekali seminggu diangkutnya, Wali Kota menegaskan kepada Dinas Lingkungan Hidup untuk membuat surat untuk Dinas Kebersihan DKI Jakarta agar meminta 5 buah Dum Truck sampah yang telah bersedia memberikan mobil tersebut untuk Kota Bekasi (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-29 16:43:00', '2017-04-29 16:43:00', NULL),
('eb3d1f8f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Tatap Muka dengan Warga Perumahan Pulo Permatasari Kecamatan Bekasi Selatan', 'wali-kota-tatap-muka-dengan-warga-perumahan-pulo-permatasari-kecamatan-bekasi-selatan-2', 'Kota Bekasi ---- Jumat Malam (28/04/2017) Wali Kota Bekasi, Dr. Rahmat Effendi hadiri ke acara silaturahmi dengan RW 19 Perumahan Pulo Permatasari, Kecamatan Bekasi Selatan bersama Asisten Pemerintaha', '<p>Kota Bekasi ---- Jumat Malam (28/04/2017) Wali Kota Bekasi, Dr. Rahmat Effendi hadiri ke acara silaturahmi dengan RW 19 Perumahan Pulo Permatasari, Kecamatan Bekasi Selatan bersama Asisten Pemerintahan, Dinar Faizal Badar, Kepala Dinas PUPR, Tri Adhianto, Silaturahmi ini juga sekaligus dikarenakan adanya keluhan warga yakni mengenai dampak banjir akibat pembangunan Apartemen Grand Kamala Lagoon.</p>\n\n<p><br />\nAudiensi dengan warga Perumahan Pulo Permatasari ini menjadi temu warga kedua yang sebelum yang dilakukan dengan warga Perumahan Taman Cikas yang juga sama mengeluh karena terjadi dampak banjir dari pembangunan tersebut,</p>\n\n<p><br />\nPada kesempatannya Wali Kota yang memberikan sambutan menjelaskan bahwa pembangunan Grand Kamala Lagoon telah berdiskusi mengenai dampak wilayah, tidak hanya di Perumahan Pulo Permatasari, di sekitar nya juga ada taman cikas, serta area villa Galaxy, berikut juga Pondok Timur Mas yang juga terkena dampak banjir, menurut keluhan warga saat berdiskusi memang perumahan cikas sudah menjadi langganan banjir hampr satu minggu 3 kali banjir namun menurut warga setelah adanya pembangunan Apartemen GKL hujan sedikit saja sudah menggenangi perumahan tersebut.</p>\n\n<p><br />\nWalau di Grand Kamala Lagoon ada waduk yang menampung air, akan tetapi resapan air nya tidak sampai dan telah dibangun Poulder air Cikas akan tetapi tetap tidak menjadi solusi.</p>\n\n<p><br />\nWali Kota Bekasi juga menyampaikan solusi yang akan membentuk tim dari Pemerintah Kota Bekasi, Perwakilan dari Grand Kamala Lagoon dan 2 orang warga baik dari Perumahan Cikas, PTM, PPS dan Taman Galaxy yang ada di sekitar area tersebut, dari terbentuknya tim tersebut akan menghasilkan hasil terbaik.</p>\n\n<p><br />\n&quot;Jangan memikirkan diri sendiri dengan pendirian apartemen yang telah di ijinkan, namun saya harus juga mendengarkan keluhan warga di sekitar tersebut&quot; tegas Wali Kota.</p>\n\n<p>Perumahan Pulo Permata Mas akan mendapatkan 2 buah mobil dump truck dan 2 mobil lagi untuk Perumahan Taman Cikas yang akan berguna untuk mengangkut sampah seminggu 3 kali karena di wilayah tersebut hanya sekali seminggu diangkutnya, Wali Kota menegaskan kepada Dinas Lingkungan Hidup untuk membuat surat untuk Dinas Kebersihan DKI Jakarta agar meminta 5 buah Dum Truck sampah yang telah bersedia memberikan mobil tersebut untuk Kota Bekasi (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-29 16:42:00', '2017-04-29 16:42:00', NULL),
('eb3d1fe6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Hadiri Rencana Pembangunan Tugu Persaudaraan di Kampung Sawah Kecamatan Pondok Melati', 'wali-kota-hadiri-rencana-pembangunan-tugu-persaudaraan-di-kampung-sawah-kecamatan-pondok-melati', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi membuka Musyawarah rencana pembangunan Tugu di Kampung Sawah Kecamatan Pondok Melati, pada hari Sabtu, 29/04/2017 di Kantor Kecamatan Pondok Melat', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi membuka Musyawarah rencana pembangunan Tugu di Kampung Sawah Kecamatan Pondok Melati, pada hari Sabtu, 29/04/2017 di Kantor Kecamatan Pondok Melati didampingi Camat Pondok Melati, Ika Indahyarti</p>\n\n<p>Mengusung tema &quot;Kampung Sawah, Kampung Pancasila, Kampung Persaudaraan&quot; dan sekaligus deklarasi pembangunan tugu pancasila di dalam Kampung Sawah, rencana ini akan berlansung jika sudah dibangun akan di undang Presiden Republik Indonesia, Ir. Joko Widodo agar beliau mengetahui bahwa kondisi di Kota Bekasi telah memiliki simbol kerukunannya melalui pancasila, dan juga setelah mendapatkan penghargaan dari Komnas Ham dari 3 kota yang berada di Indonesia yakni Kota Manado, Kota Bandung dan Kota Bekasi meraih penghargaan Kota dengan Kerukunan Umat Beragama, maka dibentuklah tugu tersebut.</p>\n\n<p><br />\nWali Kota Bekasi memaparkan bahwa Kota Bekasi dalam lembaga survey yang telah diterima hasilnya, kini Suku Jawa sudah mencapai 43% yang sudah hampir setengah penduduk Kota Bekasi, ini merupakan satu bukti bahwa Kota Bekasi sudah tidak lagi menjadi Kaum Minoritas dan Mayoritas karena beberapa suku, ras, budaya bahjan agama telah berkependudukan di Kota Bekasi.</p>\n\n<p><br />\n&quot;Hasil survey tersebut membuktikan bahwa Kota Bekasi sudah menjadi satu, tidak ada lagi minoritas milik asli keturunan Bekasi atau betawi, warga dari Jawa, Batak dan berbagai suku sudah menjadi satu untuk menjadi harmonis di Kota Bekasi&quot; papar Rahmat Effendi.</p>\n\n<p><br />\nBerikutnya, Wali Kota juga menyampaikan mengenai program kartu sehat berbasis NIK yang dimiliki oleh Kota Bekasi, fungsinya Kartu tersebut akan berguna di semua rumah sakit milik pemerintah maupun swasta yang telah berkomitmen tidak menolak pasien dengan kartu sehat berbasis NIK, kartu tersebut telah di launching pada Januari 2017, dan sedang dalam proses untuk Lurah, RW, RT yang akan mendata para pemilik Kartu Keluarga di wilayah masing masing.</p>\n\n<p><br />\n&quot; Saya pribadi akan tidak segan segan menutup rumah sakit tersebut jika menolak kartu sehat keluaran pemerintah Kota Bekasi,&quot; tegas Wali Kota.</p>\n\n<p><br />\nWali Kota juga menambahkan bahwa pendirian rumah ibadah baik dari Masjid, gereja maupun lainnya harus memiliki izin mendirikan bangunan (imb) sehingga nantinya tidak lagi ketidakselarasan kedepannya, semua harus memiliki payung hukum.</p>\n\n<p><br />\n&quot;Tugu Kampung Sawah, Kampung Pancasila, Kampung Persaudaraan akan menjadi simbol di Kota Bekasi, dan semoga di wilayah wilayah lain di Kota Bekasi bisa menjadikan contoh di Kampung Sawah,&quot; ujar Wali Kota. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-04-30 04:15:00', '2017-04-30 04:15:00', NULL),
('eb3d2038-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'PFRB diharapkan menjadi Organisasi Bidang Sosial', 'pfrb-diharapkan-menjadi-organisasi-bidang-sosial', 'Bekasi, Bagian Humas Setda Kota Bekasi Hadiri Peresmian Organisasi Paguyuban Fans Radio Bekasi (PFRB) Periode 2016-2018 bertempat di Bekasi Trade Center Jl. ,Bekasi, Minggu (30/4) pagi.\n\n\nBagian Humas', '<p>Bekasi, Bagian Humas Setda Kota Bekasi Hadiri Peresmian Organisasi Paguyuban Fans Radio Bekasi (PFRB) Periode 2016-2018 bertempat di Bekasi Trade Center Jl. ,Bekasi, Minggu (30/4) pagi.</p>\n\n<p><br />\nBagian Humas Setda Kota Bekasi di wakili oleh Kasubag Publikasi Eksternal Arie Halimatussadiyyah, S.STP, M.Si, hadir pula Penasehat PFRB Hj. Wiwiek Hilwiyah Arief, parapimpinan radio se-Kota Bekasi serta para anggota Fans Radio Bekasi.</p>\n\n<p><br />\nDjana Ketua PFRB &nbsp;mengatakan Paguyuban telah berdiri sejak 10 September 2004 yang merupakan tempat berkumpulnya masyarakat yang sering mendengarkan radio-radio yang ada di Bekasi, namum selama ini belum berbentuk organisasi sehingga tidak dapat melakukan kegiatan atau pemberia bantuan kepada anggota maupun masyarakat secara maksimal.</p>\n\n<p><br />\nDengan adanya paguyuban ini kami telah melakukan banyak kegiatan-kegiatan untuk anggota maupun masyarakat diantaranya pemberian bantuan kepada warga yang terkena penyakit kanker dan warga yang memerlukan dana untuk cuci darah, diharapkan setelah menjadi organisasi kami akan lebih banyak lagi melakukan hal-hal sosial lainnya.</p>\n\n<p><br />\nDalam sambutannya Kasubag Publikasi Eksternal Arie Halimatussadiyyah menyapaikan pesan dari Bapak Wali Kota Bekasi Rahmat Effendi yang mengharapkan paguyuban Fans Radio Bekasi Dapat Bergerak di bidang sosial yang merupakan wadah komunitas tempat berkumpul masyarakat yang mendengarkan radio-radio di Bekasi sehingga informasi dan komunikasi khusunya program pembangunan yang dilakukan oleh Pemerintah Kota Bekasi dapat tersampaikan.</p>\n\n<p><br />\n&quot;Kami Pemerintah Kota Bekasi berharap dengan adanya Paguyuban Fans Radio Bekasi ini dapat bermanfaat khususnya untuk masyarakat Kota Bekasi, sehingga Visi Misi Kota Bekasi yang Maju Sejahtera dan Ihsan dapat terwujud&quot; tambahnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-01 13:33:00', '2017-05-01 13:33:00', NULL),
('eb3d2088-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'ASDA I Hadiri Peringatan May Day Di Alun - Alun Kota Bekasi', 'asda-i-hadiri-peringatan-may-day-di-alun-alun-kota-bekasi', 'Bekasi, Asisten Pemerintahan Pemerintah Kota Bekasi menghadiri peringatan Hari Buruh Internasional Tingkat Kota Bekasi di Alun-alun Kota Bekasi Jl. Veteran Kota, Bekasi Selatan, Senin (1/5) pagi.\n\nHad', '<p>Bekasi, Asisten Pemerintahan Pemerintah Kota Bekasi menghadiri peringatan Hari Buruh Internasional Tingkat Kota Bekasi di Alun-alun Kota Bekasi Jl. Veteran Kota, Bekasi Selatan, Senin (1/5) pagi.</p>\n\n<p>Hadir pada peringatan ini unsur Forkominda, para pejabat Eselon 2 dan 3 di Lingkungan Pemkot Bekasi, Para Ketua Dewan Pimpinan Cabang Serikat Pekerja/Serikat Buruh se-Kota Bekasi serta unsur Polres Metro Bekasi.</p>\n\n<p>Asda I Pemkot Bekasi mengatakan bahwa buruh atau pekerja mempunyai peran yang sangat strategis untuk menentukan berhasil atau tidaknya pembangunan, juga sebagai modal pertama dan utama pembangunansehingga perlu mendapatkan perhatian sesuai dengan martabatnya sebagai manusia.</p>\n\n<p>&quot;Upah Minimum Kota Bekasi pada tahun 2016 mencapai 3,3 jt dan di tahun 2017 naik menjadi 3,6 jt, ada kenaikan 8,25 persen, pemerintah melalui Dinas Tenaga Kerja akan melakukan monitoring upah sebagainya salah satu indikator salam penetapan upah&quot; ujarnya.</p>\n\n<p>&quot;Kita bersiap untuk menghadapi Masyarakat Ekonomi Asean (MEA), sehingga diperlukan strategi yang harus dimiliki bersama diantaranya adalah pertama penguatan daya saing global, kedua pengamanan pasar domestik dan ketiga penguatan ekspor&quot; tambahnya.</p>\n\n<p>&quot;Sekali lagi saya ucapkan Selamat Hari Buruh Untuk Para Buruh Indonesia, jadilah buruh yang cerdas, ulet, rajin, mandiri dan jujur, semoga kedepannya nasib para Buruh Indonesia menjadi lebih baik dan lebih sejahtera lagi&quot; pungkasnya.&nbsp;</p>\n\n<p>Pada peringatan ini Dinas Tenaga Kerja Kota Bekasi bekerjasama dengan beberapa Perusahaan menyediakan doorprice utama 4 buah sepeda gunung dan berapa hadiah hiburan untuk para buruh yang hadir dalam peringatan ini (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-01 13:35:00', '2017-05-01 13:35:00', NULL),
('eb3d20d6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Ajak Investor Pindahkan Kantornya di Kota Bekasi', 'wali-kota-bekasi-ajak-investor-pindahkan-kantornya-di-kota-bekasi', 'Kota Bekasi - &nbsp;Laju perekonomian Pemerintah Republik Indonesia yang meningkat berdampak positif pada perkembangan ekonomi kota megapolitan salah satunya Kota Bekasi.\n\nLaju inflasi yang rendah men', '<p>Kota Bekasi - &nbsp;Laju perekonomian Pemerintah Republik Indonesia yang meningkat berdampak positif pada perkembangan ekonomi kota megapolitan salah satunya Kota Bekasi.</p>\n\n<p>Laju inflasi yang rendah menjadi daya tarik tersendiri bagi para investor untuk memindahkan kantor pusatnya di Kota Bekasi. &quot; Tidak hanya itu yang menjadi daya tarik jalur transportasi yang terintegrasi juga dapat menjadi bahan pertimbangan investor untuk menanamkan investasinya di Kota Bekasi, &quot; rayu Wali Kota Bekasi DR. Rahmat Effendi.</p>\n\n<p>Dengan jumlah penduduk yang 2.6 juta, tambahnya, dan mayoritas masyarakat kota bekasi bekerja di DKI Jakarta menjadi salah satu solusi untuk memecah kemacetan yang kerap terjadi di ibu kota negara.</p>\n\n<p>Dalam hal ini saya sangat mengapresiasi pihak Management dari pihak gold coin yang telah memindahkan kantor pusatnya ke kota bekasi, ungkapnya pada saat melakukan Inspeksi Mendadak (Sidak) perusahaan gold coin, Selasa, 2/5.</p>\n\n<p>&quot; jadi jangan kantornya di Jakarta pabrik nya disini, kalo sudah ada masalah terkait limbah Pemerintah daerah yang disalahkan oleh masyarakat, &quot; ucapnya.</p>\n\n<p>Kalau kantornya sudah disini, lanjutnya, otomatis pajaknya kan masuk ke dalam Pendapatan Asli Daerah Kota Bekasi dan pemecahannya mari kita tangani secara bersama melalui mekanisme yang berlaku.</p>\n\n<p>Wali Kota juga berpesan dalam kesempatan ini agar investor tidak melupakan kewajiban dalam melaksanakan Civil Social Responbilty( CSR ) sehingga masyarakat yang Maju Sejahtera dan Ihsan di kota bekasi dapat kita wujudkan bersama.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-03 02:08:00', '2017-05-03 02:08:00', NULL),
('eb3d2126-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'APBD 2017', 'apbd-2017', 'APBD 2017 &nbsp; &nbsp; Lihat/Unggah\n\nLampiran Perda No 01 Tahun 2017&nbsp;tentang Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2017\n&nbsp;\nLampiran I &nbsp; &nbsp;Lihat/Unggah\n&nbsp;\nLampira', '<p>APBD 2017 &nbsp; &nbsp; <a href=\"https://drive.bekasikota.go.id/index.php/s/lkJbABxRaOrvjEZ\">Lihat/Unggah</a></p>\n\n<p>Lampiran Perda No 01 Tahun 2017&nbsp;tentang Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2017<br />\n&nbsp;<br />\nLampiran I &nbsp; &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/hdSuuhJDDtIFUZI\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran II &nbsp; &nbsp; <a href=\"https://drive.bekasikota.go.id/index.php/s/Ji1y2ORfgsv329d\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran IIa &nbsp; <a href=\"https://drive.bekasikota.go.id/index.php/s/DOPa6lGfsdg4Z5L\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran III : Per SKPD &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/tKziXJWoiqyMe19\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran IV &nbsp; <a href=\"https://drive.bekasikota.go.id/index.php/s/j1Ihleaen3D9kYq\">Lihat/Unggah</a><br />\n&nbsp;<br />\nPERWAL 2017 &nbsp;&nbsp;&nbsp;&nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/zGOv849Kj6P1Mhd\">Lihat/Unggah</a></p>\n\n<p>Lampiran I &nbsp; &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/ExBzKrczFQAWfr5\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran Ia&nbsp; &nbsp; &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/Ya1QVcnz7Vm69aU\">Lihat/Unggah</a><br />\n&nbsp;<br />\nLampiran II&nbsp; &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/PBhAROCRhjj1Lq8\">Lihat/Unggah</a></p>\n\n<p>&nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-03 03:57:00', '2017-05-03 03:57:00', NULL),
('eb3d2178-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Hibah dan Bansos pada APBD TA 2017', 'hibah-dan-bansos-pada-apbd-ta-2017', '1. Lampiran III Peraturan Walikota Bekasi Nomor 04&nbsp;Tahun 2017&nbsp; &nbsp;Lihat/Unggah\n\n2. Lampiran IV Peraturan Walikota Bekasi Nomor 04&nbsp;Tahun 2017&nbsp;&nbsp;&nbsp;Lihat/Unggah\n', '<p>1. Lampiran III Peraturan Walikota Bekasi Nomor 04&nbsp;Tahun 2017&nbsp; &nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/ksKvaIHryxx7f0F\">Lihat/Unggah</a></p>\n\n<p>2. Lampiran IV Peraturan Walikota Bekasi Nomor 04&nbsp;Tahun 2017&nbsp;&nbsp;&nbsp;<a href=\"https://drive.bekasikota.go.id/index.php/s/0CND6im1ao3BckS\">Lihat/Unggah</a></p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-03 07:06:00', '2017-05-03 07:06:00', NULL),
('eb3d2292-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Think Out Of The Box Pesan Wali Kota Bekasi', 'think-out-of-the-box-pesan-wali-kota-bekasi', 'Kota Bekasi - Birokrasi merupakan instrumen penting dalam masyarakat modern yang kehadiran nya tak mungkin terelakkan. Birokrasi yang baik dan efektif harus ditunjang oleh Aparatur Sipil Negara ( ASN)', '<p>Kota Bekasi - Birokrasi merupakan instrumen penting dalam masyarakat modern yang kehadiran nya tak mungkin terelakkan. Birokrasi yang baik dan efektif harus ditunjang oleh Aparatur Sipil Negara ( ASN) yang profesional dan berkompeten.</p>\n\n<p>Untuk menunjang hal tersebut Badan Kepegawaian Pendidikan dan Kepegawaian Daerah ( BKPPD) melaksanakan kegiatan pembinaan motivasi kerja dalam rangka reposisi pejabat struktural Esselon IV di lingkungan Pemerintah Daerah Kota Bekasi, Rabu, 3/5.</p>\n\n<p>Motivasi yang dilaksanakan di Aula serba guna yayasan pendidikan Al- Azhar, Medan Satria, di ikuti oleh seluruh pejabat Esselon IV di lingkup Pemda yang berjumlah 130 orang.</p>\n\n<p>Wali Kota Bekasi DR. Rahmat Effendi dalam motivasinya mengatakan kita sebagai ASN harus mulai berubah cara pandang dan mereformasi tentang cara birokrasi kita, &quot; Think Out Of The Box &quot;, ucap nya.&nbsp;</p>\n\n<p>Peran para pejabat sebagai motor penggerak administrasi harus dapat membangun sikap mental yang sehat dan positif, serta mampu berpikir dan bekerja cerdas, jelasnya.</p>\n\n<p>Tugas seorang pejabat adalah mampu mengarahkan para stafnya untuk berubah untuk melakukan tindakan yang sesuai dengan tugas masing-masing, &quot; kemampuan dan ketrampilan dalam berkomunikasi, juga sangat diperlukan, &quot; ucap nya.</p>\n\n<p>Saya berharap, semua pejabat mampu membuat pembaharuan dalam mengakselerasi kan capaian visi dan misi Kota Bekasi yang maju, Sejahtera dan Ihsan.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-03 08:15:00', '2017-05-03 08:15:00', NULL),
('eb3d2340-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sambut Hari Pendidikan Wali Kota Bekasi Kunjungi Sekolah Dasar', 'sambut-hari-pendidikan-wali-kota-bekasi-kunjungi-sekolah-dasar', 'Kota Bekasi - &nbsp;Tanggal 2 Mei dimaknai sebagai Hari Pendidikan Nasional disambut penuh suka cita oleh seluruh elemen pendidikan mulai dari seluruh tenaga pendidik dan murid.\n\nDalam menyambut Hari ', '<p>Kota Bekasi - &nbsp;Tanggal 2 Mei dimaknai sebagai Hari Pendidikan Nasional disambut penuh suka cita oleh seluruh elemen pendidikan mulai dari seluruh tenaga pendidik dan murid.</p>\n\n<p>Dalam menyambut Hari pendidikan Nasional Wali Kota Bekasi Sekolah Dasar Negri 07 yang berlokasi di Kayu Ringin. Kunjungan yang dilaksanakan secara mendadak ini dimaksudkan melihat secara langsung proses belajar dan mengajar yang dilaksanakan disekolah tersebut.</p>\n\n<p>Pada kesempatan ini, Wali Kota juga melihat kondisi bangunan sekolah dimana pada Lokasi tersebut terdapat beberapa sekolah dasar Negri yaitu SDN 07, SDN 03 , SDN 17 yang saling berdampingan.</p>\n\n<p>Sekolah yang dipisahkan oleh pagar pembatas tersebut agar di hilang kan sehingga semua murid dapat leluasa bermain pada saat jam istirahat.</p>\n\n<p>Wali Kota juga meminta agar kepala sekolah dasar tersebut memperbaiki sarana dan Prasana perpustakaan, &quot; karna masyarakat yang maju tidak lepas dari masyarakat yang cerdas,&quot; ungkapnya.</p>\n\n<p>Perpustakaan sebagai sarana mencerdaskan generasi bangsa tidak lepas dari peran serta tenaga pengajar,&quot; pengajar memiliki andil yang sangat besar dalam mendidik karakter anak, &quot; lanjutnya.</p>\n\n<p>Gimana guru - gurunya baik apa galak, tanyanya kepada murid murid, &quot; baik &quot; jawab mereka dengan serentak,&quot; kalo semuanya pada baik nanti di 2018 tunjangannya akan bapak naikkan,&quot; jawab Wali Kota.</p>\n\n<p>Dalam kesempatan ini Wali Kota berpesan kepada tenaga pengajar agar meningkatkan kualitas pengajaran untuk mencetak generasi yang cerdas sehingga kota yang kita idamkan yang maju,sejahtera dan Ihsan dapat terwujud secara berkesinambungan. ( tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-03 13:03:00', '2017-05-03 13:03:00', NULL),
('eb3d23e7-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sidak Kelurahan Perwira, Wali Kota Tegaskan ASN Datang Sesuai Jam Kerja', 'sidak-kelurahan-perwira-wali-kota-tegaskan-asn-datang-sesuai-jam-kerja', 'Kota Bekasi --- Sebelum menghadiri acara di Kantor Kecamatan Bekasi Utara, Wali Kota Bekasi, Dr. Rahmat Effendi bersama Camat Bekasi Utara, Lukmanul Hakim mengadakan Inspeksi mendadak ke Kantor Kelura', '<p>Kota Bekasi --- Sebelum menghadiri acara di Kantor Kecamatan Bekasi Utara, Wali Kota Bekasi, Dr. Rahmat Effendi bersama Camat Bekasi Utara, Lukmanul Hakim mengadakan Inspeksi mendadak ke Kantor Kelurahan Perwira untuk melihat proses pelayanan di Kelurahan tersebut pada hari Kamis (04/05/2017) tepat pukul 09.00 WIB.</p>\n\n<p><br />\nPada saat memasuki kantor, Wali Kota sempat berinteraksi dengan beberapa warga yang sedang menunggu antrian, Wali Kota menanyakan sedang membuat surat mengenai apa, Ibu yang sedang menunggu menjawab membuat e-ktp dan langsung memanggil petugas yang membuat pada bagian tersebut, akan tetapi petugas tersebut belum hadir pada saat itu. Di saat bersamaan Camat Bekasi Utara memanggil Lurah Perwira dan langsung menegur staf kelurahan tersebut agar segera diselesaikan urusannya dengan tidak menunda nunda lagi.</p>\n\n<p><br />\nSelain itu, Wali Kota juga berdialog dengan warga lain yang sedang membuat Kartu Bekasi Sehat, dan dijelaskan fungsinya untuk Kartu Sehat Berbasis NIK tersebut bisa digunakan ke rumah sakit baik milik Pemerintah maupun Swasta, Wali Kota juga menegaskan tidak ada pasien dengan membawa Kartu Sehat Bekasi ditolak.</p>\n\n<p><br />\n&quot;Jika ada pasien sudah membawa kartu sehat ini ditolak, laporkan ke saya, pasti saya tegur dengan tegas, jika masih menolak, saya akan tutup rumah sakit tersebut&quot; tegas Wali Kota menjelaskan kepada warga.</p>\n\n<p><br />\nWali Kota meminta data kepada warga yang sedang mengurus kartu Bekasi Sehat dan menjanjikan sore ini sudah jadi dan tidak di tunda tunda. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-04 08:16:00', '2017-05-04 08:16:00', NULL),
('eb3d2448-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Peresmian Al-Fursan Islamic School, Wali Kota Apresiasi Pendirian Sekolah Islam di Kota Bekasi.', 'peresmian-al-fursan-islamic-school-wali-kota-apresiasi-pendirian-sekolah-islam-di-kota-bekasi', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara peresmian Sekolah Islam Baru yakni Al- Fursan Islamic School yang berada di Kecamatan Jatiasih pada hari Kamis (04/05/2017), did', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara peresmian Sekolah Islam Baru yakni Al- Fursan Islamic School yang berada di Kecamatan Jatiasih pada hari Kamis (04/05/2017), didampingi oleh Camat Jatiasih, Nessan Sujana.</p>\n\n<p><br />\nDalam sambutannya, Wali Kota sangat mengapresiasikan pembangunan sekolah islam tersebut karena menambah daya tampung dalam bidang pendidikan di Kota Bekasi dan pastinya akan mencetak para siswa dan siswi untuk kedepannya di Kota Bekasi.</p>\n\n<p><br />\n&quot;Diharapkan kepada Al Fursan Islamic School bisa memberikan kontribusi untuk masyarakat Kota Bekasi dalam pendidikan,&quot; Jelas Wali Kota.</p>\n\n<p><br />\nWali Kota berpesan kepada para invenstor investor yang ingin menanamkan modalnya di Kota Bekasi agar bisa menjadi salah satu pengembang yang bisa memajukan Kota Bekasi dalam Visi Misi nya, karena Kota Bekasi telah pesat berkembang dalam bidang pembangunan.</p>\n\n<p><br />\nSelain itu, Wali Kota juga mengingatkan untuk hidup secara harmonis baik.dari segi beragama budaya serta golongan untuk tidak membeda bedakan antar warga Kot Bekasi, tidak ada minoritas dan mayoritas karena semua warga Kota Bekasi. (ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-04 22:07:00', '2017-05-04 22:07:00', NULL),
('eb3d2499-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'WAWALI HADIRI WISUDA DAN PELANTIKAN 179 LULUSAN SMK BINA HUSADA MANDIRI', 'wawali-hadiri-wisuda-dan-pelantikan-179-lulusan-smk-bina-husada-mandiri', 'Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri Wisuda dan Pelantikan 179 orang lulusan dari SMK Bina Husada Mandiri bertempat Gedung Mahkamah Konstitusi Jalan RA Kartini No.22 - 24, Sepanjang', '<p>Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri Wisuda dan Pelantikan 179 orang lulusan dari SMK Bina Husada Mandiri bertempat Gedung Mahkamah Konstitusi Jalan RA Kartini No.22 - 24, Sepanjang Jaya, Bekasi, Kamis (4/5) pagi.</p>\r\n\r\n<p>Di awal sambutannya Wawali sempatkan berpantun untuk&nbsp; para wisudawan dan wisudawati yang pantunya &ldquo;pergi wisata ke taman bunga, lihat bungan indah berseri, alangkah bahagia yang di wisuda, semoga sukses mengukir prestasi&rdquo;.</p>\r\n\r\n<p>&ldquo;Saya dan Pemerintah Kota Bekasi mengapresiasi SMK Bina Husada Mandiri yang tahun ini telah melahirkan 179 lulusan dan secara total keseluruhan ada 786&nbsp; yang telah berhasil lulus dan hampir 75 persen telah masuk dalam dunia kerja&rdquo; ujarnya.</p>\r\n\r\n<p>&ldquo;Ini merupakan pecetakan lapangan kerja yang luar biasa dan tentunya ini sejalan dengan Visi Pemerintah Kota Bekasi, Maju Sejahtera dan Ihsan. Kemajuan kita coba dengan menata dan memperbaiki infrastruktur secara terus-menerus, kemudian kesejahteraan akan sangat tergantung kepada bagaimana masyarakat bekerja dan mendapatkan penghasilan&rdquo; tambahnya.</p>\r\n\r\n<p>&ldquo;Saya yakin kalau dari 179 orang 75 persennya bekerja kemudian mendapatkan penghasilan sendiri maka kalian sudah mulai menata kesejahteraan untuk sukses di masa depan&rdquo; imbuhnya.</p>\r\n\r\n<p>Wawali menyampaikan juga bahwa saat ini sedang berusaha memasifkan ekonomi syariah bagi masyarakat Kota Bekasi, karena kita mempunyai beban dan tanggung jawab untuk mencapai visi ihsan, yaitu bagaimana nilai religiusitas tumbuh, hidup dan berkembang di tengah masyarakat Kota Bekasi.</p>\r\n\r\n<p>Beliau juga berpesan walaupun kalian sudah menyelesaikan pendidikan maka janganlah kalian berhenti membaca buku atau selesai membaca buku, hidupkan terus tradisi literasi kalian karena karya-karya yang besar akan bisa kalian lahirkan ketika kalian terus dapat mengikuti perkembangan-perkembangan keilmuan.</p>\r\n\r\n<p>&ldquo;Apa yang telah dibekalkan oleh orang tua dan guru-guru, hanya digunakan untuk perkembangan saat ini, sedangkan yang namanya dunia keperawatan, dunia analis farmasi dan dunia perbankkan syarian ini yang akan terus berkembang dan kalian harus mengikuti perkembangannya sehingga dapat mengantarkan kalian kepada prestasi puncak&rdquo; ujarnya</p>\r\n\r\n<p>Kepada orang tua siswa Wakil Walikota Bekasi mengucapkan selamat karena anak-anaknya telah berhasil dan sukses menyelesaikan pendidikan di SMK ini , mudah-mudahan kesuksesan ini akan terus berlanjut sampai ke dunia kerja, sukses sampai dengan tingkat pendidikan akademis selanjutnya dan juga bisa menghasilkan karya-karya yang lebih besar lagi.</p>\r\n\r\n<p>Pada akhir sambutannya Wawali Ahmad Syaikhu juga menutup dengan pantun, &ldquo;ngajak besan naik kereta, turun di stasiun Jatinegara, jangan bosan kita berkaya, agar hidup lebih sejahtera&rdquo;. (gie)</p>', 'images/20170823073457-2017-08-23post073456.jpg', NULL, NULL, 3506, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-04 22:11:00', '2017-05-04 22:11:00', NULL),
('eb3d24e8-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wagub Jabar Dan Wawali Nobar Film SETERU Bersama 1.160 Pelajar SMAN Kota Bekasi ', 'wagub-jabar-dan-wawali-nobar-film-seteru-bersama-1-160-pelajar-sman-kota-bekasi', 'Bekasi, Wakil Gubernur Jawa Barat Dedy Mizwar dan Wakil Wali Kota Bekasi Ahmad Syaikhu nonton bareng (nobar) Film SETERU bersama dengan 1.160 pelajar SMAN di XXI Mega Bekasi Hypermall Bekasi, Kamis (4', '<p>Bekasi, Wakil Gubernur Jawa Barat Dedy Mizwar dan Wakil Wali Kota Bekasi Ahmad Syaikhu nonton bareng (nobar) Film SETERU bersama dengan 1.160 pelajar SMAN di XXI Mega Bekasi Hypermall Bekasi, Kamis (4/5) siang.</p>\n\n<p>Penggagas kegiatan ini adalah Bank Pembangunan Daerah BJB yang bertujuan berkomitmen untuk membangun bangsa Indonesia dan memahami Negeri, serta memperkenalkan semangat nasionalisme dalam bentuk bela Negara kepada generasi muda</p>\n\n<p>Wakil Gubernur Jawa Barat Deddy Muzwar sangat mengapresiasi kehadiran para pelajar untuk menonton film yang bertemakan bela negara, yang memang film untuk remaja yang bagaimana ceritanya nanti akan merubah paradigma dalam pandangan remaja yang sering tawuran, sering melakukan sesuatu yang diluar kendali sehingga timbul kesadaran bagaimana spirit dan energi yang luar biasa dari pemuda untuk bela negara.</p>\n\n<p>&ldquo;Ini adalah film dengan tema dan misi yang baik, disutradai oleh&nbsp;Hanung Bramanty yang standart kualitasnya terjamin dan kalau memang bagus maka sebarkan kepada teman-teman kalian untuk menonton&rdquo; ungkapnya.</p>\n\n<p>&ldquo;Karena mengapresiasi film Indonesia, berarti kita semua memelihara keberagaman dan kebhinekaan, film adalah cermin dari masyarakat dimana film itu dibuat, inilah sebagian wajah kita yang nanti akan kita tonton&rdquo; imbuhnya</p>\n\n<p>&nbsp;</p>\n\n<p>Sementara itu Wawali Ahmad Syaikhu juga menyampaikan beberapa waktu lalu ada sebagian remaja yang harus meregang nyawa karena dampak tawuran, mudah-mudahan itu kali terakhir yang ada di Kota Bekasi,</p>\n\n<p>&ldquo;Kedepan kita akan terus bersemangat untuk berprestasi, kita jangan terus menerus dibuly dan dibuly tapi kedepan harus semangat, makanya sekarang &ldquo;BEKASI&rdquo; harus menjadi &ldquo;Bersama Kita Raih Prestasi&rdquo;, saya yakin dengan ini semua dapat menginspirasi kita untuk berprestasi&rdquo; ujarnya (ais/gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-04 22:15:00', '2017-05-04 22:15:00', NULL),
('eb3d2537-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Sosialisasi Kartu Sehat Bekasi saat Subuh Keliling di Masjid Raya Ar-Ridlwan Medan Satria', 'wali-kota-sosialisasi-kartu-sehat-bekasi-saat-subuh-keliling-di-masjid-raya-ar-ridlwan-medan-satria', 'Kota Bekasi ---- Pelaksanaan Subuh Keliling di Masjid Ar-Ridlwan, Jalan Sultan Agung, Kecamatan Medan Satria pada hari Jumat (05/05/2017) yang diadakan dari Dewan Masjid Indonesia (DMI) Cabang Kota Be', '<p>Kota Bekasi ---- Pelaksanaan Subuh Keliling di Masjid Ar-Ridlwan, Jalan Sultan Agung, Kecamatan Medan Satria pada hari Jumat (05/05/2017) yang diadakan dari Dewan Masjid Indonesia (DMI) Cabang Kota Bekasi, &nbsp;di hadiri oleh Wali Kota Bekasi, Dr. Rahmat Effendi, Camat Medan Satria, Taufik, serta jajaran Kepala Satuan Kerja Perangkat Daerah (SKPD) lingkup Pemerintah Kota Bekasi.</p>\n\n<p><br />\nWali Kota dalam sambutannya menyampaikan mengenai status Masjid Raya Ar- Ridlwan bahwa telah memiliki surat ketetapan sebagai Masjid Raya, oleh karena itu segala bentuk dana maupun apapun harus dari Pemerintah dan menggunakan dana APBD, sesuai dengan ketentuan Masjid Raya harus dimiliki di tiap tiap Kecamatan untuk menjadi simbol, selain itu Wali Kota juga menegaskan bahwa pendirian Masjid Raya mengenai Izin Mendirikan Bangunan harus dipayungi hukum, untuk itu Asisten Daerah 1 segera lakukan pembuatan izin tersebut.</p>\n\n<p><br />\nMengenai petugas penjaga masjid dan rumah ibadah lainnya, juga harus di perhatikan mengenai insentif dari Pemerintah, termasuk Imam di Masjid agar segera dibuatkan surat serta termasuk para pe jaga rumah ibadah lainnya karena di Kota Bekasi sudah menjadi satu bentuk simbol kerukunan umat beragama yang telah didirikan Majelis Umat Beragama di tiap tiap Kelurahan yang berfungsi sebagai wadah jika terjadi beda pendapat.</p>\n\n<p><br />\nDalam Subuh Keliling menurut Wali Kota bisa juga menjadi ajang silaturahmi sekaligus menyampaikan event event yang ada di Kota Bekasi seperti keberadaan mengenai Kartu Sehat Berbasis NIK yang telah di keluarkan oleh Pemerintah Kota Bekasi sejak 1 Januari 2017, dengan sosialisasi pada subuh keliling bisa diteruskan kepada warga diluar Camat dan Lurah memaparkan saat kunjungan warga.</p>\n\n<p><br />\nUsI sambutan, Wali Kota Bekasi didampingi Camat Medan Satria menandatangani prasasti peresmian pembangunan musholla Ar-Rahmat di Kantor Kecamatan Nedan Satria. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 00:53:00', '2017-05-05 00:53:00', NULL),
('eb3d2587-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Sosialisasi PERMENDAGRI Nomor 3 Tahun 2017 Tingkat Propinsi', 'sosialisasi-permendagri-nomor-3-tahun-2017-tingkat-propinsi', 'Kota Bekasi, -- &nbsp;Diskominfostandi Kota Bekasi menghadiri acara seminar sosialisasi dan Diskusi Peraturan Menteri Dalam Negeri Nomor 3 tahun 2017 di ruang Rapat Papandayan Gedung Sate Kota Bandung', '<p>Kota Bekasi, -- &nbsp;Diskominfostandi Kota Bekasi menghadiri acara seminar sosialisasi dan Diskusi Peraturan Menteri Dalam Negeri Nomor 3 tahun 2017 di ruang Rapat Papandayan Gedung Sate Kota Bandung Propinsi Jawa Barat.(4/5)</p>\n\n<p><br />\nAcara dibuka langsung oleh Gubernur yang &nbsp;diwakilkan oleh Asisten Daerah Hukum dan Sosial &nbsp; Propinsi Jawa Barat Drs. kusmayadi dalam sambutannya menyatakan bahwa didalam era keterbukaan &nbsp;dan transparansi informasi ini kita harus bisa merespon informasi secara maksimal ,karena itu kita disini untuk sharing mengenai permendagri nomor 3 tahun 2017 ungkapnya&quot;.</p>\n\n<p>dan dihadiri oleh Ketua Komisioner Informasi &nbsp;Propinsi Jawa Barat Drs. Dan satriana.sementara itu perwakilan dari Kementrian Dalam Negeri &nbsp;Dr. Handayani Ningrum kabid Fasilitasi pengaduan dan pengelolaan informasi &nbsp;pusat penerangan Sekertaris Jenderal Kementrian Dalam Negeri.</p>\n\n<p>dan Diskominfostandi Kota Bekasi diwakilkan oleh Abdul Hakim Amir S.H Kasie kemitraan dan informasi publik.</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 01:02:00', '2017-05-05 01:02:00', NULL),
('eb3d25d5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Sosialisasi Kartu Sehat Bekasi saat Subuh Keliling di Masjid Raya Ar-Ridlwan Medan Satria', 'wali-kota-sosialisasi-kartu-sehat-bekasi-saat-subuh-keliling-di-masjid-raya-ar-ridlwan-medan-satria-2', 'Kota Bekasi ---- Pelaksanaan Subuh Keliling di Masjid Ar-Ridlwan, Jalan Sultan Agung, Kecamatan Medan Satria pada hari Jumat (05/05/2017) yang diadakan dari Dewan Masjid Indonesia (DMI) Cabang Kota Be', '<p>Kota Bekasi ---- Pelaksanaan Subuh Keliling di Masjid Ar-Ridlwan, Jalan Sultan Agung, Kecamatan Medan Satria pada hari Jumat (05/05/2017) yang diadakan dari Dewan Masjid Indonesia (DMI) Cabang Kota Bekasi, &nbsp;di hadiri oleh Wali Kota Bekasi, Dr. Rahmat Effendi, Camat Medan Satria, Taufik, serta jajaran Kepala Satuan Kerja Perangkat Daerah (SKPD) lingkup Pemerintah Kota Bekasi.</p>\n\n<p><br />\nWali Kota dalam sambutannya menyampaikan mengenai status Masjid Raya Ar- Ridlwan bahwa telah memiliki surat ketetapan sebagai Masjid Raya, oleh karena itu segala bentuk dana maupun apapun harus dari Pemerintah dan menggunakan dana APBD, sesuai dengan ketentuan Masjid Raya harus dimiliki di tiap tiap Kecamatan untuk menjadi simbol, selain itu Wali Kota juga menegaskan bahwa pendirian Masjid Raya mengenai Izin Mendirikan Bangunan harus dipayungi hukum, untuk itu Asisten Daerah 1 segera lakukan pembuatan izin tersebut.</p>\n\n<p><br />\nMengenai petugas penjaga masjid dan rumah ibadah lainnya, juga harus di perhatikan mengenai insentif dari Pemerintah, termasuk Imam di Masjid agar segera dibuatkan surat serta termasuk para pe jaga rumah ibadah lainnya karena di Kota Bekasi sudah menjadi satu bentuk simbol kerukunan umat beragama yang telah didirikan Majelis Umat Beragama di tiap tiap Kelurahan yang berfungsi sebagai wadah jika terjadi beda pendapat.</p>\n\n<p><br />\nDalam Subuh Keliling menurut Wali Kota bisa juga menjadi ajang silaturahmi sekaligus menyampaikan event event yang ada di Kota Bekasi seperti keberadaan mengenai Kartu Sehat Berbasis NIK yang telah di keluarkan oleh Pemerintah Kota Bekasi sejak 1 Januari 2017, dengan sosialisasi pada subuh keliling bisa diteruskan kepada warga diluar Camat dan Lurah memaparkan saat kunjungan warga.</p>\n\n<p><br />\nUsI sambutan, Wali Kota Bekasi didampingi Camat Medan Satria menandatangani prasasti peresmian pembangunan musholla Ar-Rahmat di Kantor Kecamatan Nedan Satria. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 01:05:00', '2017-05-05 01:05:00', NULL),
('eb3d262d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Letakkan Batu Pertama Menara Masjid Jamie Harapan Jaya', 'wali-kota-letakkan-batu-pertama-menara-masjid-jamie-harapan-jaya', 'Kota Bekasi ---- Usai Lakukan Subuh Keliling, Wali Kota Bekasi, Dr. Rahmat Effendi bergegas ke acara berikut yakni meletakkan batu pertama Menara Masjid Jamie Harapan Jaya, Kecamatan Bekasi Utara pada', '<p>Kota Bekasi ---- Usai Lakukan Subuh Keliling, Wali Kota Bekasi, Dr. Rahmat Effendi bergegas ke acara berikut yakni meletakkan batu pertama Menara Masjid Jamie Harapan Jaya, Kecamatan Bekasi Utara pada hari Jumat (05/05/2017), didampingi Sekretaris Kecamatan, Zalaludin dan hadir juga Anggota DPR RI dari Fraksi PKS, Sutriyono.</p>\n\n<p><br />\nSama seperti saat subuh keliling di Masjid Raya Ar-Ridlwan Kecamatan Medan Satria, Wali Kota menyampaikan mengenai status payung hukum yang dimiliki rumah ibadah di antaranya Masjid dan lainnya, harus memiliki dasar hukum pembangunan yang kuat, jika tidak memiliki segera diurus agar kedepannya tidak lagi ada kekeliruan.</p>\n\n<p><br />\nJuga dijelaskan mengenai insentif para penjaga rumah ibadah yang sedang dalam proses, agar para penjaga rumah ibadah tersebut memiliki semangat lebih dalam tugasnya, dan juga ada sedikit perhatian dari Pemerintah Kota Bekasi untuk para marbot dan penjaga rumah ibadah lainnya.</p>\n\n<p><br />\n&quot;Tahun berikutnya, setiap Kelurahan Harus ditetapkan di 56 Kelurahan untuk mempunyai kapasitas Masjid Jami dan juga di Kecamatan memiliki Masjid Raya,&quot; ujar Wali Kota Bekasi.</p>\n\n<p><br />\nKedepannya, Wali Kota mengharapkan adanya penentuan titik titik Masjid Jamie di tiap Kelurahan, dan juga menentukan titik Masjid Raya untuk tiap Kecamatan, dan Kota Bekasi sudah memiliki Masjid Agung Al-barkah sebagai ikon di Kota Bekasi.</p>\n\n<p><br />\nSeusai itu, Wali Kota juga sempat berdialog dengan para anggota Perlindungan Masyarakat (Linmas) Kelurahan Harapan Jaya dan sempat menanyakan mengenai honor dan akan naik sebesar 500 ribu perbulan. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 04:07:00', '2017-05-05 04:07:00', NULL),
('eb3d267d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Berikan Kartu Sehat, Wali Kota Datangkan Ambulance Warga Penderita Infeksi Paru Paru', 'berikan-kartu-sehat-wali-kota-datangkan-ambulance-warga-penderita-infeksi-paru-paru', 'Kota Bekasi --- Jumat (05/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi mengunjungi rumah warga bernama Devi Aryani yang mendapatkan laporan bahwa warga tersebut terinfeksi paru paru yang beralamat d', '<p>Kota Bekasi --- Jumat (05/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi mengunjungi rumah warga bernama Devi Aryani yang mendapatkan laporan bahwa warga tersebut terinfeksi paru paru yang beralamat di Rawa Pasung RT 06/06, Kecamatan Bekasi Barat, Wali Kota mengantarkan sendiri ke kediaman si penderita infeksi paru paru tersebut.</p>\n\n<p><br />\nSaat masuk ke dalam kediaman, rumah dengan mengontrak yang kebetulan kepala keluarga bernama Bapak Surya Wijaya sedang bekerja, hidup 2 orang anak dan ibu Devi Aryani yang terserang penyakit infeksi paru paru yang tidak sanggup berobat.</p>\n\n<p><br />\nWali Kota mengantarkan langsung kartu sehat berbasis NIK ke tangan ibu Devi Aryani yang hanya tergeletak di kasur, setelah berinteraksi bahwa pasien bekum bisa berobat karena biaya, Wali Kota langsung menelpon tim untuk menjemput pasien dan membawanya ke rumah sakit.</p>\n\n<p><br />\nSelain itu, warga juga sempat melaporkan untuk melihat satu masjid yang terbengkalai namun luas, Wali Kota mengintruksikan kepada RT untuk segera membuat laporan ke &nbsp;Pemerintah Kota Bekasi agar bisa masuk dalam anggaran, begitu juga untuk pengumpulan Kartu Bekasi Sehat agar warga yang membutuhkan bisa mendapatkannya. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 08:01:00', '2017-05-05 08:01:00', NULL),
('eb3d26cf-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Hadir Dalam Sholat Jumat Keliling di Masjid Nurani Kelurahan Kranji', 'wali-kota-hadir-dalam-sholat-jumat-keliling-di-masjid-nurani-kelurahan-kranji', 'Kota Bekasi ---- Rangkaian Sholat Jumat Keliling dari Pemerintah Kota Bekasi bertempatan di Masjid Nurani, Kelurahan Kranji Kecamatan Bekasi Barat pada Jumat (05/05/2017) didampingi Kepala Badan Kesba', '<p>Kota Bekasi ---- Rangkaian Sholat Jumat Keliling dari Pemerintah Kota Bekasi bertempatan di Masjid Nurani, Kelurahan Kranji Kecamatan Bekasi Barat pada Jumat (05/05/2017) didampingi Kepala Badan Kesbangpol, H. Abdillah, Sekretaris Kecamatan, Supomo dan Lurah Kranji, Andy.</p>\n\n<p><br />\nDalam Kunjungannya, Wali Kota tetap mensosialisasikan bahwa warga Kota Bekasi harus memiliki Kartu Sehat Berbasis NIK, tidak memandang sudut berada ataupun tidak, kartu tersebut bisa dimiliki satu kepala keluarga dan bisa dipakai untuk nama yang tercantum.</p>\n\n<p><br />\nProgram program Pemerintah Kota Bekasi seperti Subuh Keliling, Jumat Keliling, sampai Maghrib Keliling dan nantinya ada Tarawih Keliling itu merupakan satu cara untuk mendekatkan tali silaturahmi sekaligus mempromokan event event yang ada di Kota Bekasi seperti pembuatan Kartu sehat Berbasis NIK.</p>\n\n<p><br />\nDilain itu, Insentif yang dimiliki para RT dan RW akan dicanangkan dan telah diproses pada 2018 nanti naik honornya sebesar 2 juta untuk RT dan 2,5 juta untuk RW, dimana maksudnya untuk bekerja lebih untuk salah satunya untuk terjun langsung mendata mengenai kebutuhan warga baik kartu bekasi sehat maupun pelayanan lainnya.</p>\n\n<p><br />\n&quot;Lurah dan Camat terjun langsung ke warga, jangan selalu duduk di kantor, karena dengan melihat langsung ke wilayah kita tau apa yang dibutuhkan warga&quot; tegas Wali Kota. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-05 08:10:00', '2017-05-05 08:10:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d271d-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Keliling Antarkan Langsung Kartu Sehat Bekasi Ke Rumah Warga di Bekasi Utara.', 'wali-kota-keliling-antarkan-langsung-kartu-sehat-bekasi-ke-rumah-warga-di-bekasi-utara', 'Kota Bekasi ---- Sabtu Pagi (06/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi memulai kegiatan dengan berkeliling untuk mengantarkan Kartu Bekasi Sehat Berbasis NIK keluaran dari Pemerintah Kota Beka', '<p>Kota Bekasi ---- Sabtu Pagi (06/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi memulai kegiatan dengan berkeliling untuk mengantarkan Kartu Bekasi Sehat Berbasis NIK keluaran dari Pemerintah Kota Bekasi yang telah diluncurkan pada Januari 2017, Wali Kota mengantarkan Kartu Sehat Bekasi tersebut dimulai di Kelurahan Padurenan dan di berikan ke koordinator warga untuk segera sampai ke tangan warga.</p>\n\n<p><br />\nUsai dari Padurenan, Wali Kota menuju Kecamatan Bekasi Utara tepatnya di RW 09 Villa Mas Garden untuk mengantar 2 kartu sehat yang sudah jadi, atas nama Kepala Keluarga Bapak Supadi ya g diterima oleh istrinya beralamt di RT.04/RW.09 Villa Mas Garden Kecamatan Bekasi Utara, kedua atas nama Bapak Sugiyanto dan diterima langsung olehnya, beralamat di RT.03/03 Villa Mas Garden.</p>\n\n<p><br />\nDalam penyerahannya, Wali Kota mengharapkan agar Kartu tersebut berguna untuk warga sakit, walaupun tidak bermaksud untuk sakit, fungsi kartu tersebut telah berlaku di semua rumah sakit yang ada di Kota Bekasi dan secara gratis untuk pembayarannya, karena berdasarkan pembayaran pajak oleh warga Kota Bekasi, Wali Kota Bekasi bersama Camat Bekasi Utara, Lukmanul Hakim yang diintruksikan agar segera mendata para warga untuk di buat kan Kartu Sehat.</p>\n\n<p><br />\nSelanjutnya, Wali Kota berlanjut ke Taman Wisma Asri ke kediaman ibu Sri Wahyuni di alamat Blok C6 Rt.03/03 Keclurahan Teluk Pucung Kecamatan Bekasi Utara, saat usai diberikan kartu sehat, Wali Kota diajak keliling bersama warga untuk melihat Musolla yang belum jadi pembangunannya dikarenakan dana yang kurang, Wali Kota mengintruksikan Sekretaris Kecamatan, Zalaludin untuk dikirimkan proposal ke Kantor Wali Kota agar bisa masuk dana apbd untuk melanjutkan pembangunan Musolla Nurul Hikmah, dan terakhir warga mengahak ke Lapangan Futsal yang di area Kantor Sekretaiat RW yang sudah rusak bagian lapangannya, dan akan segera ditindaklanjuti agar masuk dalam anggaran pemerintah Kota. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-06 05:11:00', '2017-05-06 05:11:00', NULL),
('eb3d276b-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Keliling Antarkan Langsung Kartu Sehat Bekasi Ke Rumah Warga di Bekasi Utara', 'wali-kota-keliling-antarkan-langsung-kartu-sehat-bekasi-ke-rumah-warga-di-bekasi-utara-2', 'Kota Bekasi -&nbsp;Sabtu Pagi (06/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi memulai kegiatan dengan berkeliling untuk mengantarkan Kartu Bekasi Sehat Berbasis NIK keluaran dari Penerintah Kota Be', '<p>Kota Bekasi -&nbsp;Sabtu Pagi (06/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi memulai kegiatan dengan berkeliling untuk mengantarkan Kartu Bekasi Sehat Berbasis NIK keluaran dari Penerintah Kota Bekasi yang telah diluncurkan pada Januari 2017, Wali Kota mengantarkan Kartu Sehat Bekasi tersebut dimulai di Kelurahan Padurenan dan di berikan ke koordinator warga untuk segera sampai ke tangan warga.</p>\n\n<p>Usai dari Padurenan, Wali Kota menuju Kecamatan Bekasi Utara tepatnya di RW 09 Villa Mas Garden untuk mengantar 2 kartu sehat yang sudah jadi, atas nama Kepala Keluarga Bapak Supadi ya g diterima oleh istrinya beralamt di RT.04/RW.09 Villa Mas Garden Kecamatan Bekasi Utara, kedua atas nama Bapak Sugiyanto dan diterima langsung olehnya, beralamat di RT.03/03 Villa Mas Garden.</p>\n\n<p>Dalam penyerahannya, Wali Kota mengharapkan agar Kartu tersebut berguna untuk warga sakit, walaupun tidak bermaksud untuk sakit, fungsi kartu tersebut telah berlaku di semua rumah sakit yang ada di Kota Bekasi dan secara gratis untuk pembayarannya, karena berdasarkan pembayaran pajak oleh warga Kota Bekasi, Wali Kota Bekasi bersama Camat Bekasi Utara, Lukmanul Hakim yang diintruksikan agar segera mendata para warga untuk di buatkan Kartu Sehat.</p>\n\n<p>Selanjutnya, Wali Kota berlanjut ke Taman Wisma Asri ke kediaman ibu Sri Wahyuni di alamat Blok C6 Rt.03/03 Keclurahan Teluk Pucung Kecamatan Bekasi Utara, saat usai diberikan kartu sehat, Wali Kota diajak keliling bersama warga untuk melihat Musolla yang belum jadi pembangunannya dikarenakan dana yang kurang, Wali Kota mengintruksikan Sekretaris Kecamatan, Zalaludin untuk dikirimkan proposal ke Kantor Wali Kota agar bisa masuk dana apbd untuk melanjutkan pembangunan Musolla Nurul Hikmah, dan terakhir warga mengahak ke Lapangan Futsal yang di area Kantor Sekretaiat RW yang sudah rusak bagian lapangannya, dan akan segera ditindaklanjuti agar masuk dalam anggaran pemerintah Kota. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-06 06:30:00', '2017-05-06 06:30:00', NULL),
('eb3d27bb-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Hadiri Pelantikan Pengurus Pemuda Katolik Cabang Kota Bekasi', 'wali-kota-hadiri-pelantikan-pengurus-pemuda-katolik-cabang-kota-bekasi', 'Kota Bekasi -&nbsp;Acara Pelantikan Pengurus Pemuda Katolik Komisariat Cabang Kota Bekasi di Gedung Karya Pastoral St. Bartolomeus, Kecamatan Bekasi Selatan pada hari Sabtu (06/05/2017), Wali Kota Bek', '<p>Kota Bekasi -&nbsp;Acara Pelantikan Pengurus Pemuda Katolik Komisariat Cabang Kota Bekasi di Gedung Karya Pastoral St. Bartolomeus, Kecamatan Bekasi Selatan pada hari Sabtu (06/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi di undang untuk memberikan sambutan sekaligus menyaksikan pelantikan pengurus tersebut.</p>\n\n<p>Hadir juga Kepala Badan Kesbangpol Kota Bekasi, H. Abdillah, Ketua FKUB Kota Bekasi, H. Abdul Manan, dan juga Ketua Umum Pengurus Pusat Pemuda Katolik, dr. Karolin Margaret Natasa, Ketua Umum Pemuda Pancasila Kota Bekasi, Ariyes, Ketua KNPI Kota Bekasi, Gilang Esa serta Ketua terpilih Cabang Pemuda Katolik Kota Bekasi, R. Andreas.</p>\n\n<p>Dalam Sambutannya, Wali Kota Bekasi mengharapkan kepada Ketua Terpilih bisa lakukan interaksi dengan para Ketua (OKP) baik dari KNPI, Pemuda Pancasila, juga berkoordinasi dengan HMI, KAHMI, serta lainnya, agar bisa bersinergi untuk tetap membantu dalam pencapaian Visi Kota Bekasi yang maju, sejahtera, dan Ihsan.</p>\n\n<p>Selain itu, Kota Bekasi telah mencapai penghargaan dari Komnas Ham mengenai kerukunan umat beragama, dan menjadi target Kota Bekasi sebagai miniatur kerukunan umat beragama di Indonesia, yang tidak membeda bedakan agama, suku, ras dan budaya, semua berhak berdiri di Kota Bekasi sebagai warga.</p>\n\n<p>Wali Kota berpesan setelah pelantikan ini, di harapkan ikut berpartisipasi dengan Majelis Umat Beragama yang telah terbentuk di 56 Kelurahan, dan 12 Kecamatan dan ada Forum Kerukunan Umat Beragama di wilayah Kota Bekasi.</p>\n\n<p>&quot;Jika terjadi permasalahan ataupun apapun bisa dirembukan di MUB Kelurahan masing masing, agar bisa memecahkan solusi dari tiap perbedaan&quot; ujar Rahmat Effendi. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-06 06:33:00', '2017-05-06 06:33:00', NULL),
('eb3d280c-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '                        Wali Kota Bekasi laksanakan Subuh Keliling dan Peringatan Isra dan Mira\'j', 'wali-kota-bekasi-laksanakan-subuh-keliling-dan-peringatan-isra-dan-mira-j', 'Kota Bekasi - Untuk mempererat tali silahturahmi antara pemimpin, alim ulama dan masyarakat Wali Kota Bekasi laksanakan subuh keliling dan peringatan Isra Mira&#39;j yang dilakukan di dua tempat berbe', '<p>Kota Bekasi - Untuk mempererat tali silahturahmi antara pemimpin, alim ulama dan masyarakat Wali Kota Bekasi laksanakan subuh keliling dan peringatan Isra Mira&#39;j yang dilakukan di dua tempat berbeda, Minggu, 7/5.</p>\n\n<p>Wali Kota Bekasi DR. Rahmat Effendi dalam sambutannya pada saat memperingati Isra dan Mira&#39;j Nabi Muhammad SAW di masjid at taqwa mengatakan peran alim dan ulama sangat penting untuk membentuk kepribadian dan peradaban manusia.</p>\n\n<p>Selanjutnya, ia mengucapkan terima kasih yang sebesar besar nya kepada alim dan ulama yang selalu dan tak segan segan nya memberikan nasihat kepada Pemerintah daerah untuk menjadikan kota bekasi yang Ihsan.</p>\n\n<p>Dalam kesempatan ini Wali Kota Bekasi juga mensosialisasikan tentang Kartu Bekasi Sehat Berbasis Nomor Induk Kependudukan (NIK). Kartu sehat yang dikeluarkan oleh Pemerintah Kota Bekasi sebagai perwujudan dari visi dan misi yaitu kota bekasi yang maju, Sejahtera dan Ihsan.</p>\n\n<p>Kartu Sehat ini, lanjutnya, akan kita berikan kepada masyarakat kota bekasi yang berpenghasilan rendah dan kegunaannya hampir sama dengan BPJS Kesehatan, &quot; tapi bedanya masyarakat tidak perlu bayar bulanan, &quot; ucapnya.</p>\n\n<p>Ia juga menjelaskan bahwa dalam pengajuan kartu sehat ini tidak perlu melengkapi persyaratan yang susah cukup dengan Kartu Tanda Penduduk dan surat permohonan dari RT dan RW, &quot; tidak lama kok pengajuan sehari juga masyarakat dapat menggunakan kartu sehat tersebut, &quot; jelasnya.</p>\n\n<p>Wali Kota juga menjelaskan bahwa Kota Bekasi merupakan kota dengan multi kultur suku dan agama,&quot;jadi pemimpin di kota bekasi baik itu lurah maupun camat harus mampu mengayomi seluruh masyarakat tanpa membedakan suku dan agama,&quot; tegasnya.</p>\n\n<p>Badan Pusat Statistik kota bekasi &nbsp;pada akhir April lalu mengeluarkan data bahwa Masyarakat asli bekasi hanya 28%, suku Jawa 48% dan sisa nya suku - suku yang ada di Indonesia.</p>\n\n<p>&quot; Dengan keragaman ini marilah kita bersatu padu dalam menciptakan kedamaian dan ketentraman masyarakat untuk mewujudkan Kota Bekasi yang Maju, Sejahtera dan Ihsan, &quot; ajaknya.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-07 08:51:00', '2017-05-07 08:51:00', NULL),
('eb3d2862-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Resmikan CCTV Wali Kota Serap Aspirasi Masyarakat ', 'resmikan-cctv-wali-kota-serap-aspirasi-masyarakat', 'Kota Bekasi - Untuk mengurangi angka kriminalitas yang kerap terjadi Dilingkungan warga RT 04 RW 04 perumahan wisma asri 2 kelurahan teluk pucung kecamatan bekasi utara membuat CCTV, Minggu,7/5.\n\nPemb', '<p>Kota Bekasi - Untuk mengurangi angka kriminalitas yang kerap terjadi Dilingkungan warga RT 04 RW 04 perumahan wisma asri 2 kelurahan teluk pucung kecamatan bekasi utara membuat CCTV, Minggu,7/5.</p>\n\n<p>Pembuatan yang diswakarsai oleh masyarakat ini mendapatkan apresiasi positif dari Wali Kota Bekasi DR. Rahmat Effendi yang langsung meninjau dan meresmikan penggunaan nya.</p>\n\n<p>Dalam kunjungan nya Wali Kota Bekasi mengatakan bentuk Program nyata seperti ini yang harus dipertahankan oleh masyarakat sebagaimana tercermin dalam Pancasila yang berbunyi persatuan Indonesia.&nbsp;</p>\n\n<p>Bentuk persatuan inilah yang wajib kita pertahankan dan nilai nilai gotong royong yang hampir pudar dalam kehidupan bermasyarakat, ia mengucap kan.</p>\n\n<p>Berbagai macam masalah telah saya kaji, lanjutnya, mulai dari permasalahan banjir jalan rusak hingga penerangan jalan yang kurang memadai.</p>\n\n<p>Untuk permasalahan banjir tidak bisa langsung Kita laksanakan karna harus ada kajian yang lebih mendalam mulai dari kontur wilayah dan estimasi biaya,&quot; penanggulangan banjir perlu kajian yang lebih dalam lagi dan insya Allah tahun depan bisa kita realisasikan, &quot; ucapnya.</p>\n\n<p>Untuk jalan rusak bisa lah kita kerjakan dalam waktu dekat, tambahnya, untuk penerangan jalan kita telah dapat hibah dari Pemerintah DKI Jakarta sebanyak 20 ribu unit lampu penerangan jalan yang akan kita alokasi kan ke warga sehingga jalan di kota bekasi terang benderang, ia menerangkan.</p>\n\n<p>Pada kesempatan ini Wali Kota Bekasi juga mensosialisasikan Program Pemerintah kota bekasi yang dengan jumlah penduduk yang hampir 2.6 juta jiwa Pemerintah kota bekasi telah mengalokasikan anggaran kesehatan untuk warga nya.</p>\n\n<p>&quot; Alokasi tersebut kita realisasikan melalui kartu bekasi sehat persyaratan nya gampang kok, cukup Kartu Tanda Penduduk dan Kartu Keluarga, &quot; jelasnya.</p>\n\n<p>Kartu Bekasi Sehat ini, tambahnya, telah diterima di 38 rumah sakit swasta yang ada di Kota Bekasi, &quot; apa bila ada yang tidak mau menerima kartu ini kita akan tutup izin operasional nya, &quot; tegasnya.</p>\n\n<p>Persyaratan lain nya adalah, tambahnya, kartu ini kita berikan untuk warga masyarakat kota bekasi yang berpenghasilan rendah yaitu dengan penghasilan dalam sebulannya kurang dari 5 juta rupiah.</p>\n\n<p>&quot; Inilah bentuk tanggung jawab Pemerintah terhadap warganya sehingga semua masyarakat kota bekasi dapat merasakan keberhasilan yang telah kita raih sehingga masyarakat kota bekasi yang Maju, Sejahtera dan Ihsan yang kita Idam kan terwujud secara berkesinambungan, &quot; harapnya.( tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-07 12:26:00', '2017-05-07 12:26:00', NULL),
('eb3d28b1-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Jalin Tali silahturahmi Kelurahan Jaka Sampurna Gelar Acara Keriaan', 'jalin-tali-silahturahmi-kelurahan-jaka-sampurna-gelar-acara-keriaan', 'Kota Bekasi- &nbsp;Untuk menjaga keutuhan dan memperkokoh tali silahturahmi masyarakat, tokoh agama dan Aparatur Pemerintah daerah Kelurahan Jaka Sampurna menggelar acara Keriaan yang berlangsung di p', '<p>Kota Bekasi- &nbsp;Untuk menjaga keutuhan dan memperkokoh tali silahturahmi masyarakat, tokoh agama dan Aparatur Pemerintah daerah Kelurahan Jaka Sampurna menggelar acara Keriaan yang berlangsung di pelataran kelurahan Jaka Sampurna, Jl. K.H.Noer Ali, Bekasi Barat, Kota Bekasi, Minggu, 7/5.</p>\n\n<p>Keriaan adalah budaya masyarakat Bekasi pabila melakukan &nbsp;acara besar seperti pernikahan dan acara lainnya. Acara ini diadopsi oleh masyarakat Jaka Sampurna dengan dipadu padankan dengan budaya dari semua suku yang ada di Indonesia.</p>\n\n<p>Wali Kota Bekasi DR.Rahmat Effendi pada pembukaan acara keriaan mengatakan ajang ini harus lah menjadi introspeksi dari semua pemangku wilayah untuk berubah &quot; pabila semua pejabat mau terjun langsung ke masyarakat maka permasalahan yang ada di masyarakat dapat diselesaikan sesingkat mungkin, &quot; ucapnya.</p>\n\n<p>Acara keriaan yang dihadiri oleh tokoh masyarakat tokoh perwakilan agama dan para pengurus RT dan RW se- kelurahan Jaka Sampurna Wali Kota Berpesan bahwa kebiasaan kebiasaan birokrasi yang telah lama terbentuk harus lah dirubah dari dilayani kini melayani, &quot; jadi sekarang bukan warga yang datengin lurah atau camat tapi lurah atau camat mendatangi warga,&quot; tegasnya.</p>\n\n<p>Apabila, lanjutnya, fungsi - fungsi dari kecamatan dan kelurahan berjalan baik maka harus nya tidak ada lagi pelayanan kepada masyarakat yang dikerjakan sampai berpuluh-puluh hari tetapi dapat dikerjakan secepat mungkin.&nbsp;</p>\n\n<p>&quot; kebiasaan - kebiasaan dari pengayom dan pangreh nya pengen jadi pejabat padahal sesungguhnya kita adalah pelayan masyarakat, &quot; tegasnya.</p>\n\n<p>Ia juga menambahkan bahwa pola mind set yang sudah terbentuk harus lah cepat dirubah baik itu tentang pelayanan dan administrasi ke masyarakat.</p>\n\n<p>&quot;Pabila semua sudah berubah bukan hal yang tak mungkin peradaban kita &nbsp;untuk kota bekasi yang Maju, Sejahtera dan Ihsan cepat kita raih, &quot; harapnya.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-07 12:28:00', '2017-05-07 12:28:00', NULL),
('eb3d28ff-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Hadiri Pendidikan Politik Bagi Elemen Masyarakat', 'wawali-hadiri-pendidikan-politik-bagi-elemen-masyarakat', 'Bekasi, Wakil Wali Kota Bekasi menghadiri kegiatan Pendidikan Politik bagi Organanisasi Masyarakat, Lembaga Swadaya Masyarakat, OKP, Mahasiswa, Gabungan Organisasi Wanita dan Majelis Taklim se-Kota Be', '<p>Bekasi, Wakil Wali Kota Bekasi menghadiri kegiatan Pendidikan Politik bagi Organanisasi Masyarakat, Lembaga Swadaya Masyarakat, OKP, Mahasiswa, Gabungan Organisasi Wanita dan Majelis Taklim se-Kota Bekasi bertempat di Gedung Dewi Sartika Jl. Veteran, Bekasi Selatan, Senin (8/5). &nbsp;</p>\n\n<p><br />\nHadir dalam kegiatan ini Ketua KPUD Kota Bekasi Drs. Pujo Asmoro Hadi, Dr. Dirgantara selaku narasumber dan Tarmaji perwakilan dari Badan Kesatuan Bangsa dan Politik Kota Bekasi. &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n\n<p>Dalam sambutannya Wawali Ahmad Syaikhu mengatakan dalam kaitan perpolitikan, pendidikan politik ini &nbsp;menjadi hal yang penting karena akan memjadi sentral &nbsp;bergerak tidaknya berbagai elemen dalam masalah perpolitikan di Kota Bekasi.</p>\n\n<p><br />\n&quot;Indikator suksesnya pendidikan politik ini adalah bagaimana partisipasi masyarakat terhadap perpolitikan khususnya di dalam pilkada atau pemilu. Semakin tinggi partisipasi di maayarakat dalam mengikuti perpolitikan, &nbsp;maka itu menunjukkan pendidikan politinya berhasil, &nbsp;tetapi bila masyarakatnya apatis partisipasi semakin kecil maka berarti pendidikan atau edukasi tidak berjalan dengan baik&quot; ujarnya</p>\n\n<p><br />\n&quot;Pemerintah Kota Bekasi sengaja mengundang berbagai elemen-elemen kunci seperti Bapak Ibu yang di LSM, &nbsp;Ormas, &nbsp;Mahasiswa, Gabungan Organisasi Wanita dan Organisasi Kepemudaan dan Majelis Taklim yanv &nbsp;kemudian dapat menginformasikan kembali kepada masyarakat Kota Bekasi secara luas sehingga mereka sadar dan mau berpartisipasi dalam perpolitikan di Kota Bekasi&quot; ungkapnya.</p>\n\n<p><br />\n&quot;Tentunya kita juga berharap kualitas perpolitikan di Kota Bekasi seharusnya semakin baik, dengan &nbsp;tidak adanya hal-hal yang menciderai proses demokrasi misalnya money politik dan lain sebagainya dan saya yakin bila masyarakat di edukasi dan pendidilan politiknya berjalan mereka tidak akan di iming-imingi money politik karena mereka telah mempunyai keyakinan akan pilihannya&quot; tambahnya.</p>\n\n<p><br />\nDiakhir sambutannya beliau menyampaikan harapannya agar dengan adanya pendidikan politik maka pemikiran dan pengetahuan kita akan utuh memandang bagaimana demokrasi yang ada di Kota Bekasi, juga kita akan mudah untuk menyamakan presepsi kita sehingga tidak timbul konflik-konflik di tengah kehidupan demokrasi kita.</p>\n\n<p><br />\nSelain itu beliau juga menyampaikan perlu membangun komunikasi dengan berbagai elemen-elemen masyarakat sehingga banyak hal-hal yang dibicarakan terutama tentang isu-isu strategis&nbsp;dengan begitu akan muncul kesepahaman dalam menyelesaikan isu-isu strategis sehingga dapat melakukan upaya agar proses demokrasi berjalan dengan baik.</p>\n\n<p><br />\n&quot;Dengan semakin banyaknya kita bersilahturahim dan bertemu maka semakin banyak pula upaya-upaya untuk mempersatukan berbagai pandangan dalam menyelesaikan persoalan-persoalan kehidupan di Kota Bekasi, &nbsp;sehingga apa yang di inginkan oleh seluruh elemen mssyarakat Kota Bekasi mewujudkan Kota Bekaai yang lebih baik akan bisa di capai bersama&quot; ujarnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-09 16:40:00', '2017-05-09 16:40:00', NULL),
('eb3d294f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Pemkot Bekasi akan Siapkan 1000 Titik WIFId dan 1000 cctv di Area Publik', 'pemkot-bekasi-akan-siapkan-1000-titik-wifid-dan-1000-cctv-di-area-publik', 'Kota Bekasi,8-5-2017. &nbsp; 1000 wifi dan 1000&nbsp;Closed Circuit Television (&nbsp;CCTV) akan dipasang di tempat-tempat Publik di wilayah Kota Bekasi oleh Pemerintah Kota Bekasi.&nbsp;\n\n&nbsp;\n\nPro', '<div dir=\"ltr\" id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2590\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Kota Bekasi,8-5-2017. &nbsp; 1000 wifi dan 1000&nbsp;<span id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2756\"  rgb(84, 84, 84); font-family: arial, sans-serif; font-size: small;\">Closed Circuit Television (&nbsp;</span>CCTV) akan dipasang di tempat-tempat Publik di wilayah Kota Bekasi oleh Pemerintah Kota Bekasi.&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2590\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2590\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Program ini merupakan kerjasama antara pemerintah Kota Bekasi &nbsp;dengan PT .Telkom Bekasi yang dituangkan dalam Addendum ditandatangani oleh Wali Kota Bekasi, Dr.Rahmat Effendi dengan GM Telkom Bekasi, Dwi Pratomo Juniarto &nbsp;disela-sela Apel ASN Pemerintah kota Bekasi di Plaza Alun-alun Kantor Walikota, Senin ( 8/5).</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2595\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2597\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Program pemasangan wifi gratis dan CCTV merupakan bagian dari program smart city Kota Bekasi, terang Wali Kota Bekasi, Dr.Rahmat Effendi dalam arahannya</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2599\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">pada apel di plaza senin pagi.&nbsp;</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2599\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2602\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Dengan adanya cctv dan wifi gratis di setiap area publik diharapkan dapat memberi keamananan dan kenyamanan serta menunjang aktfitas bagi warga masyarakat Kota Bekasi, ujarnya.</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2605\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">&nbsp;</div>\n\n<div id=\"m_1583162913766614258yui_3_16_0_ym19_1_1494237563403_2607\"  rgb(0, 0, 0); font-family: \"bookman old style\", \"new york\", times, serif; font-size: 16px;\">Namun dirinya juga berharap, warga masyarakat dapat menjaga degnan baik perangkat-perangkat tersebut, tandasnya.(yas). &nbsp;</div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-08 22:39:00', '2017-05-08 22:39:00', NULL),
('eb3d29a5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Adakan  Dialog  Dengan Tokoh Agama dan Tokoh Masyarakat', 'wali-kota-adakan-dialog-dengan-tokoh-agama-dan-tokoh-masyarakat', 'Kota Bekasi, 8-5-2017 . Wali Kota Bekasi, Dr.Rahmat Effendi adakan dialog dengan Tokoh Agama dan Tokoh Masyarakat Kota Bekasi bertempat &nbsp;di Griya Wulan Sari Jl. Kemakmuran Bekasi Selatan. Senin (', '<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2237\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2238\">Kota Bekasi, 8-5-2017 . Wali Kota Bekasi, Dr.Rahmat Effendi adakan dialog dengan Tokoh Agama dan Tokoh Masyarakat Kota Bekasi bertempat &nbsp;di Griya Wulan Sari Jl. Kemakmuran Bekasi Selatan. Senin (8/5/2017).</span></div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2240\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2241\">&nbsp;Dalam dialog kali ini turut hadir dari Polresta Bekasikota, Kejaksaan , TNI, Ketua FKUB Kota Bekasi.</span></div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2240\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\">&nbsp;</div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2243\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2244\">&nbsp;Wali Kota Bekasi mengatakan bahwa toleransi yang sudah kita bangun sedemikian rupa harus menjadi kesepakatan bersama khususnya di Kota Bekasi.</span></div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2243\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\">&nbsp;</div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2246\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2247\">Perlu kita sadari bersama, bahwa hubungan antar beragama merupakan sesuatu yang sangat kompleks dan kerap menemui hambatan-hambatan dalam menciptakan kerukunan umat beragama.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2246\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\">&nbsp;</div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2249\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2250\">Untuk mengatasi berbagai hambatan tersebut, bukan hanya pemerintah sebagai pemeran utama, namun tokoh agama dan tokoh masyarakat pun mempunyai peran yang sangat penting untuk sama-sama mewujudkan kerukunan antar umat beragama, terang Wali Kota.</span></div>\n\n<div id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2249\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\">&nbsp;</div>\n\n<div  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif;\">&nbsp;</div>\n\n<div dir=\"ltr\" id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2252\"  rgb(0, 0, 0); font-family: \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; text-indent: 0.5in;\"><span id=\"m_1221753299969567864yiv6090035822yui_3_16_0_ym19_1_1494241073758_2253\">Apabila kita berkomitmen untuk merealisasikan kehidupan bermasyarkat dan bernegara secara harmonis , niscaya perhatian dan konsentrasi pemerintah Kota Bekasi&nbsp;untuk mewujudkan visi Bekasi&nbsp;maju, sejahatera dan ihsan dapat terwujud berkat dukungan semua pihak, pungaksnya. (bar/yas)</span></div>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-08 22:48:00', '2017-05-08 22:48:00', NULL),
('eb3d29f5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', '   Rakor  Integrasi Kanal  Pemerintah Daerah Kab/Kota Tingkat Provinsi', 'rakor-integrasi-kanal-pemerintah-daerah-kab-kota-tingkat-provinsi', 'Kota Bekasi, -- Diskominfostandi mengikuti Rapat koordinasi  Integrasi kanal Pemerintah Daerah kabupaten dan kota  Se - Provinsi Jawa Barat dan Banten.\n\nAcara yang diselenggarakan oleh direktorat kemi', '<p>Kota Bekasi, -- Diskominfostandi mengikuti Rapat koordinasi  Integrasi kanal Pemerintah Daerah kabupaten dan kota  Se - Provinsi Jawa Barat dan Banten.</p>\n\n<p>Acara yang diselenggarakan oleh direktorat kemitraan komunikasi,Ditjen . informasi dan komunikasi publik,kementrian Komunikasi dan Informatika RI bertempat Kota Bukit indah plaza hotel  Purwakarta Jawa Barat.(9/5)</p>\n\n<p>Dalam Sambutannya  R .Niken Widiastuti selaku Ditjen Informasi dan Komunikasi Publik menyatakan bahwa Diskominfo harus ambil bagian dalam penguatan kebijakan kebijakan pemerintah untuk membangun reputasi yang positif dari masyarakat,Demi persatuan NKRI Ungkapnya\".</p>\n\n<p>peserta yang hadir terdiri dari 30 perwakilan  Kabupaten/Kota yang ada di Provinsi Jawa Barat dan Kota.sementara dari diskominfostandi diwakil kan oleh kasie Layanan Komunikasi Dan Informasi Publik Adelina Murni.(Gege)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-09 05:33:00', '2017-05-09 05:33:00', NULL),
('eb3d2a45-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Menandatangani Komitmen Bersama Kemitraan Bidang Kesehatan  ', 'wakil-wali-kota-menandatangani-komitmen-bersama-kemitraan-bidang-kesehatan', 'Pemerintah Kota Bekasi melalui Dinas Kesehatan mengadakan pertemuan jejaring kemitraan bidang kesehatan yang bertempat di Gedung Marga Jaya Jl. Kemakmuran Bekasi Selatan. Selasa (9/5/2017).\n\nAcara ini', '<p>Pemerintah Kota Bekasi melalui Dinas Kesehatan mengadakan pertemuan jejaring kemitraan bidang kesehatan yang bertempat di Gedung Marga Jaya Jl. Kemakmuran Bekasi Selatan. Selasa (9/5/2017).</p>\n\n<p>Acara ini dihadiri oleh Wakil Wali Kota Bekasi, H. Ahmad Syaikhu, Kepala Dinas Kesehatan Kota Bekasi, H. Kusnanto, FKUB, Camat se-Kota Bekasi dan perangkat daerah lainnya.</p>\n\n<p>Wakil Wali Kota Bekasi mengatakan bahwa progam &ndash; progam pemerintah di berbagai kesehatan tidak dapat berjalan sendiri tanpa peran serta berbagai pihak dan untuk itu diperlukan dukungan dan peran aktif dari berbagai unsur, seperti dunia usaha, LSM, Ormas, Media dan lainnya.</p>\n\n<p>Kepala Dinas Kesehatan Kota Bekasi pada kesempatan ini juga menyampaikan upaya kesehatan dalam menggalang kemitraan yaitu dengan membangun sinergi lintas sektor dan lintas progam seperti menciptakan kebutuhan masyarakat serta ketersediaan sarana sanitasi.</p>\n\n<p>Akhir dari kegiatan ini Wakil Wali Kota Bekasi mengawali penandatanganan komitmen bersama kemitraaan bidang kesehatan serta dilanjutkan penandatangan dari Kepala Dinas Kesehatan Kota Bekasi, Ketua FKUB, perwakilan perusahaan swasta, Media, Ormas, LSM dan pusat perbelanjaan.</p>\n\n<p>Komitmen bersama kemitraan bidang kesehatan perwakilan dari perangkat daerah, dunia usaha, Ormas, LSM dan Media untuk mendukung progam - progam kesehatan serta upaya meningkatkan derajat kesehatan masyarakat Kota Bekasi. Semoga komitmen ini dapat menjadikan Masyarakat Kota Bekasi yang maju, sejahtera dan ihsan. Pungkas Wakil Wali Kota Bekasi. (BAR)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-09 13:52:00', '2017-05-09 13:52:00', NULL),
('eb3d2a95-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Berikan Semangat Bocah Penderita Lumpuh Layu', 'wali-kota-berikan-semangat-bocah-penderita-lumpuh-layu', 'Kota Bekasi - Wali Kota Bekasi, Dr. Rahmat Effendi memberikan semangat kepada Rasyid, bocah 11 tahunyang menderita lumpuh layu dirumahnya di wilayah kelurahan Kranji, Kecamatan Bekasi Barat Senin(8/5)', '<p>Kota Bekasi - Wali Kota Bekasi, Dr. Rahmat Effendi memberikan semangat kepada Rasyid, bocah 11 tahunyang menderita lumpuh layu dirumahnya di wilayah kelurahan Kranji, Kecamatan Bekasi Barat Senin(8/5). &quot; Kamu harus semangat dan yakin pasti sembuh&quot;, kata Wali Kota kepada Rasyid.</p>\n\n<p>Wali Kota sempat berinteraksi dengan Rasyid dengan menanyakan tentang cita-citanya kelak mau jadi apa. Wali Kota apresiasi terhadap Rasyid yang responsif<br />\nmampu menjadwab dengan baik pertanyaan yang disampaikan oleh Wali Kota walau pun dalam kondisi seperti ini. &quot; Saya melihat anak ini sangat cerdas serta mempunyai keinginan yang tinggi untuk sembuh dan ini menjadi nilai yang positif dalam proses penyembuhannya&quot;, ujarnya.</p>\n\n<p>Penyakit yang diderita Rasyid sudah dialaminya sejak umur 11 bulan, tutur Amani, Nenek yang merawat rasyid tiap harinya.</p>\n\n<p>Ditempat itu pula, Wali Kota Segera memerintahkan camat Bekasi Barat dan pihak Puskesmas setempat untuk merujuk Rasyid ke Rumash Sakit agar segera mendapatkan pelayanan medis yang lebih baik. &quot;dari kecamatan dan puskesmas segera tangani dan layani dengan baik&quot; , kata Wali Kota.</p>\n\n<p>&quot;kita harus memberikan pelayanan yang baik kepada masyarakat yang membutuhkan pelayanan kesehatan seperti ini, pungkasnya.(yas)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-09 14:06:00', '2017-05-09 14:06:00', NULL),
('eb3d2ae5-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Kukuhkan KKBTQ Kota Bekasi', 'wali-kota-bekasi-kukuhkan-kkbtq-kota-bekasi', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi mengkukuhkan Kelompok Kerja Bina Taman Pendidikan Al-Qur&#39;an (KKBTPQ) Kota Bekasi di Gedung Mahkamah Kontitusi pada hari Rabu (10/05/2017), dih', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi mengkukuhkan Kelompok Kerja Bina Taman Pendidikan Al-Qur&#39;an (KKBTPQ) Kota Bekasi di Gedung Mahkamah Kontitusi pada hari Rabu (10/05/2017), dihadiri perwakilan dari Kementerian Agama serta dirangkaikan dengan Wisuda ke 18 para siswa siswi yayasan dan sekolah yang tergabung di dalam KKBTPQ Kota Bekasi.</p>\n\n<p><br />\nKetua Terpilih KKBTPQ yang telah di kukuhkan Wali Kota Bekasi, Dedy Haryanto mengatakan dalam sambutannya atas pelantikan pengurus yang di kukuhkan Wali Kota Bekasi berterima kasih atas kehadirannya, juga menyampaikan bahwa acara dirangkaikan dengan 1300 para santri di wisuda dan melanjutkan tingkat Sekolah Dasar.</p>\n\n<p><br />\n&quot;Kami dari pengurus sangat menjamin kepada para siswa dan siswi yang telah di wisuda untuk melanjutkan tingkat SD sudah memiliki ilmu, karena proses lulus tersebut terdapat ujian agama, tes kehafalan, hafalan surat pendek, berikut doa harian, itu yang menjadi target kami dalam kelulusan&quot; tegas Dedy Haryanto</p>\n\n<p><br />\nHarapan dari Ketua terpilih kepada Wali Kota Bekasi untuk penambahan mengenasi tunjangan kinerja dari guru guru TPQ atau pun sekolah islam, karena masih ada guru yang belum terdaftar.</p>\n\n<p><br />\nWali Kota dalam sambutannya, memberikan apresiasi atas kinerja KKBTPQ untuk pelantikan serta wisuda yang telah berjlan 18 kali, dan menjadikan target para santri dan peserta didik ke jenjang SD lebih mengetahui tentang agama, juga peran para guru yang telah berjasa memperjuangkan belajar agama di Kota Bekasi harus bisa sebanding dengan guru guru negeri.</p>\n\n<p><br />\nBerdasarkan rencana para guru agama akan di sepakati diberikan tunjangan sebesar 500 ribu dan nanti akan di naikkan secara berkala dengan dilihat sumber anggaran.</p>\n\n<p><br />\nWali Kota Bekasi juga menyerahkan satu mobil operasional untuk pengurus keperluan apapun di KKBTPQ agar bisa digunakan sebagaimana tugas dan tanggung jawabnya dalam bertugas.</p>\n\n<p><br />\nDi intruksikan kepada Kepala Kantor Agama Kota Bekasi agar segera mendata para guru yang belum masuk dalam tunjangan kinerjanya agar segera diproses. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 07:17:00', '2017-05-10 07:17:00', NULL),
('eb3d2b33-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Kukuhkan KKBTQ Kota Bekasi.', 'wali-kota-bekasi-kukuhkan-kkbtq-kota-bekasi-2', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi mengkukuhkan Kelompok Kerja Bina Taman Pendidikan Al-Qur&#39;an (KKBTPQ) Kota Bekasi di Gedung Mahkamah Kontitusi pada hari Rabu (10/05/2017), dih', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi mengkukuhkan Kelompok Kerja Bina Taman Pendidikan Al-Qur&#39;an (KKBTPQ) Kota Bekasi di Gedung Mahkamah Kontitusi pada hari Rabu (10/05/2017), dihadiri perwakilan dari Kementerian Agama serta dirangkaikan dengan Wisuda ke 18 para siswa siswi yayasan dan sekolah yang tergabung di dalam KKBTPQ Kota Bekasi.</p>\n\n<p><br />\nKetua Terpilih KKBTPQ yang telah di kukuhkan Wali Kota Bekasi, Dedy Haryanto mengatakan dalam sambutannya atas pelantikan pengurus yang di kukuhkan Wali Kota Bekasi berterima kasih atas kehadirannya, juga menyampaikan bahwa avara dirangkaikan dengan 1300 para santri di wisuda dan melanjutkan tingkat Sekolah Dasar.</p>\n\n<p><br />\n&quot;Kami dari pengurus sangat menjamin kepada para siswa dan siswi yang telah di wisuda untuk melanjutkan tingkat SD sudah memiliki ilmu, karena proses lulus tersebut terdapat ujian agama, tes kehafalan, hafalan surat pendek, berikut doa harian, itu yang menjadi target kami dalam kelulusan&quot; tegas Dedy Haryanto</p>\n\n<p><br />\nHarapan dari Ketua terpilih kepada Wali Kota Bekasi untuk penambahan mengenasi tunjangan kinerja dari guru guru TPQ atau pun sekolah islam, karena masih ada guru yang belum terdaftar.</p>\n\n<p><br />\nWali Kota dalam sambutannya, memberikan apresiasi atas kinerja KKBTPQ untuk pelantikan serta wisuda yang telah berjlan 18 kali, dan menjadikan target para santri dan peserta didik ke jenjang SD lebih mengetahui tentang agama, juga peran para guru yang telah berjasa memperjuangkan belajar agama di Kota Bekasi harus bisa sebanding dengan guru guru negeri.</p>\n\n<p><br />\nBerdasarkan rencana para guru agama akan di sepakati diberikan tunjangan sebesar 500 ribu dan nanti akan di naikkan secara berkala dengan dilihat sumber anggaran.</p>\n\n<p><br />\nWali Kota Bekasi juga menyerahkan satu mobil operasional untuk pengurus keperluan apapun di KKBTPQ agar bisa digunakan sebagaimana tugas dan tanggung jawabnya dalam bertugas.</p>\n\n<p><br />\nDi intruksikan kepada Kepala Kantor Agama Kota Bekasi agar segera mendata para guru yang belum masuk dalam tunjangan kinerjanya agar segera diproses. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 07:26:00', '2017-05-10 07:26:00', NULL),
('eb3d2b89-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dinas PMPTSP Sosialisasi Kebijakan Penanaman Modal dengan Pengusaha di Kota Bekasi', 'dinas-pmptsp-sosialisasi-kebijakan-penanaman-modal-dengan-pengusaha-di-kota-bekasi', 'Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara yang dibentuk dari Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu (DPMPTSP) yakni menggelar acara pertemuan para pengusaha Kota Bekasi te', '<p>Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara yang dibentuk dari Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu (DPMPTSP) yakni menggelar acara pertemuan para pengusaha Kota Bekasi terkait Sosialisasi Kebijakan Penanaman Modal di Hotel Merapi Merbabu pada hari Rabu (10/05/2017), di dampingi Kepala Dinas PMPTSP, Amit Riyadi.</p>\n\n<p><br />\nUpaya Pemerintah Kota Bekasi dalam mencapai tujuan dari perkembangan kegiatan ekonomi daerah termasuk pertumbuhan ekonomi dengan cara berpartisipasi baik dari Pemerintahannya maupun masyarakat, termasuk memperhatikan pelaku usaha yang menanamkan modalnya di Kota Bekasi.</p>\n\n<p><br />\nWali Kota Bekasi menjelaskan dalam mengantisipasi permasalahan permasalahan yang ada seperti adanya daya saing, produktivitas efisiensi telah berupaya mengajarkan di birokasi melalui simplikasi pelayanan perizinan, pembenahan SDM aparatur, penataan kelembagaan dan infrastruktur pendukung lainnya.</p>\n\n<p><br />\n&quot;Uang yang beredar sebesar 75 trilyun per tahun di Kota Bekasi, karena itu saya lebih suka ada investasi di Kota Bekasi karena kita tidak punya kekayaan&quot; ujar Wali Kota.</p>\n\n<p><br />\nDPMTSP harus memberikan izin yang cepat untuk mempermudah investasi di Kota Bekasi. Sektor jasa dan perdagangan harus menjadi tujuan utama investor karena Kota Bekasi tidak memiliki kekayaan alam.</p>\n\n<p>Saat ini sudah ada 64 ribu warga yang terserap masuk dunia usaha di Kota Bekasi, karena itu harus ada kepastian hukum bagi para pengususaha di wilayah Kota Bekasi.</p>\n\n<p><br />\n&quot;Terimakasih bagi para pengusaha. Npwp harusnya bukan pusat saja tapi daerah juga harus bikin. Kota Bekasi memiliki peluang untuk memacu pertumbuhan ekonomi, &quot; jelas Wali Kota</p>\n\n<p><br />\nSebelumnya kabid penanaman modal dan investasi dpmptsp Kota Bekasi Nevindo mengatakan jika kepatuhan pengusaha untuk melaporkan penanaman modal di wilayah Kota Bekasi masih sangat rendah. Dari ribuan pengusaha yang ada baru 85 yang telah melaporkan jumlah modal yang di investasikan di Kota Bekasi.</p>\n\n<p><br />\n&quot;Kita berharap agar para pengusaha juga rajin melaporkan jumlah investasinya, saat ini baru tercatat sekitar delapan trilyun investasi di Kota Bekasi. Sementara jika kita liat kasat mata maka bisa puluhan trilyun inveatasi di Kota Bekasi ini, &quot; Ungkap Nevindo. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 08:40:00', '2017-05-10 08:40:00', NULL),
('eb3d2bd9-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gebyar Tim PKK Kelurahan Kali Abang Tengah, Wali Kota \"Tunjangan Kader Wilayah Harus Keluar Perbulan', 'gebyar-tim-pkk-kelurahan-kali-abang-tengah-wali-kota-tunjangan-kader-wilayah-harus-keluar-perbulan', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir di acara Gebyar Tim Penggerak PKK Kelurahan Kaliabang Tengah dalam menyambut Bulan Suci Ramadhan sekaligus silaturahmi bersama Lurah dan Wal', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir di acara Gebyar Tim Penggerak PKK Kelurahan Kaliabang Tengah dalam menyambut Bulan Suci Ramadhan sekaligus silaturahmi bersama Lurah dan Wali Kota Bekasi pada hari Rabu (10/05/2017) di aula Kelurahan Kali Abang Tengah.</p>\n\n<p><br />\nDalam penyampaiannya, Wali Kota Bekasi juga menegaskan bahwa dana insentif untuk para kader wilayah seperti Kader Tim Penggerak PKK, Kader Posyandu, Linmas dan lainnya harus melalui transferan bank BJB seperti para Aparatur Sipil Negeri, ditujukan agar bisa menjadi tranparansi dan tidak ada dana potongan potongan dari manapun, juga harus di cairkan sebulan sekali tidak lagi 3 bulan lagi.</p>\n\n<p><br />\nWali Kota juga menegaskan bahwa harus berulang kali harus mensosialisasikan mengenai Kartu Sehat yang di keluarkan dari Kota Bekasi, semua warga harus memiliki Kartu tersebut mengenai hak dalam pelayanan kesehatan di Kota Bekasi.</p>\n\n<p><br />\nDemi menjamin Kesehatan warga Kota Bekasi dikeluarkan Kartu Sehat Berbasis NIK, yang pengajuan dari warga dengan mengumpulkan Kartu Keluarga dan KTP Elektronik Kepala Keluarga dan juga mengajukan Surat pengajuan dari Kelurahan setempat. Kartu tersebut, nanti nya akan berfungsi dengan menjamin pelayanan kesehatan bagi warga dengan tidak mengeluarkan biaya dan ditanggung pemerintahan. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 08:51:00', '2017-05-10 08:51:00', NULL),
('eb3d2c28-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Gebyar Tim PKK Kelurahan Kali Abang Tengah,Wali Kota \"Tunjangan Kader Wilayah Harus Keluar Perbulan\"', 'gebyar-tim-pkk-kelurahan-kali-abang-tengah-wali-kota-tunjangan-kader-wilayah-harus-keluar-perbulan-2', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir di acara Gebyar Tim Penggerak PKK Kelurahan Kaliabang Tengah dalam menyambut Bulan Suci Ramadhan sekaligus silaturahmi bersama Lurah dan Wal', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadir di acara Gebyar Tim Penggerak PKK Kelurahan Kaliabang Tengah dalam menyambut Bulan Suci Ramadhan sekaligus silaturahmi bersama Lurah dan Wali Kota Bekasi pada hari Rabu (10/05/2017) di aula Kelurahan Kali Abang Tengah.</p>\n\n<p><br />\nDalam penyampaiannya, Wali Kota Bekasi juga menegaskan bahwa dana insentif untuk para kader wilayah seperti Kader Tim Penggerak PKK, Kader Posyandu, Linmas dan lainnya harus melalui transferan bank BJB seperti para Aparatur Sipil Negeri, ditujukan agar bisa menjadi tranparansi dan tidak ada dana potongan potongan dari manapun, juga harus di cairkan sebulan sekali tidak lagi 3 bulan lagi.</p>\n\n<p><br />\nWali Kota juga menegaskan bahwa harus berulang kali harus mensosialisasikan mengenai Kartu Sehat yang di keluarkan dari Kota Bekasi, semua warga harus memiliki Kartu tersebut mengenai hak dalam pelayanan kesehatan di Kota Bekasi.</p>\n\n<p><br />\nDemi menjamin Kesehatan warga Kota Bekasi dikeluarkan Kartu Sehat Berbasis NIK, yang pengajuan dari warga dengan mengumpulkan Kartu Keluarga dan KTP Elektronik Kepala Keluarga dan juga mengajukan Surat pengajuan dari Kelurahan setempat. Kartu tersebut, nanti nya akan berfungsi dengan menjamin pelayanan kesehatan bagi warga dengan tidak mengeluarkan biaya dan ditanggung pemerintahan. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 09:00:00', '2017-05-10 09:00:00', NULL),
('eb3d2c77-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Temui Warga Terkait Dana Talangan Untuk Warga TPST Bantargebang', 'wali-kota-temui-warga-terkait-dana-talangan-untuk-warga-tpst-bantargebang', 'Kota Bekasi &ndash; Pemerintah Kota Bekasi akan mengeluarkan dana talangan, untuk warga TPST Bantargebang, yang belum menerima uang kompensasi dari Pemerintah Provinsi DKI Jakarta.\n\n\nDana talangan ini', '<p>Kota Bekasi &ndash; Pemerintah Kota Bekasi akan mengeluarkan dana talangan, untuk warga TPST Bantargebang, yang belum menerima uang kompensasi dari Pemerintah Provinsi DKI Jakarta.</p>\n\n<p><br />\nDana talangan ini di gunakan oleh Pemkot Bekasi untuk meredam keresahan warga TPST Bantargebang. Sebab, hal ini baru diketahui Wali Kota Bekasi, Rahmat Effendi, jika mitra pemerintahannya itu belum membayarakan kewajibannya selama lima bulan.</p>\n\n<p><br />\n&ldquo;Kita baru tahu hal ini, sebab biasanya Bantuan Langsung Tunai (BLT) itu di berikan oleh Pemkot Bekasi, namun ternyata Pemprov DKI belum membayarkan kewajibannya sampai bulan lima ini,&rdquo; ungkap Rahmat Effendi usai menemui warga di Kelurahan Cikiwul, Kecamatan Bantargebang, Rabu (10/5/2017) siang.</p>\n\n<p><br />\nHal itu, kata Rahmat bukan menjadi persoalan, sebab Pemkot Bekasi akan mencairkan dana talangan ini, usai melakukan konsultasi dengn tim 32. Sebab keterlambatan tersebut bisa digantikan oleh Pemkot sebagaimana MoU yang pernah dilakukan bersama Pemprov DKI beberapa waktu lalu.</p>\n\n<p><br />\n&ldquo;Kita akan keluarkan dana talang, agar tidak jadi keresahan bagi si penerima, sekarang kita sedang konsultasikan dengan tim 32, untuk segera mencairkan dana yang ada,&rdquo; pungkasnya.</p>\n\n<p><br />\nWali Kota Bekasi juga berencana akan bersurat ke Plt Gubernur DKI Jakarta, untuk menanyai keterlambatan pemberian uang kompensasi ini.</p>\n\n<p><br />\n&ldquo;Kalau yang untuk 2017 ini memang belum kita terima, makanya saya akan menyurati Gubernur,&rdquo; ujarnya. (alf/foto : ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-10 23:11:00', '2017-05-10 23:11:00', NULL);
INSERT INTO `beritas` (`uuid`, `user_uuid`, `category_uuid`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `video`, `scheduled_at`, `views`, `tagging`, `status`, `search_engine`, `is_featured`, `is_popular`, `is_urgent`, `created_at`, `updated_at`, `deleted_at`) VALUES
('eb3d2cc6-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Jajaran Pemerintah Kota Bekasi Jalin Silahturahmi Dengan Penerintah Kabupaten Lebak', 'jajaran-pemerintah-kota-bekasi-jalin-silahturahmi-dengan-penerintah-kabupaten-lebak', 'Kabupaten Lebak - Wali Kota Bekasi DR. Rahmat Effendi dan Wakil Wali Kota Ahmad Syaikhu&nbsp; bersama seluruh pejabat&nbsp; pemerintah kota bekasi jalin tali silaturahmi dengan Pemerintah Kabupaten Le', '<p>Kabupaten Lebak - Wali Kota Bekasi DR. Rahmat Effendi dan Wakil Wali Kota Ahmad Syaikhu&nbsp; bersama seluruh pejabat&nbsp; pemerintah kota bekasi jalin tali silaturahmi dengan Pemerintah Kabupaten Lebak, Jum&#39;at, 12/5.</p>\n\n<p>Selain menjalin tali silaturahmi pemerintah kota bekasi juga belajar dengan pemerintah kabupaten lebak tentang bagaimana menjaga nilai luhur budaya lokal ditengah arus modernisasi yang terus berkembang.</p>\n\n<p>Dalam kunjungan kerja ini Pemerintah Kota Bekasi mengajak seluruh kepala dinas untuk belajar dan berbagi pengalaman dengan kabupaten lebak mulai dari pendidikan, kesehatan dan pembangunan hingga permasalahan sosial.</p>\n\n<p>Wali Kota dan Wakil Wali Kota&nbsp; Bekasi diterima langsung oleh Bupati Lebak Iti Octavia Jayabaya beserta seluruh kepala dinas di lingkungan pemerintah Kabupaten Lebak di Istana Negara Kabupaten Lebak.</p>\n\n<p>Dalam penerimaan nya Bupati Lebak menjelaskan tentang kondisi geografi dan kondisi sosial masyarakat, pembangunan hingga hal hal yang terkait permasalahan pembangunan infrastruktur.</p>\n\n<p>&quot;Pembangunan infrastruktur jalan di daerah kami berbenturan dengan banyak jalan provinsi dan jalan negara jadi agak sulit, masyarakat hanya tau bahwa jalan rusak tetapi kita pemerintah kabupaten tak mau merapikannya,&quot; keluhnya.</p>\n\n<p>Ia juga menambahkan dengan jumlah penduduk yang hampir 2.6 juta jiwa, luas wilayah hampir 300 Ha dan kondisi geografi yang berbukit hingga banyaknya hutan jadi pembangunan infrastruktur terutama jalan tidak lah mungkin dikerjakan dalam waktu dekat.</p>\n\n<p>&quot;Air baku untuk jabotabek juga bersumber disini yaitu melalui sungai yang bermuara ke wilayah tanggerang, &quot;ungkapnya.</p>\n\n<p>Wali Kota Bekasi mengungkapkan bahwa pembangunan dikota bekasi tidak lah luput dari permasalahan tetapi bagaimana caranya kita dan aparatur berkonsisten untuk menciptakan masyarakat yang maju.</p>\n\n<p>Pembangunan di kota bekasi juga banyak berbenturan dengan kebijakan pemerintah pusat dan pemerintah provinsi jadi caranya adalah kita berkoordinasi dan langsung menyampaikanya, ucapnya.</p>\n\n<p>Bupati lebak berharap semoga dengan datang nya Wali kota dan Wakil Wali kota bekasi dapat memberikan informasi kepada masyarakat kota bekasi dan masyarakat umumnya tentang budaya kabupaten lebak, sehingga meningkatkan antusias masyarakat untuk berkunjung ke kabupaten lebak.</p>\n\n<p>Wali kota dan Wakil Wali kota bekasi berharap agar kunjungan seluruh aparatur Pemerintah Kota Bekasi dapat membuka seluruh masyarakat bahwa masih banyak daerah wisata yang harus di gali di indonesia salah satu nya di kabupaten lebak, &quot; karna dengan banyak nya wistawan maka akan bertambah pendapatan pemerintah dan masyarakatnya, &quot;ajaknya.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-12 10:05:00', '2017-05-12 10:05:00', NULL),
('eb3d2d21-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'PENGUMUMAN PENGADAAN KONSULTAN PERORANGAN TENAGA AHLI', 'pengumuman-pengadaan-konsultan-perorangan-tenaga-ahli', 'PENGUMUMAN PENGADAAN\n\nKONSULTAN PERORANGAN TENAGA AHLI\n\nPADA DISKOMINFOSTANDI KOTA BEKASI\n\n&nbsp;\n\nDalam rangka mendukung kegiatan pada Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Bek', '<h2><strong>PENGUMUMAN PENGADAAN</strong></h2>\n\n<h2><strong>KONSULTAN PERORANGAN TENAGA AHLI</strong></h2>\n\n<h2><strong>PADA DISKOMINFOSTANDI KOTA BEKASI</strong></h2>\n\n<p>&nbsp;</p>\n\n<p>Dalam rangka mendukung kegiatan pada Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Bekasi Tahun Anggaran 2017, dengan ini kami membuka proses pengadaan konsultan perorangan sebagai berikut :</p>\n\n<p>A. PERSYARATAN UMUM</p>\n\n<ol>\n <li>Warga Negara Indonesia (WNI);</li>\n <li>Bertaqwa kepada Tuhan Yang Maha Esa;</li>\n <li>Memiliki Integritas yang tinggi terhadap Negara Kesatuan Republik Indonesia;</li>\n <li>Tidak pernah dihukum penjara atau kurungan berdasarkan putusan pengadilan yang sudah mempunyai kekuatan hukum tetap, karena melakukan suatu tindak pidana kejahatan;</li>\n <li>Bersedia mengikuti ketentuan dan memenuhi target kerja yang ditetapkan;</li>\n <li>Tidak berkedudukan sebagai calon pegawai negeri sipil atau pegawai negeri sipil;</li>\n <li>Mempunyai kualifikasi pendidikan, kecakapan, keahlian, dan keterampilan yang diperlukan;</li>\n <li>Berkelakuan baik;</li>\n <li>Sehat jasmani dan rohani.</li>\n</ol>\n\n<p>&nbsp;</p>\n\n<p>B. PENGIRIMAN BERKAS LAMARAN</p>\n\n<ol>\n <li>Berkas lamaran ditujukan kepada <strong><em>Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Bekasi Up. Sekretariat Jalan Ahmad Yani No. 1 Kota Bekasi</em></strong> (ditulis kode tenaga ahli pada sudut kanan atas amplop coklat tertutup);</li>\n <li>Berkas lamaran terdiri dari : Surat lamaran, Curiculum Vitae (CV), Foto berwarna ukuran 3x4 sebanyak 1 lembar (ditempelkan disudut kiri atas surat lamaran), fotocopy ijazah dan transkrip nilai, fotocopy KTP dan NPWP;</li>\n <li>Lamaran paling lambat diterima tanggal <strong>19<em>&nbsp;Mei&nbsp;2017</em></strong></li>\n <li>Hanya kandidat yang memenuhi kualifikasi administrasi yang diproses untuk uji kompetensi</li>\n</ol>\n\n<p>Contact Information :&nbsp;</p>\n\n<p>Novrizal (0816-1464-236), (0811-1129-686)</p>\n\n<p>&nbsp;</p>\n\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"1\" width=\"500\">\n <tbody>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Integrasi Data</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/j8iPSdd2tfh5sOc\">1. Database Enginer</a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/TarW5eFyCK71fft\"><u>2. Database Integrator</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/ExAJf9MKsn2J3qI\"><u>3. Full Stack Developer</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/f5yQ9tlNLsFhGTh\"><u>4. Senior System Analys</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Pembangunan Dashboard Open Data</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/QTnzXhAT4GiCjP7\"><u>1. Interface Design (Design Muka Aplikasi Front End)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/5Ipzbg5yhida1gl\">2. Sistem Analis</a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/U0ZqIMMlzCblRrx\"><u>3. Pemrograman Dan Integrator Data</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/N11YobT1Isk2QDL\"><u>4. Pemrograman Back End</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Pembangunan Early Warning System &#40;EWS&#41;</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/XPvHK137O7JuLIx\">1. Senior Sistem Analis</a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/huZSxmQEH2KXipM\">2. Programmer</a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/Yk1JsOx9P48C3JO\"><u>3. Programmer (Pemrograman Full Stack Developer)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/YmioSmmlHW59lS0\"><u>4. Database Enginner (Desain dan Integrasi Database)</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Pembangunan Sistem Monitoring Sampah Terintegrasi</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/ILX7sAjYGLgNuCL\">1. Sistem Analis</a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/INC8UwQieUqbXWc\"><u>2. Programmer (Pemrograman dan Config IoT Module/Embeded Device)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/8Wv1pXeFMGtqSFr\"><u>3. Programmer (Pemrograman Full Stack Developer</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/M7l6SbJXkRIt5zQ\"><u>4. Database Enginner (Desain dan Integrasi Database)</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Pembuatan Motiongraphic Pengaduan Online</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/B4yV4l4SGwCDwzw\"><u>1. Desain Animasi</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/Aq32z3fRiiBQsfO\"><u>2. Desain Ilustrator</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/TzzmbPyNmNpjBod\"><u>3. Dubbing</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Pembuatan Program Android Pengaduan Online</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/YYueM8Z2RQFmcK5\"><u>1. Programmer Android</u></a></p>\n   </td>\n  </tr>\n  <tr>\n   <td>\n   <p>Kebutuhan Tenaga Ahli Programmer Website</p>\n   </td>\n   <td>\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/mKsvYpQ2JteQZD4\"><u>1. Analyst/Database (Aplikasi Monitoring Media Social)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/oFqpXA9xP8POyr6\"><u>2. Programmer (Aplikasi Monitoring Media Social)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/qWn6zabPem2uhFt\"><u>1. Web Programmer (Web Bekasi Kota)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/xC69e4cPd2lvOib\"><u>2. Web Desain (Web Bekasi Kota)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/kh3NnHRkehT1nP4\"><u>3. Web Programmer (Web Diskominfo)</u></a></p>\n\n   <p><a href=\"https://drive.bekasikota.go.id/index.php/s/tk0aOWH2MDHPm0y\"><u>4. Web Programmer (Web Kecamatan)</u></a></p>\n   </td>\n  </tr>\n </tbody>\n</table>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-12 12:59:00', '2017-05-12 12:59:00', NULL),
('eb3d2d72-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Resmikan Masjid Al-Barokah As-Saidah, Wali Kota Tegaskan Izin Masjid Tidak Ada Pungutan Biaya', 'resmikan-masjid-al-barokah-as-saidah-wali-kota-tegaskan-izin-masjid-tidak-ada-pungutan-biaya', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadiri dan resmikan pembangunan Masjid Al-Barokah As-Saidah Kelurahan Jatisari Kecamatan Jatiasih pada hari Sabtu (13/05/2017), di dampingi Camat ', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi hadiri dan resmikan pembangunan Masjid Al-Barokah As-Saidah Kelurahan Jatisari Kecamatan Jatiasih pada hari Sabtu (13/05/2017), di dampingi Camat Jatiasih, Nesan Sujana serta Lurah setempat.</p>\n\n<p><br />\nDalam sambutannya, Wali Kota Bekasi menegaskan bahwa Kota Bekasi telah memiliki 1200 Masjid yang beberapanya harus di lindungin payung hukum perizinan, karena proses perizinan tersebut amat penting untuk kedepannya agar tidak terjadi kekeliruan, disamping itu, Wali Kota juga menjamin bahwa mengenai perijinan Masjid tidak ada pungutan biaya apapun dan termasuk prosesnya harus cepat.</p>\n\n<p><br />\n&quot;Pengurusan proses ijin masjid, tidak dikenakan biaya apapun alias gratis, juga dihimbau untuk para pelayanan izin proses tersebut harus cepat, tidak diperlambat&quot; tegas Wali Kota.</p>\n\n<p><br />\nDi intruksikan kepada sluruh Camat agar mendata masjid-masjid yang ada di wilayahnya, untuk melindungi dengan payung hukum, serta di himbau kepada Lurah di seluruh Kota Bekasi, di setiap wilayah Kelurahan harus memiliki Masjid Jami dan di Wilayah Kecamatan harus pilih salah satu Masjid untuk dijadikan Masjid Raya agar setiap warga di kota bekasi mempunyai khas di wilayahnya.</p>\n\n<p><br />\nSelain itu, Wali Kota juga menceritakan tidak hanya pembangunan rumah ibadah seperti gereja dan lain lain, pembangunan Masjid pun juga ada terjadi penolakan akan tetapi sudah terselesaikan. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-13 10:40:00', '2017-05-13 10:40:00', NULL),
('eb3d2dc0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota hadiri Pengukuhan Federasi Olahraga Rekreasi Masyarakat Indonesia (FORMI) Kota Bekasi', 'wali-kota-hadiri-pengukuhan-federasi-olahraga-rekreasi-masyarakat-indonesia-formi-kota-bekasi', 'Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi menyaksikan Pelantikan serta Pengukuhan Federasi Olahraga Rekreasi Masyarakat Indonesia (FORMI) cabang Kota Bekasi Periode 2016-2021 pada hari Min', '<p>Kota Bekasi ---- Wali Kota Bekasi, Dr. Rahmat Effendi menyaksikan Pelantikan serta Pengukuhan Federasi Olahraga Rekreasi Masyarakat Indonesia (FORMI) cabang Kota Bekasi Periode 2016-2021 pada hari Minggu (14/05/2017) di Arena Car Free Day Kota Bekasi, hadir Ketua FORMI Provinsi Jawabarat, Drs. Sigit Pramono yang melakukan pengukuhan untuk Cabang Kota Bekasi.</p>\n\n<p><br />\nH. Solecha, Ketua FORMI Cabang Kota Bekasi terpilih sekaligus Anggota Dewan DPRD Kota Bekasi dengan siap akan bersinegritas dengan Pemerintah Kota Bekasi untuk lakukan aktifitas positif di wilayah Kota Bekasi, dengan sinegritas Dinas Pemuda dan Olahraga Kota Bekasi untuk mengadakan event rutin di CFD maupun ajang lainnya.</p>\n\n<p><br />\nWali Kota Bekasi dalam sambutannya, berharap FORMI Kota Bekasi bisa menjadi mitra dalam pengembangan Olahraga Rekreasi di Kota Bekasi, agar bisa memajukan di bidang olahraga sesuai visi Kota Bekasi. Selain itu, Wali Kota menceritakan mengenai penghargaan dari Nasional mengenai penyelenggara Car Free Day terbaik untuk Kota Bekasi.</p>\n\n<p><br />\nDi kesempatan yang sama, Wali Kota memperkenalkan Kartu Sehat Bekasi berbasis NIK keluaran dari Pemerintah Kota Bekasi yang bisa dimiliki Warga Kota Bekasi, berguna untuk pelayanan di bidang kesehatan dan tanpa biaya yang di atur dari keuangan apbd dari pajaknyang dibayarkan oleh warga. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-14 10:03:00', '2017-05-14 10:03:00', NULL),
('eb3d2e0f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'HUT BJB Ke 56, Wali Kota Bekasi Hadiri Khitanan Massal', 'hut-bjb-ke-56-wali-kota-bekasi-hadiri-khitanan-massal', 'Kota Bekasi ---- Dalam rangka Hari Jadi Bank Jabar Banten (BJB) ke 56, BJB Kota Bekasi menyelenggarakan Khitanan Massal di Kantor Cabang Kota Bekasi, Jalan Ir. H. Juanda, Bekasi Timur, Wali Kota Bekas', '<p>Kota Bekasi ---- Dalam rangka Hari Jadi Bank Jabar Banten (BJB) ke 56, BJB Kota Bekasi menyelenggarakan Khitanan Massal di Kantor Cabang Kota Bekasi, Jalan Ir. H. Juanda, Bekasi Timur, Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam kegiatan tersebut bersama Kepala BPKAD, Supandi Budiman.</p>\n\n<p><br />\nDi dalamnya, Wali Kota yang menyempatkan menyapa para warga Kota Bekasi yang ikut mendaftarkan anak-anaknya dalam event khitanan massal, sekaligus dialog mengenai Kartu Bekasi Sehat berbasis NIK, Wali Kota menjelaskan proses membuat kartu tersebut, dengan memberikan data Fotokopi KTP Kepala Keluarga dan Kartu Keluarga serta diberikan kepada Lurah dan nantinya akan diserahkan kembali berbentuk Kartu Sehat. Adapun yang menanyakan tetapi dari luar Warga Kota Bekasi seperti Kabupaten Bekasi, Wali Kota menyanggah bahwa program tersebut hanya dimiliki Warga berKTP Kota Bekasi.</p>\n\n<p><br />\nWali Kota Bekasi memberikan sambutan tetap mensosialisasikan mengenai Kartu Sehat Berbasis NIK, karena kartu tersebut bisa berfungsi di rumah sakit swasta mana saja yang dibangun di Kota Bekasi, Wali Kota juga menegaskan jika ada yang menolak kartu tersebut maka lapor ke Wali Kota ataupun Dinas Kesehatan Kota Bekasi dan kami tidak segan menegur hingga menutup Rumah Sakit tersebut.</p>\n\n<p><br />\nAcara yang terselenggara dari BJB, hampir 80% warga Kota Bekasi, terdaftar sebanyak 300 anak anaka yang akan di khitan dan diberi santunan, Wali Kota juga menyapaikan salam kepada Direktur Utama Bank Jabar Banten telah berpartisipasi untuk Kota Bekasi. (Ndoet)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-14 10:06:00', '2017-05-14 10:06:00', NULL),
('eb3d2e5e-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Hadiri Tabligh Akbar dan Haul KH. Muchtar Tabrani Ponpes An-Nur', 'wali-kota-hadiri-tabligh-akbar-dan-haul-kh-muchtar-tabrani-ponpes-an-nur', '&nbsp;\n\n\nKota Bekasi ---- Bersama Menteri Tenaga Kerja Republik Indonesia, Hanif Dhakiri, Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara Tabligh Akbar dan Haul KH. Muchtar Tabrani yang diselen', '<p>&nbsp;</p>\n\n<p><br />\nKota Bekasi ---- Bersama Menteri Tenaga Kerja Republik Indonesia, Hanif Dhakiri, Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara Tabligh Akbar dan Haul KH. Muchtar Tabrani yang diselenggarakan dari Pondok Pesantren An-Nur Bekasi Utara pada hari Minggu (14/05/2017).</p>\n\n<p><br />\nWali Kota Bekasi akan memberikan bantuan dari Pemerintah Kota Bekasi untuk Pondok Pesantren An-Nur dan beberapa Ponpes lain sebesar 1 Milyar untuk membantu kelengkapan dan pendirian ponpes tersebut, ada 3 Ponpes yang akan dibantu dari Pemerintah Kota Bekasi.</p>\n\n<p><br />\nDalam sambutannya, Wali Kota juga menerangkan bahwa sebagai Kepala Daerah harus berdiri di semua golongan, karena Kota Bekasi telah menjadi satu simbol percontohan mengenai kerukunan umat beragama dan mendapatkan penghargaan dari Komnas HAM mengenai Kota bertoleransi dengan Kota Bandung dan Kota Manado.</p>\n\n<p><br />\nSelain itu, Wali Kota juga mensosialisasikan kembali mengenai Kartu Sehat Bekasi yang harus di miliki Warga Kota Bekasi, untuk mempermudah pelayanan di Kesehatan dan antisipasi warga yang berpenghasilan rendah jika ada yang sakit dan membutuhkan pengobatan di Rumah Sakit yang berdiri di Kota Bekasi.</p>\n\n<p><br />\nSementara itu, selain Menteri Tenaga Kerja RI, Ponpes An-Nur juga mengundang Wali Kota Bandung, Ridwan Kamil akan tetapi tidak bisa hadir dikarenakan ada acara lain. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-14 10:13:00', '2017-05-14 10:13:00', NULL),
('eb3d2ead-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Hadiri Musrenbang Kepolisian Republik Indonesia', 'wali-kota-bekasi-hadiri-musrenbang-kepolisian-republik-indonesia', 'Jakarta - Wali Kota Bekasi DR. Rahmat Effendi menghadiri Musyawarah Rencana Pembangunan( Musrenbang) Mabes Polri yang bertempat di Auditorium Sekolah Tinggi Ilmu Kepolisian (STIK ), Jakarta, , Senin (', '<p>Jakarta - Wali Kota Bekasi DR. Rahmat Effendi menghadiri Musyawarah Rencana Pembangunan( Musrenbang) Mabes Polri yang bertempat di Auditorium Sekolah Tinggi Ilmu Kepolisian (STIK ), Jakarta, , Senin (15/5/2017) pagi.</p>\n\n<p>Musrenbang tingkat kepolisian tahun 2017 dibuka oleh Kapolri Jenderal Pol Drs Tito Karnavian, M.A, Ph.D, dengan mengambil Tema &ldquo;Akselerasi Reformasi Birokrasi Guna Mewujudkan Polri Yang Promoter&rdquo;, yang diikuti Wakapolda dan Karo Rena Polda se Indonesia,&nbsp; Karo Renmin dan Kabag Renmin Satk dan disaksikan secara langsung oleh seluruh kapolda di Indonesia.</p>\n\n<p>Kapolri Jenderal Pol Drs Tito Karnavian, M.A, Ph.D dalam arahannya meminta seluruh&nbsp; jajaran untuk melakukan perbaikan kultur dan media manajemen dalam pelaksanaan tugas.</p>\n\n<p>&ldquo;Optimalisasi pelatihan diskresi kepolisian untuk meningkatkan ketrampilan anggota melalui pendidikan dan pelatihan.&nbsp; Karena tanpa adanya pelatihan mustahil anggota bisa memahami dan memperoleh pengetahuan yang cukup , &ldquo;terang Kapolri.</p>\n\n<p><br />\nDalam musrenbang ini Kapolri juga berterima kasih kepada pemimpin daerah yang telah banyak membantu kepolisian ditempat mereka masing - masing yaitu dengan memberikan fasilitas dan infrastruktur untuk meningkatkan pelayanan kepolisian kepada masyarakat.</p>\n\n<p>Dalam musrenbang ini beberapa Walikota hadir diantaranya Walikota Bekasi DR. Rahmat Effendi, Wali Kota Tanggerang Selatan Airin Rachmi, Wali Kota Bandung Ridwan Kamil dan Wali Kota Makassar.</p>\n\n<p>Pada kesempatan ini Kapolri juga berharap kepada pemerintah daerah yang hadir dalam musrembang agar kembali membantu kepolisian dalam hal pembangunan perumahan bagi anggota polri.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-15 06:49:00', '2017-05-15 06:49:00', NULL),
('eb3d2f02-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Kunjungi Warga yang di Indikasikan Terkena Saraf Kejepit', 'wali-kota-bekasi-kunjungi-warga-yang-di-indikasikan-terkena-saraf-kejepit', 'Kota Bekasi - Kurang maksimal nya pelayanan publik kembali dikeluhkan oleh masyarakat Kota Bekasi hal ini ditunjukkan oleh mereka yang langsung mengadukan permasalahan mereka kepada Wali Kota Bekasi D', '<p>Kota Bekasi - Kurang maksimal nya pelayanan publik kembali dikeluhkan oleh masyarakat Kota Bekasi hal ini ditunjukkan oleh mereka yang langsung mengadukan permasalahan mereka kepada Wali Kota Bekasi DR. Rahmat Effendi, Senin( 15/5).</p>\n\n<p>Dalam aspirasinya masyarakat mengeluhkan pelayan Rumah Sakit yang banyak tidak mau menerima peserta BPJS Kesehatan, &quot; ribet pak harus mondar - mandir kesana kemari begitu udah selesai malah ditolak , &quot;ucap anak dari bapak asmawi.</p>\n\n<p>Bapak Asnawi beralamat Jl. Jatikramat Indah II No. 22 Rt. 007/003 Kel. Jatikramat Kec.Jatiasih. Kota Bekasi di indikasikan menderita saraf kejepit, &quot; sebelumnya kita sudah ke berbagai rumah sakit tetapi dengan terbentur biaya dengan gaji saya yang hanya 2.5 juta perbulan tidak mencukupi biaya seharihari, &quot; ucap erik suseno menantu bapak asnawi.</p>\n\n<p>&quot; Sekitar jam sebelas saya mendapat telpon dari warga, kebetulan saya selesai menghadiri acara polri yang melewati daerah tersebut langsung kita menuju ke tempat bapak asnawi, &quot; ucap Wali Kota Bekasi.</p>\n\n<p>Apa yang saya dapati dilapangan, tambahnya, masyarakat sudah terbentuk opini bahwa pelayanan publik sangat jauh dari ekspetasi saya dan memang apabila ditinjau langsung dilapangan memang begitulah adanya.</p>\n\n<p>Saya menginginkan seluruh birokrat dan pelayanan di lingkup Kota Bekasi untuk merubah mindset tentang pelayanan terhadap masyarakat, &quot; Kita harus berfikir out the box kalau memang dapat diselesaikan hari ini tidak usah menunggu waktu yang telah ditentukan, &quot; tegas nya.</p>\n\n<p>Ia juga menegaskan agar pola pola birokrasi yang dapat menghambat masrakat agar cepat dibuang, apabila kita tidak berubah bukan tidak mungkin kepercayaan masyarakat terhadap pemerintah akan hilang.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-15 06:53:00', '2017-05-15 06:53:00', NULL),
('eb3d2f51-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Mengapresiasi 108 Siswa-siswi Dengan Beasiswa', 'wali-kota-mengapresiasi-108-siswa-siswi-dengan-beasiswa', '&nbsp;Kota Bekasi, -- Pemerintah Kota Bekasi memberikan apresiasi bagi para siswa dan siswi se-Kota Bekasi yang diterima di Universitas Padjadjaran melalui jalur Seleksi Nasional Masuk Perguruan Tingg', '<p>&nbsp;Kota Bekasi, -- Pemerintah Kota Bekasi memberikan apresiasi bagi para siswa dan siswi se-Kota Bekasi yang diterima di Universitas Padjadjaran melalui jalur Seleksi Nasional Masuk Perguruan Tinggi Negri (SNMPTN) tahun ajaran 2017&ndash;2018 bertempat di Aula H. Nonon Sonthanie Gedung Lt. 10 Kantor Wali Kota Bekasi. Senin (15/5/2017)</p>\n\n<p>Wali Kota Bekasi, Rahmat Effendi, turut menghadiri kegiatan ini dalam memberikan apresiasi bagi siswa-siswi yang diterima menjadi mahasiswa Universitas Padjadjaran melalui jalur SNMPTN tahun ajaran 2017&ndash;2018 berjumlah 108 orang.</p>\n\n<p>Kepala Cabang Bank BJB Kota Bekasi, Imam, juga turut menghadiri acara tersebut beserta Guru Besar Universitas Padjadjaran, Camat, Sekretaris Dinas Pendidikan Kota Bekasi, Staff Ahli Wali Kota Bekasi dan Orang Tua dari siswa-siswi yang diterima di Universitas Padjadjaran.&nbsp;</p>\n\n<p>Dalam acara apresiasi ini yang terselenggara berkat kemitraan antara Pemerintah Kota Bekasi, Universitas Padjadjaran dan Bank BJB. Rahmat Effendi mengatakan bahwa pada awal tahun 2018, Pemerintah Kota Bekasi akan memberikan beasiswa kepada 108 siswa yang berhasil melalui proses SNMPTN dan lulus diterima di Universitas Padjadjaran, diberikan per semester setinggi - tingginya 10 juta yaitu menjadi 20 juta selama satu tahun perkuliahan.&nbsp;</p>\n\n<p>Besar harapan juga tidak lupa disampaikan oleh Wali Kota Bekasi, Rahmat Effendi, bagi siswa-siswi yang diterima menjadi mahasiswa di Universitas Padjadjaran melalui proses SNMPTN &ldquo;semoga anak-anakku sekalian sebagai regenerasi dari proses kepemimpinan masyarakat Kota Bekasi yang mampu menciptakan masyarakat yang dinamis, maju, sejahtera dan ihsan. Selamat dan suskes untuk kalian semua anak-anakku dalam menuntut ilmu di Universitas Padjadjaran melalui jalur SNMPTN dan menjadi orang-orang berkapasitas intelektual, emosional dan spiritual&rdquo;. (bar)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-16 01:45:00', '2017-05-16 01:45:00', NULL),
('eb3d2fa0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Dishub Kota Bekasi Luncurkan Angkot Ber- AC', 'dishub-kota-bekasi-luncurkan-angkot-ber-ac', 'Kota Bekasi, 16/5/2017. Dirjen perhubungan Daerat Kemenhub RI Pudji Hartanto Iskandar meresmikan peluncuran Angkot Ber-AC, hari selasa (15/5) bertempat di halaman Kantor Wali Kota Bekasi.\n\nAngkutan um', '<p>Kota Bekasi, 16/5/2017. Dirjen perhubungan Daerat Kemenhub RI Pudji Hartanto Iskandar meresmikan peluncuran Angkot Ber-AC, hari selasa (15/5) bertempat di halaman Kantor Wali Kota Bekasi.</p>\n\n<p>Angkutan umum konvensional berpendingin udara (AC) merupakan solusi efektif menyikapi persaingan bisnis dengan angkutan online saat ini, ujarnya.Pudji menjelaskan, peningkatan fasilitas bagi angkutan kota juga di atur dalam Peraturan Menteri Perhubungan (Permenhub) Nomor 29 tahun 2015, bahwa, angkutan perkotaan minimum memiliki AC.</p>\n\n<p>&quot;Saya apresiasi terhadap ibu Haiva Rossi yang mau malakukan inovasinya terhadap angkot miliknya yaitu dengan memberikan AC&quot;, tuturnya.</p>\n\n<p>Sementara itu, Kepala Dinas Perhubungan Kota Bekasi, Yayan yuliana mengatakan, angkot K-02 Jurusan Terminal Bekasi-Pondok gede milik ibu Haiva ini akan menjadi angkot percontohan bagi angkot-angkot lain.Diharapkan nanti para pemilik angkot akan mengikuti apa yang sudah dilakukan oleh ibu Haiva. sehingga masyarakat akan merasa nyaman ketika<br />\nmenaiki angkot yang memiliki AC, ujarnya.</p>\n\n<p>&quot; ini patut kita apresiasi dan kita dukung demi meningkatkan pelayanan terhadap penumpang&quot;, tandasnya. (yas).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-16 04:53:00', '2017-05-16 04:53:00', NULL),
('eb3d2ffc-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wakil Wali Kota Hadiri Tarhib Ramadhan 1438 H', 'wakil-wali-kota-hadiri-tarhib-ramadhan-1438-h', 'Bekasi - Kegembiraan akan datangnya bulan suci Ramadhan 1438 H, Wakil Wali Kota Bekasi, Ahmad Syaikhu, menghadiri Tarhib Ramadhan beserta Wakil Gubernur Jawa Barat, Deddy Mizwar, yang bertempat di Isl', '<p>Bekasi - Kegembiraan akan datangnya bulan suci Ramadhan 1438 H, Wakil Wali Kota Bekasi, Ahmad Syaikhu, menghadiri Tarhib Ramadhan beserta Wakil Gubernur Jawa Barat, Deddy Mizwar, yang bertempat di Islamic Centre KH. Noer Alie Bekasi. Selasa (16/5/2017).</p>\n\n<p>Pada kegiatan ini yang bertema &quot;Membangun Mental Sabar Dan Taqwa Untuk Kemenangan Sejati &quot; (Qs.3 : 120 &amp; 7 : 201) dihadiri juga oleh Istri Gubernur Jawa Barat, Netty Prasetiyani Heryawan, Ketua Dewan Yayasan Nurul Islam Islamic Centre KH. Noer Alie Bekasi, Ketua MUI Pusat, Ketua BKMT DKI Jakarta dan diikuti kurang lebih 400 peserta.</p>\n\n<p>&quot;Ramadhan adalah bulan ketahanan keluarga, melihat banyaknya permasalahan sosial terhadap anak yang dialami di dalam keluarga. Sebagai orang tua harus lebih banyak mendengar suara anak, orang tua harus kreatif dan harus mampu menjaga dari bahaya zaman&quot;, demikian disampaikan oleh Netty Prasetiyani Heryawan.</p>\n\n<p>Ahmad Syaikhu menambahkan, bahwa rasa kasih sayang yang tumbuh dalam keluarga tidak akan ada kekerasan di dalam keluarga.</p>\n\n<p>Menyambut akan datangnya bulan suci Ramadhan yang penuh berkah, orang-orang berlomba untuk memperbaiki diri dengan berbuat kebaikan, menjalin silaturahmi dan berbagi kepada yang membutuhkan.</p>\n\n<p>Wakil Wali Kota Bekasi, Ahmad Syaikhu, mengajak masyarakat Kota Bekasi untuk menyongsong bulan suci Ramadhan dengan penuh kegembiraan dan semoga di bulan suci Ramadhan 1438 H dapat menjadikan cahaya kehidupan menuju insan yang lebih baik dikemudian hari. (bar)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-17 02:08:00', '2017-05-17 02:08:00', NULL),
('eb3d304f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Perintahkan Tindak Tegas Reklame Tak Berizin', 'wali-kota-bekasi-perintahkan-tindak-tegas-reklame-tak-berizin', 'Kota Bekasi - Kota Bekasi yang mengandalkan&nbsp; Pendapatan Asli Daerah (PAD) dari sektor jasa&nbsp; terus berbenah untuk meningkatkan pendapatan dari sektor izin pendirian reklame.\n\nUntuk meningkatk', '<p>Kota Bekasi - Kota Bekasi yang mengandalkan&nbsp; Pendapatan Asli Daerah (PAD) dari sektor jasa&nbsp; terus berbenah untuk meningkatkan pendapatan dari sektor izin pendirian reklame.</p>\n\n<p>Untuk meningkatkan pendapatan dari sektor tersebut Wali Kota Bekasi DR. Rahmat Effendi bersama Kepala Dinas Pekerjaan Umum dan Penataan Ruang (PUPR) Tri Adhianto, melakukan pemeriksaan mendadak terhadap reklame videotron yang terpasang di salah satu apartemen yang terletak di Jalan Caman, Kota Bekasi, Rabu, 17/5.</p>\n\n<p><br />\n&quot; Kebocoran pajak dari izin reklame ini sangat merugikan Kota Bekasi, karena pajak reklame tersebut adalah salah satu potensi yang dapat mendongkrak PAD Kota Bekasi, &quot; jelas Wali Kota Bekasi.</p>\n\n<p>Ia juga memerintahkan kepada dinas terkait agar segera menindaknya, &quot; dalam 1 x 24 jam saya perintahkan dinas PUPR untuk mencopot videotron yang telah terpasang, karena ini adalah salah satu sektor yang menyebabkan kebocoran PAD Kota Bekasi, &quot; tegasnya.</p>\n\n<p>Dilokasi yang sama Tri Adianto Kepala Dinas PUPR mengatakan sebelumnya wewenang pengawasan reklame ada di bawah Dinas Pertamanan Pemakaman dan Penerangan Jalan Umjm (DPPPJU). Namun, sejak terbentuknya Satuan Organisasi Tata Kerja (SOTK) baru merujuk pada Peraturan Pemerintah nomor 18 Tahun 2016, wewenang pengawasan reklame pun berpindah tangan di bawah Dinas PUPR.</p>\n\n<p>Tri Adhianto juga menjelaskan dari 1.175 titik reklame yang ada sudah kita turunkan secara paksa sebanyak 10 papan reklame. Namun ia memperkirakan masih ada sekitar 350 reklame serupa yang nanti akan kita turunkan secara paksa bila tak kunjung menyelesaikan kewajibannya.</p>\n\n<p>&quot; untuk videotron ini sebelumnya sudah kita berikan surat peringatan 1, 2 dan 3 tetapi mereka belum juga merespon surat kita, maka sesuai arahan Wali Kota pada hari ini akan kita copot, &quot; ujar kepala Dinas PUPR.(tdy)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-17 08:52:00', '2017-05-17 08:52:00', NULL),
('eb3d309f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Bekasi Kembali Antarkan Kartu Sehat ke Warga Bintara', 'wali-kota-bekasi-kembali-antarkan-kartu-sehat-ke-warga-bintara', 'Kota Bekasi ---- Kamis (18/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi kembali antarkan Kartu Sehat Berbasis Nomor Induk Kependudukan (NIK), kali ini warga bernama Novi Rahmawati yang terkena Tumor', '<p>Kota Bekasi ---- Kamis (18/05/2017), Wali Kota Bekasi, Dr. Rahmat Effendi kembali antarkan Kartu Sehat Berbasis Nomor Induk Kependudukan (NIK), kali ini warga bernama Novi Rahmawati yang terkena Tumor Ganas menurut info disebabkan karena jatuh, beralamatkan di Jalan Bintara RT 07/04, Kelurahan Bintara, Kecamatan Bekasi Barat di dampingi Lurah Bintara, Endang.</p>\n\n<p><br />\nDalam kunjungannya, Wali Kota Bekasi sempat menanyakan kondisi Novi Rahmawati dan sempat membujuk untuk mau berobat, terlihat ananda Novi tersebut takut untuk berobat dan diangkat penyakitnya, hingga menangis saat di bujuk oleh Wali Kota.</p>\n\n<p><br />\nSelain Hal tersebut, Keluarga Novi atas nama Kepala Keluarga Hartoyo juga tidak memiliki biaya untuk berobat ke Rumah Sakit, ajuan untuk kartu sehat yang langsung dari tim langsung diberikan dan diantar langsung oleh Wali Kota Bekasi kepada Bapak Hartoyo, tersentak bapak tersebut memeluk Wali Kota.</p>\n\n<p><br />\nRencananya, Pasien akan di bawa ke Rumah Sakit Cipto Mangun Kusumo di Jakarta yang sudah siap menerima secara urgent untuk warga Kota Bekasi yang memiliki Kartu Sehat Berbasis NIK.</p>\n\n<p><br />\nDilain itu, ada juga warga yang langsung meminta tolong agar di buatkan Kartu sehat untuk anaknya karena sakit sudah lama dan tidak bisa berobat karena tidak memiliki biaya berobat, Wali Kota mengintruksikan kepada lurah agar langsung di antar ke bagian Dinas Kependudukan dan Catatan Sipil untuk perekaman E-KTP agar bisa dibuatkan langsung kartu sehat berbasis NIK. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-18 02:17:00', '2017-05-18 02:17:00', NULL),
('eb3d30f0-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Rapat Paripurna Mengenai Rekomendasi DPRD Kota Bekasi Terhadap LKPJ Wali Kota Bekasi Tahun 2016', 'rapat-paripurna-mengenai-rekomendasi-dprd-kota-bekasi-terhadap-lkpj-wali-kota-bekasi-tahun-2016', 'Kota Bekasi ----- Wali Kota Bekasi, Dr. Rahmat Effendi bersama Wakil Wali Kota Bekasi, Ahmad Syaikhu hadiri Rapat Paripurna penyampaian rekomendasi DPRD Kota Bekasi terhadap Laporan Keterangan Pertang', '<p>Kota Bekasi ----- Wali Kota Bekasi, Dr. Rahmat Effendi bersama Wakil Wali Kota Bekasi, Ahmad Syaikhu hadiri Rapat Paripurna penyampaian rekomendasi DPRD Kota Bekasi terhadap Laporan Keterangan Pertanggungjawaban (LKPJ) Wali Kota Bekasi Tahun 2016 pada hari Kamis (18/05/2017) di gedung DPRD Kota Bekasi, Kecamatan Bekasi Timur, Rapat Paripurna di pimpin oleh Wakil Ketua DPRD Kota Bekasi, Heri Koswara.</p>\n\n<p><br />\nWakil Wali Kota Bekasi, Ahmad Syaikhu membacakan sambutan mewakili Wali Kota Bekasi yang juga hadir dalam rapat paripurna tersebut.</p>\n\n<p><br />\nReview Rencana Pembangunan Jangka Panjang Menengah Daerah (RPJMD) Tahun 2013-2018, pada tahun 2016 ditekankan pada pembangunan infrastruktur dan utilitas dengan maksud memberikan landasan pembangunan yang bertumbuh pesat melalui penyediaan infrastruktur dan utilitas perkotaan yang mendorong bagi para masuknya modal pihak swasta untuk berinvestasi di Kota Bekasi.</p>\n\n<p><br />\nFungsinya memberikan arahan dan gambaran bahwa Pemerintah Kota Bekasi menginginkan arah pembangunan yang di fokuskan kepada mengingkatnya infrastruktur perkotaan dan meningkatkan pengendalian Sampah serta Banjir dengan sistem drainase yang baik.</p>\n\n<p><br />\n&quot;Kami yakin masih banyak keberhasilan pembangunan lainnya dalam bidang seperti peningkatan akses dan mutu pendidikan, kesehatan, penataan taman-taman, pembenahan sektor pelayanan publik, kualitas sdm dan lainnya&quot; ujar Wakil Wali Kota Bekasi.</p>\n\n<p><br />\nSelain itu, di sampaikan juga ucapan terimakasih kepada Pansus 19 DPRD Kota Bekasi yang telah bekerja keras dalam melakukan pembahasan dan pendalaman atas LKPJ kepala daerah Kota Bekasii, dan kami percaya bahwa seluruh anggota pansus 19 DPRD bekerja sesuai dengan ketentuan dan mekanisme serta melakukan pembahasan dan pendalaman secara objektif sehingga menghasilkan rekomendasi hingga menjadi Tim Pansus 20 DPRD Kota Bekasi</p>\n\n<p><br />\nKami selaku Kepala Daerah baik dari Wali Kota dan Wakil Wali Kota menyadari masih belum sempurna dalam melaksanakan program-program pada tahun 2016, akan tetapi kita bisa lihat dari segi pembangunan di Kota Bekasi yang telah berkembang pesat, pembangunan apartemen, pusat perbelanjaan dan yang menjadi penting mengenai para pihak swasta yang telah ikut partisipasi dalam penggabungan modal untuk dibayarkan pajak dan menginvestasikan untuk dilimpahkan menjadi APBD Kota Bekasi. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-18 06:21:00', '2017-05-18 06:21:00', NULL),
('eb3d313f-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Kabag Humas Terima Kunker DPRD Kabupaten Bangka', 'kabag-humas-terima-kunker-dprd-kabupaten-bangka', 'Kota BEkasi, 18/5/2017. Kepala Bagian Humas Setda Kota Bekasi Dr. H. MHD Jufri, SH, MH menerima kunjungan kerja dari anggota Dewan DPRD Kabupaten Bangka dalam rangka&nbsp;&nbsp;studi banding guna mena', '<p>Kota BEkasi, 18/5/2017. Kepala Bagian Humas Setda Kota Bekasi Dr. H. MHD Jufri, SH, MH menerima kunjungan kerja dari anggota Dewan DPRD Kabupaten Bangka dalam rangka&nbsp;&nbsp;studi banding guna menambah wawasan dan referensi dalam pembahasan terhadap Raperda tentang pencabutan peraturan Daerah Kabupaten Bangka , bertempat di Press Room Bagian Humas setda Kota Bekasi, Kamis, (18/5).</p>\n\n<p>Hadir mendampingi Kepala Bagian Humas Kepala Sub Bagian&nbsp;&nbsp;Hukum, Gomos Jaksana, Kasubag Fasilitasi Kunjungan Daerah Rosmala Sulastri, SE, MM beserta jajarannya.</p>\n\n<p>Rombongan DPRD Kabupaten Bangka yang berjumlah 12 orang dipimpin oleh H. Hendra Yunus selaku Ketua Pansus II hadir bersama 12 orang.</p>\n\n<p>Dalam dialog interaktif dibahas &nbsp;tentang Pencabutan Perda yang &quot;overlap&quot; tentang pertambangan dan perhutanan.</p>\n\n<p>Undang-undang yang overlap perlu diadakan komunikasi dengan pusat untuk diadakannya recovery, salah satu bentuk recoverynya dengan memfoto kerusakan-kerusakan yang telah ditimbulkan, terang Kepala Bagian Humas, MHD Jufri menjawab pertanyaan salah satu anggota DPRD Kabupaten Bangka. &nbsp;</p>\n\n<p>&quot;Jika Perda tidak ada aturan diatasnya seperti Peraturan Menteri atau peraturan pemerintah atau Undang-Undang maka perda tersebut implementasinya lemah sehingga pengawasan Perda ini memicu persoalan di tengah masyarakat.&quot; ujarnya&nbsp;.(dro/yas)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-19 15:30:00', '2017-05-19 15:30:00', NULL),
('eb3d3196-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali : Kasie Kessos Akan Jadi Ujung Tombak Pencegahan Zoonosis', 'wawali-kasie-kessos-akan-jadi-ujung-tombak-pencegahan-zoonosis', 'Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri dan membuka Sosialisasi Komisi Daerah (Komda) Pengendalian Penyakit Hewan Liar atau zoonosis tentang penularan penyakit dari hewan kepada m', '<p>Kota Bekasi, Wakil Wali Kota Bekasi Ahmad Syaikhu menghadiri dan membuka Sosialisasi Komisi Daerah (Komda) Pengendalian Penyakit Hewan Liar atau zoonosis tentang penularan penyakit dari hewan kepada manusia bertempat di Aula RM. Wulan Sari Jl. Kemakmuran, Bekasi Selatan, Kamis (18/5).</p>\n\n<p>Hadir pada kegiatan ini Kepala Bagian Kessos Ahmad Yani sebagai lini sektor penyelenggaraankegiatan, juga kepala SKPD dil lingkungan Pemerintah Kota Bekasi, perwakilan Kantor Kementrian Agama Kota Bekasi serta para peserta kegiatan Sosialisasi para Kasie Kessos kecamatan dan kelurahan se-Kota Bekasi</p>\n\n<p>Pada awal sambutannya Wakil Wali Kota sangat berharap agar sosialisasi ini benar-benar dimanfaatkan dengan sebaik-baiknya untuk lebih mendalami hal-hal yang menyangkut penyebaran penyakit yang di sebarkan oleh hewan-hewan di sekitar kita.</p>\n\n<p>&quot;Karena nantinya bapak ibu Kasie Kessos dapat menjadi ujung tombak untuk dapat mengsosialisasikan kembali ke masyarakat yang ada dilingkungannnya karena banyak penyakit-penyakit muncul dari hewan seperti Antrax, Rabies, DBD, Cikumunya dan flu burung sehingga semakin sadar bahwa lingkungan kita akan sangat rentan terhadap berbagai infeksi yang disebabkan oleh hewan&quot;&nbsp;ungkapnya.</p>\n\n<p>&quot;Bila hal-hal ini dipahami maka sumber-sumber yang menyebabkan penyakit seperti rabies bisa kita deteksi misalnya bila melihat hewan anjing dan terindikasi mengidap penyakit rabies dapat dilaporkan, dengan di foto kemudian masukkan laporannya melalui Sorot atau POT nantinya laopan akan didistribusi ke dinas terkait&quot; ujarnya</p>\n\n<p>Wawali juga menyampaikan bahwa kunci yang sesungguhnya adalah kepedulian dan rasa sensitifitas kita ketika kita berinteraksi dengan hal-hal yang ada di lingkungan sehingga mampu meminimalisir berbagai permasalahan zoonosis yang ada di Kota Bekasi dan akhirnya akan ada rasa kepemilikan terhadap lingkungan.</p>\n\n<p>&quot;Keprihatinannya bahwa diantara penyakit-penyakit yang ada 70% emerging infeksius disease disebabkan oleh faktor-faktor zoonosis, oleh karenanya bila kita tidak memiliki kepedulian dan terjadi pembiaran maka sangat mungkin berbagai penyebaran-penyebaran penyakit akan semakin mewabah di lingkungan masyakarat kita&quot; ungkapnya.</p>\n\n<p>Mudah-mudahan dengan sosialisasi ini, nantinya pada tataran implementasinya harus dilakukan dengan penanganan secara terpadu yang mana terdapat unsur kesehatan manusianya yang terjaga, kesehatan hewan yang ada dilingkungan juga terjaga.</p>\n\n<p>&quot;Juga dengan pola hidup sehat, sehat orangnya, sehat hewannya dan sehat lingkungan sekitarnya saya yakin ini juga akan mampu meminimalisir berbagai macam penyakit yang disebabkan oleh hewan&quot; (gie)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-19 15:35:00', '2017-05-19 15:35:00', NULL),
('eb3d31eb-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wali Kota Dialog Dengan Para PSM dan TKSK Kecamatan', 'wali-kota-dialog-dengan-para-psm-dan-tksk-kecamatan', 'Cisarua-Bogor ------ Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara peningkatan Kapasitas Kelembagaan Pekerja Sosial Masyarakat (PSM) dan Tenaga Kesejahteraan Sosial Kecamatan (TKSK) Kota Beka', '<p>Cisarua-Bogor ------ Wali Kota Bekasi, Dr. Rahmat Effendi hadir dalam acara peningkatan Kapasitas Kelembagaan Pekerja Sosial Masyarakat (PSM) dan Tenaga Kesejahteraan Sosial Kecamatan (TKSK) Kota Bekasi pada hari Kamis (18/05/2017) di Vila Puri Avia, Cipayung didampingi Kepala Dinas Sosial Kota Bekasi, H. Junaedi.</p>\n\n<p><br />\nDalam diskusinya, salah satu koordinator PSM wilayah Kecamatan Jatisampurna, Saman dipanggil oleh Wali Kota Bekasi untuk menceritakan mengenai permasalahan permasalahan yang terjasi di masyarakat, ia pun menceritakan bahwa PSM maupun TKSK adalah Pekerja Sosial yang tanpa pamrih dibayarkan, akan tetapi tetap membutuhkan sesuatu untuk menjadi penyemangat dalam bekerja di bidang sosial.</p>\n\n<p><br />\nPekerja sosial seperti PSM dan TKSK berdiri sebanyak 133 orang, &nbsp;yang terdiri dari TKSK 1 Kecamatan 1 Koordinator selain itu 121 ialah kader dari PSM yang meliputi tugas mengkoordinatorkan para masyarakat yang membutuhkan pertolongan bagi warga yang kurang mampu dan lainnya, Jelas Saman.</p>\n\n<p><br />\nSeperti yang dijelaskan, warga yang membutuhkan di antaranya Anak terlantar, wanita rawan ekonomi, fakir miskin, penyandang disabilitas, pengemis dan gelandangan dan lainnya.</p>\n\n<p><br />\nWali Kota Bekasi memberikan satu masukan penting yakni Harus ada balai latihan kerja, dan rumah singgah untuk para warga yang disebutkan agar masyarakat memiliki solusi untuk para Koordinator PSM dan TKSK setelah bekerja sosial, warga binaan di masukan ke dalam Balai Latihan Kerja agar tau dan berfungsi dalam mengembangkan program PSM dan TKSK tersebut.</p>\n\n<p><br />\nDi lanjutkan, Dinas Sosial harus bekerja sama dengan Dinas Koperasi di bagian Usaha Menengah Kecil Mikro (UMKM) agar mendapatkan kerjasama di bidang rehabilitasi bagi penyandang disibilitas dan para gepeng.</p>\n\n<p><br />\nSerta untuk Ukuran para fakir dan miskin dan yatim piatu yang di jalanan dari penghasilan tapi yang mendidik, seperti dibuatkan home industri.</p>\n\n<p><br />\nJika terjadi bagi penyandang disabilitas jika hanya diberikan bantuan alat itu termasuk Mengurangi kesulitan tapi tidak menyelesaikan permasalahan.</p>\n\n<p><br />\nRencananya, Balai latihan kerja harus menjadi kebutuhan pokok yang nantinya dibangun tiap Kecamatan ada 2 gedung.</p>\n\n<p><br />\nSelain itu, Wali Kota Bekasi memberikan insentif untuk para pekerja Sosial perbulannya akan dirumuskan oleh Kepala Dinas Sosial, agar mendapatkan tambahan insentif selain dari Kementrian Sosial RI, juga akan diberikan kendaraan dinas berupa motor yang akan di dapatkan untuk bekerja sebanyak 133 orang yang ada di PSM dan TKSK, ini merupakan bukti nyata untuk para pekerja sosial agar benar benar serius membantu program Dinas Sosial Kota Bekasi dalam pelayanan masyarakat. (Ndoet)</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-19 15:45:00', '2017-05-19 15:45:00', NULL),
('eb3d323b-d449-11f1-9352-00090faa0001', '0a091f5a-c510-4110-b2b2-2f992091fb1d', '2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Wawali Ingin Munculkan Pribadi Bertaqwa Melalui Masjid dan Majelis Ta\'lim', 'wawali-ingin-munculkan-pribadi-bertaqwa-melalui-masjid-dan-majelis-ta-lim', 'Kota Bekasi, Wakil Wali Kota Bekasi menhadiri Peringatan Isra Mi&#39;raj Nabi Muhammad SAW dan Tarhib Ramadhan 1438 H yang diselenggarakan oleh Badan Keluarga Masyarakat Bekasi (BKMB) Bhagasasi bertem', '<p>Kota Bekasi, Wakil Wali Kota Bekasi menhadiri Peringatan Isra Mi&#39;raj Nabi Muhammad SAW dan Tarhib Ramadhan 1438 H yang diselenggarakan oleh Badan Keluarga Masyarakat Bekasi (BKMB) Bhagasasi bertempat di&nbsp;Markas Budaya dan Adat BKMB Bhagasasi Jl. Kartini No.9 Bekasi Timur, Kamis (18/5).</p>\n\n<p>Hadir pula dalam acara ini Kepala SKPD, Camat dan Lurah se-Kota Bekasi, Ketua BKMB Bhagasasi Aan Suhanda, Ketua Koni Bekasi Abdul Rosyad, Ketua Perbakin Kota Bekasi DR. H. Adhy Firdaus dan Ketua IPSI Kota Bekasi Rahmadsyah.</p>\n\n<p>Wawali pada awal sambutannya berharap dengan semangat kita dekat ke masjid karena ingin menegakkan sholat dan menghidupkan Ramadhan yang sebentar lagi akan tiba, maka inilah yang akan menempa pribadi kita menjadi pribadi yang bertaqwa.</p>\n\n<p>&quot;Kalau pribadi-pribadi yang bertaqwa sudah muncul di tengah masyarakat maka mereka akan bergabung dan ingin pastinya mereka ingin membangun keluarga yang Sakinah Mawadah wa Rahmah, keluarga yang kokoh, keluarga yang ajeg keluarga yang betul-betul tersinari dengan cahaya Al-Qur&#39;an&quot; ujarnya</p>\n\n<p>&quot;Bila sudah banyak keluarga-keluarga yang disinari oleh cahaya Al-Qur&#39;an saya yakin inilah wujud dari Bekasi yang Ihsan dan saya, Pak Wali dan seluruh aparatur akan mudah untuk mengarahkan masyarakat dengan nilai-nilai religiusitas, nilai-nilai yang dekat dengan Al-Qur&#39;an&quot; tambahnya.</p>\n\n<p>Wawali juga sempatkan berpantun &quot;Hari senin ustad mengaji, dari An-Najmi sampai Al-Qomari, kalau pengen bekasi bergengsi, kudu ngaji dan berperstasi&quot;</p>\n\n<p>&quot;Pantun ini muncul ketika ada sebagian orang-orang yang memisahkan kalau mengaji tidak bisa berprestasi, dan kalau berprestasi tidak perlu mengaji, sekarang kita akan buktikan bahwa bagaimana mengaji ini tidak bertentangan dengan berprestasi&quot; ungkapnya</p>\n\n<p>&quot;Kedepan kita harus munculkan semangat untuk mengaji, hadir kemasjid dan majelis ta&#39;lim namun sejalan dengan itu kita terus berprestasi sehingga bekasi kedepan bukan hanya di bully, tapi kita akan banyak prestasi-prestasi yang diukir karena sekarang &quot;Bekasi&quot; itu Bersama Kita Meraih Prestasi&quot; pungkasnya (gie).</p>\n', 'images/20170823065445-2017-08-23post065438.jpg', NULL, NULL, 54146, 'bekasi', 'published', 'index', 1, 0, 0, '2017-05-19 01:46:00', '2017-05-19 01:46:00', NULL);
