INSERT INTO `categories` (`uuid`, `name`, `slug`, `description`, `icon`, `created_at`, `updated_at`) VALUES
('1210a3c0-8ec1-4e8a-9752-b20ed127eb36', 'Pelayanan Publik', 'pelayanan-publik', 'Kegiatan yang berkaitan dengan pelayanan publik dan interaksi langsung dengan masyarakat.', NULL, '2026-10-29 11:19:59', '2026-10-29 11:19:59'),
('15c65e37-42ee-47f2-a864-2ea42178d195', 'Daily Report Media Online', 'daily-report-media-online', 'Laporan harian mengenai publikasi berita, aktivitas media online, dokumentasi pemberitaan, dan rekapitulasi informasi yang diterbitkan.', NULL, '2026-10-29 11:19:42', '2026-10-29 11:19:42'),
('2162d145-9ef3-4e2f-8c55-81971a015bc5', 'Blog', 'blog', 'Artikel, opini, pandangan, dan tulisan informatif yang membahas berbagai topik menarik untuk pembaca.', NULL, '2025-09-15 18:03:22', '2026-10-29 11:11:35'),
('274b0f6b-c25e-43a4-81b7-71d68f0f30da', 'Komunitas', 'komunitas', 'Berita mengenai aktivitas komunitas, kegiatan sosial, pemberdayaan masyarakat, kolaborasi warga, dan gerakan sosial.', NULL, '2026-10-29 11:19:04', '2026-10-29 11:19:04'),
('34103609-8116-4baf-bd17-557fc6989e8e', 'Pemerintahan', 'pemerintahan', 'Berita seputar kebijakan pemerintah, pelayanan publik, program kerja, peraturan, dan kegiatan pemerintahan.', NULL, '2025-09-15 18:03:16', '2026-10-29 11:11:55'),
('3cd6aeb4-305c-4941-a123-ab4da9914b36', 'Kegiatan', 'kegiatan', 'Informasi mengenai pelaksanaan acara, agenda resmi, seminar, sosialisasi, kunjungan kerja, dan aktivitas lainnya.', NULL, '2026-10-29 11:18:47', '2026-10-29 11:18:47'),
('46d66d0b-b094-4b32-b065-30d10ea533d0', 'Ekonomi', 'ekonomi', 'Informasi mengenai perkembangan ekonomi, perdagangan, UMKM, investasi, lapangan kerja, dan aktivitas perekonomian masyarakat.', NULL, '2026-10-29 11:18:20', '2026-10-29 11:18:20'),
('55f28ece-e7c8-4b56-960a-43d22aea4aa5', 'Penghargaan', 'penghargaan', 'Berita mengenai pemberian penghargaan, pencapaian, prestasi, dan apresiasi kepada individu, organisasi, maupun instansi.', NULL, '2026-10-29 11:18:33', '2026-10-29 11:18:33'),
('6ac86b4c-7931-447f-99bd-c276ecb34e6e', 'Olahraga', 'olahraga', 'Berita mengenai pertandingan, kompetisi, prestasi atlet, kegiatan olahraga, dan perkembangan dunia olahraga.', NULL, '2026-10-29 11:19:17', '2026-10-29 11:19:17'),
('72561291-cdcb-484b-a556-0400fbd53c3d', 'Infrastruktur', 'infrastruktur', 'Informasi mengenai pembangunan, perbaikan, dan pemeliharaan infrastruktur seperti jalan, jembatan, drainase, dan fasilitas umum.', NULL, '2025-10-30 20:07:08', '2026-10-29 11:12:15'),
('773cd47c-dc89-4546-b6f0-bfb26f74a0a2', 'Smart City', 'smart-city', 'Berita mengenai inovasi teknologi, transformasi digital, dan penerapan konsep kota cerdas untuk meningkatkan kualitas pelayanan publik.', NULL, '2026-10-07 07:03:26', '2026-10-29 11:17:21'),
('a58f5ebc-c8ec-48da-b6f9-a80b05ca40a0', 'Acara & Seremonial', 'acara-seremonial', 'Peresmian, upacara, peringatan, pelantikan, dan kegiatan seremonial lainnya.', 'fa-calendar-days', '2026-06-20 05:47:44', '2026-10-07 07:03:08'),
('af4bae44-b520-43a2-b653-163cdd4d6dbd', 'Pengumuman', 'pengumuman', 'Informasi resmi mengenai pemberitahuan, jadwal kegiatan, perubahan layanan, dan hal-hal penting yang perlu diketahui masyarakat.', NULL, '2026-10-29 11:17:53', '2026-10-29 11:17:53'),
('e9823f1c-3b6b-4707-92c7-a1586fdce371', 'Foto', 'foto', 'Galeri foto yang mendokumentasikan peristiwa, kegiatan, kondisi lingkungan, dan momen penting lainnya.', NULL, '2026-10-29 11:19:28', '2026-10-29 11:19:28'),
('efed1859-0f9c-4bce-b55c-16f583620e75', 'Pendidikan', 'pendidikan', 'Berita seputar dunia pendidikan, sekolah, perguruan tinggi, prestasi akademik, program pendidikan, dan pengembangan sumber daya manusia.', NULL, '2026-10-29 11:18:04', '2026-10-29 11:18:04');
