INSERT INTO `faqs` (`uuid`, `pertanyaan`, `jawaban`, `kategori`, `urutan`, `status`, `created_at`, `updated_at`) VALUES
('003b8966-bfda-4cb1-9340-7a21929f0c48', 'Siapa yang menjadi wajib pajak Penerangan Jalan?', '<p>Pihak yang menjadi wajib pajak ditetapkan berdasarkan ketentuan peraturan perundang-undangan dan kondisi penggunaan tenaga listrik. Untuk memastikan status dan kewajiban pajak, masyarakat dapat menghubungi perangkat daerah yang menangani pajak daerah.</p>', 'informasi-umum', 3, 'active', '2025-03-02 19:02:30', '2026-11-01 12:59:30'),
('19d4a137-194b-4158-a6f6-a5486ae2abb5', 'Apa yang harus dilakukan jika terdapat ketidaksesuaian data pelanggan listrik?', '<p>Jika menemukan ketidaksesuaian data, masyarakat dapat menyampaikan klarifikasi kepada perangkat daerah terkait dengan melampirkan informasi atau dokumen pendukung yang relevan agar dapat ditindaklanjuti sesuai prosedur.</p>', 'data-pelanggan-listrik', 3, 'active', '2024-02-11 00:48:30', '2026-11-01 12:59:30'),
('1bdd0365-1a05-4f0d-a7be-9af434fe0de7', 'Bagaimana cara mengetahui perkembangan penerimaan pajak dari waktu ke waktu?', '<p>Perkembangan penerimaan dapat diketahui melalui laporan atau publikasi resmi pemerintah daerah yang menyajikan data berdasarkan periode. Ketersediaan rincian informasi mengikuti kebijakan keterbukaan informasi yang berlaku.</p>', 'regulasi-dan-ketentuan', 1, 'active', '2024-05-21 11:40:39', '2026-11-01 12:59:30'),
('259efbb7-c473-4bb3-b295-24c7a14ee585', 'Bagaimana cara mengetahui apakah terdapat tunggakan pajak?', '<p>Wajib pajak dapat meminta informasi mengenai status kewajiban pajaknya kepada perangkat daerah yang menangani pajak daerah melalui kanal layanan resmi dengan menyiapkan identitas atau dokumen pendukung.</p>', 'tunggakan-pajak', 2, 'active', '2026-02-09 13:17:24', '2026-11-01 12:59:30'),
('2cd9d626-f81f-47c7-82b0-0013977c0f4c', 'Apa yang dimaksud dengan potensi Pajak Penerangan Jalan?', '<p>Potensi Pajak Penerangan Jalan adalah perkiraan penerimaan yang dapat dihitung berdasarkan data dan informasi pendukung yang tersedia. Nilai potensi merupakan bahan perencanaan dan evaluasi, sehingga tidak selalu sama dengan jumlah penerimaan yang terealisasi.</p>', 'potensi-pajak', 1, 'active', '2025-05-27 17:32:37', '2026-11-01 12:59:30'),
('2d605f5b-1acf-4dd9-9090-aaf865739a5d', 'Di mana masyarakat dapat memperoleh informasi mengenai potensi penerimaan pajak?', '<p>Informasi resmi mengenai pengelolaan dan potensi penerimaan pajak dapat diperoleh melalui publikasi pemerintah daerah atau perangkat daerah yang berwenang, sepanjang informasi tersebut tersedia untuk masyarakat.</p>', 'potensi-pajak', 2, 'active', '2025-05-26 17:03:50', '2026-11-01 12:59:30'),
('2e68e1c7-3586-45dd-81d9-a7220bfeb4b4', 'Bagaimana cara memastikan pembayaran pajak telah tercatat?', '<p>Simpan bukti pembayaran, kemudian lakukan konfirmasi melalui kanal layanan resmi pemerintah daerah apabila diperlukan. Petugas dapat membantu memeriksa pencatatan pembayaran berdasarkan informasi transaksi yang disampaikan.</p>', 'pembayaran-pajak', 2, 'active', '2024-10-16 17:19:18', '2026-11-01 12:59:30'),
('40bb7232-dd06-4abd-b41f-2cd07239bf1a', 'Di mana masyarakat dapat memperoleh informasi mengenai peraturan Pajak Penerangan Jalan?', '<p>Masyarakat dapat merujuk pada peraturan perundang-undangan dan peraturan daerah yang berlaku melalui Jaringan Dokumentasi dan Informasi Hukum (JDIH) pemerintah atau kanal resmi instansi terkait.</p>', 'regulasi-dan-ketentuan', 2, 'active', '2026-08-27 15:42:27', '2026-11-01 12:59:30'),
('4109270b-07bb-4f2b-8798-4ca78212a280', 'Apa yang dimaksud dengan tunggakan pajak?', '<p>Tunggakan pajak adalah kewajiban pajak yang belum dibayar atau belum diselesaikan sesuai ketentuan dan jangka waktu yang berlaku.</p>', 'tunggakan-pajak', 1, 'active', '2026-02-03 00:07:48', '2026-11-01 12:59:30'),
('42009c05-3bd1-494c-9048-85b53f374985', 'Bagaimana cara memastikan data perpajakan saya sudah tercatat dengan benar?', '<p>Wajib pajak dapat melakukan konfirmasi kepada perangkat daerah yang menangani pajak daerah melalui kanal layanan resmi. Siapkan identitas atau dokumen pendukung agar petugas dapat membantu melakukan pemeriksaan data.</p>', 'data-wajib-pajak', 3, 'active', '2024-03-08 12:09:24', '2026-11-01 12:59:30'),
('46c8b5d7-615a-4550-aadb-a1c0755331f3', 'Apakah laporan penerimaan pajak dapat diunduh?', '<p>Ketersediaan dokumen untuk diunduh bergantung pada publikasi resmi pemerintah daerah. Silakan kunjungi situs web atau kanal informasi resmi untuk melihat dokumen yang tersedia.</p>', 'laporan-dan-statistik', 3, 'active', '2024-04-02 20:59:47', '2026-11-01 12:59:30'),
('5b96a11a-f5ad-4cb7-a149-aa3487b465a0', 'Mengapa data pelanggan listrik diperlukan dalam pengelolaan Pajak Penerangan Jalan?', '<p>Data pelanggan listrik dapat menjadi salah satu informasi pendukung dalam pengelolaan dan pengawasan Pajak Penerangan Jalan sesuai ketentuan yang berlaku. Penggunaan data dilakukan dengan memperhatikan kewenangan dan ketentuan perlindungan data.</p>', 'data-pelanggan-listrik', 1, 'active', '2024-07-30 19:49:25', '2026-11-01 12:59:30'),
('7ed0887d-f47a-4e5f-880b-ef069477ac8a', 'Apa yang dimaksud dengan Pajak Penerangan Jalan (PJU)?', '<p>Pajak Penerangan Jalan merupakan pajak daerah yang berkaitan dengan penggunaan tenaga listrik sesuai ketentuan peraturan perundang-undangan. Pajak ini menjadi salah satu sumber pendapatan daerah yang digunakan untuk mendukung penyelenggaraan pemerintahan dan pembangunan daerah.</p>', 'informasi-umum', 1, 'active', '2024-07-13 16:39:18', '2026-11-01 12:59:30'),
('91a7605f-d3ab-4282-8b20-d163ff04aea0', 'Bagaimana proses pemeriksaan atau verifikasi data pajak dilakukan?', '<p>Verifikasi dilakukan dengan meneliti kesesuaian data dan dokumen pendukung berdasarkan ketentuan yang berlaku. Apabila diperlukan informasi tambahan, petugas akan menyampaikannya melalui mekanisme resmi.</p>', 'pengendalian-dan-verifikasi', 3, 'active', '2024-01-03 04:16:34', '2026-11-01 12:59:30'),
('961fe965-3ed6-4bc0-bca2-1569657fa7c8', 'Apa tujuan pemungutan Pajak Penerangan Jalan?', '<p>Pemungutan Pajak Penerangan Jalan bertujuan mendukung pendapatan daerah untuk membiayai penyelenggaraan pemerintahan dan pembangunan serta pelayanan kepada masyarakat sesuai ketentuan yang berlaku.</p>', 'informasi-umum', 2, 'active', '2024-03-19 10:00:32', '2026-11-01 12:59:30'),
('a8179d24-f312-4565-a83a-6cb11102fbb5', 'Bagaimana cara memperbarui data yang berkaitan dengan Pajak Penerangan Jalan?', '<p>Apabila terdapat perubahan data yang berkaitan dengan kewajiban Pajak Penerangan Jalan, wajib pajak dapat menghubungi perangkat daerah terkait melalui kanal layanan resmi dengan menyampaikan identitas dan dokumen pendukung yang diperlukan.</p>', 'data-wajib-pajak', 2, 'active', '2024-01-11 16:25:22', '2026-11-01 12:59:30'),
('a8bb687f-f530-416e-869e-2df2088dab90', 'Apa arti apabila realisasi penerimaan pajak belum mencapai target?', '<p>Kondisi tersebut menunjukkan bahwa penerimaan yang tercatat masih berada di bawah jumlah yang direncanakan. Pemerintah daerah dapat melakukan evaluasi dan langkah tindak lanjut sesuai kewenangannya.</p>', 'target-dan-realisasi', 3, 'active', '2024-06-09 13:00:09', '2026-11-01 12:59:30'),
('aa4e04c4-b3c2-4bf0-82c6-20aa111bd058', 'Bagaimana cara menyampaikan keberatan atau klarifikasi atas informasi pajak?', '<p>Masyarakat dapat menyampaikan permohonan klarifikasi atau menempuh mekanisme keberatan sesuai ketentuan yang berlaku melalui perangkat daerah yang berwenang. Pastikan dokumen pendukung disiapkan dan ikuti prosedur resmi.</p>', 'pengendalian-dan-verifikasi', 1, 'active', '2026-09-04 16:06:09', '2026-11-01 12:59:30'),
('af6737f9-9dc1-450b-942d-8a47f72e3264', 'Ke mana saya harus menyampaikan pertanyaan terkait data pelanggan listrik?', '<p>Untuk pertanyaan atau klarifikasi mengenai data pelanggan listrik yang berkaitan dengan Pajak Penerangan Jalan, masyarakat dapat menghubungi perangkat daerah terkait melalui kanal layanan resmi pemerintah daerah.</p>', 'data-pelanggan-listrik', 2, 'active', '2025-11-24 13:35:40', '2026-11-01 12:59:30'),
('b17d6501-3356-4e40-acaf-bcf066cae551', 'Mengapa masyarakat perlu memperhatikan perubahan peraturan Pajak Penerangan Jalan?', '<p>Perubahan peraturan dapat memengaruhi ketentuan, hak, dan kewajiban perpajakan. Oleh karena itu, masyarakat dianjurkan merujuk pada informasi dan peraturan terbaru yang diterbitkan melalui kanal resmi pemerintah.</p>', 'regulasi-dan-ketentuan', 3, 'active', '2026-10-08 18:29:09', '2026-11-01 12:59:30'),
('bae8cba6-1b98-4821-a1ba-2596765db96b', 'Mengapa pencatatan pemeriksaan dan tindak lanjut pajak diperlukan?', '<p>Pencatatan diperlukan untuk mendukung transparansi, ketertiban administrasi, dan akuntabilitas dalam pengelolaan pajak serta memastikan setiap tindak lanjut dapat ditelusuri.</p>', 'laporan-dan-statistik', 1, 'active', '2024-06-28 22:31:05', '2026-11-01 12:59:30'),
('c1b9f719-aaae-47c2-a8ea-03314b35176d', 'Apa perbedaan target dan realisasi penerimaan Pajak Penerangan Jalan?', '<p>Target merupakan jumlah penerimaan yang direncanakan dalam periode tertentu, sedangkan realisasi adalah jumlah penerimaan yang telah diterima dan tercatat pada periode tersebut.</p>', 'target-dan-realisasi', 1, 'active', '2025-07-03 07:49:58', '2026-11-01 12:59:30'),
('c23ceefc-c82e-47bf-ac8f-7343f910daa9', 'Bagaimana pemerintah daerah memastikan data dan pembayaran pajak tercatat dengan benar?', '<p>Pemerintah daerah melaksanakan pemeriksaan dan verifikasi data sesuai kewenangan serta prosedur yang berlaku untuk mendukung ketepatan administrasi dan akuntabilitas pengelolaan pajak.</p>', 'pengendalian-dan-verifikasi', 2, 'active', '2026-05-20 12:30:38', '2026-11-01 12:59:30'),
('cdf8beb9-287b-473a-a6ad-d2c61668b60e', 'Bagaimana cara mengetahui informasi mengenai Pajak Penerangan Jalan?', '<p>Masyarakat dapat memperoleh informasi mengenai Pajak Penerangan Jalan melalui kanal informasi resmi pemerintah daerah atau perangkat daerah yang menangani pengelolaan pajak daerah.</p>', 'data-wajib-pajak', 1, 'active', '2024-05-21 09:52:04', '2026-11-01 12:59:30'),
('d2de2e5d-637a-47ad-90d7-a36e5e132e44', 'Apa yang harus dilakukan jika terdapat informasi tunggakan pajak?', '<p>Periksa terlebih dahulu rincian kewajiban dan riwayat pembayaran. Jika terdapat perbedaan atau pembayaran yang belum tercatat, sampaikan klarifikasi beserta bukti pendukung kepada perangkat daerah terkait.</p>', 'tunggakan-pajak', 3, 'active', '2024-08-08 18:42:59', '2026-11-01 12:59:30'),
('d4223c49-3876-4f86-9efb-0a5c65b8698b', 'Di mana masyarakat dapat melihat informasi atau laporan penerimaan pajak?', '<p>Masyarakat dapat mengakses informasi yang telah dipublikasikan melalui situs web dan kanal informasi resmi pemerintah daerah, termasuk laporan kinerja atau laporan keuangan daerah.</p>', 'laporan-dan-statistik', 2, 'active', '2024-06-18 06:39:28', '2026-11-01 12:59:30'),
('e2fd7400-7f72-420c-98c6-30d0603c46c2', 'Apa yang harus dilakukan jika terdapat perbedaan antara bukti pembayaran dan catatan pajak?', '<p>Segera sampaikan permohonan klarifikasi kepada perangkat daerah terkait dengan menyertakan bukti pembayaran dan informasi transaksi. Pemeriksaan akan dilakukan sesuai prosedur yang berlaku.</p>', 'pembayaran-pajak', 3, 'active', '2025-09-04 06:28:11', '2026-11-01 12:59:30'),
('e3830aa1-d2b4-4866-bcef-44a0e28fcc11', 'Bagaimana masyarakat dapat mengetahui pencapaian target penerimaan pajak?', '<p>Informasi mengenai target dan realisasi penerimaan pajak dapat dilihat melalui publikasi resmi pemerintah daerah, seperti laporan kinerja atau laporan keuangan daerah, apabila telah dipublikasikan.</p>', 'target-dan-realisasi', 2, 'active', '2026-01-29 00:18:48', '2026-11-01 12:59:30'),
('f5968f86-0ee4-4929-81d2-e173ad9965a3', 'Bagaimana cara melakukan pembayaran Pajak Penerangan Jalan?', '<p>Tata cara pembayaran mengikuti ketentuan dan mekanisme yang berlaku. Untuk memperoleh informasi mengenai kanal pembayaran, persyaratan, dan prosedur yang tepat, silakan menghubungi perangkat daerah terkait atau melihat pengumuman resmi pemerintah daerah.</p>', 'pembayaran-pajak', 1, 'active', '2025-08-25 19:08:07', '2026-11-01 12:59:30'),
('fd2c4aad-d18c-4499-a405-3f631d1ce45f', 'Apakah informasi potensi pajak dapat berubah?', '<p>Ya. Perkiraan potensi dapat berubah apabila terdapat pembaruan data, perubahan kondisi, atau penyesuaian ketentuan. Informasi terbaru dapat dikonfirmasi melalui kanal resmi pemerintah daerah.</p>', 'potensi-pajak', 3, 'active', '2024-12-06 13:41:43', '2026-11-01 12:59:30');
